INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indentation'), 1, 'code_output', 'What does this print?', 'if True:\n    print("yes")\nprint("done")', 'python', 'yes\ndone', 'Which lines belong to the if, and which line is back at the left edge?', 'print(''yes'') is inside the if (indented) and runs because the condition is True; print(''done'') is outside and always runs.', 'if True:            <- block starts after the colon\n    print("yes")    <- indented: inside the if\nprint("done")       <- back at column 0: outside', NULL, 17);
