INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'input'), 1, 'mcq', 'A user types 42 when your program calls input(). What type of value does input() give back?', NULL, NULL, 'str (text)', 'input() can''t know whether you wanted text or a number.', 'input() always returns a string, here ''42''. Convert it yourself with int() or float() if you need a number.', NULL, NULL, 22);
