INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'execution'), 1, 'mcq', 'Which statement best describes how you run Python code?', NULL, NULL, 'You run the source file directly with the python program; there''s no separate build step you run yourself', 'Think of `node app.js` compared with `javac` + `java`.', 'Python is used like an interpreted language: `python file.py` runs the source. (Under the hood it compiles to bytecode automatically, see the expert questions.)', NULL, NULL, 24);
