INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 2, 'code_output', 'What does this print?', 'print(2 ** -1, 4 ** 0.5)', 'python', '0.5 2.0', 'A negative power means ''one over''; a power of 0.5 is a square root.', '2 ** -1 = 1/2 = 0.5, and 4 ** 0.5 = sqrt(4) = 2.0 (a float, because the exponent is a float).', NULL, NULL, 32);
