INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 2, 'code_output', 'What does this print?', 'print(7 // 2 * 2 + 7 % 2)', 'python', '7', '//, * and % have the same precedence and go left to right; + comes last.', '(7 // 2) * 2 = 6 and 7 % 2 = 1, so 6 + 1 = 7. This is the identity a == (a // b) * b + a % b.', NULL, NULL, 36);
