INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cli-args'), 1, 'true_false', 'When you run `python train.py --epochs 5`, the words after the file name are handed to the script as command-line arguments.', NULL, NULL, 'True', 'That''s how one script can be run with different settings.', 'Everything after the script name is passed in as text. The script reads it from sys.argv (or with argparse), which is how training jobs get settings like epochs or learning rate.', NULL, NULL, 82);
