INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cli-args'), 2, 'code_output', 'What does this print?', 'import sys\nsys.argv = ["train.py", "--lr", "0.1"]   # what `python train.py --lr 0.1` gives\nprint(sys.argv[1:], type(sys.argv[2]).__name__)', 'python', '[''--lr'', ''0.1''] str', 'The terminal only ever passes text.', 'sys.argv is a list of strings: the script name first, then every argument. ''0.1'' is a str until you convert it with float().', NULL, NULL, 89);
