INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cli-args'), 2, 'mcq', 'You run `python train.py data.csv`. Inside train.py, what is `sys.argv[0]`?', NULL, NULL, '''train.py''', 'Position 0 is taken before your own arguments start.', 'sys.argv[0] is the script''s name; your arguments start at sys.argv[1]. The word ''python'' is the program, not part of argv.', NULL, NULL, 90);
