INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'cli-args'), 2, 'fill_blank', 'The list that holds a script''s command-line arguments is sys.____.', NULL, NULL, 'argv', 'Short for ''argument vector'', a name inherited from C.', 'sys.argv[0] is the script name and sys.argv[1:] are the arguments, all as strings.', NULL, NULL, 91);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 2, 'code_output', 'What does this print?', 'print(2 ^ 3)', 'python', '1', 'In Python, ^ is not the power operator.', '^ is bitwise XOR: 10 XOR 11 = 01, which is 1. The power operator is **, so 2 ** 3 is 8. A classic bug when porting maths from a spreadsheet.', '  2 = 1 0\n  3 = 1 1\nXOR = 0 1   -> 1   (1 where the bits differ)', NULL, 92);
