INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arithmetic'), 2, 'code_output', 'What does this print?', 'print((0 - 1) % 5, (4 + 1) % 5)', 'python', '4 0', '% with a positive divisor always lands in 0..divisor-1.', 'Python''s % wraps around: one step back from 0 is 4, one step forward from 4 is 0. That makes % perfect for circular buffers and round-robin GPU assignment.', '   0 -> 1 -> 2 -> 3 -> 4\n   ^                   |\n   +-------------------+   (i + 1) % 5 / (i - 1) % 5', 'Like a clock: one hour before 0 is 11, not -1.', 94);
