INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 2, 'code_output', 'What does this print?', 'print(2 * 3 % 4, 2 * (3 % 4))', 'python', '2 6', '* and % have the same precedence.', 'Same precedence means left to right: (2 * 3) % 4 = 6 % 4 = 2. The brackets force 3 % 4 = 3 first, giving 6.', NULL, NULL, 95);
