INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'naming'), 1, 'mcq', 'Which of these is a valid Python variable name?', NULL, NULL, 'user_name', 'Names can''t start with a digit, can''t contain a dash, and can''t be a reserved word.', 'user_name uses letters and an underscore. 2users starts with a digit, user-name reads as ''user minus name'', and class is a keyword.', NULL, NULL, 8);
