INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 1, 'code_output', 'What does this print?', 'print(str(10) + "5")', 'python', '105', 'After str(10), what type is the left side?', 'str(10) is the text ''10''; ''10'' + ''5'' joins the two strings into ''105''.', NULL, NULL, 18);
