INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 1, 'code_output', 'What does this print?', 'print(int(3.9))', 'python', '3', 'int() doesn''t round, it chops.', 'int() drops everything after the decimal point, so 3.9 becomes 3. Use round(3.9) to get 4.', NULL, NULL, 19);
