INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dynamic-typing'), 1, 'true_false', 'Before using a variable in Python you must declare its type, as in `int x = 5;`.', NULL, NULL, 'False', 'How did you create variables in the earlier questions?', 'Python has no type declarations. `x = 5` creates the name x; Python works out the type from the value.', NULL, 'Like `let x = 5` in JavaScript, not `int x = 5;` in Java.', 20);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dynamic-typing'), 1, 'code_output', 'What does this print?', 'x = 5\nx = "five"\nprint(x)', 'python', 'five', 'Can a name point at a different type of value later?', 'A name can be rebound to any type. The value now attached to x is the string ''five''.', NULL, NULL, 21);
