INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'identity'), 1, 'mcq', 'What does `a == b` check?', NULL, NULL, 'Whether a and b have equal values', 'Two equals signs compare; one equals sign assigns.', '== compares values. A single = is assignment. ''Same object'' is a different check (`is`), covered later.', NULL, NULL, 22);
