INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unpacking'), 1, 'code_output', 'What does this print?', 'a, b = 1, 2\nprint(a, b)', 'python', '1 2', 'The values on the right are handed out to the names on the left, in order.', 'Multiple assignment: a gets 1, b gets 2.', NULL, NULL, 23);
