INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'floats'), 1, 'code_output', 'What does this print?', 'print(0.1 + 0.2)', 'python', '0.30000000000000004', 'Computers store decimals in binary, which can''t hold 0.1 exactly.', '0.1 and 0.2 are each stored as a tiny bit off, so the sum is 0.30000000000000004. Same in JavaScript and Java: it''s how floating point works.', NULL, NULL, 24);
