INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 1, 'mcq', 'A variable is created inside a function. Where can you use it?', NULL, NULL, 'Only inside that function', 'The function''s variables are its private workspace.', 'Names assigned inside a function are local: they exist while the function runs and can''t be seen from outside.', NULL, NULL, 25);
