INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binding'), 2, 'code_output', 'What does this print?', 'a = [1, 2]\nb = a\nb.append(3)\nprint(a)', 'python', '[1, 2, 3]', 'How many lists exist here?', 'b = a doesn''t copy; both names point at ONE list. Appending through b changes the list a sees. Use a.copy() for a separate list.', 'a --+\n    +--> [1, 2, 3]\nb --+', 'Two variables holding the same object reference in Java or JS.', 26);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 3]', 1), (@q, 'B', '[3]', 0), (@q, 'C', 'None', 0), (@q, 'D', '[1, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binding'), 2, 'code_output', 'What does this print?', 's = "hi"\nt = s\ns += "!"\nprint(t)', 'python', 'hi', 'Strings can''t be changed, so += must make something new.', 'Strings are immutable: s += ''!'' builds a new string and rebinds s. t still points at the original ''hi''.', NULL, NULL, 27);
