INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'identity'), 2, 'code_output', 'What does this print?', 'a = [1, 2]\nb = [1, 2]\nprint(a == b, a is b)', 'python', 'True False', 'Same contents, but were they created separately?', '== compares contents (equal). `is` asks whether they''re the same object; two list literals create two separate lists.', NULL, NULL, 28);
