INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'identity'), 2, 'true_false', 'The recommended way to test for None is `if x is None:` rather than `if x == None:`.', NULL, NULL, 'True', 'None is a singleton: there is only ever one None object.', '`is None` checks identity with the one None object; it''s faster and can''t be fooled by a class that overrides ==. PEP 8 recommends it.', NULL, NULL, 29);
