INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'identity'), 2, 'mcq', 'Which of these types is mutable (can be changed in place)?', NULL, NULL, 'list', 'Which one has methods like append?', 'Lists (and dicts, sets) are mutable. int, float, str, bool and tuple are immutable: ''changing'' them creates a new object.', NULL, NULL, 30);
