INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'identity'), 2, 'fill_blank', 'The built-in that returns an object''s unique identity number (its memory address in CPython) is ____.', NULL, NULL, 'id', 'Two letters.', 'id(x) returns an integer unique to the object while it lives. `a is b` is the same as id(a) == id(b).', NULL, NULL, 31);
