INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 1, 'code_output', 'What does this print?', 'print(float("2.5") * 2)', 'python', '5.0', 'After float(), is it still text?', 'float(''2.5'') turns the text into the number 2.5, and 2.5 * 2 is 5.0. Without the conversion, ''2.5'' * 2 would repeat the text: ''2.52.5''.', NULL, NULL, 89);
