INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-precision'), 1, 'mcq', 'What kind of numbers are a neural network''s weights usually stored as?', NULL, NULL, 'Floating-point numbers, usually 32-bit (float32)', 'Weights are small decimal values like 0.0132 that get nudged during training.', 'Weights need fractions, so they''re floats. Frameworks use 32-bit floats by default, and often 16-bit floats to save memory on big models.', NULL, NULL, 90);
