INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unpacking'), 2, 'code_output', 'What does this print?', 'x, y = "ab"\nprint(y, x)', 'python', 'b a', 'A string is a sequence too.', 'Unpacking works on any iterable with the right number of items. ''ab'' has two characters, so x = ''a'' and y = ''b''.', NULL, NULL, 91);
