INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unpacking'), 2, 'mcq', 'What does the `_` on the left-hand side mean here?', '_, label = ("img_001.png", "cat")\nprint(label)', 'python', 'It''s an ordinary variable name, used by convention for a value you don''t need', '_ is a normal name, used by convention for ''I don''t need this''.', 'The underscore takes the file name and label takes ''cat''. Writing _ tells readers (and linters) the value is deliberately ignored.', NULL, 'Like skipping a slot in JavaScript destructuring: const [, label] = pair.', 92);
