INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'core-types'), 2, 'code_output', 'What does this print?', 'print(type(True + 1).__name__, type(10 * 2.0).__name__, type(7 // 2).__name__)', 'python', 'int float int', 'bool behaves like int; any float in the mix makes a float.', 'True + 1 is the int 2, 10 * 2.0 is the float 20.0, and int // int stays an int (3).', NULL, NULL, 93);
