INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 2, 'code_output', 'What does this print?', 'print(bool([]), bool([0]), bool(0.0), bool(" "))', 'python', 'False True False True', 'bool() asks ''is it empty or zero?'', not ''what''s inside?''.', 'An empty list is False, but [0] has one item, so it''s True. 0.0 is False, and '' '' is a non-empty string (a space), so it''s True.', NULL, NULL, 95);
