INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-precision'), 2, 'true_false', 'Python''s built-in float is a 64-bit IEEE 754 double, the same format as NumPy''s float64.', NULL, NULL, 'True', 'There''s only one size of float in plain Python.', 'Python has a single float type: a 64-bit double with about 15-16 significant digits. NumPy and PyTorch add smaller types like float32 and float16.', NULL, NULL, 102);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binding'), 3, 'code_output', 'What does this print?', 'base = {"lr": 0.1, "layers": [64]}\nexp = base.copy()\nexp["lr"] = 0.01\nexp["layers"].append(32)\nprint(base)', 'python', '{''lr'': 0.1, ''layers'': [64, 32]}', '.copy() makes a new dict, but what about the list inside it?', 'A shallow copy has its own keys, so changing exp[''lr''] is safe. But both dicts point at the SAME inner list, so append shows up in base. Use copy.deepcopy for nested experiment configs.', 'base --> {''lr'': 0.1,  ''layers'': --+\nexp  --> {''lr'': 0.01, ''layers'': --+--> [64, 32]\n          own values             shared list', NULL, 103);
