INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conversion'), 3, 'code_output', 'What does this print?', 'import json\nprint(json.dumps({"ok": True, "missing": None}))', 'python', '{"ok": true, "missing": null}', 'JSON has its own spelling for booleans and ''nothing''.', 'json.dumps converts True -> true, None -> null and uses double quotes. That''s the text an API or an LLM tool call expects; print(dict) is NOT valid JSON.', NULL, 'Python''s JSON.stringify.', 110);
