INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 2, 'true_false', 'Strings in Python can be changed in place, e.g. s[0] = ''X''.', NULL, NULL, 'False', 'Try it in a cell and read the error.', 'Strings are immutable. s[0] = ''X'' raises TypeError; make a new string instead, e.g. ''X'' + s[1:].', NULL, NULL, 6);
