INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'immutability'), 3, 'mcq', 'Why are Python strings immutable?', NULL, NULL, 'So they can be hashed and used as dict keys, shared safely between variables and threads, and interned', 'Think about what a dict needs from its keys.', 'A dict key''s hash must never change, so keys must be immutable. Immutability also lets two names share one string with no risk. Java''s String is immutable for the same reasons.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Because Python is a slow language and copying is cheaper', 0), (@q, 'B', 'Because Unicode characters can''t be changed', 0), (@q, 'C', 'So they can be hashed and used as dict keys, shared safely between variables and threads, and interned', 1), (@q, 'D', 'They aren''t: you can change them with s[0] = ''x''', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'code_output', 'What does this print?', 'print("Hello".strip("Ho"))', 'python', 'ell', 'strip''s argument isn''t a word to remove.', 'strip(''Ho'') removes any of the characters ''H'' and ''o'' from both ends until it meets another character, leaving ''ell''.', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Hello', 0), (@q, 'B', 'llo', 0), (@q, 'C', 'Hell', 0), (@q, 'D', 'ell', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'code_output', 'What does this print?', 'print("settings".lstrip("set"), "settings".removeprefix("set"))', 'python', 'ings tings', 'One removes a set of characters, the other removes one exact prefix.', 'lstrip(''set'') keeps removing s, e and t from the left (s, e, t, t) until it hits ''i''. removeprefix(''set'') removes exactly ''set'' once (Python 3.9+).', NULL, NULL, 55);
