INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'split-join'), 3, 'code_output', 'What does this print?', 'print("a\\nb\\n".splitlines(), "a\\nb\\n".split("\\n"))', 'python', '[''a'', ''b''] [''a'', ''b'', '''']', 'What comes after the last newline?', 'split(''\\n'') produces an empty string after the trailing newline; splitlines() doesn''t (and also handles \\r\\n). Use splitlines() for text files.', NULL, NULL, 56);
