INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 3, 'code_output', 'What does this print?', 'print(len("café".encode("utf-8")))', 'python', '5', 'In UTF-8, plain English letters take 1 byte. Do accented letters?', 'c, a, f take 1 byte each; é takes 2 bytes in UTF-8. len of the str is 4 but the encoded bytes are 5.', NULL, NULL, 64);
