INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'performance'), 3, 'mcq', 'You build a 1 MB report line by line with `report += line` inside a loop of 100,000 iterations. What''s the recommended fix?', NULL, NULL, 'Append lines to a list and call "".join(lines) once at the end', 'Strings are immutable, so what does each += potentially do?', 'Each += may copy the whole string so far, which is O(n²) total. Collecting pieces and joining once is O(n). Same idea as StringBuilder in Java.', NULL, 'Java: StringBuilder instead of String + in a loop.', 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Append lines to a list and call "".join(lines) once at the end', 1), (@q, 'B', 'Nothing: += is always constant time in every Python implementation', 0), (@q, 'C', 'Convert report to bytes before adding', 0), (@q, 'D', 'Use report = report + line instead of +=', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'performance'), 3, 'code_output', 'What does this print?', 'vals = [3, 1, 4]\nprint(",".join(map(str, vals)))', 'python', '3,1,4', 'map(str, vals) converts each number first.', 'map(str, ...) turns each int into a str, so join works. This is the idiomatic, fast way to build a CSV line.', NULL, NULL, 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3,1,4', 1), (@q, 'B', '3, 1, 4', 0), (@q, 'C', '[3, 1, 4]', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'interning'), 3, 'true_false', 'You should compare strings with `is` because CPython interns strings, which makes `is` a faster equality check.', NULL, NULL, 'False', 'Does every string get interned?', 'Only some strings are interned. Strings built at runtime (input, file contents, joins) usually aren''t, so `is` can be False for equal text. Always use ==.', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 4, 'code_output', 'What does this print?', 'print("\\u00e9" == "e\\u0301", len("e\\u0301"))', 'python', 'False 2', 'There are two ways to write é in Unicode.', '''\\u00e9'' is the single code point é. ''e\\u0301'' is e + a combining accent: it looks the same but is 2 code points and not ==. Normalise with unicodedata.normalize(''NFC'', s) before comparing text.', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False 2', 1), (@q, 'B', 'True 1', 0), (@q, 'C', 'True 2', 0), (@q, 'D', 'False 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 4, 'code_output', 'What does this print?', 'data = "héllo".encode("utf-8")\nprint(data.decode("latin-1"))', 'python', 'hÃ©llo', 'latin-1 maps every byte to some character, so it never fails.', 'é is two UTF-8 bytes (0xC3 0xA9); latin-1 reads each byte as its own character: Ã and ©. This garbage is called mojibake. Always decode with the encoding that was used to encode.', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'héllo', 0), (@q, 'B', 'h?llo', 0), (@q, 'C', 'hÃ©llo', 1), (@q, 'D', 'UnicodeDecodeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 4, 'code_output', 'What does this print?', 'print("ß".upper(), len("ß".upper()))\nprint("Straße".casefold() == "STRASSE".casefold())', 'python', 'SS 2\nTrue', 'Changing case can change the length of a string.', 'German ß uppercases to ''SS'', two characters. casefold() is the aggressive lowercasing meant for case-insensitive comparison, and it maps ß to ''ss''; lower() doesn''t.', NULL, NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SS 2\nTrue', 1), (@q, 'B', 'SS 2\nFalse', 0), (@q, 'C', 'ß 1\nFalse', 0), (@q, 'D', 'ẞ 1\nTrue', 0);
