INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1', 0), (@q, 'B', '11', 0), (@q, 'C', '3', 0), (@q, 'D', '5', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'performance'), 4, 'code_output', 'What does this print?', 'import sys\nascii_s = "a" * 100\neuro_s = "a" * 99 + "\\u20ac"\nprint(sys.getsizeof(euro_s) > sys.getsizeof(ascii_s) + 90)', 'python', 'True', 'CPython picks 1, 2 or 4 bytes per character for the WHOLE string, based on its widest character.', 'PEP 393: an all-ASCII string uses 1 byte per character, but one euro sign forces 2 bytes for every character, so the second string is about 100 bytes bigger.', NULL, NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', 'True', 1), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'performance'), 4, 'mcq', 'Why is s[i] O(1) on a Python str even when it contains emoji, while in a UTF-8 string type (as in Go or Rust) finding the i-th character is O(n)?', NULL, NULL, 'CPython stores each str with a fixed width per character (1, 2 or 4 bytes), so the i-th character is at a computed offset', 'If every character takes the same number of bytes, where is character i?', 'Fixed width means offset = i * width. UTF-8 is variable-width (1-4 bytes), so you''d have to scan from the start. The trade-off: more memory when one wide character is present.', NULL, NULL, 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Python strings are stored as UTF-8 with a skip list', 0), (@q, 'B', 'CPython stores each str with a fixed width per character (1, 2 or 4 bytes), so the i-th character is at a computed offset', 1), (@q, 'C', 'It isn''t: s[i] on a str with emoji is O(n)', 0), (@q, 'D', 'Python caches the position of every character in a hash table', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'performance'), 4, 'true_false', 'CPython can sometimes make `s += t` in a loop run in place without copying, but this is an implementation detail you shouldn''t rely on.', NULL, NULL, 'True', 'Think about what happens when nothing else references s.', 'When s has only one reference, CPython may resize it in place. Other implementations (PyPy) and many cases (another reference exists) don''t get this, so use join for big builds.', NULL, NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'interning'), 4, 'code_output', 'What does this print?', 'a = "".join(["hel", "lo"])\nb = "hello"\nprint(a == b, a is b)', 'python', 'True False', 'Literals can be interned; strings built at runtime usually aren''t.', 'Same text (==) but different objects: the joined string was created at runtime and not interned, while ''hello'' is a compile-time constant.', NULL, NULL, 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True False', 1), (@q, 'B', 'True True', 0), (@q, 'C', 'False False', 0), (@q, 'D', 'False True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'interning'), 4, 'code_output', 'What does this print?', 'import sys\na = sys.intern("".join(["hel", "lo"]))\nb = sys.intern("hello")\nprint(a is b)', 'python', 'True', 'sys.intern returns the one canonical copy from the intern table.', 'sys.intern adds a string to (or fetches it from) a global table, so both calls return the same object. Used to save memory and speed up repeated dict lookups on many duplicate strings.', 'intern table\n  "hello" --> obj#1\nsys.intern(runtime "hello") -> obj#1\nsys.intern("hello")         -> obj#1   => a is b', NULL, 78);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', 'True', 1), (@q, 'D', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'interning'), 4, 'mcq', 'Why does CPython intern identifier-like strings such as attribute and variable names?', NULL, NULL, 'Attribute and global lookups are dict lookups; interned keys let a lookup succeed with a fast pointer comparison instead of comparing characters', 'obj.attr is really a dictionary lookup.', 'Names in code, obj.__dict__ keys and globals are interned, so most lookups find the key by identity before any character comparison. It''s a speed optimisation, not a language guarantee.', NULL, NULL, 79);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Attribute and global lookups are dict lookups; interned keys let a lookup succeed with a fast pointer comparison instead of comparing characters', 1), (@q, 'B', 'To encrypt the names in the bytecode', 0), (@q, 'C', 'To make strings mutable when needed', 0), (@q, 'D', 'Because Unicode strings can''t be hashed otherwise', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'immutability'), 4, 'code_output', 'What does this print?', 'x = "abc"\ny = x.replace("z", "q")\nprint(y is x)', 'python', 'True', 'If nothing needs to change, does CPython bother building a copy?', 'Since strings are immutable, CPython returns the same object when replace finds nothing to replace. Safe precisely because no one can modify it. Implementation detail: never write code that depends on it.', NULL, NULL, 80);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', 'None', 0), (@q, 'C', 'True', 1), (@q, 'D', 'False', 0);
