INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fstrings'), 4, 'true_false', 'In Python 3.12+, `f"{row["name"]}"` (reusing the same quote type inside the braces) is valid syntax.', NULL, NULL, 'True', 'PEP 701 changed how f-strings are parsed.', 'From 3.12, f-strings are parsed by the real grammar, so the expression inside braces may reuse the outer quotes, span lines and contain backslashes. Before 3.12 this was a SyntaxError.', NULL, NULL, 84);
