INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 3, 'mcq', 'open(''sales.csv'').read() fails with UnicodeDecodeError: ''utf-8'' codec can''t decode byte 0x92. What''s the best first move?', NULL, NULL, 'The file isn''t UTF-8: find its real encoding (often cp1252 for Excel exports on Windows) and pass encoding= to open()', 'Decoding needs to know how the bytes were written.', '0x92 is a curly apostrophe in cp1252. Decode with the encoding the file was written in. errors=''ignore'' silently deletes data, which is a nasty bug in an ML dataset.', NULL, NULL, 93);
