INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'split-join'), 2, 'code_output', 'What does this print?', 'print("model.v2.pt".rsplit(".", 1))', 'python', '[''model.v2'', ''pt'']', 'rsplit counts its cuts from the right.', 'rsplit(''.'', 1) makes one cut at the LAST dot, giving the name and the extension. split(''.'', 1) would cut at the first dot. (pathlib''s Path.suffix does this for file paths.)', NULL, NULL, 102);
