INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'char-tests'), 3, 'mcq', 'Which is the reliable way to check that user input like ''-5'' or '' 42 '' is a valid integer?', NULL, NULL, 'Try int(s) and catch ValueError', 'What does ''-5''.isdigit() return?', 'isdigit is False for ''-5'', ''3.5'' and '' 42 '' (sign, dot, spaces), yet int() accepts ''-5'' and '' 42 ''. Asking int() itself, ''easier to ask forgiveness than permission'', is the Pythonic check.', NULL, NULL, 106);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 's.isalpha() == False', 0), (@q, 'B', 's.isdigit()', 0), (@q, 'C', 'Try int(s) and catch ValueError', 1), (@q, 'D', 's.isnumeric()', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'char-tests'), 3, 'code_output', 'What does this print?', 'print("Hello World".istitle(), "hello".islower(), "123".islower())', 'python', 'True True False', 'islower needs at least one letter to be lowercase.', 'istitle checks each word starts with a capital. islower is True only if there is at least one cased letter and none are uppercase, so ''123'' (no letters) gives False.', NULL, NULL, 107);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True False', 0), (@q, 'B', 'True True False', 1), (@q, 'C', 'True True True', 0), (@q, 'D', 'True False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'text-cleaning'), 3, 'code_output', 'What does this print?', 'table = str.maketrans("", "", "!?.,")\nprint("Hi, there! OK?".translate(table))', 'python', 'Hi there OK', 'The third argument of maketrans lists characters to delete.', 'maketrans builds a lookup table in one go and translate applies it in a single pass, which is faster than chaining replace() calls. With string.punctuation as the third argument it strips all ASCII punctuation.', 'str.maketrans(from, to, delete)\n  "!" -> None   "?" -> None\n  "." -> None   "," -> None\n"Hi, there! OK?" --translate--> "Hi there OK"', NULL, 108);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Hi, there! OK?', 0), (@q, 'B', 'Hi there OK', 1), (@q, 'C', 'TypeError', 0), (@q, 'D', 'Hi  there  OK ', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'text-cleaning'), 3, 'fill_blank', 'The static method that builds a table for str.translate is str.____(...).', NULL, NULL, 'maketrans', 'make + a short form of ''translation''.', 'str.maketrans(''abc'', ''xyz'') maps a->x, b->y, c->z; a third argument lists characters to delete.', NULL, NULL, 109);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'text-cleaning'), 3, 'code_output', 'What does this print?', 'import re\nprint(re.sub(r"\\s+", " ", "a \\t b\\n\\nc").strip())', 'python', 'a b c', '\\s+ matches one or more whitespace characters of any kind.', 're.sub replaces every run of spaces, tabs and newlines with one space. The r prefix keeps the backslash for the regex engine instead of Python''s string escapes.', NULL, NULL, 110);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'abc', 0), (@q, 'B', 'a b c', 1), (@q, 'C', 'a \\t b\\n\\nc', 0), (@q, 'D', 'a  b  c', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'text-cleaning'), 3, 'code_output', 'What does this print?', 'import re\nnums = re.findall(r"\\d+", "epoch 12, step 340")\nprint(nums, sum(map(int, nums)))', 'python', '[''12'', ''340''] 352', 'Regex works on text, so what type are the matches?', '\\d+ grabs runs of digits; findall returns them as strings, so convert before doing maths. Handy for pulling metrics out of training logs.', NULL, NULL, 111);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''12'', ''340''] 352', 1), (@q, 'B', '[''1'', ''2'', ''3'', ''4'', ''0''] 10', 0), (@q, 'C', '[12, 340] 352', 0), (@q, 'D', '[''12'', ''340''] 12340', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'text-cleaning'), 3, 'code_output', 'What does this print?', 'tpl = ''Reply as JSON like {"label": "..."} for: {text}''\nprint(tpl.format(text="great movie"))', 'python', 'KeyError', 'format() treats EVERY { } pair as a placeholder.', 'format sees {"label": "..."} as a field named ''"label"'' and raises KeyError. In LLM prompt templates that contain JSON, double the literal braces ({{ }}) or use string.Template.', NULL, NULL, 112);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Reply as JSON like {"label": "..."} for: great movie', 0), (@q, 'B', 'ValueError', 0), (@q, 'C', 'IndexError', 0), (@q, 'D', 'KeyError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'text-cleaning'), 3, 'mcq', 'Why does string.Template succeed on this prompt when str.format would raise KeyError?', 'from string import Template\nt = Template(''Reply as {"label": "..."} for: $text'')\nprint(t.substitute(text="great movie"))', 'python', 'Template only replaces $name placeholders, so the JSON braces are left as plain text', 'Template uses $name placeholders, not braces.', 'string.Template only replaces $text, so JSON braces are left alone. It''s a safe choice for prompts and user-supplied templates; safe_substitute leaves missing names in place instead of raising.', 'str.format:  {text}  and  {"label": ...}   <- both are fields\nTemplate  :  $text        {"label": ...}   <- only $ is a field', 'Like a Mustache/Handlebars template: only the marked slots are filled.', 113);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Template escapes braces automatically by doubling them', 0), (@q, 'B', 'Template converts the prompt to JSON first', 0), (@q, 'C', 'Template.substitute ignores any placeholder it can''t fill', 0), (@q, 'D', 'Template only replaces $name placeholders, so the JSON braces are left as plain text', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'text-cleaning'), 3, 'code_output', 'What does this print?', 'import textwrap\nprompt = """\n    You are a helper.\n    Be brief.\n"""\nprint(repr(textwrap.dedent(prompt)))', 'python', '''\\nYou are a helper.\\nBe brief.\\n''', 'dedent removes the indentation that every line shares, nothing more.', 'Triple-quoted strings inside functions pick up the code''s indentation. dedent strips the common leading spaces; the newline right after the opening quotes stays (add .strip() to drop it).', '"""                    ->  ''''\n    You are a helper.  ->  ''You are a helper.''\n    Be brief.          ->  ''Be brief.''\n"""   (4 common spaces removed)', NULL, 114);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '''You are a helper. Be brief.''', 0), (@q, 'B', '''You are a helper.\\nBe brief.''', 0), (@q, 'C', '''\\nYou are a helper.\\nBe brief.\\n''', 1), (@q, 'D', '''\\n    You are a helper.\\n    Be brief.\\n''', 0);
