INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4', 1), (@q, 'B', '6', 0), (@q, 'C', '2', 0), (@q, 'D', '3', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'code_output', 'What does this print?', 'print("abc".center(7, "*") + "|", "ab".ljust(4, ".") + "|")', 'python', '**abc**| ab..|', 'center pads both sides; ljust pads on the right.', 'center(7, ''*'') adds 4 stars split evenly; ljust(4, ''.'') left-justifies, padding on the right. f''{s:*^7}'' and f''{s:.<4}'' do the same.', NULL, NULL, 116);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'abc****| ab..|', 0), (@q, 'B', '**abc**| ab..|', 1), (@q, 'C', '*abc*| ab..|', 0), (@q, 'D', '**abc**| ..ab|', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'fill_blank', 'To pad ''42'' with leading zeros to width 5 (keeping any minus sign in front) you call ''42''.____(5).', NULL, NULL, 'zfill', 'z for zero.', '''42''.zfill(5) is ''00042'' and ''-42''.zfill(5) is ''-0042'': unlike a plain rjust, it puts the zeros after the sign.', NULL, NULL, 117);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'code_output', 'What does this print?', 'print("Mississippi".count("ss"), "aaaa".count("aa"))', 'python', '2 2', 'count doesn''t let matches overlap.', 'count scans left to right and skips past each match, so ''aaaa'' holds two non-overlapping ''aa'', not three. Use a regex lookahead if you need overlapping matches.', NULL, NULL, 118);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 2', 0), (@q, 'B', '4 3', 0), (@q, 'C', '2 2', 1), (@q, 'D', '2 3', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'mcq', 'This prints True True. What''s the idiomatic way to check a filename against several extensions?', 'print("cat.png".endswith((".jpg", ".png")), "img".startswith(("x", "i")))', 'python', 'fname.endswith((".jpg", ".png")): pass a tuple of suffixes', 'startswith and endswith accept a tuple of options.', 'startswith/endswith accept a tuple and return True if any option matches; a list raises TypeError. `".jpg" or ".png"` evaluates to just ".jpg", a classic silent bug. Useful for filtering image files in a dataset folder.', NULL, NULL, 119);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'fname.endswith((".jpg", ".png")): pass a tuple of suffixes', 1), (@q, 'B', 'fname.endswith(".jpg|.png")', 0), (@q, 'C', 'fname.endswith([".jpg", ".png"]): pass a list', 0), (@q, 'D', 'fname.endswith(".jpg" or ".png")', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 3, 'code_output', 'What does this print?', 's = "hello"\nprint(s[::-2], s[-100:2])', 'python', 'olh he', 'A negative step starts from the end; a far-out-of-range start is clipped.', 's[::-2] walks backwards taking every second character: o, l, h. s[-100:2] clips the start to 0, giving ''he''. Slices never raise IndexError.', NULL, NULL, 120);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ol he', 0), (@q, 'B', 'olh he', 1), (@q, 'C', 'leh he', 0), (@q, 'D', 'olh IndexError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 3, 'true_false', 'Python has no separate character type: ''abc''[1] is a str of length 1, equal to the slice ''abc''[1:2].', 'print("abc"[1:2] == "abc"[1], type("abc"[1]).__name__)', 'python', 'True', 'Compare type(''abc''[1]) with type(''abc''[1:2]).', 'There is no char type: indexing gives a string of length 1, the same as a one-character slice. (Java and C have char; Python doesn''t.)', NULL, 'Unlike Java and C, where ''b'' (char) and "b" (String) are different types.', 121);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 3, 'mcq', 'What is slice(0, 4) in this snippet (which prints 2026 11)?', 'date = "2026-11-15"\nYEAR, MONTH = slice(0, 4), slice(5, 7)\nprint(date[YEAR], date[MONTH])', 'python', 'The object that s[0:4] builds behind the scenes; you can name it and reuse it', 'slice(a, b) is the object behind the [a:b] syntax.', 's[0:4] is really s[slice(0, 4)]. Naming slices makes fixed-width record parsing readable: date[YEAR] instead of date[0:4].', 'date  = "2026-11-15"\nindex    0123456789\nYEAR  = slice(0, 4)  -> "2026"\nMONTH = slice(5, 7)  -> "11"', NULL, 122);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A list of the indexes 0, 1, 2, 3', 0), (@q, 'B', 'The object that s[0:4] builds behind the scenes; you can name it and reuse it', 1), (@q, 'C', 'A NumPy-only feature that strings borrow', 0), (@q, 'D', 'A function that cuts the string into 4 pieces', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'operators'), 3, 'code_output', 'What does this print?', 'print("abc" < "abd", "abc" < "ab", "" < "a")', 'python', 'True False True', 'When one string is a prefix of the other, the shorter one comes first.', 'Comparison goes character by character: ''c'' < ''d''. ''ab'' is a prefix of ''abc'', so ''ab'' is smaller, and '''' is smaller than every non-empty string.', NULL, NULL, 123);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False False True', 0), (@q, 'B', 'True False True', 1), (@q, 'C', 'True True True', 0), (@q, 'D', 'True False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'operators'), 3, 'mcq', 'words = [''banana'', ''apple'', ''Cherry'']. sorted(words) gives [''Cherry'', ''apple'', ''banana'']. How do you sort them alphabetically ignoring case, without changing the words?', NULL, NULL, 'sorted(words, key=str.lower)', 'Uppercase letters have smaller code points than lowercase ones.', 'Plain sorting puts ''C'' (67) before ''a'' (97). key=str.lower (or str.casefold) sorts case-insensitively without changing the strings themselves.', 'code points: ''C'' = 67  <  ''a'' = 97  <  ''b'' = 98\nplain sort:     Cherry, apple, banana\nkey=str.lower:  apple, banana, Cherry', 'Like ORDER BY LOWER(name) in SQL.', 124);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'sorted(words.lower())', 0), (@q, 'B', 'sorted(words, case=False)', 0), (@q, 'C', 'sorted(words, key=str.lower)', 1), (@q, 'D', 'words.sort(ignore_case=True)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'operators'), 3, 'true_false', '`'''' in ''abc''` is True: the empty string counts as a substring of every string.', NULL, NULL, 'True', 'Where in ''abc'' can you find zero characters?', 'The empty string is found at every position, so '''' in s is always True and s.find('''') is 0. A filter like `if keyword in text` with an empty keyword matches everything.', NULL, NULL, 125);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fstrings'), 3, 'code_output', 'What does this print?', 'print(f"{3.14159:.3}", f"{1234.5:.2e}", f"{0.000123:g}")', 'python', '3.14 1.23e+03 0.000123', 'Without f, the precision means significant digits, not decimals.', '.3 with no type keeps 3 significant digits (3.14). .2e is scientific notation with 2 decimals. g picks fixed or scientific automatically. Use .2e for tiny learning rates and losses.', NULL, NULL, 126);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3.14 1.23e+03 0.000123', 1), (@q, 'B', '3.142 1234.50 0.000123', 0), (@q, 'C', '3.142 1.23e+03 0.000', 0), (@q, 'D', '3.14 1.23e3 1.23e-04', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fstrings'), 3, 'code_output', 'What does this print?', 'x = "hi"\nwidth = 5\nprint(f"{x!r}", f"[{x:>{width}}]")', 'python', '''hi'' [   hi]', '!r means repr; a format spec can contain its own {...}.', '!r shows the value with quotes, like repr(). The width inside the spec can come from a variable via nested braces, handy for aligning table columns of varying width.', NULL, NULL, 127);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '''hi'' [   hi]', 1), (@q, 'B', 'hi [   hi]', 0), (@q, 'C', '''hi'' [hi   ]', 0), (@q, 'D', 'SyntaxError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fstrings'), 3, 'mcq', 'Why does {d:%d %b %Y} work inside an f-string (printing 15 Nov 2026)?', 'from datetime import date\nd = date(2026, 11, 15)\nprint(f"{d:%d %b %Y}")', 'python', 'The text after the colon is passed to the object''s __format__ method, and date reads it as strftime codes', 'The part after the colon is passed to the object''s own __format__.', 'Each type decides what its format spec means. For dates it''s strftime codes, so you can format timestamps for log lines and run names right inside an f-string.', NULL, NULL, 128);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The text after the colon is passed to the object''s __format__ method, and date reads it as strftime codes', 1), (@q, 'B', 'f-strings have special built-in support for dates only', 0), (@q, 'C', 'The date is first converted to a str, then sliced', 0), (@q, 'D', '%d %b %Y are f-string escape codes', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fstrings'), 3, 'code_output', 'What does this print?', 'print("%s has %d items, %.1f%%" % ("cart", 3, 12.345))', 'python', 'cart has 3 items, 12.3%', 'This is the old printf-style formatting; %% is a literal percent sign.', '%s, %d and %.1f are filled from the tuple in order. You still meet this style in older code and in the logging module.', NULL, NULL, 129);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '%s has %d items, %.1f%%', 0), (@q, 'C', 'cart has 3 items, 12.345%', 0), (@q, 'D', 'cart has 3 items, 12.3%', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'fstrings'), 3, 'code_output', 'What does this print?', 'x = 5\nprint(f"{x = }", f"{x*2=}")', 'python', 'x = 5 x*2=10', 'The = specifier copies the expression text exactly, spaces included.', 'f''{x = }'' keeps your spaces around =, and the expression can be any code: x*2=10. A quick way to label debug prints.', NULL, NULL, 130);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'x = 5 x*2=10', 1), (@q, 'B', 'x = 5 10', 0), (@q, 'C', '5 10', 0), (@q, 'D', 'x=5 x*2=10', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'escapes'), 3, 'code_output', 'What does this print?', 'print(repr("a\\tb"), len("\\x41\\u00e9"))', 'python', '''a\\tb'' 2', '\\x41 and \\u00e9 each produce one character.', 'repr shows the tab as \\t so invisible characters are visible. \\x41 is ''A'' and \\u00e9 is ''é'', so the second string has 2 characters.', NULL, NULL, 131);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '''a\\tb'' 2', 1), (@q, 'B', '''a b'' 3', 0), (@q, 'C', '''a    b'' 2', 0), (@q, 'D', '''a\\tb'' 10', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 3, 'code_output', 'What does this print?', 'print("é".encode("utf-8"), b"\\xc3\\xa9".decode("utf-8"))', 'python', 'b''\\xc3\\xa9'' é', 'In UTF-8, é takes two bytes.', 'encode turns text into bytes (shown as \\x escapes for non-ASCII), and decode turns the same bytes back into text. Data on disk and on the network is bytes; your code should work with str.', NULL, NULL, 132);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'b''\\xc3\\xa9'' é', 1), (@q, 'B', 'UnicodeEncodeError', 0), (@q, 'C', 'b''\\xe9'' é', 0), (@q, 'D', 'b''é'' é', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 3, 'code_output', 'What does this print?', 's = "\\U0001F600"   # a smiley emoji\nprint(len(s), len(s.encode("utf-8")), len(s.encode("utf-16-le")))', 'python', '1 4 4', 'One code point, but how many bytes in each encoding?', 'The emoji is a single code point. UTF-8 uses 4 bytes for it, and UTF-16 needs a surrogate pair (2 x 2 bytes). That''s why JavaScript, which uses UTF-16, reports ''😀''.length as 2.', 'char   code point   UTF-8 bytes\n''a''    U+0061       1\n''é''    U+00E9       2\n''€''    U+20AC       3\n''😀''   U+1F600      4', NULL, 133);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 4 4', 1), (@q, 'B', '2 4 4', 0), (@q, 'C', '1 4 2', 0), (@q, 'D', '4 4 4', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 3, 'code_output', 'What does this print?', 'print(ascii(b"caf\\xe9".decode("utf-8", errors="replace")))', 'python', '''caf\\ufffd''', 'errors=''replace'' swaps bad bytes for a special marker character.', '0xe9 alone isn''t valid UTF-8 (it''s latin-1 é). ''replace'' puts U+FFFD (the � character) there so you can see data was lost; ''ignore'' would silently drop it. Better still: find the right encoding. (ascii() is repr() with non-ASCII characters shown as escapes.)', NULL, NULL, 134);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '''caf''', 0), (@q, 'B', 'UnicodeDecodeError', 0), (@q, 'C', '''caf\\ufffd''', 1), (@q, 'D', '''caf\\xe9''', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unicode'), 3, 'true_false', 'In Python 3, `''abc'' == b''abc''` is False.', NULL, NULL, 'True', 'str and bytes are different types.', 'Text and bytes never compare equal, even with the same ASCII content; decode or encode one side first. This often bites when reading files in binary mode (''rb'') or handling network responses.', NULL, NULL, 135);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'split-join'), 3, 'code_output', 'What does this print?', 'print("".split(","), "".split())', 'python', '[''''] []', 'split with an explicit separator always returns at least one piece.', '''''.split('','') is [''''] (one empty field), but ''''.split() is []. An empty line in a CSV therefore looks like one empty column, not zero columns.', NULL, NULL, 136);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[] ['''']', 0), (@q, 'B', '[''''] ['''']', 0), (@q, 'C', '[''''] []', 1), (@q, 'D', '[] []', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'split-join'), 3, 'code_output', 'What does this print?', 'print("k=v".split("=", 1), "k".partition("="))', 'python', '[''k'', ''v''] (''k'', '''', '''')', 'partition always returns a 3-tuple, even when the separator is missing.', 'When ''='' isn''t found, partition returns (s, '''', ''''), so `key, _, value = line.partition(''='')` never fails, while unpacking line.split(''='') into two names would raise ValueError.', '"k=v".partition("=")  -> (''k'', ''='', ''v'')\n"k".partition("=")    -> (''k'', '''',  '''')    never raises', NULL, 137);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''k=v''] (''k'', '''', '''')', 0), (@q, 'B', '[''k'', ''v''] ValueError', 0), (@q, 'C', '[''k'', ''v''] (''k'', ''='', '''')', 0), (@q, 'D', '[''k'', ''v''] (''k'', '''', '''')', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'performance'), 3, 'mcq', 'This prints 0,1,2,. Why use io.StringIO when building a large string piece by piece?', 'import io\nbuf = io.StringIO()\nfor i in range(3):\n    buf.write(f"{i},")\nprint(buf.getvalue())', 'python', 'It''s an in-memory text buffer: writes append cheaply and getvalue() builds the final string once', 'StringIO is an in-memory text file you can keep writing to.', 'Each write appends to an internal buffer and getvalue() returns everything at once. Like ''''.join(parts), it avoids building a new string on every step.', 's += piece   : copy all of s + piece every time   O(n^2)\nbuf.write()  : append to a buffer, getvalue()     O(n)', 'Java''s StringBuilder, or building an array of chunks in JS and joining at the end.', 138);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It''s an in-memory text buffer: writes append cheaply and getvalue() builds the final string once', 1), (@q, 'B', 'It compresses the text as you write', 0), (@q, 'C', 'It makes the string mutable so you can edit single characters', 0), (@q, 'D', 'It writes to a temporary file on disk', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'immutability'), 3, 'mcq', 'This prints 0.01 False. Why does d[key] find the entry even though key is a different object from the literal ''lr''?', 'd = {"lr": 0.01}\nkey = "".join(["l", "r"])\nprint(d[key], key is "lr")', 'python', 'Dict lookup compares hash and ==, and equal strings always have equal hashes', 'Dict lookup uses hash and ==, not identity.', 'The joined key is a different object from the literal ''lr'', but it has the same content and hash, so the lookup works. This is exactly why string keys must be immutable: their hash can never change.', NULL, 'Like Java''s HashMap, which uses hashCode() and equals(), not ==.', 139);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Dicts compare keys with is, and join returned the cached literal', 0), (@q, 'B', 'Python interns every string used as a dict key', 0), (@q, 'C', 'The dict converts keys to lowercase first', 0), (@q, 'D', 'Dict lookup compares hash and ==, and equal strings always have equal hashes', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'immutability'), 3, 'code_output', 'What does this print?', 'chars = list("hello")\nchars[0] = "j"\nchars[-1] = "y"\nprint("".join(chars))', 'python', 'jelly', 'A list of characters CAN be changed in place.', 'For many edits, convert to a list, change items, then join once. Each slice-and-concatenate on a str would copy the whole string again.', NULL, NULL, 140);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'jello', 0), (@q, 'B', 'hello', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', 'jelly', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'char-tests'), 4, 'code_output', 'What does this print?', 's = "\\u00b2"   # superscript two\nprint(s.isdigit())\nprint(int(s))', 'python', 'True\nValueError', 'isdigit and int() don''t agree on what a ''digit'' is.', 'Superscript ² counts as a digit for isdigit(), but int() only accepts decimal digits (isdecimal()). So isdigit() is not a safe guard before int().', NULL, NULL, 141);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True\nValueError', 1), (@q, 'B', 'False\nValueError', 0), (@q, 'C', 'True\n2', 0), (@q, 'D', 'True\n²', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'char-tests'), 4, 'code_output', 'What does this print?', 'print("\\u00bd".isdigit(), "\\u00bd".isnumeric(), "\\u00b2".isdecimal())', 'python', 'False True False', 'The three tests form a ladder: isdecimal is the strictest, isnumeric the loosest.', '½ is numeric but not a digit; ² is a digit but not decimal. isdecimal() ⊂ isdigit() ⊂ isnumeric(). Only isdecimal() characters are guaranteed to work with int().', 'isnumeric   ''5''  ''²''  ''½''  ''五''\nisdigit     ''5''  ''²''\nisdecimal   ''5''                  <- what int() accepts', NULL, 142);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True False', 0), (@q, 'B', 'True True True', 0), (@q, 'C', 'False True False', 1), (@q, 'D', 'False False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'text-cleaning'), 4, 'code_output', 'What does this print?', 'import unicodedata\nprint(unicodedata.normalize("NFKC", "\\ufb01le \\uff28\\uff49 \\u2460"))', 'python', 'file Hi 1', 'NFKC folds ''compatibility'' characters into their plain forms.', 'NFKC turns the ﬁ ligature into ''fi'', full-width letters into ASCII and circled ① into 1. Many NLP tokenizers apply NFKC first so look-alike characters map to the same tokens.', NULL, NULL, 143);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'file Hi 1', 1), (@q, 'B', 'ﬁle Ｈｉ ①', 0), (@q, 'C', 'file Ｈｉ ①', 0), (@q, 'D', 'UnicodeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'text-cleaning'), 4, 'mcq', 'This prints cafe naive. What does the NFD-then-filter trick do, and what''s the catch?', 'import unicodedata\ns = unicodedata.normalize("NFD", "café naïve")\nprint("".join(c for c in s if not unicodedata.combining(c)))', 'python', 'It splits letters from their accent marks and drops the marks; useful for search, but it can change meaning in some languages', 'NFD splits é into e + a separate accent mark.', 'After NFD decomposition, accents are separate combining characters; dropping them leaves plain letters. A common search and dedup trick, but it changes meaning in some languages, so don''t do it blindly.', NULL, NULL, 144);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It only works on French text', 0), (@q, 'B', 'It splits letters from their accent marks and drops the marks; useful for search, but it can change meaning in some languages', 1), (@q, 'C', 'It translates the text to English', 0), (@q, 'D', 'It encodes the text as ASCII bytes', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 4, 'code_output', 'What does this print?', 'print("Hello".replace("", "-"))', 'python', '-H-e-l-l-o-', 'Where does the empty string ''appear'' in Hello?', 'The empty string matches at every position, including both ends, so replace inserts ''-'' six times. The same rule makes ''Hello''.count('''') equal 6.', NULL, NULL, 145);
