INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing-slicing'), 1, 'code_output', 'What does this print?', 'nums = [10, 20, 30]\nprint(nums[3])', 'python', 'IndexError', 'How many items are there, and where does counting start?', 'Valid indexes are 0, 1, 2. Index 3 is past the end, so Python raises IndexError (JS would quietly give undefined).', NULL, 'Like asking for seat 4 in a row of 3 seats: there''s nothing there, and Python says so instead of handing you an empty chair.', 9);
