INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing-slicing'), 1, 'code_output', 'What does this print?', 'letters = ["a", "b", "c", "d", "e"]\nprint(letters[1:3])', 'python', '[''b'', ''c'']', 'A slice [start:stop] includes start but stops BEFORE stop.', 'Index 1 is ''b'', index 2 is ''c'', and index 3 is excluded: [''b'', ''c''].', ' index:    0    1    2    3    4\n         [ a  | b  | c  | d  | e ]\n              ^start    ^stop (not included)\n result:   [''b'', ''c'']', NULL, 10);
