INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copying'), 3, 'code_output', 'What does this print?', 'a = [[1, 2], [3, 4]]\nb = a[:]\nb[0].append(99)\nprint(a)', 'python', '[[1, 2, 99], [3, 4]]', 'a[:] copies the outer list. What about the rows inside?', 'A shallow copy makes a new outer list but both lists point at the SAME inner lists, so b[0].append changes a[0] too.', ' a ---> [ * , * ]\n          |   |\n          v   v\n        [1,2] [3,4]     <- shared rows\n          ^   ^\n          |   |\n b ---> [ * , * ]       (new outer list)', NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[99], [3, 4]]', 0), (@q, 'B', '[[1, 2], [3, 4], 99]', 0), (@q, 'C', '[[1, 2, 99], [3, 4]]', 1), (@q, 'D', '[[1, 2], [3, 4]]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copying'), 3, 'code_output', 'What does this print?', 'import copy\na = [[1, 2], [3, 4]]\nb = copy.deepcopy(a)\nb[0].append(99)\nprint(a, b[0])', 'python', '[[1, 2], [3, 4]] [1, 2, 99]', 'deepcopy copies every level.', 'deepcopy also copies the inner lists, so b''s rows are independent and a is untouched.', NULL, 'Shallow copy is copying a folder of shortcuts; deep copy is copying the folder and every file the shortcuts point to.', 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[1, 2], [3, 4]] [1, 2, 99]', 1), (@q, 'B', '[[1, 2], [3, 4]] [1, 2]', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', '[[1, 2, 99], [3, 4]] [1, 2, 99]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 3, 'code_output', 'What does this print?', 'grid = [[0] * 3] * 3\ngrid[0][0] = 1\nprint(grid)', 'python', '[[1, 0, 0], [1, 0, 0], [1, 0, 0]]', '* 3 on the outer list repeats a reference, not a fresh row.', '[[0]*3]*3 makes ONE row and three references to it, so changing grid[0][0] shows up in every row. Use [[0]*3 for _ in range(3)].', ' grid -> [ * , * , * ]\n           \\   |   /\n            v  v  v\n          [ 0, 0, 0 ]   <- one row, three arrows', NULL, 54);
