INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-queue'), 3, 'code_output', 'What does this print?', 'from collections import deque\nlast = deque(maxlen=3)\nfor x in [1, 2, 3, 4, 5]:\n    last.append(x)\nprint(list(last))', 'python', '[3, 4, 5]', 'A full bounded deque drops from the opposite end.', 'With maxlen=3, each new append pushes the oldest item out the left: you keep the last 3. Handy for moving averages of training loss.', ' append 4:  [1, 2, 3] -> [2, 3, 4]   (1 falls out)\n append 5:  [2, 3, 4] -> [3, 4, 5]   (2 falls out)', NULL, 58);
