INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'code_output', 'What does this print?', 'rows = [("bob", 30), ("amy", 25), ("cat", 30)]\nprint(sorted(rows, key=lambda r: r[1]))', 'python', '[(''amy'', 25), (''bob'', 30), (''cat'', 30)]', 'Python''s sort is stable.', 'Sort by age; bob and cat tie at 30, and a stable sort keeps their original order (bob before cat).', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[(''amy'', 25), (''bob'', 30), (''cat'', 30)]', 1), (@q, 'B', '[(''bob'', 30), (''cat'', 30), (''amy'', 25)]', 0), (@q, 'C', '[(''amy'', 25), (''cat'', 30), (''bob'', 30)]', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'code_output', 'What does this print?', 'rows = [("bob", 30), ("amy", 25), ("cat", 30)]\nprint(sorted(rows, key=lambda r: (-r[1], r[0])))', 'python', '[(''bob'', 30), (''cat'', 30), (''amy'', 25)]', 'Tuples compare item by item; the minus flips one direction.', 'Key (-age, name): age descending first, then name ascending to break ties: bob, cat, then amy.', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[(''bob'', 30), (''cat'', 30), (''amy'', 25)]', 1), (@q, 'B', '[(''cat'', 30), (''bob'', 30), (''amy'', 25)]', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', '[(''amy'', 25), (''bob'', 30), (''cat'', 30)]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'code_output', 'What does this print?', 'print(sorted(["banana", "Apple", "cherry"]))', 'python', '[''Apple'', ''banana'', ''cherry'']', 'Strings compare by character code.', 'Uppercase letters have smaller codes than lowercase, so ''Apple'' comes first. Use key=str.lower for case-insensitive order.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''cherry'', ''banana'', ''Apple'']', 0), (@q, 'B', '[''Apple'', ''banana'', ''cherry'']', 1), (@q, 'C', '[''Apple'', ''cherry'', ''banana'']', 0), (@q, 'D', '[''banana'', ''Apple'', ''cherry'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'code_output', 'What does this print?', 'print(sorted([3, "1", 2]))', 'python', 'TypeError', 'Can Python decide whether 3 < ''1''?', 'Python 3 refuses to order int against str and raises TypeError (JS would coerce silently).', NULL, 'Like asking whether a banana is bigger than the number 3: Python refuses to guess, where JS would quietly convert one of them.', 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 3]', 0), (@q, 'B', 'TypeError', 1), (@q, 'C', '[''1'', 2, 3]', 0), (@q, 'D', '[2, 3, ''1'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'mcq', 'You need to check `user_id in seen` 100,000 times against 100,000 ids. Which is the right fix if `seen` is a list?', NULL, NULL, 'Convert seen to a set once, then check membership', 'Which container has O(1) average lookup?', 'List membership is O(n), so 100k checks is ~10^10 steps. A set is hashed: O(1) average per check.', NULL, 'A list is reading the whole guest list each time; a set is a bouncer who knows instantly whether a name is on it.', 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Use seen.index(user_id) instead', 0), (@q, 'B', 'Use a tuple instead of a list', 0), (@q, 'C', 'Convert seen to a set once, then check membership', 1), (@q, 'D', 'Sort the list first', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'mcq', 'Which operation on a list of n items is O(n), not O(1)?', NULL, NULL, 'a.insert(0, x)', 'Which one forces everything to shift?', 'Inserting at the front moves all n items one slot right. Append, pop from the end and index assignment don''t move anything.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'a[i] = x', 0), (@q, 'B', 'a.insert(0, x)', 1), (@q, 'C', 'a.append(x)', 0), (@q, 'D', 'a.pop()', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-defaults'), 3, 'code_output', 'What does this print?', 'def add(item, bucket=None):\n    if bucket is None:\n        bucket = []\n    bucket.append(item)\n    return bucket\n\nadd(1)\nprint(add(2))', 'python', '[2]', 'Where is the list created now?', 'With the None sentinel, a fresh list is created inside each call, so the calls don''t share state.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2]', 1), (@q, 'B', 'None', 0), (@q, 'C', '[1, 2]', 0), (@q, 'D', '[None, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'true_false', 'A Python list of 1,000 floats stores the 1,000 float values directly next to each other in memory, like a C double array.', NULL, NULL, 'False', 'Each item is a full Python object.', 'A list stores pointers (references) to float objects that live elsewhere. That''s why NumPy arrays, which store raw values contiguously, are much smaller and faster.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'code_output', 'What does this print?', 'x = [0]\na = [x, x]\na[0].append(1)\nprint(a)', 'python', '[[0, 1], [0, 1]]', 'Both slots hold a reference to the same object.', 'a contains the same list x twice; mutating it through a[0] is visible through a[1].', NULL, NULL, 67);
