INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing-slicing'), 2, 'code_output', 'What does this print?', 'a = [1, 2, 3, 4, 5]\nprint(a[-3:-1])', 'python', '[3, 4]', 'Translate the negatives to positions first.', '-3 is index 2 (the 3) and -1 is index 4 (the 5), which is excluded, so you get [3, 4].', NULL, NULL, 96);
