INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iter-tools'), 2, 'fill_blank', 'To loop over `items` from last to first without building a reversed copy, write `for x in ____(items):`', NULL, NULL, 'reversed', 'A built-in function, not a slice.', 'reversed(items) returns an iterator that walks backwards. items[::-1] also works but copies the whole list first.', NULL, NULL, 97);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'code_output', 'What does this print?', 'a = [1, 2]\nb = [3, 4]\nprint(a + b, a * 2)', 'python', '[1, 2, 3, 4] [1, 2, 1, 2]', 'Lists are containers, not vectors.', '+ joins lists and * repeats them. If you expected element-wise maths ([4, 6] and [2, 4]) you need NumPy arrays: np.array(a) + np.array(b).', NULL, NULL, 98);
