INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 2, 'code_output', 'What does this print?', 'm = [[1, 2], [3, 4], [5, 6]]\nprint([row[1] for row in m])', 'python', '[2, 4, 6]', 'm[1] would be a row. How do you get one item from each row?', 'The comprehension takes item 1 of every row, which is column 1. With plain lists there''s no m[:, 1]; that''s NumPy syntax.', NULL, NULL, 100);
