INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iter-tools'), 2, 'code_output', 'What does this print?', 'a = [1, 2, 3]\nfor x in a:\n    x *= 10\nprint(a)', 'python', '[1, 2, 3]', 'x is a name for each item, not a slot in the list.', 'x *= 10 makes a new int and rebinds x; the list still holds the old ints. To change items, write a[i] = ... with enumerate, or build a new list.', NULL, NULL, 101);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[10, 20, 30]', 0), (@q, 'B', '[1, 2, 3]', 1), (@q, 'C', 'TypeError', 0), (@q, 'D', '[10, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'code_output', 'What does this print?', 'runs = [{"lr": 0.1, "acc": 0.8}, {"lr": 0.01, "acc": 0.9}]\nbest = max(runs, key=lambda r: r["acc"])\nprint(best["lr"])', 'python', '0.01', 'max compares the runs by the value key= returns.', 'key picks the accuracy to compare, but max returns the whole winning run, so you can read its lr. Handy for picking the best hyperparameters.', NULL, NULL, 102);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '0.1', 0), (@q, 'C', '0.9', 0), (@q, 'D', '0.01', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iter-tools'), 3, 'code_output', 'What does this print?', 'pairs = zip([1, 2, 3], ["a", "b"], strict=True)\nprint(list(pairs))', 'python', 'ValueError', 'strict=True turns a silent truncation into an error.', 'With strict=True, zip raises ValueError as soon as one input runs out before the other. Use it whenever two lists must line up, e.g. predictions and labels.', NULL, NULL, 103);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'ValueError', 1), (@q, 'C', '[(1, ''a''), (2, ''b'')]', 0), (@q, 'D', '[(1, ''a''), (2, ''b''), (3, None)]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iter-tools'), 3, 'true_false', 'A `zip` object can be looped over twice; the second loop gives the same pairs again.', NULL, NULL, 'False', 'zip returns an iterator, not a list.', 'Iterators are single-use: after list(z) consumes it, a second list(z) is []. Wrap it in list() once if you need it more than once.', NULL, NULL, 104);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'You shuffle training data with `random.shuffle(X)` and then `random.shuffle(y)`. What''s wrong?', NULL, NULL, 'The two shuffles use different random orders, so examples no longer line up with their labels', 'Each call draws a fresh random order.', 'The pairs (X[i], y[i]) are broken, so the model trains on random labels and accuracy drops to chance. Shuffle one list of indices and apply it to both, or shuffle zipped pairs.', NULL, 'Shuffling the question cards and, separately, the answer cards: every card is still there, but the answers no longer match.', 105);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'random.shuffle returns a new list and leaves X unchanged', 0), (@q, 'B', 'random.shuffle only works on NumPy arrays', 0), (@q, 'C', 'Nothing; shuffling both keeps them aligned', 0), (@q, 'D', 'The two shuffles use different random orders, so examples no longer line up with their labels', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'code_output', 'What does this print?', 'seqs = [[5, 2], [7], [1, 4, 9]]\nL = max(len(s) for s in seqs)\npadded = [s + [0] * (L - len(s)) for s in seqs]\nprint(padded)', 'python', '[[5, 2, 0], [7, 0, 0], [1, 4, 9]]', 'Each row gets as many zeros as it is short of the longest.', 'L is 3, so rows get 1, 2 and 0 zeros on the right. Token-id sequences are padded like this (with a pad id) so a batch becomes a rectangle a tensor can hold.', ' [5 2 .]     [5 2 0]\n [7 . .]  -> [7 0 0]    pad id = 0, length = 3\n [1 4 9]     [1 4 9]', NULL, 106);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[0, 5, 2], [0, 0, 7], [1, 4, 9]]', 0), (@q, 'B', '[[5, 2, 0], [7, 0, 0], [1, 4, 9]]', 1), (@q, 'C', '[[5, 2], [7], [1, 4, 9]]', 0), (@q, 'D', '[[5, 2, 0], [7, 0], [1, 4, 9]]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'code_output', 'What does this print?', 'import numpy as np\nnp.array([[1, 2], [3]])', 'python', 'ValueError', 'Rows of different lengths can''t form a rectangle.', 'NumPy 2 refuses ragged nested lists (''inhomogeneous shape'') unless you pass dtype=object. Pad the rows first, as tokenizers do.', NULL, NULL, 107);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'IndexError', 0), (@q, 'C', 'Nothing is printed; it makes a 2x2 array', 0), (@q, 'D', 'ValueError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing-slicing'), 3, 'code_output', 'What does this print?', 'a = [1, 2, 3, 4, 5]\na[1:4] = []\nprint(a)', 'python', '[1, 5]', 'Replacing a slice with an empty list...', 'The three items at positions 1, 2, 3 are replaced by nothing, so the list shrinks. Same effect as del a[1:4].', NULL, NULL, 108);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', '[1, [], 5]', 0), (@q, 'C', '[1, 5]', 1), (@q, 'D', '[1, 2, 5]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing-slicing'), 3, 'code_output', 'What does this print?', 'a = list(range(6))\nprint(a[4:1:-1], a[1:4:-1])', 'python', '[4, 3, 2] []', 'With a negative step, start must be to the RIGHT of stop.', 'a[4:1:-1] walks 4, 3, 2 and stops before 1. a[1:4:-1] asks to walk backwards from 1 to 4, which is impossible, so it''s empty (no error).', NULL, NULL, 109);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[4, 3, 2] [1, 2, 3]', 0), (@q, 'B', '[4, 3, 2] []', 1), (@q, 'C', '[] [3, 2, 1]', 0), (@q, 'D', '[4, 3, 2, 1] [3, 2, 1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'code_output', 'What does this print?', 'a = [1, 2, 3]\nprint(a.reverse(), a[::-1], a)', 'python', 'None [1, 2, 3] [3, 2, 1]', 'Arguments are evaluated left to right, and reverse() works in place.', 'a.reverse() flips a and returns None. By the time a[::-1] runs, a is [3, 2, 1], so its reversed copy is [1, 2, 3].', NULL, NULL, 110);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3, 2, 1] [1, 2, 3] [1, 2, 3]', 0), (@q, 'B', 'None [3, 2, 1] [1, 2, 3]', 0), (@q, 'C', '[3, 2, 1] [3, 2, 1] [3, 2, 1]', 0), (@q, 'D', 'None [1, 2, 3] [3, 2, 1]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 3, 'mcq', 'What is `a` after this code runs?', 'a = [1, 2, 3]\na.insert(100, "x")\na.insert(-1, "y")', 'python', '[1, 2, 3, ''y'', ''x'']', 'insert never raises for a big index; a negative index means ''before that item''.', 'insert(100, ''x'') clamps to the end, so it appends. insert(-1, ''y'') puts ''y'' before the current last item, which is now ''x''.', NULL, NULL, 111);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 3, ''x'', ''y'']', 0), (@q, 'B', '[1, 2, ''y'', 3, ''x'']', 0), (@q, 'C', 'IndexError', 0), (@q, 'D', '[1, 2, 3, ''y'', ''x'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copying'), 3, 'code_output', 'What does this print?', 'def add_bias(xs):\n    xs.append(1)\n    return xs\n\nfeatures = [0.5, 0.2]\nresult = add_bias(features)\nprint(features, result is features)', 'python', '[0.5, 0.2, 1] True', 'The function receives the same list object, not a copy.', 'Python passes a reference to the object. append mutates the caller''s list, and the returned value is that same list. Build a new list (xs + [1]) if the caller must not see changes.', NULL, 'Same as passing an array into a JS function: arr.push() inside is visible outside.', 112);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0.5, 0.2, 1] False', 0), (@q, 'B', '[0.5, 0.2] False', 0), (@q, 'C', '[0.5, 0.2] True', 0), (@q, 'D', '[0.5, 0.2, 1] True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copying'), 3, 'code_output', 'What does this print?', 'def reset_a(xs):\n    xs = []\n\ndef reset_b(xs):\n    xs[:] = []\n\na = [1, 2]\nb = [1, 2]\nreset_a(a)\nreset_b(b)\nprint(a, b)', 'python', '[1, 2] []', 'One rebinds a local name; the other changes the object.', 'xs = [] only points the local name at a new list. xs[:] = [] replaces the contents of the caller''s list in place.', ' reset_a:  a  -----> [1, 2]   (untouched)\n           xs -----> []       (new list, thrown away)\n reset_b:  b, xs --> [1, 2] -> emptied in place -> []', NULL, 113);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2] []', 1), (@q, 'B', '[] [1, 2]', 0), (@q, 'C', '[] []', 0), (@q, 'D', '[1, 2] [1, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copying'), 3, 'mcq', 'Which line gives fully independent rows of a 2-D list of numbers `grid`, without importing `copy`?', NULL, NULL, 'new = [row[:] for row in grid]', 'You need a new outer list AND a new list for each row.', 'The comprehension copies every row. The other three copy only the outer list, so the rows are still shared. For deeper nesting use copy.deepcopy.', NULL, NULL, 114);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'new = grid[:]', 0), (@q, 'B', 'new = grid * 1', 0), (@q, 'C', 'new = [row[:] for row in grid]', 1), (@q, 'D', 'new = list(grid)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 3, 'code_output', 'What does this print?', 'm = [[1, 2], [3, 4]]\nflat = [x for row in m for x in row]\nprint(flat)', 'python', '[1, 2, 3, 4]', 'Read the for clauses left to right, like nested loops.', 'It is ''for row in m: for x in row: keep x''. The outer loop comes first, so the result goes row by row: [1, 2, 3, 4].', NULL, NULL, 115);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 3, 2, 4]', 0), (@q, 'B', 'NameError', 0), (@q, 'C', '[[1, 2], [3, 4]]', 0), (@q, 'D', '[1, 2, 3, 4]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 3, 'mcq', 'What is `m` after this code runs?', 'm = [[1, 2], [3, 4]]\nfor row in m:\n    row = [0, 0]', 'python', '[[1, 2], [3, 4]]', 'Assigning to the loop variable doesn''t touch the list.', 'row = [0, 0] just rebinds the name row. To change rows in place write row[:] = [0, 0], or m[i] = [0, 0].', NULL, NULL, 116);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[0, 0], [0, 0]]', 0), (@q, 'B', '[[1, 2], [3, 4]]', 1), (@q, 'C', '[[0, 0], [3, 4]]', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tuples'), 3, 'code_output', 'What does this print?', 'x = 1,\nprint(x, type(x).__name__)', 'python', '(1,) tuple', 'It''s the comma that makes a tuple, not the brackets.', 'x = 1, creates a one-item tuple. A stray trailing comma like `total = compute(),` is a classic bug: total becomes a tuple and later maths fails.', NULL, NULL, 117);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(1,) tuple', 1), (@q, 'B', 'SyntaxError', 0), (@q, 'C', '1 int', 0), (@q, 'D', '[1] list', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tuples'), 3, 'mcq', 'You need a lightweight immutable record with named fields (`p.x`, `p.y`) that still unpacks and compares like a tuple. Which fits?', NULL, NULL, 'collections.namedtuple (or typing.NamedTuple)', 'It''s a tuple subclass with field names.', 'namedtuple(''P'', ''x y'') makes a class whose instances are tuples: p.x works, p[0] works, and P(1, 2) == (1, 2) is True. A dict is mutable and doesn''t unpack by position.', NULL, NULL, 118);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'collections.namedtuple (or typing.NamedTuple)', 1), (@q, 'B', 'A dict', 0), (@q, 'C', 'A set', 0), (@q, 'D', 'A list', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tuples'), 3, 'mcq', 'What does `return mean, std` in a function actually return?', NULL, NULL, 'One tuple (mean, std) that the caller can unpack', 'Remember what the comma does.', 'The comma builds a tuple, so the function returns one object. `m, s = stats(x)` unpacks it. That''s how Python ''returns multiple values''.', NULL, NULL, 119);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Two separate return values', 0), (@q, 'B', 'One tuple (mean, std) that the caller can unpack', 1), (@q, 'C', 'A list [mean, std]', 0), (@q, 'D', 'Only mean; std is ignored', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-queue'), 3, 'code_output', 'What does this print?', 'import heapq\nh = [5, 1, 4]\nheapq.heapify(h)\nprint(heapq.heappop(h), heapq.heappop(h))', 'python', '1 4', 'A heap always gives the smallest item first.', 'heapify rearranges the list into a min-heap in O(n); each heappop removes the current smallest in O(log n). Used for top-k and beam search.', ' heap as a tree:     1        list: [1, 5, 4]\n                    / \\\n                   5   4      parent <= children', 'A hospital triage queue: whoever has the most urgent (smallest) number is seen next, whatever their arrival order.', 120);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '5 1', 0), (@q, 'B', '1 4', 1), (@q, 'C', '4 1', 0), (@q, 'D', '1 5', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-queue'), 3, 'code_output', 'What does this print?', 'import heapq\nh = []\nfor x in [3, 9, 1]:\n    heapq.heappush(h, -x)\nprint(-h[0])', 'python', '9', 'heapq only does min-heaps; the minus sign flips the order.', 'Storing negatives makes the largest number the smallest entry, so h[0] is -9 and -h[0] is 9. The standard trick for a max-heap in Python.', NULL, NULL, 121);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3', 0), (@q, 'B', '9', 1), (@q, 'C', '1', 0), (@q, 'D', '-9', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-queue'), 3, 'fill_blank', 'For `d = deque([1, 2, 3])`, `d.____(1)` moves the last item to the front, giving [3, 1, 2].', NULL, NULL, 'rotate', 'Think of turning a wheel by one step.', 'rotate(n) shifts right by n (a negative n shifts left). Useful for round-robin scheduling.', NULL, NULL, 122);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-queue'), 3, 'code_output', 'What does this print?', 'def ok(s):\n    st = []\n    pairs = {")": "(", "]": "["}\n    for ch in s:\n        if ch in "([":\n            st.append(ch)\n        elif not st or st.pop() != pairs[ch]:\n            return False\n    return not st\n\nprint(ok("([])"), ok("(]"), ok("(("))', 'python', 'True False False', 'Push openers; a closer must match the most recent opener; nothing may be left at the end.', '''(]'' fails on the mismatch and ''(('' leaves openers on the stack. This stack check is a classic interview question (and how parsers check JSON nesting).', NULL, NULL, 123);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True False', 0), (@q, 'B', 'True False True', 0), (@q, 'C', 'True False False', 1), (@q, 'D', 'False False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'code_output', 'What does this print?', 'print(sorted(["b", "B", "a", "A"], key=str.lower))', 'python', '[''a'', ''A'', ''b'', ''B'']', 'key=str.lower makes ''a'' and ''A'' tie. What decides the order of ties?', 'Case is ignored for comparison, and the stable sort keeps tied items in their original order: ''a'' came before ''A'', and ''b'' before ''B''.', NULL, NULL, 124);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''a'', ''b'', ''A'', ''B'']', 0), (@q, 'B', '[''A'', ''B'', ''a'', ''b'']', 0), (@q, 'C', '[''a'', ''A'', ''b'', ''B'']', 1), (@q, 'D', '[''A'', ''a'', ''B'', ''b'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'mcq', 'Why can `for i in range(len(a)): total += sum(a[i:])` be very slow on a long list?', NULL, NULL, 'Every slice a[i:] copies the rest of the list, so the loop does O(n^2) work', 'Is a list slice a window or a new list?', 'List slices create new lists, costing O(k) for k items. Doing that n times is quadratic. Keep a running total, or use indexes instead of slicing in a loop.', NULL, NULL, 125);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Slicing is O(1) but sum is O(n^2)', 0), (@q, 'B', 'range(len(a)) builds a huge list in memory', 0), (@q, 'C', 'Python caches every slice, so memory runs out', 0), (@q, 'D', 'Every slice a[i:] copies the rest of the list, so the loop does O(n^2) work', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'true_false', '`len(a)` on a list is O(n) because Python counts the items each time you call it.', NULL, NULL, 'False', 'The list keeps a number in its header.', 'A list stores its current size, so len() just reads it: O(1). Calling len(a) in a loop condition is cheap.', NULL, NULL, 126);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'fill_blank', 'The `bisect` module finds positions in a SORTED list in O(log n) using ____ search (one word).', NULL, NULL, 'binary', 'Halve the range each step.', 'bisect_left / bisect_right do binary search. The list must already be sorted, otherwise the answer is meaningless.', NULL, NULL, 127);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'You have a list of file paths with repeats and must drop duplicates but keep the first-seen order. Which is best?', NULL, NULL, 'list(dict.fromkeys(paths))', 'Dicts remember insertion order, and keys are unique.', 'dict.fromkeys keeps the first occurrence of each key, in order, in O(n). set() loses the order, sorted() changes it, and the `not in out` loop is O(n^2).', NULL, NULL, 128);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'sorted(set(paths))', 0), (@q, 'B', 'A loop doing `if p not in out: out.append(p)`', 0), (@q, 'C', 'list(set(paths))', 0), (@q, 'D', 'list(dict.fromkeys(paths))', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-defaults'), 3, 'mcq', 'Which default argument is safe to use as-is?', NULL, NULL, 'def f(x, tags=()):', 'The danger is a default that can be mutated.', 'An empty tuple is immutable, so sharing it across calls can''t leak state. The others are mutable objects created once and shared by every call.', NULL, NULL, 129);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'def f(x, tags=[]):', 0), (@q, 'B', 'def f(x, tags=()):', 1), (@q, 'C', 'def f(x, tags={}):', 0), (@q, 'D', 'def f(x, tags=set()):', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-defaults'), 3, 'code_output', 'What does this print?', 'class Model:\n    layers = []\n    def add(self, layer):\n        self.layers.append(layer)\n\na = Model()\nb = Model()\na.add("conv")\nprint(b.layers)', 'python', '[''conv'']', 'Where does `layers` live: on each object, or on the class?', 'layers is a class attribute: one list shared by every instance, the same trap as a mutable default. Create it in __init__ with self.layers = [].', NULL, 'Like a static field in Java: every instance sees the same one.', 130);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[]', 0), (@q, 'B', 'None', 0), (@q, 'C', 'AttributeError', 0), (@q, 'D', '[''conv'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'true_false', 'After `b = a[:]`, `a[0] is b[0]` is True: the copy holds the same element objects, not duplicates of them.', NULL, NULL, 'True', 'What exactly does a slice copy?', 'A slice copies the references into a new outer list. Every element object is shared, which is fine for immutable items and a trap for mutable ones.', NULL, NULL, 131);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'mcq', 'Why is `sum(values)` over a Python list of 1 million floats much slower than `np.sum(arr)`?', NULL, NULL, 'Each list item is a separate boxed object, so Python follows a pointer and checks the type for every element', 'Recall what a list slot actually stores.', 'A list holds pointers to float objects scattered in memory, and the loop runs in the interpreter. NumPy stores raw doubles side by side and sums them in C.', NULL, NULL, 132);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Each list item is a separate boxed object, so Python follows a pointer and checks the type for every element', 1), (@q, 'B', 'Lists can''t hold more than 65,536 floats efficiently', 0), (@q, 'C', 'np.sum uses the GPU automatically', 0), (@q, 'D', 'sum() sorts the list first', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing-slicing'), 4, 'code_output', 'What does this print?', 'a = [0, 1, 2, 3, 4, 5]\na[1::2] = "xyz"\nprint(a)', 'python', '[0, ''x'', 2, ''y'', 4, ''z'']', 'Extended slices need the same number of items, and a string is iterable.', 'a[1::2] has 3 slots (1, 3, 5) and ''xyz'' supplies exactly 3 characters, so each slot gets one letter. Any iterable of the right length works.', NULL, NULL, 133);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'ValueError', 0), (@q, 'C', '[0, ''xyz'', 2, 4]', 0), (@q, 'D', '[0, ''x'', 2, ''y'', 4, ''z'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing-slicing'), 4, 'true_false', 'Assigning `a[5:] = [9]` to a 3-item list pads positions 3 and 4 with None, then puts 9 at index 5.', NULL, NULL, 'False', 'Out-of-range slice bounds are clipped first.', 'The slice a[5:] is clipped to the empty slice at the end, so 9 is just appended: [1, 2, 3, 9]. Lists never have gaps.', NULL, NULL, 134);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 4, 'code_output', 'What does this print?', 'a = [1, 2, 3]\na += (4, 5)\nprint(a)\na = a + (6,)', 'python', '[1, 2, 3, 4, 5]\nTypeError', '+= and + are different methods with different rules.', 'list += calls extend, which accepts any iterable, so the tuple works. list + requires another list and raises TypeError. Same symbol, different strictness.', NULL, NULL, 135);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 3, 4, 5]', 0), (@q, 'B', '[1, 2, 3, 4, 5]\nTypeError', 1), (@q, 'C', 'TypeError', 0), (@q, 'D', '[1, 2, 3, (4, 5)]\nTypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copying'), 4, 'code_output', 'What does this print?', 'a = [1, 2]\na.append(a)\nprint(a, a[2][2][0])', 'python', '[1, 2, [...]] 1', 'The list now contains itself.', 'a[2] is a itself, so a[2][2][0] is a[0]. repr spots the cycle and prints [...] instead of recursing forever. copy.deepcopy handles such cycles with its memo.', ' a ---> [ 1 | 2 | * ]\n   ^              |\n   +--------------+   (slot 2 points back to a)', NULL, 136);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, [...]] 1', 1), (@q, 'B', '[1, 2, [1, 2]] 1', 0), (@q, 'C', '[1, 2, [1, 2, [...]]] 2', 0), (@q, 'D', 'RecursionError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copying'), 4, 'code_output', 'What does this print?', 'import copy\nt = (1, 2)\nu = (1, [2])\nprint(copy.deepcopy(t) is t, copy.deepcopy(u) is u)', 'python', 'True False', 'Copying something that can never change is pointless.', 'deepcopy returns the same tuple when everything inside is immutable. If the tuple holds a list, it must build a new tuple around a copied list.', NULL, NULL, 137);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False False', 0), (@q, 'B', 'True True', 0), (@q, 'C', 'False True', 0), (@q, 'D', 'True False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 4, 'mcq', 'What is `nums` after this loop?', 'nums = [1, 2, 3]\nfor x in nums:\n    if x < 3:\n        nums.append(x + 10)', 'python', '[1, 2, 3, 11, 12]', 'A list iterator re-checks the length on every step.', 'The loop also visits 11 and 12 (which add nothing). Lists don''t raise like dicts do; if the appended items also passed the test, the loop would never end.', NULL, NULL, 138);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'RuntimeError', 0), (@q, 'B', '[1, 2, 3, 11, 12]', 1), (@q, 'C', '[1, 2, 3, 11, 12, 21, 22]', 0), (@q, 'D', '[1, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 4, 'mcq', 'In `[[0] * 3] * 3`, why is the inner `[0] * 3` harmless but the outer `* 3` a trap?', NULL, NULL, 'Both repeat references; sharing the immutable int 0 is fine, sharing one mutable row list is not', 'What happens when you ''change'' a shared int vs a shared list?', '* never copies objects. grid[0][0] = 1 replaces the int in the row (ints can''t change), but every outer slot points to that same row, so all rows show it.', NULL, NULL, 139);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Both repeat references; sharing the immutable int 0 is fine, sharing one mutable row list is not', 1), (@q, 'B', 'Python special-cases numbers in *', 0), (@q, 'C', 'The inner * copies values and the outer * copies references', 0), (@q, 'D', 'The outer * is lazy and the inner * is eager', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tuples'), 4, 'code_output', 'What does this print?', '(a, b), *rest = [(1, 2), 3, 4]\nprint(a, b, rest)', 'python', '1 2 [3, 4]', 'Unpacking patterns can be nested.', 'The first element (1, 2) is unpacked into a and b; *rest collects the rest as a list. The same nesting works in loops: for i, (x, y) in enumerate(points).', NULL, NULL, 140);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', '1 2 (3, 4)', 0), (@q, 'C', '1 2 [3, 4]', 1), (@q, 'D', '(1, 2) 3 [4]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tuples'), 4, 'mcq', 'What is `x` after this code runs?', 'x = [1, 2]\ni = 0\ni, x[i] = 1, 9', 'python', '[1, 9]', 'The right side is built first; then targets are assigned LEFT to RIGHT.', 'i becomes 1 first, and only then is x[i] worked out as a target, so x[1] = 9. Unpacking into a name and an index that uses it is a subtle bug source.', ' right side:  (1, 9)   built first\n step 1:      i    = 1\n step 2:      x[i] = 9   -> x[1] = 9  (i is already 1)', NULL, 141);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[9, 9]', 0), (@q, 'B', 'IndexError', 0), (@q, 'C', '[1, 9]', 1), (@q, 'D', '[9, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-queue'), 4, 'true_false', '`deque.append` and `deque.popleft` are thread-safe in CPython, but `if d: d.popleft()` run from two threads can still raise IndexError.', NULL, NULL, 'True', 'Each call is atomic; the pair of calls is not.', 'Another thread can empty the deque between the check and the pop (a check-then-act race). Use queue.Queue for producer/consumer code, or catch IndexError.', NULL, 'Two cashiers both see one item left on the shelf, and both promise it to a customer.', 142);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-queue'), 4, 'code_output', 'What does this print?', 'import heapq\nh = []\nheapq.heappush(h, (1, {"id": "a"}))\nheapq.heappush(h, (1, {"id": "b"}))', 'python', 'TypeError', 'When the priorities tie, what does tuple comparison compare next?', 'Equal first items make Python compare the dicts, and dicts don''t support <. The standard fix is (priority, counter, item) with an increasing counter as a tie-breaker.', NULL, NULL, 143);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Nothing is printed; both are pushed', 0), (@q, 'B', 'TypeError', 1), (@q, 'C', 'ValueError', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 4, 'code_output', 'What does this print?', 'print(sorted([3, 1, 2], key=lambda x: x > 1))', 'python', '[1, 3, 2]', 'The keys are booleans, and False < True.', 'Keys are True, False, True. False sorts first; the two True items keep their original order (3 before 2). A stable sort by a boolean key is a partition.', NULL, NULL, 144);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 3, 2]', 1), (@q, 'B', '[3, 2, 1]', 0), (@q, 'C', '[1, 2, 3]', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 4, 'code_output', 'What does this print?', 'print(sorted([3, float("nan"), 1]))', 'python', '[3, nan, 1]', 'Every comparison with NaN is False.', 'Sorting relies on <, and NaN breaks it silently: the result isn''t sorted at all and no error is raised. Drop or fill NaN losses and metrics before sorting or ranking.', NULL, NULL, 145);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[nan, 1, 3]', 0), (@q, 'B', '[1, 3, nan]', 0), (@q, 'C', '[3, nan, 1]', 1), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 4, 'code_output', 'What does this print?', 'from functools import cmp_to_key\nnums = ["3", "30", "34"]\nnums.sort(key=cmp_to_key(lambda a, b: (b + a > a + b) - (b + a < a + b)))\nprint("".join(nums))', 'python', '34330', 'The comparator puts a first when a + b makes the bigger string.', 'This is the ''largest number'' interview problem: order by concatenation, so 34, then 3, then 30. cmp_to_key adapts an old two-argument comparator to key=.', NULL, NULL, 146);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '34303', 0), (@q, 'B', '34330', 1), (@q, 'C', '33034', 0), (@q, 'D', '30334', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 4, 'mcq', 'What is the cost of `a.pop(i)` on a list of n items?', NULL, NULL, 'O(n - i): only the items after i have to shift left', 'What moves when you take an item out of the middle?', 'Removing index i shifts the n - i - 1 items after it. So pop() at the end is O(1), pop(0) is O(n), and the middle is in between.', NULL, NULL, 147);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'O(log n)', 0), (@q, 'B', 'O(1) for every i', 0), (@q, 'C', 'O(n - i): only the items after i have to shift left', 1), (@q, 'D', 'O(n) for every i, including the last', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 4, 'true_false', '`list.sort()` on a list that is already sorted runs in O(n), not O(n log n).', NULL, NULL, 'True', 'Timsort looks for runs that are already in order.', 'Timsort detects existing ascending (or strictly descending) runs and merges them, so sorted or nearly sorted data, common with timestamps, sorts in near-linear time.', NULL, NULL, 148);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'code_output', 'What does this print?', 'import sys\na = [0] * 10\nb = []\nfor _ in range(10):\n    b.append(0)\nprint(a == b, sys.getsizeof(a) < sys.getsizeof(b))', 'python', 'True True', 'One list was sized exactly; the other grew step by step.', '[0] * 10 allocates exactly 10 slots. The appended list over-allocated spare capacity (16 slots) while growing. Same contents, different memory.', NULL, NULL, 149);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True', 1), (@q, 'B', 'False True', 0), (@q, 'C', 'False False', 0), (@q, 'D', 'True False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'fill_blank', 'In CPython, a list object stores `ob_size` (the length), `ob_item` (a pointer to the array of item pointers) and its capacity in a field named `____`.', NULL, NULL, 'allocated', 'It counts slots reserved, not slots used.', 'allocated >= ob_size; the gap is the spare room that makes append amortised O(1). sys.getsizeof reflects allocated, not len.', NULL, NULL, 150);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.array([1, 2.5, 3]).dtype, np.array([1, "2"]).dtype)', 'python', 'float64 <U21', 'NumPy picks ONE type that can hold every item.', 'An int and a float upcast to float64. An int and a str upcast to a Unicode string, so 1 becomes ''1'' and maths will fail later. Check dtype after converting a list.', NULL, NULL, 151);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'float64 int64', 0), (@q, 'B', 'float64 <U21', 1), (@q, 'C', 'object object', 0), (@q, 'D', 'int64 <U1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'mcq', 'A PyTorch training loop does `losses.append(loss)` every step, and GPU memory keeps growing. Why?', NULL, NULL, 'Each loss tensor keeps its autograd graph alive; store loss.item() (a plain float) instead', 'What else does a loss tensor hold on to?', 'A loss tensor references the computation graph that produced it, so keeping it keeps the activations too. loss.item() or loss.detach() drops the graph.', NULL, NULL, 152);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'append copies the whole model each time', 0), (@q, 'B', 'Python lists can''t be freed while a loop is running', 0), (@q, 'C', 'Each loss tensor keeps its autograd graph alive; store loss.item() (a plain float) instead', 1), (@q, 'D', 'GPU memory always grows during training; it''s normal', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'code_output', 'What does this print?', 'vals = [0.1] * 10\ntotal = 0.0\nfor v in vals:\n    total += v\nprint(total == 1.0, sum(vals) == 1.0)', 'python', 'False True', 'A plain += loop rounds after every step. Does the built-in do the same (Python 3.12+)?', 'The loop ends at 0.9999999999999999. Since Python 3.12, sum() of floats uses compensated summation, which tracks the lost bits and gives exactly 1.0. Still never compare float totals with ==; use math.isclose.', NULL, NULL, 153);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True', 0), (@q, 'B', 'False True', 1), (@q, 'C', 'False False', 0), (@q, 'D', 'True False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iter-tools'), 4, 'code_output', 'What does this print?', 'it = iter([1, 2, 3, 4])\nprint(list(zip(it, it)))', 'python', '[(1, 2), (3, 4)]', 'Both arguments are the SAME iterator.', 'Each tuple pulls two values from one shared iterator, so items are grouped in pairs. A known chunking idiom (itertools.batched in 3.12 does it more readably).', NULL, NULL, 154);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '[(1, 2), (3, 4)]', 1), (@q, 'C', '[(1, 1), (2, 2), (3, 3), (4, 4)]', 0), (@q, 'D', '[(1, 3), (2, 4)]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-defaults'), 4, 'code_output', 'What does this print?', 'def add(x, acc=[]):\n    acc.append(x)\n    return acc\n\nprint(add(1, []), add(2), add(3, []), add(4))', 'python', '[1] [2, 4] [3] [2, 4]', 'print evaluates all its arguments before printing, and two of them are the same object.', 'Calls that pass a list are fine. add(2) and add(4) both use and return the one default list, so by print time it holds [2, 4], shown twice.', NULL, NULL, 155);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1] [2] [3] [4]', 0), (@q, 'B', '[1] [2] [3] [2, 4]', 0), (@q, 'C', '[1] [1, 2] [3] [3, 4]', 0), (@q, 'D', '[1] [2, 4] [3] [2, 4]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copying'), 1, 'mcq', '`a` is a list of numbers. You want a separate list `b` you can change without touching `a`. Which line?', NULL, NULL, 'b = a.copy()', 'One of these only gives the same list a second name.', 'a.copy() builds a new list with the same items. b = a is just another name for the same list, == compares, and append returns None.', NULL, 'b = a is sharing a link to the same online doc; a.copy() is downloading your own copy.', 156);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'b = a.copy()', 1), (@q, 'B', 'b = a.append()', 0), (@q, 'C', 'b = a', 0), (@q, 'D', 'b == a', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'methods'), 2, 'fill_blank', 'To add every item of `more` to the end of `a` in place, call `a.____(more)`.', NULL, NULL, 'extend', 'append would add `more` as ONE item.', 'a.extend(more) adds each item separately, like a += more. a.append(more) would nest the whole list inside.', NULL, NULL, 157);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 2, 'mcq', 'Which of these is O(1) on a list of n items, no matter how big n is?', NULL, NULL, 'a[-1]', 'Which one can jump straight to a position?', 'Indexing computes the slot''s address directly from the position. The other three may have to look at every item.', ' a[-1]:   start + (n-1) * 8 bytes  -> one jump\n x in a:  [ ? ][ ? ][ ? ] ... [ ? ]  -> check one by one', NULL, 158);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'x in a', 0), (@q, 'B', 'a.count(x)', 0), (@q, 'C', 'a[-1]', 1), (@q, 'D', 'a.index(x)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stack-queue'), 3, 'mcq', 'An editor''s ''undo'' history and a printer''s job queue: which structure suits each?', NULL, NULL, 'Undo: a stack (list append/pop); print jobs: a queue (deque append/popleft)', 'Undo takes back the LAST action; the printer serves the FIRST job sent.', 'Undo is last-in-first-out, a stack. A print queue is first-in-first-out, and deque gives O(1) at the front where list.pop(0) is O(n).', ' stack (LIFO):  push -> [a, b, c] -> pop gives c\n queue (FIFO):  c -> [a, b, c] -> popleft gives a', NULL, 159);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Both: a sorted list', 0), (@q, 'B', 'Undo: a stack (list append/pop); print jobs: a queue (deque append/popleft)', 1), (@q, 'C', 'Undo: a queue; print jobs: a stack', 0), (@q, 'D', 'Both: a stack', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iter-tools'), 3, 'mcq', 'Why prefer `for i, x in enumerate(items):` over `for i in range(len(items)): x = items[i]`?', NULL, NULL, 'It''s clearer and works on any iterable, even generators and files that have no len()', 'Not everything you can loop over can be indexed.', 'enumerate pairs a counter with whatever the loop yields, so it works on file lines, generators and DataLoaders. Indexing needs a sequence with len() and [].', NULL, NULL, 160);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'enumerate makes a copy, so the list is protected', 0), (@q, 'B', 'enumerate is always ten times faster', 0), (@q, 'C', 'range(len(...)) is wrong and skips the last item', 0), (@q, 'D', 'It''s clearer and works on any iterable, even generators and files that have no len()', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'true_false', '`sorted()` accepts any iterable (tuple, set, dict, generator) and always returns a new list.', NULL, NULL, 'True', 'What type does sorted give back for a tuple input?', 'sorted(iterable) collects the items into a new list and sorts it. sorted(d) sorts a dict''s keys; sorted((3, 1)) gives [1, 3], not a tuple.', NULL, NULL, 161);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'Why is a list of 1 million dicts (one per training row) a poor format compared with a DataFrame or NumPy arrays?', NULL, NULL, 'Each row is a separate object that repeats every key, and maths must loop in Python instead of running vectorised', 'Picture the memory layout of each format.', 'Row dicts store the column names a million times and scatter values across memory. Columnar arrays store each column once, side by side, so a mean is a single C loop.', ' list of dicts:  [{a:1, b:2}, {a:3, b:4}, ...]  keys repeated\n columnar:       a: [1, 3, ...]\n                 b: [2, 4, ...]                 one array each', NULL, 162);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Each row is a separate object that repeats every key, and maths must loop in Python instead of running vectorised', 1), (@q, 'B', 'Lists can''t hold more than a million items', 0), (@q, 'C', 'It''s the same; pandas converts it for free with no cost', 0), (@q, 'D', 'Dicts inside lists are read-only', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copying'), 4, 'mcq', 'Why can `copy.deepcopy(trainer_state)` fail or be very slow when the object holds a lock, an open file or large GPU tensors?', NULL, NULL, 'deepcopy recurses into every attribute: some objects can''t be copied (TypeError) and big tensors get fully duplicated', 'deepcopy follows every reference it finds.', 'It copies the entire object graph. Locks and file handles can''t be copied, and tensors are duplicated in full. Copy only the parts you need (e.g. a state_dict).', NULL, NULL, 163);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'deepcopy recurses into every attribute: some objects can''t be copied (TypeError) and big tensors get fully duplicated', 1), (@q, 'B', 'Locks are copied, so both copies deadlock', 0), (@q, 'C', 'deepcopy only copies the first level', 0), (@q, 'D', 'deepcopy refuses objects bigger than 1 MB', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 4, 'true_false', '`x in a` stops at the first match, so finding an item at index 0 costs the same however long the list is.', NULL, NULL, 'True', 'Does `in` keep scanning after a hit?', 'Membership is a linear scan that stops early: the best case is O(1) and the worst (missing item) is O(n). Big-O usually quotes the worst case.', NULL, NULL, 164);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tuples'), 4, 'mcq', 'Inside a hot loop, why is `point = (1, 2, 3)` cheaper than `point = [1, 2, 3]`?', NULL, NULL, 'A tuple of constants is built once at compile time and reused; the list is built fresh on every pass', 'Only one of them can safely be shared, because it never changes.', 'The compiler folds a constant tuple into a single stored object (one LOAD_CONST). A list is mutable, so a new one must be created every time the line runs.', NULL, NULL, 165);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Tuples are stored on the GPU', 0), (@q, 'B', 'Lists are always copied twice', 0), (@q, 'C', 'A tuple of constants is built once at compile time and reused; the list is built fresh on every pass', 1), (@q, 'D', 'There''s no difference; both are constants', 0);
