INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 1, 'mcq', 'What is a dictionary in Python?', NULL, NULL, 'A collection of key -> value pairs where you look values up by key', 'Think of a JSON object.', 'A dict maps keys to values, e.g. {''lr'': 0.01, ''epochs'': 10}. You look things up by key, not by position.', NULL, 'A coat check: you hand over a ticket (the key) and get your coat (the value) back.', 7);
