INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 1, 'code_output', 'What does this print?', 'config = {"lr": 0.01, "epochs": 10}\nconfig["epochs"] = 20\nprint(config)', 'python', '{''lr'': 0.01, ''epochs'': 20}', 'Assigning to a key that already exists...', 'Keys are unique, so assigning to ''epochs'' replaces the old value 10 with 20.', ' before:  "lr" -> 0.01   "epochs" -> 10\n after:   "lr" -> 0.01   "epochs" -> 20   (same key, new value)', NULL, 8);
