INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ordering'), 1, 'true_false', 'In modern Python (3.7+), a dict remembers the order in which keys were inserted.', NULL, NULL, 'True', 'Print a dict after adding keys in some order.', 'Insertion order is a language guarantee since 3.7: looping or printing gives keys in the order you added them.', NULL, NULL, 15);
