INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 2, 'code_output', 'What does this print?', 'from collections import defaultdict\nby_label = defaultdict(list)\nfor x, y in [(1, "cat"), (2, "dog"), (3, "cat")]:\n    by_label[y].append(x)\nprint(dict(by_label))', 'python', '{''cat'': [1, 3], ''dog'': [2]}', 'A missing key gets a fresh empty list automatically.', 'defaultdict(list) calls list() to create [] the first time a label is seen, so append always works.', NULL, NULL, 37);
