INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 2, 'code_output', 'What does this print?', 'a = {1, 2, 3}\nb = {2, 3, 4}\nprint(sorted(a & b), sorted(a - b), sorted(a ^ b))', 'python', '[2, 3] [1] [1, 4]', '& is ''in both'', - is ''in a but not b'', ^ is ''in exactly one''.', 'Intersection {2, 3}, difference {1}, symmetric difference {1, 4}.', '   a          b\n ( 1  ( 2 3 )  4 )\n   ^    ^^^    ^\n  a-b   a&b   b-a      a^b = {1, 4}', 'Two club member lists: & is people in both clubs, - is people only in the first, ^ is people in exactly one.', 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2, 3] [4] [1, 4]', 0), (@q, 'B', '[2, 3] [1, 4] [1]', 0), (@q, 'C', '[1, 2, 3, 4] [1] [4]', 0), (@q, 'D', '[2, 3] [1] [1, 4]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 2, 'code_output', 'What does this print?', 's = {1, 2}\ns.discard(5)\nprint("ok")\ns.remove(5)', 'python', 'ok\nKeyError', 'One of these is the forgiving version.', 'discard ignores a missing item; remove raises KeyError (not ValueError like list.remove).', NULL, NULL, 39);
