INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 3, 'code_output', 'What does this print?', 'd = dict.fromkeys(["a", "b"], [])\nd["a"].append(1)\nprint(d)', 'python', '{''a'': [1], ''b'': [1]}', 'How many lists did fromkeys create?', 'fromkeys uses the SAME value object for every key, so both keys share one list. Use {k: [] for k in keys} instead.', ' "a" --+\n       +--> [ ]  one list, two keys\n "b" --+', 'Handing every employee a pointer to the same shared notebook: a note from one appears for all.', 42);
