INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'get-setdefault'), 3, 'code_output', 'What does this print?', 'def expensive():\n    print("computing")\n    return 0\n\nd = {"k": 5}\nprint(d.get("k", expensive()))', 'python', 'computing\n5', 'Arguments are evaluated before the call happens.', 'Python evaluates expensive() before calling get, even though the key exists. For costly defaults use `d[k] if k in d else expensive()`.', NULL, 'Ordering a backup meal before checking whether your first order has already arrived.', 43);
