INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ordering'), 3, 'code_output', 'What does this print?', 'd = {"a": 1, "b": 2}\ndel d["a"]\nd["a"] = 1\nprint(list(d), d == {"a": 1, "b": 2})', 'python', '[''b'', ''a''] True', 'Deleting forgets the position. Does == care about order?', 'Re-inserting a deleted key puts it at the end. Plain dict equality ignores order, so they''re still equal.', NULL, NULL, 46);
