INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 3, 'code_output', 'What does this print?', 'a = {"x": 1}\nalias = a\na |= {"y": 2}\nprint(alias)', 'python', '{''x'': 1, ''y'': 2}', '|= is the in-place form.', 'a |= other updates a in place (like update), so every alias sees the new key. a = a | other would make a new dict.', NULL, 'Like Object.assign(a, other) in JS, which mutates a, versus {...a, ...other}, which builds a new object.', 53);
