INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 2, 'true_false', 'Sets keep items in insertion order, just like dicts do.', NULL, NULL, 'False', 'Only one of the two got an ordering guarantee in 3.7.', 'Dicts guarantee insertion order; sets don''t guarantee any order. If you need unique items in order, use dict.fromkeys(items).', NULL, NULL, 89);
