INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 2, 'mcq', 'You have sets `train_ids` and `test_ids` of example ids. What does `train_ids & test_ids` being non-empty tell you?', NULL, NULL, 'Some examples are in both splits: data leakage, so test scores will look too good', '& keeps only items found in both sets.', 'The intersection lists ids that appear in both train and test. Any overlap means the model is tested on data it trained on. A one-line leakage check.', NULL, NULL, 93);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The split is perfect', 0), (@q, 'B', 'Nothing; & just merges the sets', 0), (@q, 'C', 'The test set is bigger than the training set', 0), (@q, 'D', 'Some examples are in both splits: data leakage, so test scores will look too good', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 3, 'code_output', 'What does this print?', 'import json\nd = {1: "a"}\nback = json.loads(json.dumps(d))\nprint(back, back == d)', 'python', '{''1'': ''a''} False', 'JSON object keys can only be strings.', 'dumps turns the int key 1 into the string ''1'', and loads keeps it a string, so the round trip changes the dict. A saved id2label read back has ''1'', not 1, as keys.', ' {1: "a"} -dumps-> ''{"1": "a"}'' -loads-> {''1'': ''a''}\n  int key          JSON text           str key', NULL, 94);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''1'': ''a''} False', 1), (@q, 'B', '{1: ''a''} True', 0), (@q, 'C', '{''1'': ''a''} True', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 3, 'code_output', 'What does this print?', 'import json\nprint(json.loads(json.dumps({"shape": (2, 3)})))', 'python', '{''shape'': [2, 3]}', 'JSON has arrays but no tuples.', 'Tuples are written as JSON arrays and come back as lists. Code that later uses the value as a dict key or compares it to a tuple will break.', NULL, NULL, 95);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''shape'': (2, 3)}', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', '{''shape'': ''(2, 3)''}', 0), (@q, 'D', '{''shape'': [2, 3]}', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 3, 'code_output', 'What does this print?', 'import json\njson.dumps({"tags": {"a", "b"}})', 'python', 'TypeError', 'Which Python types have a JSON equivalent?', 'json only knows dict, list, tuple, str, int, float, bool and None. A set raises TypeError: convert it first, e.g. sorted(tags).', NULL, NULL, 96);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', 'ValueError', 0), (@q, 'C', 'Nothing is printed; it works', 0), (@q, 'D', 'TypeError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 3, 'code_output', 'What does this print?', 'import json\njson.loads("{''a'': 1}")', 'python', 'JSONDecodeError', 'JSON is stricter than Python''s dict syntax.', 'JSON requires double quotes. Models often reply with Python-style single-quoted dicts, which json.loads rejects with JSONDecodeError (a subclass of ValueError).', NULL, NULL, 97);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', 'SyntaxError', 0), (@q, 'C', 'JSONDecodeError', 1), (@q, 'D', 'Nothing is printed; it returns {''a'': 1}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 3, 'mcq', 'An LLM is asked to reply in JSON. What is the safest way to turn its reply into a dict?', NULL, NULL, 'json.loads inside try/except json.JSONDecodeError, then check the keys and types you need', 'Model output is untrusted input.', 'Treat the reply like a request body: parse strictly, catch the failure (retry or repair), and validate the shape. eval would run any code the text contains.', NULL, 'Same as validating a POST body in an API handler before touching the database.', 98);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'eval(reply), because it also accepts single quotes', 0), (@q, 'B', 'json.loads inside try/except json.JSONDecodeError, then check the keys and types you need', 1), (@q, 'C', 'Trust it; models always return valid JSON when asked', 0), (@q, 'D', 'reply.split('':'') and build the dict by hand', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 3, 'code_output', 'What does this print?', 'import json\nprint(json.loads(''{"a": 1, "a": 2}''))', 'python', '{''a'': 2}', 'Keys are unique, so one of the two must win.', 'Duplicate keys are accepted and the last one silently wins, the same as in a dict literal. A hand-edited config with a repeated key loses the first value without any error.', NULL, NULL, 99);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'JSONDecodeError', 0), (@q, 'B', '{''a'': 2}', 1), (@q, 'C', '{''a'': [1, 2]}', 0), (@q, 'D', '{''a'': 1}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'code_output', 'What does this print?', 'sd = {"enc.w": 1, "enc.b": 2, "head.w": 3}\nenc = {k.removeprefix("enc."): v for k, v in sd.items() if k.startswith("enc.")}\nprint(enc)', 'python', '{''w'': 1, ''b'': 2}', 'Filter by prefix, then rename the key.', 'This is how you pull one sub-module''s weights out of a PyTorch state_dict, whose keys are dotted names like ''encoder.layer.0.weight''.', NULL, NULL, 100);
