INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'code_output', 'What does this print?', 'def f(lr, **kw):\n    return lr\n\ncfg = {"lr": 0.1}\nprint(f(0.5, **cfg))', 'python', 'TypeError', 'lr arrives once by position and once from the dict.', 'f() got multiple values for argument ''lr'': the same parameter can''t be filled twice. Remove the key from the dict or stop passing it by position.', NULL, NULL, 101);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.5', 0), (@q, 'B', '{''lr'': 0.1}', 0), (@q, 'C', 'TypeError', 1), (@q, 'D', '0.1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'code_output', 'What does this print?', 'logs = [{"loss": 0.5}, {"loss": 0.3, "acc": 0.9}]\nprint(sorted(set().union(*logs)))', 'python', '[''acc'', ''loss'']', 'Iterating a dict yields its keys, and union accepts any iterables.', 'set().union(*logs) collects every key seen across the logs: the full list of metric columns, even when some steps didn''t log some metrics.', NULL, NULL, 102);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '[''loss'', ''acc'']', 0), (@q, 'C', '[''acc'', ''loss'']', 1), (@q, 'D', '[0.3, 0.5, 0.9]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'A tokenizer stores its vocabulary as a list and looks up ids with `vocab.index(token)` for every token in a 1-million-token corpus. What''s the fix?', NULL, NULL, 'Build a dict token -> id once, so each lookup is O(1) instead of a scan', 'list.index scans from the front.', 'Each index() is O(V) for a vocabulary of V words, so the corpus costs O(N x V). A dict turns that into O(N). That''s why real tokenizers keep token -> id dicts.', NULL, NULL, 103);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Call index() with a start argument', 0), (@q, 'B', 'Use a tuple instead of a list', 0), (@q, 'C', 'Build a dict token -> id once, so each lookup is O(1) instead of a scan', 1), (@q, 'D', 'Sort the list so index() is faster', 0);
