INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'get-setdefault'), 3, 'code_output', 'What does this print?', 'd = {"n": 0}\nprint(d.get("n") or 10)', 'python', '10', 'What does `or` do with a falsy value?', 'get returns 0, which is falsy, so `or` falls back to 10. If 0 is a valid setting (like dropout=0), use d.get(''n'', 10) instead.', NULL, NULL, 106);
