INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 3, 'true_false', 'Changing the VALUES of existing keys inside `for k in d:` is safe; only adding or removing keys raises RuntimeError.', NULL, NULL, 'True', 'What does the iterator actually watch?', 'Reassigning d[k] keeps the key set the same, so iteration is fine. Inserting or deleting keys during the loop raises ''dictionary changed size during iteration''.', NULL, NULL, 107);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 3, 'code_output', 'What does this print?', 'd = {"a": 1, "b": 2, "c": 3}\nfor k in list(d):\n    if d[k] < 2:\n        del d[k]\nprint(d)', 'python', '{''b'': 2, ''c'': 3}', 'list(d) takes a snapshot of the keys first.', 'Looping over a list copy of the keys lets you delete from the dict safely. Alternatively build a new dict: {k: v for k, v in d.items() if v >= 2}.', NULL, NULL, 108);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'RuntimeError', 0), (@q, 'B', '{''b'': 2, ''c'': 3}', 1), (@q, 'C', '{''a'': 1}', 0), (@q, 'D', '{''c'': 3}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ordering'), 3, 'fill_blank', 'Get the first key of a dict without building a whole list: `next(____(d))`', NULL, NULL, 'iter', 'Make an iterator, then take one step.', 'iter(d) is an iterator over the keys in insertion order, and next() takes the first. list(d)[0] works too but copies every key.', NULL, NULL, 109);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ordering'), 3, 'code_output', 'What does this print?', 'd = {"a": 1, "b": 2, "c": 3}\nprint(list(reversed(d)), d.popitem())', 'python', '[''c'', ''b'', ''a''] (''c'', 3)', 'Dicts are ordered, so ''reverse order'' means something.', 'Since 3.8 reversed() works on dicts and their views. popitem() also takes from the end (last inserted).', NULL, NULL, 110);
