INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 3, 'code_output', 'What does this print?', 'd = {0.3: "x"}\nprint(d.get(0.1 + 0.2))', 'python', 'None', 'Is 0.1 + 0.2 exactly 0.3?', '0.1 + 0.2 is 0.30000000000000004, a different float, so the key isn''t found. Don''t use computed floats as keys; round them or use ints (e.g. ''lr_1e-3'' strings).', NULL, NULL, 111);
