INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 3, 'code_output', 'What does this print?', 'words = ["a", "bb", "a"]\nprint({w: words.count(w) for w in words})', 'python', '{''a'': 2, ''bb'': 1}', 'Repeated keys collapse.', 'The result is right, but each count() scans the whole list, so this is O(n^2). Counter(words) gives the same counts in one pass.', NULL, NULL, 112);
