INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 3, 'code_output', 'What does this print?', 'print({k: v for k, v in zip("abc", range(3)) if v})', 'python', '{''b'': 1, ''c'': 2}', '`if v` tests truthiness. What is 0?', 'The pair (''a'', 0) is dropped because 0 is falsy. Filtering with `if v` silently removes zero counts or zero scores; write `if v is not None` when 0 is valid.', NULL, NULL, 113);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''a'': 0}', 0), (@q, 'B', '{}', 0), (@q, 'C', '{''b'': 1, ''c'': 2}', 1), (@q, 'D', '{''a'': 0, ''b'': 1, ''c'': 2}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 3, 'code_output', 'What does this print?', 'from collections import ChainMap\ndefaults = {"lr": 0.1, "bs": 32}\ncli = {"lr": 0.01}\ncfg = ChainMap(cli, defaults)\nprint(cfg["lr"], cfg["bs"])', 'python', '0.01 32', 'ChainMap looks through the dicts left to right and stops at the first hit.', 'cli is searched first, so its lr wins; bs is only in defaults. Unlike |, no merged copy is made, so later changes to defaults show through.', ' lookup "lr":  cli {lr: 0.01}  -> found, stop\n lookup "bs":  cli {}  -> miss -> defaults {bs: 32} -> found', 'Like config layers: command-line flags override env vars, which override the defaults file.', 114);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.01 32', 1), (@q, 'B', '0.1 32', 0), (@q, 'C', 'KeyError', 0), (@q, 'D', '0.01 KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 3, 'code_output', 'What does this print?', 'from collections import Counter\nc = Counter(a=1)\nc.update({"a": 5})\nd = {"a": 1}\nd.update({"a": 5})\nprint(c["a"], d["a"])', 'python', '6 5', 'Counter.update has a different meaning from dict.update.', 'Counter.update ADDS counts (1 + 5 = 6); dict.update REPLACES values. Mixing them up double-counts or loses counts in word-frequency code.', NULL, 'Counter.update is adding tally marks; dict.update is erasing the board and writing a new number.', 115);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '5 5', 0), (@q, 'B', '1 5', 0), (@q, 'C', '6 6', 0), (@q, 'D', '6 5', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 3, 'code_output', 'What does this print?', 'from collections import defaultdict\nd = defaultdict(lambda: "<unk>")\nprint(d["xyz"], dict(d))', 'python', '<unk> {''xyz'': ''<unk>''}', 'The factory can be any zero-argument function, and reading still inserts.', 'The lambda supplies ''<unk>'' for the missing key AND stores it. A vocabulary lookup built like this grows with every unknown word it sees.', NULL, NULL, 116);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '<unk> {}', 0), (@q, 'C', '<unk> {''xyz'': ''<unk>''}', 1), (@q, 'D', 'None {}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 3, 'code_output', 'What does this print?', 'from collections import defaultdict\nd = defaultdict([])', 'python', 'TypeError', 'defaultdict wants something it can CALL.', 'The argument must be a callable such as list, int or a lambda, not an instance like []. defaultdict(list) calls list() each time a key is missing.', NULL, NULL, 117);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', 'Nothing is printed; it works', 0), (@q, 'C', 'ValueError', 0), (@q, 'D', 'TypeError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 3, 'code_output', 'What does this print?', 'print({1, 2} <= {1, 2, 3}, {1, 2} < {1, 2}, {1, 2}.isdisjoint({3}))', 'python', 'True False True', '<= is subset, < is proper (strict) subset.', '{1, 2} is inside {1, 2, 3}; a set is not a strict subset of itself; {1, 2} and {3} share nothing. Handy for ''are all required columns present?'' checks.', NULL, NULL, 118);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False False True', 0), (@q, 'B', 'True False True', 1), (@q, 'C', 'True True True', 0), (@q, 'D', 'True False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 3, 'code_output', 'What does this print?', 's = {1, 2}\nfor x in s:\n    s.add(x + 10)', 'python', 'RuntimeError', 'Sets have the same rule as dicts.', 'Adding to a set while looping over it raises ''Set changed size during iteration''. Loop over a copy (for x in list(s)) or collect the new items separately.', NULL, NULL, 119);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'RuntimeError', 1), (@q, 'B', 'TypeError', 0), (@q, 'C', 'Nothing is printed; the loop never ends', 0), (@q, 'D', 'Nothing is printed; s grows to 4 items', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'mcq', 'Why can `if 0.9 in scores.values():` be slow for a dict with a million entries?', NULL, NULL, 'Values aren''t hashed; checking a values view scans every value, O(n)', 'Only one side of a dict has an index.', 'Keys are in the hash table; values are just stored. `in d.values()` is a linear scan. If you search by value often, keep a reverse dict.', NULL, NULL, 120);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It''s fast; values() is hashed like keys()', 0), (@q, 'B', 'Values aren''t hashed; checking a values view scans every value, O(n)', 1), (@q, 'C', 'Floats can''t be compared with in', 0), (@q, 'D', 'values() copies the dict first', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 3, 'mcq', 'Why must two objects that compare equal (`a == b`) also have equal hashes?', NULL, NULL, 'A lookup uses the hash to pick the slot; if equal keys hashed differently, d[b] would look in the wrong place and miss a', 'Which step happens first in a lookup: hash or ==?', 'The hash chooses where to look; == only confirms inside that spot. That''s why 1, 1.0 and True all hash to 1, and why __eq__ without a matching __hash__ is disabled.', NULL, NULL, 121);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Python checks hashes instead of == to save time, so == is never called', 0), (@q, 'B', 'Otherwise the dict would keep its keys sorted wrongly', 0), (@q, 'C', 'A lookup uses the hash to pick the slot; if equal keys hashed differently, d[b] would look in the wrong place and miss a', 1), (@q, 'D', 'It''s a style rule with no effect on dicts', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 4, 'code_output', 'What does this print?', 'from collections import defaultdict\ntree = lambda: defaultdict(tree)\nt = tree()\nt["a"]["b"]["c"] = 1\nprint(t["a"]["b"]["c"], len(t), "x" in t)', 'python', '1 1 False', 'Each missing key creates another tree.', 'The factory returns a new defaultdict of the same kind, so any depth of nesting is created on demand (''autovivification''). `in` doesn''t trigger the factory.', NULL, NULL, 122);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 1 True', 0), (@q, 'B', '1 1 False', 1), (@q, 'C', '1 3 False', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 4, 'code_output', 'What does this print?', 'd = {"a": 1}\nd |= [("b", 2)]\nprint(d)\nprint({"a": 1} | [("b", 2)])', 'python', '{''a'': 1, ''b'': 2}\nTypeError', '|= behaves like update; | wants two dicts.', 'd |= accepts anything update accepts, including a list of pairs. d | other requires other to be a dict. The same split as list += (any iterable) vs + (lists only).', NULL, NULL, 123);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''a'': 1}\nTypeError', 0), (@q, 'B', '{''a'': 1, ''b'': 2}\nTypeError', 1), (@q, 'C', 'TypeError', 0), (@q, 'D', '{''a'': 1, ''b'': 2}\n{''a'': 1, ''b'': 2}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 4, 'code_output', 'What does this print?', 'import json\nprint(json.dumps({"loss": float("nan")}))', 'python', '{"loss": NaN}', 'Python''s json module is lenient by default.', 'It writes NaN, which is NOT valid JSON: a JavaScript dashboard''s JSON.parse will reject the whole payload. Pass allow_nan=False to fail early, or replace NaN with None.', NULL, NULL, 124);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', '{"loss": NaN}', 1), (@q, 'C', '{"loss": null}', 0), (@q, 'D', '{"loss": "nan"}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 4, 'code_output', 'What does this print?', 'import json\ns = json.dumps({1: "a", "1": "b"})\nprint(s, json.loads(s))', 'python', '{"1": "a", "1": "b"} {''1'': ''b''}', '1 and ''1'' are different dict keys but the same JSON key.', 'dumps converts the int key to ''1'' and writes duplicate keys without complaint; loads keeps the last. Mixed int/str keys silently lose data on a JSON round trip.', NULL, NULL, 125);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{"1": "a", "1": "b"} {1: ''a'', ''1'': ''b''}', 0), (@q, 'B', '{"1": "b"} {''1'': ''b''}', 0), (@q, 'C', '{"1": "a", "1": "b"} {''1'': ''b''}', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'get-setdefault'), 4, 'mcq', 'In a hot loop over millions of rows, what does `groups.setdefault(key, []).append(row)` waste compared with `defaultdict(list)`?', NULL, NULL, 'It builds a new empty list on every call, even when the key already exists', 'Arguments are evaluated before the method runs.', 'The [] default is created (and then thrown away) on every call. defaultdict only calls list() for a genuinely missing key, so it''s faster and clearer for grouping.', NULL, NULL, 126);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It copies the existing list before appending', 0), (@q, 'B', 'It builds a new empty list on every call, even when the key already exists', 1), (@q, 'C', 'Nothing; they compile to the same code', 0), (@q, 'D', 'It rehashes the whole dict on every call', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 4, 'code_output', 'What does this print?', 'd = {"x": 1}\nprint(d.values() == d.values(), d.keys() == {"x"}, sorted(d.items() & {("x", 1)}))', 'python', 'False True [(''x'', 1)]', 'keys() and items() act like sets; values() doesn''t.', 'Values may be unhashable and repeated, so values views have no set behaviour and == falls back to identity: two separate views are never equal. Compare list(d.values()) instead.', NULL, NULL, 127);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True [(''x'', 1)]', 0), (@q, 'B', 'False False []', 0), (@q, 'C', 'True False [(''x'', 1)]', 0), (@q, 'D', 'False True [(''x'', 1)]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 4, 'code_output', 'What does this print?', 'd = {"a": 1}\nfor k in d:\n    del d[k]\n    d["b"] = 2', 'python', 'RuntimeError', 'The size stayed at 1. Does Python still notice?', 'Python 3.8+ also tracks key changes, raising ''dictionary keys changed during iteration''. Deleting one key and adding another doesn''t fool it.', NULL, NULL, 128);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Nothing is printed; d is {''b'': 2}', 0), (@q, 'B', 'RuntimeError', 1), (@q, 'C', 'KeyError', 0), (@q, 'D', 'The loop never ends', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ordering'), 4, 'code_output', 'What does this print?', 'from collections import OrderedDict\ncache = OrderedDict()\nfor k in ["a", "b", "c"]:\n    cache[k] = 1\ncache.move_to_end("a")\ncache.popitem(last=False)\nprint(list(cache))', 'python', '[''c'', ''a'']', 'move_to_end marks ''a'' as recently used; popitem(last=False) evicts from the front.', 'After the move the order is b, c, a; evicting the oldest removes b. That''s an LRU cache in a few lines, a classic interview question.', ' insert:       [a, b, c]\n move_to_end:  [b, c, a]     (a = most recent)\n evict front:  [c, a]        (b was least recent)', 'Like a browser cache: whatever you used last moves to the ''fresh'' end, and the stalest entry is evicted first.', 129);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''b'', ''c'', ''a'']', 0), (@q, 'B', '[''a'', ''b'']', 0), (@q, 'C', '[''b'', ''c'']', 0), (@q, 'D', '[''c'', ''a'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 4, 'code_output', 'What does this print?', 'from dataclasses import dataclass\n\n@dataclass(frozen=True)\nclass K:\n    x: int\n\n@dataclass\nclass M:\n    x: int\n\nprint({K(1): "a"}[K(1)])\nhash(M(1))', 'python', 'a\nTypeError', 'A dataclass with eq=True (the default) must decide what to do about __hash__.', 'frozen=True makes instances immutable and generates __hash__ from the fields, so they work as keys. A plain dataclass defines __eq__, so __hash__ is set to None: unhashable.', NULL, NULL, 130);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'a\nTypeError', 1), (@q, 'B', 'a\na', 0), (@q, 'C', 'KeyError', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hashability'), 4, 'true_false', 'A frozen dataclass is hashable even if one of its fields holds a list.', NULL, NULL, 'False', 'The generated __hash__ hashes a tuple of the field values.', 'hash() of the instance hashes (field1, field2, ...), and a list inside raises TypeError at that moment. frozen only blocks reassigning fields; it doesn''t make the values themselves immutable.', NULL, NULL, 131);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 4, 'code_output', 'What does this print?', 'fns = {k: (lambda: k) for k in "ab"}\nprint(fns["a"]())', 'python', 'b', 'When does the lambda look up k: when it''s made, or when it''s called?', 'Closures capture the variable, not its value. By the time fns[''a'']() runs, the loop has finished and k is ''b''. Bind it early with lambda k=k: k.', NULL, 'The same bug as JS closures created in a `var` loop, which all see the final i.', 132);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', 'k', 0), (@q, 'C', 'a', 0), (@q, 'D', 'b', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comprehensions'), 4, 'code_output', 'What does this print?', 'i = iter(range(4))\nprint({next(i): next(i) for _ in range(2)})', 'python', '{0: 1, 2: 3}', 'In a dict comprehension, is the key or the value evaluated first?', 'Since Python 3.8 the key is evaluated before the value (matching dict literals), so each step pulls key then value: {0: 1, 2: 3}.', NULL, NULL, 133);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{1: 0, 3: 2}', 0), (@q, 'B', 'StopIteration', 0), (@q, 'C', '{0: 0, 2: 2}', 0), (@q, 'D', '{0: 1, 2: 3}', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 4, 'code_output', 'What does this print?', 'from collections import Counter\nc = Counter(a=2, b=1)\nc.subtract(Counter(a=3))\nprint(c["a"], +c)', 'python', '-1 Counter({''b'': 1})', 'subtract keeps negatives; unary + keeps only positives.', 'subtract() works in place and allows negative counts (a = -1). +c returns a new Counter with zero and negative counts removed.', NULL, NULL, 134);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '-1 Counter({''b'': 1})', 1), (@q, 'C', '-1 Counter({''a'': -1, ''b'': 1})', 0), (@q, 'D', '0 Counter({''b'': 1})', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'collections'), 4, 'fill_blank', 'Since Python 3.10, `Counter("aab").____()` returns 3, the sum of all the counts.', NULL, NULL, 'total', 'It''s an adjective meaning ''whole sum''.', 'total() adds up all counts. Before 3.10 you wrote sum(c.values()). Handy for turning counts into frequencies: c[w] / c.total().', NULL, NULL, 135);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 4, 'code_output', 'What does this print?', 's = {frozenset({1, 2})}\nprint({1, 2} in s)', 'python', 'True', 'A plain set is unhashable, so how can `in` work?', 'set.__contains__ has a special case: if the probe is an unhashable set, it retries with a temporary frozenset of it. A dict lookup with a set key would still raise TypeError.', NULL, NULL, 136);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'KeyError', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'true_false', 'Deleting most of the keys from a huge dict immediately shrinks the memory it uses.', NULL, NULL, 'False', 'Deleted slots are marked, not compacted.', 'CPython leaves ''dummy'' markers and doesn''t shrink on delete; the table only resizes during later inserts. To reclaim memory from a big filtered dict, build a new one.', NULL, NULL, 137);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'mcq', 'Why do 100,000 instances of the same class use less memory for their attribute dicts than 100,000 separate plain dicts would?', NULL, NULL, 'Instance __dict__s share one keys table (key-sharing dicts) and store only their own values', 'All instances usually have the same attribute names.', 'PEP 412 key-sharing dicts let instances of a class share the key/hash part and keep only values per object. __slots__ goes further by removing the dict.', NULL, NULL, 138);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Instances store attributes in a list instead of a dict', 0), (@q, 'B', 'They don''t; each instance dict is a full copy', 0), (@q, 'C', 'Python compresses dicts of the same size', 0), (@q, 'D', 'Instance __dict__s share one keys table (key-sharing dicts) and store only their own values', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'internals'), 4, 'code_output', 'What does this print?', 'class E:\n    def __eq__(self, o):\n        print("eq called")\n        return True\n    def __hash__(self):\n        return 1\n\nk = E()\nd = {k: "v"}\nprint(d[k])\nprint(d[E()])', 'python', 'v\neq called\nv', 'Python checks identity before calling __eq__.', 'Looking up the very same object short-circuits on `is`, so __eq__ never runs. A different object with the same hash needs __eq__ to confirm.', ' d[key]:  hash(key) -> slot\n          stored is key?  -- yes --> found (no __eq__)\n                |no\n          stored == key?  -- yes --> found', NULL, 139);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'eq called\nv\neq called\nv', 0), (@q, 'B', 'v\nv', 0), (@q, 'C', 'v\neq called\nv', 1), (@q, 'D', 'v\nKeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'mcq', 'Loading a checkpoint fails with: Missing keys ''fc.weight'' ... Unexpected keys ''module.fc.weight''. What''s the usual fix?', NULL, NULL, 'Strip the ''module.'' prefix from every key with a dict comprehension before load_state_dict', 'Compare the two key names character by character.', 'Models saved while wrapped in DataParallel/DDP get ''module.'' in every key. {k.removeprefix(''module.''): v for k, v in sd.items()} makes the names match.', NULL, NULL, 140);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Call load_state_dict twice', 0), (@q, 'B', 'Convert the state_dict to a list', 0), (@q, 'C', 'Strip the ''module.'' prefix from every key with a dict comprehension before load_state_dict', 1), (@q, 'D', 'Retrain the model from scratch', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'code_output', 'What does this print?', 'cfg = {"lr": 0.1, "bs": 32}\nresults = {tuple(sorted(cfg.items())): 0.91}\nsame = {"bs": 32, "lr": 0.1}\nprint(results[tuple(sorted(same.items()))])', 'python', '0.91', 'A dict can''t be a key, but a sorted tuple of its items can.', 'Sorting the items makes the key independent of insertion order, and the tuple is hashable. That''s how you cache experiment results per hyperparameter setting.', NULL, NULL, 141);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None', 0), (@q, 'B', 'KeyError', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', '0.91', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'code_output', 'What does this print?', 'import json\nimport numpy as np\nprint(json.dumps({"a": np.float64(0.5)}))\njson.dumps({"b": np.float32(0.5)})', 'python', '{"a": 0.5}\nTypeError', 'One NumPy float type is a subclass of Python''s float.', 'np.float64 subclasses float, so json accepts it; np.float32 doesn''t, giving ''Object of type float32 is not JSON serializable''. Convert metrics with float(x) before logging.', NULL, NULL, 142);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '{"a": np.float64(0.5)}\nTypeError', 0), (@q, 'C', '{"a": 0.5}\n{"b": 0.5}', 0), (@q, 'D', '{"a": 0.5}\nTypeError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'crud'), 1, 'mcq', 'Which line creates an empty dictionary?', NULL, NULL, 'd = {}', 'Curly braces are for dicts (and, with items, sets).', '{} is an empty dict, [] an empty list, () an empty tuple and set() an empty set. In ML code you''d start a metrics log like this: metrics = {}.', NULL, NULL, 143);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'd = []', 0), (@q, 'B', 'd = {}', 1), (@q, 'C', 'd = ()', 0), (@q, 'D', 'd = set()', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 1, 'true_false', 'A tokenizer''s vocabulary, which maps each token to a number, is naturally stored as a dict.', NULL, NULL, 'True', 'You look up a token and want its id back fast.', 'token -> id is a key -> value lookup, and dicts do it in O(1). Tokenizers keep this dict plus the reverse (id -> token) to decode.', ' "the"  -> 1\n "cat"  -> 2      "the cat" -> [1, 2]\n "<unk>"-> 0      (unknown words)', NULL, 144);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'get-setdefault'), 2, 'mcq', 'When is `d[k]` a better choice than `d.get(k)`?', NULL, NULL, 'When the key must exist: a KeyError points straight at the bug instead of a None leaking further', 'Failing loudly is sometimes the point.', 'get hides a missing required key behind None, and the crash shows up later somewhere unrelated. Use d[k] for required fields and get for truly optional ones.', NULL, 'Like a required field in an API schema: reject the request at once rather than storing a null and failing in a report a week later.', 145);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'When the dict is empty', 0), (@q, 'B', 'Never; get is always safer', 0), (@q, 'C', 'When the key is a string', 0), (@q, 'D', 'When the key must exist: a KeyError points straight at the bug instead of a None leaking further', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 2, 'mcq', 'What''s the difference between `json.load` and `json.loads`?', NULL, NULL, 'load reads from an open file object; loads parses a string', 'The s stands for ''string''.', 'json.load(f) reads JSON from a file object; json.loads(text) parses text you already have (e.g. an HTTP response body). The same pair exists for writing: dump and dumps.', NULL, NULL, 146);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'loads loads several files at once', 0), (@q, 'B', 'There''s no difference', 0), (@q, 'C', 'load reads from an open file object; loads parses a string', 1), (@q, 'D', 'load is the older, slower version', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'json-nested'), 2, 'fill_blank', 'To write readable, indented JSON, call `json.dumps(cfg, ____=2)`.', NULL, NULL, 'indent', 'The keyword describes how far each level is pushed in.', 'indent=2 puts each key on its own line with two spaces per level, the usual format for config files you commit to git.', NULL, NULL, 147);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'complexity'), 3, 'mcq', 'What is the average cost of building a dict from n (key, value) pairs?', NULL, NULL, 'O(n): each insert is O(1) on average, including occasional resizes', 'Add up n average-O(1) inserts.', 'Each insert hashes the key and drops it in a slot. Resizes double the table, so their cost spreads out (amortised), just like list appends.', NULL, NULL, 148);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'O(1): dicts are built lazily', 0), (@q, 'B', 'O(n^2): each insert scans the earlier keys', 0), (@q, 'C', 'O(n): each insert is O(1) on average, including occasional resizes', 1), (@q, 'D', 'O(n log n): keys are kept sorted', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merging'), 3, 'true_false', '`{**a, **b}` works in Python 3.5+, while `a | b` needs Python 3.9 or newer.', NULL, NULL, 'True', 'The | operator for dicts was added by PEP 584.', 'Unpacking in dict literals came first (PEP 448, 3.5); the merge operators | and |= arrived in 3.9. Older servers and Colab images may still matter.', NULL, NULL, 149);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sets'), 3, 'mcq', 'Which set expression gives the tokens that appear in the test set but never in training (out-of-vocabulary tokens)?', NULL, NULL, 'test_tokens - train_tokens', 'In test, and not in train.', 'a - b keeps what''s in a but not in b. A high OOV rate warns you that the model will see many words it never learned.', '   train         test\n (  ....  ( both )  OOV )\n                    ^^^\n          test_tokens - train_tokens', NULL, 150);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'train_tokens - test_tokens', 0), (@q, 'B', 'test_tokens & train_tokens', 0), (@q, 'C', 'test_tokens - train_tokens', 1), (@q, 'D', 'test_tokens | train_tokens', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'mcq', 'Why do larger projects move configs from plain dicts to dataclasses or pydantic models?', NULL, NULL, 'A typo like cfg[''lerning_rate''] fails late or silently; typed fields catch wrong names and types at load time', 'What happens when you misspell a dict key?', 'A dict accepts any key, so a typo creates a new key (on write) or a KeyError deep inside training (on read). A schema validates names, types and ranges once, up front.', NULL, 'Like moving from untyped JS objects to TypeScript interfaces.', 151);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Dict lookups are too slow for configs', 0), (@q, 'B', 'Dataclasses use less memory than any dict', 0), (@q, 'C', 'A typo like cfg[''lerning_rate''] fails late or silently; typed fields catch wrong names and types at load time', 1), (@q, 'D', 'Dicts can''t be saved to JSON', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'iteration'), 4, 'true_false', 'In Python 3, `for k, v in d.items():` first copies every pair into a new list, as Python 2 did.', NULL, NULL, 'False', 'What does items() return in Python 3?', 'items() returns a view, a lightweight window over the dict, with no copy. That''s why it''s cheap, and also why changing the dict''s size during the loop is an error.', NULL, NULL, 152);
