INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ternary'), 2, 'code_output', 'What does this print?', 'n = 1\nprint(f"{n} item{"s" if n != 1 else ""}")', 'python', '1 item', 'When n is 1, which string is chosen?', 'n != 1 is False, so the empty string is added: ''1 item''. Python 3.12+ allows the same quote type inside an f-string.', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 item', 1), (@q, 'B', 'SyntaxError', 0), (@q, 'C', '1 items', 0), (@q, 'D', '1 item{}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'match-case'), 2, 'code_output', 'What does this print?', 'def describe(code):\n    match code:\n        case 200:\n            return "OK"\n        case 404:\n            return "Not Found"\n        case _:\n            return "Other"\n\nprint(describe(404), describe(500))', 'python', 'Not Found Other', '_ is the catch-all case.', 'match compares the value against each case top to bottom. 404 matches the second; 500 matches nothing specific, so `case _` runs.', NULL, 'Like a JS switch, but no fall-through and no break needed: only the first matching case runs.', 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'OK Other', 0), (@q, 'B', 'Not Found Not Found', 0), (@q, 'C', 'Other Other', 0), (@q, 'D', 'Not Found Other', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'match-case'), 2, 'code_output', 'What does this print?', 'def kind(day):\n    match day:\n        case "sat" | "sun":\n            return "weekend"\n        case _:\n            return "weekday"\n\nprint(kind("sun"), kind("mon"))', 'python', 'weekend weekday', '| inside a case means ''or''.', 'case ''sat'' | ''sun'' matches either string. ''mon'' falls to the wildcard.', NULL, NULL, 33);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'weekend weekend', 0), (@q, 'B', 'weekday weekday', 0), (@q, 'C', 'SyntaxError', 0), (@q, 'D', 'weekend weekday', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'precedence'), 2, 'code_output', 'What does this print?', 'print(not 1 == 2)', 'python', 'True', 'Which runs first: == or not?', '== binds tighter than not, so this is not (1 == 2) -> not False -> True.', NULL, NULL, 34);
