INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'if-structure'), 2, 'code_output', 'What does this print?', 'score = 95\nif score >= 50:\n    grade = "pass"\nelif score >= 90:\n    grade = "distinction"\nprint(grade)', 'python', 'pass', 'The order of the branches matters.', '95 >= 50 is checked first and is True, so the ''distinction'' branch can never run. Put the strictest condition first.', ' 95 >= 50 ? yes -> "pass"  (stop)\n 95 >= 90 ?  never reached\n fix: test >= 90 first, then >= 50', NULL, 38);
