INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'comparisons'), 3, 'code_output', 'What does this print?', 'print([1, 2, 3] < [1, 3], (1, 2) < (1, 2, 0))', 'python', 'True True', 'Sequences compare item by item, left to right, like words in a dictionary.', '[1, 2, 3] vs [1, 3]: first items tie, then 2 < 3, so True. (1, 2) is a prefix of (1, 2, 0), and the shorter one is smaller.', ' [1, 2, 3]\n [1, 3]\n  =  2<3  -> decided: True (rest ignored)', NULL, 41);
