INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'truthiness'), 3, 'code_output', 'What does this print?', 'batch_size = 0\nbs = batch_size or 32\nprint(bs)', 'python', '32', 'Is 0 truthy?', '`or` treats 0 as falsy and falls back to 32, even though 0 was a real value. If only None should fall back, write `32 if batch_size is None else batch_size`.', ' batch_size = 0  -> falsy -> or picks 32   (wrong!)\n batch_size = None -> falsy -> or picks 32 (intended)', 'A form that treats ''number of children: 0'' as ''field left blank'' and fills in a default.', 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0', 0), (@q, 'B', 'True', 0), (@q, 'C', '32', 1), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'truthiness'), 3, 'code_output', 'What does this print?', 'import numpy as np\nmask = np.array([True, False])\nif mask:\n    print("yes")', 'python', 'ValueError', 'Is a two-element array True or False as a whole?', 'NumPy refuses to guess: ''The truth value of an array with more than one element is ambiguous''. Use mask.any() or mask.all().', ' mask = [True, False]\n any()?  True     all()?  False\n if mask: ?  -> ambiguous -> ValueError', 'Asking ''is this class tall?'': every student, any student, or the average? NumPy makes you say which.', 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'yes', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', 'Nothing is printed', 0), (@q, 'D', 'ValueError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'logic-ops'), 3, 'code_output', 'What does this print?', 'def check():\n    print("called")\n    return True\n\nresult = False and check()\nprint(result)', 'python', 'False', 'If the left side of `and` is False, is the right side needed?', 'and short-circuits: False and anything is False, so check() is never called.', NULL, 'A security gate that stops at the first failed check and never runs the rest.', 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'called\nFalse', 0), (@q, 'B', 'False', 1), (@q, 'C', 'None', 0), (@q, 'D', 'called\nTrue', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'logic-ops'), 3, 'code_output', 'What does this print?', 'user = None\nname = user and user["name"]\nprint(name)', 'python', 'None', '`and` returns the first falsy operand.', 'user is None (falsy), so `and` returns None without evaluating user[''name'']. That''s why `x and x.attr` works as a guard.', NULL, 'The same idea as JS user && user.name (or user?.name).', 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None', 1), (@q, 'B', 'False', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', 'KeyError', 0);
