INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'if-structure'), 2, 'code_output', 'What does this print?', 'age, has_id = 20, False\nif age >= 18:\n    if has_id:\n        print("enter")\n    else:\n        print("show id")\nelse:\n    print("too young")', 'python', 'show id', 'Follow the outer if first, then the inner one.', 'age >= 18 is True, so we go inside; has_id is False, so the inner else runs. Each else belongs to the if at the same indentation.', NULL, NULL, 93);
