INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'identity'), 2, 'true_false', '`x is not None` and `not x is None` give the same result, but `is not` is the preferred style.', NULL, NULL, 'True', '`is` binds tighter than `not`.', 'not x is None parses as not (x is None), so both agree. PEP 8 recommends `is not` because it reads as one operator and can''t be misread.', NULL, NULL, 94);
