INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'code_output', 'What does this print?', 'labels = [1, 0, 1]\npreds = [1, 1, 1]\nacc = sum(p == y for p, y in zip(preds, labels)) / len(labels)\nprint(round(acc, 2))', 'python', '0.67', 'Each comparison is True (1) or False (0).', 'Two of the three predictions match, so the sum is 2 and accuracy is 2/3, about 0.67. Comparisons that sum to counts are behind most metric code.', NULL, NULL, 95);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.33', 0), (@q, 'B', '2', 0), (@q, 'C', '1.0', 0), (@q, 'D', '0.67', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'code_output', 'What does this print?', 'accs = [0.70, 0.75, 0.74, 0.73]\npatience, bad = 2, 0\nbest = accs[0]\nfor a in accs[1:]:\n    if a > best:\n        best, bad = a, 0\n    else:\n        bad += 1\n    if bad >= patience:\n        print("stop at", a)\n        break', 'python', 'stop at 0.73', 'Count epochs without improvement; reset on improvement.', '0.75 improves (bad = 0); 0.74 and 0.73 don''t (bad = 1, then 2), so the loop stops at 0.73. This is early stopping with patience = 2.', ' acc:   0.70  0.75  0.74  0.73\n best:  0.70  0.75  0.75  0.75\n bad:    -     0     1     2   -> 2 >= patience: stop', NULL, 96);
