INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'match-case'), 3, 'code_output', 'What does this print?', 'def kind(v):\n    match v:\n        case bool():\n            return "bool"\n        case int() | float():\n            return "number"\n        case str():\n            return "text"\n        case _:\n            return "other"\n\nprint(kind(True), kind(3.5), kind(None))', 'python', 'bool number other', 'Class patterns use isinstance, and order matters.', 'bool() is checked first, so True is ''bool'' (otherwise it would match int()). 3.5 matches float(); None matches nothing until _.', NULL, NULL, 110);
