INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'for-basics'), 1, 'mcq', 'In `for item in basket:`, what is `item`?', NULL, NULL, 'A name that holds the current element on each pass', 'It changes every time round the loop.', 'The loop variable is just a name. On each pass Python binds it to the next element of basket.', NULL, 'Like `for (const item of basket)` in JavaScript.', 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The index of the element', 0), (@q, 'B', 'The whole list', 0), (@q, 'C', 'A keyword Python reserves', 0), (@q, 'D', 'A name that holds the current element on each pass', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'for-basics'), 1, 'mcq', 'How does Python know which lines are inside the loop body?', NULL, NULL, 'By indentation (the lines indented under the for line)', 'Python has no braces for blocks.', 'The body is every line indented under `for ...:`. The first line back at the outer indentation is after the loop.', NULL, NULL, 9);
