INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'range'), 1, 'fill_blank', 'To loop exactly 4 times with i = 0, 1, 2, 3, write `for i in ____:`', NULL, NULL, 'range(4)', 'One argument: how many numbers, starting from 0.', 'range(4) gives 0, 1, 2, 3: four numbers, starting at 0.', NULL, NULL, 12);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'while'), 1, 'mcq', 'What is the key difference between `for` and `while`?', NULL, NULL, 'for walks through a collection; while repeats as long as a condition is True', 'One is driven by items, the other by a yes/no test.', 'Use for when you have things to go through; use while when you repeat until some condition changes.', NULL, NULL, 13);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'for walks through a collection; while repeats as long as a condition is True', 1), (@q, 'B', 'while can only run once', 0), (@q, 'C', 'while is faster than for', 0), (@q, 'D', 'for can only loop over numbers', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'while'), 1, 'code_output', 'What does this print?', 'count = 0\nwhile count < 3:\n    count += 1\nprint(count)', 'python', '3', 'The check happens before each pass.', 'count goes 1, 2, 3; then 3 < 3 is False and the loop stops. count is 3.', NULL, NULL, 14);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0', 0), (@q, 'B', '4', 0), (@q, 'C', '3', 1), (@q, 'D', '2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'while'), 1, 'true_false', 'If the condition of a while loop is never made False, the loop runs forever.', NULL, NULL, 'True', 'What would stop it?', 'A while loop only stops when its condition is False (or on break). Forgetting `n -= 1` is the classic infinite loop.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'break-continue'), 1, 'code_output', 'What does this print?', 'for i in range(5):\n    if i == 2:\n        continue\n    print(i)', 'python', '0\n1\n3\n4', 'continue skips the rest of THIS pass only.', 'When i is 2, continue jumps straight to the next pass, so 2 is never printed. The loop carries on.', NULL, NULL, 16);
