INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'while'), 2, 'code_output', 'What does this print?', 'n = 0\nwhile True:\n    n += 2\n    if n > 5:\n        break\nprint(n)', 'python', '6', 'while True only stops on break.', 'n goes 2, 4, 6. At 6 the test n > 5 is True, so break exits with n = 6.', NULL, NULL, 29);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '6', 1), (@q, 'B', 'Runs forever', 0), (@q, 'C', '4', 0), (@q, 'D', '5', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'while'), 2, 'code_output', 'What does this print?', 'queue = [3, 1, 2]\nwhile queue:\n    print(queue.pop())', 'python', '2\n1\n3', 'An empty list is falsy; pop() takes from the end.', 'pop() removes the LAST item each time: 2, 1, 3. When the list is empty, `while queue` is False.', NULL, NULL, 30);
