INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'break-continue'), 2, 'code_output', 'What does this print?', 'total = 0\nfor n in range(1, 8):\n    if n % 2 == 0:\n        continue\n    if n > 5:\n        break\n    total += n\nprint(total)', 'python', '9', 'Even numbers are skipped; the loop ends at the first odd number above 5.', 'Odd values reached: 1, 3, 5 are added (total 9). At 7, n > 5 triggers break before adding.', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '16', 0), (@q, 'B', '4', 0), (@q, 'C', '12', 0), (@q, 'D', '9', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loop-else'), 2, 'code_output', 'What does this print?', 'for n in [3, 5, 7]:\n    if n % 2 == 0:\n        print("found even")\n        break\nelse:\n    print("no even")', 'python', 'no even', 'The loop''s else runs when the loop finishes WITHOUT break.', 'No even number, so break never runs. The loop ends normally and the else block runs.', NULL, NULL, 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'found even', 0), (@q, 'B', 'found even\nno even', 0), (@q, 'C', 'no even', 1), (@q, 'D', 'Nothing is printed', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loop-else'), 2, 'code_output', 'What does this print?', 'for n in [3, 4, 7]:\n    if n % 2 == 0:\n        print("found", n)\n        break\nelse:\n    print("no even")', 'python', 'found 4', 'What happens to the else when break fires?', 'break exits at 4, and a loop that ended by break skips its else.', NULL, NULL, 33);
