INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'enumerate-zip'), 2, 'mcq', 'Which loop is the most Pythonic way to get both the index and the value of `items`?', NULL, NULL, 'for i, x in enumerate(items):', 'There''s a built-in made for exactly this.', 'enumerate is clear and fast. items.index(x) is slow and wrong with duplicates; `for i, x in items` tries to unpack each item.', NULL, NULL, 35);
