INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'while'), 3, 'mcq', '`x = 0.0` then `while x != 1.0: x += 0.1`. What happens?', NULL, NULL, 'It loops forever, because 0.1 added ten times is not exactly 1.0', 'Try 0.1 + 0.2 == 0.3 in your head.', 'Floats can''t represent 0.1 exactly; after ten additions x is 0.9999999999999999, then jumps past 1.0. Use `while x < 1.0` or loop over a count.', NULL, NULL, 49);
