INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'recursion'), 1, 'code_output', 'What does this print?', 'def fact(n):\n    if n == 1:\n        return 1\n    return n * fact(n - 1)\n\nprint(fact(4))', 'python', '24', 'fact(4) = 4 * fact(3) = ...', '4 * 3 * 2 * 1 = 24. `if n == 1` is the base case that stops the recursion.', NULL, NULL, 20);
