INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-default'), 2, 'code_output', 'What does this print?', 'def add_item(item, basket=[]):\n    basket.append(item)\n    return basket\n\nadd_item("apple")\nprint(add_item("pear"))', 'python', '[''apple'', ''pear'']', 'When is the default list created?', 'The [] default is created once, when def runs, and shared by every call. The second call sees the apple from the first.', ' def time:  basket -> [ ]  (one list object)\n call 1:    [ ''apple'' ]\n call 2:    [ ''apple'', ''pear'' ]  <- same list', NULL, 31);
