INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'closures'), 2, 'code_output', 'What does this print?', 'def make_multiplier(k):\n    def mul(x):\n        return x * k\n    return mul\n\ntriple = make_multiplier(3)\nprint(triple(5))', 'python', '15', 'mul remembers k even after make_multiplier has returned.', 'That memory is a closure: the inner function keeps a reference to k = 3.', NULL, 'A factory that bakes a setting into the function it returns, like a configured middleware.', 33);
