INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'args-kwargs'), 3, 'code_output', 'What does this print?', 'def f(**kw):\n    return kw\n\nprint(f(**{"a": 1}, a=2))', 'python', 'TypeError', 'Two keyword arguments with the same name in one call.', 'Unpacking {''a'': 1} and also passing a=2 gives ''got multiple values for keyword argument a''. Use {**d, ''a'': 2} to merge dicts instead.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{''a'': 2}', 0), (@q, 'B', 'TypeError', 1), (@q, 'C', '{''a'': 1}', 0), (@q, 'D', '{''a'': [1, 2]}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'param-kinds'), 3, 'code_output', 'What does this print?', 'def scale(x, /, factor):\n    return x * factor\n\nprint(scale(x=2, factor=3))', 'python', 'TypeError', 'What does the / in the parameter list do?', 'Parameters before / are positional-only: scale(2, factor=3) works, x=2 doesn''t. Many built-ins like len(obj, /) work this way.', NULL, NULL, 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '6', 0), (@q, 'B', '2', 0), (@q, 'C', 'TypeError', 1), (@q, 'D', 'SyntaxError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-default'), 3, 'code_output', 'What does this print?', 'def add_item(item, basket=None):\n    if basket is None:\n        basket = []\n    basket.append(item)\n    return basket\n\nadd_item("apple")\nprint(add_item("pear"))', 'python', '[''pear'']', 'A fresh list is made inside the function now.', 'The None sentinel pattern: the default is immutable None, and a new list is created on each call that needs one.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '[''pear'']', 1), (@q, 'C', '[''apple'', ''pear'']', 0), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-default'), 3, 'code_output', 'What does this print?', 'def f(x, acc=[]):\n    acc.append(x)\n    return len(acc)\n\nf(1)\nf(2)\nprint(f.__defaults__)', 'python', '([1, 2],)', 'The default lives on the function object.', 'Defaults are stored in f.__defaults__, a tuple. The shared list has been mutated by both calls.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2]', 0), (@q, 'B', '([],)', 0), (@q, 'C', '(None,)', 0), (@q, 'D', '([1, 2],)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 3, 'code_output', 'What does this print?', 'x = 1\n\ndef f():\n    print(x)\n    x = 2\n\nf()', 'python', 'UnboundLocalError', 'Python decides which names are local before the function runs.', 'Because x is assigned somewhere in f, x is local for the whole body. Reading it before assignment raises UnboundLocalError.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1', 0), (@q, 'B', 'UnboundLocalError', 1), (@q, 'C', '2', 0), (@q, 'D', '1\n2', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 3, 'code_output', 'What does this print?', 'items = [1]\n\ndef add():\n    items += [2]\n\nadd()', 'python', 'UnboundLocalError', '+= is an assignment.', 'items += [2] assigns to items, so items is local and unbound. items.append(2) would work since it only reads the name.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', 'Nothing is printed and items becomes [1, 2]', 0), (@q, 'D', 'UnboundLocalError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'closures'), 3, 'code_output', 'What does this print?', 'fs = [lambda: i for i in range(3)]\nprint([f() for f in fs])', 'python', '[2, 2, 2]', 'When does each lambda look up i?', 'Closures capture the variable, not its value. All three lambdas read i when called, after the loop ended at 2.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 1, 2]', 0), (@q, 'B', '[0, 0, 0]', 0), (@q, 'C', 'NameError', 0), (@q, 'D', '[2, 2, 2]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'closures'), 3, 'code_output', 'What does this print?', 'fs = [lambda i=i: i for i in range(3)]\nprint([f() for f in fs])', 'python', '[0, 1, 2]', 'A default is evaluated when the lambda is created.', 'i=i freezes the current value into each lambda''s default. functools.partial is another fix.', NULL, NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '[0, 1, 2]', 1), (@q, 'C', '[None, None, None]', 0), (@q, 'D', '[2, 2, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'first-class'), 3, 'code_output', 'What does this print?', 'm = map(str.upper, ["a", "b"])\nprint(list(m), list(m))', 'python', '[''A'', ''B''] []', 'map returns an iterator in Python 3.', 'The first list() consumes the map object; the second gets nothing.', NULL, NULL, 53);
