INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hints-docs'), 1, 'mcq', 'What does `def area(r: float) -> float:` tell you?', NULL, NULL, 'r is expected to be a float and the function returns a float; it''s documentation for readers and tools', 'These are called type hints.', 'Type hints describe the intended types. Editors and checkers like mypy use them, but Python itself doesn''t convert or check anything at runtime.', NULL, 'Like TypeScript annotations: helpful to tools, gone at runtime.', 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The function can only be called once', 0), (@q, 'B', 'Python will convert r to a float automatically', 0), (@q, 'C', 'Python raises an error if r is not a float', 0), (@q, 'D', 'r is expected to be a float and the function returns a float; it''s documentation for readers and tools', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'passing'), 2, 'true_false', 'This code prints `[''a'', ''new'']`.', 'def add_tag(tags):\n    tags.append("new")\n\nmine = ["a"]\nadd_tag(mine)\nprint(mine)', 'python', 'True', 'tags and mine point to the same list.', 'append mutates the shared list object, so the caller''s list changes. Functions that do this should say so in their name or docstring.', ' mine --+\n        +--> [''a'', ''new'']   (one list object)\n tags --+', NULL, 84);
