INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'passing'), 2, 'true_false', 'This code prints `[]`.', 'def reset(tags):\n    tags = []\n\nmine = ["a"]\nreset(mine)\nprint(mine)', 'python', 'False', 'Is this mutating the list, or pointing a name at a new one?', 'tags = [] only re-points the local name tags at a new empty list. mine still points at the original. To empty the caller''s list use tags.clear().', ' before: mine, tags --> [''a'']\n after:  mine --> [''a'']     tags --> []', NULL, 85);
