INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arguments'), 2, 'fill_blank', 'What does this print? Type the exact output.', 'def f(a, b=2, c=3):\n    return a + b + c\n\nprint(f(1, c=10))', 'python', '13', 'A keyword argument can skip over defaults in the middle.', 'a = 1, b keeps its default 2, c = 10, so the total is 13. Keywords let you set just the option you care about.', ' f(1, c=10)\n   a <- 1      (position)\n   b <- 2      (default kept)\n   c <- 10     (by name)', NULL, 89);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'arguments'), 2, 'mcq', 'Which function definition is a SyntaxError?', NULL, NULL, 'def f(a=1, b):', 'Think about how Python would fill b from a positional call.', 'A parameter without a default can''t follow one with a default (unless it''s keyword-only, after *). The last option is fine because a and b are both keyword-only.', NULL, NULL, 90);
