INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'args-kwargs'), 2, 'code_output', 'What does this print?', 'def f(a, *rest):\n    return a, rest\n\nprint(f(1), f(1, 2, 3))', 'python', '(1, ()) (1, (2, 3))', '*rest is always a tuple, even when there are no extras.', 'With no extra arguments, rest is an empty tuple, never None. With extras it''s (2, 3).', NULL, NULL, 91);
