INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'param-kinds'), 2, 'code_output', 'What does this print?', 'def fit(X, *, epochs=1, lr=0.1):\n    return epochs, lr\n\nprint(fit("data", lr=0.5))', 'python', '(1, 0.5)', 'After *, parameters must be named.', 'Keyword-only options can''t be mixed up by position, which is why libraries like scikit-learn make most estimator options keyword-only.', NULL, 'Like a JS options object, fit(X, { epochs, lr }): options are named, never positional.', 94);
