INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'mutable-default'), 2, 'true_false', 'The mutable default trap only affects lists; dict and set defaults are safe.', NULL, NULL, 'False', 'What do lists, dicts and sets have in common?', 'Any mutable default (list, dict, set, or an object you change) is created once and shared by every call. Use None and build a fresh one inside.', NULL, NULL, 95);
