INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 2, 'code_output', 'What does this print?', 'list = [1, 2]\nprint(list("ab"))', 'python', 'TypeError', 'LEGB: which ''list'' is found first?', 'The global name list now hides the built-in list type, so calling it raises TypeError: ''list'' object is not callable. A common notebook bug; restart the kernel or `del list`.', NULL, NULL, 96);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', '[1, 2]', 0), (@q, 'C', 'TypeError', 1), (@q, 'D', '[''a'', ''b'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 2, 'code_output', 'What does this print?', 'x = "global"\n\ndef outer():\n    x = "enclosing"\n    def inner():\n        return x\n    return inner()\n\nprint(outer())', 'python', 'enclosing', 'Search order: Local, Enclosing, Global, Built-in.', 'inner has no local x, so Python checks the enclosing function next and finds ''enclosing'' before it ever reaches the global.', ' B  built-ins   (len, print, list)\n G  module      x = "global"\n E  outer()     x = "enclosing"   <- found here\n L  inner()     (no x)', NULL, 97);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'global', 0), (@q, 'B', 'enclosing', 1), (@q, 'C', 'NameError', 0), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 2, 'code_output', 'What does this print?', 'def setup():\n    global model\n    model = "bert"\n\nsetup()\nprint(model)', 'python', 'bert', 'global can also create a module-level name.', 'With `global model`, the assignment creates or rebinds the module variable. It works, but hidden globals make notebooks hard to reason about; return the value instead.', NULL, NULL, 98);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', 'None', 0), (@q, 'C', 'UnboundLocalError', 0), (@q, 'D', 'bert', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'closures'), 2, 'fill_blank', 'What does this print? Type the exact output.', 'def make_counter():\n    n = 0\n    def inc():\n        nonlocal n\n        n += 1\n        return n\n    return inc\n\nc = make_counter()\nc()\nc()\nprint(c())', 'python', '3', 'nonlocal lets inc update n in the enclosing function.', 'Each call bumps the same captured n: 1, 2, 3. The closure keeps private state between calls, like a tiny object with one field.', NULL, 'Like a private field in a class with a single increment method.', 99);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'first-class'), 2, 'code_output', 'What does this print?', 'words = ["b", "a", "C"]\nprint(sorted(words), sorted(words, key=str.lower))', 'python', '[''C'', ''a'', ''b''] [''a'', ''b'', ''C'']', 'Upper-case letters come before lower-case ones in plain string order.', 'Default string order compares character codes, and ''C'' (67) is before ''a'' (97). key=str.lower sorts case-insensitively but returns the original strings.', NULL, NULL, 100);
