INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'code_output', 'What does this print?', 'print([w for w in ["cat", "dog", "cow"] if w.startswith("c")])', 'python', '[''cat'', ''cow'']', 'The if at the end decides what''s kept.', 'Only words starting with ''c'' pass the filter. The kept items are the words themselves, not True/False.', NULL, NULL, 11);
