INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 2, 'code_output', 'What does this print?', 'print(["even" if n % 2 == 0 else "odd" for n in range(3)])', 'python', '[''even'', ''odd'', ''even'']', 'if-else in front transforms every item; it doesn''t drop any.', 'Each n becomes ''even'' or ''odd'', so the result has the same length as the input.', NULL, NULL, 21);
