INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 4, 'code_output', 'What does this print?', 'fns = {k: (lambda: k) for k in "ab"}\nprint(fns["a"]())', 'python', 'b', 'Each lambda closes over the comprehension''s variable, not its value.', 'All lambdas share one k, which ends as ''b''. Use lambda k=k: k to freeze each value.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', 'k', 0), (@q, 'C', 'a', 0), (@q, 'D', 'b', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 4, 'true_false', 'Since Python 3.12, list, dict and set comprehensions are inlined into the enclosing code instead of running as a hidden nested function, but their iteration variable still doesn''t leak.', NULL, NULL, 'True', 'PEP 709 changed the implementation, not the visible scoping.', 'PEP 709 inlined comprehensions for speed (no extra function frame); isolation of the loop variable is preserved. Generator expressions are still separate frames.', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 4, 'code_output', 'What does this print?', 'm = [[1, 2], [3, 4]]\nprint([x for x in row for row in m])', 'python', 'NameError', 'Write it as nested loops in the same clause order.', 'The first `for x in row` runs before `row` exists. Clause order matches nested loops top to bottom: [x for row in m for x in row].', NULL, NULL, 61);
