INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 4, 'code_output', 'What does this print?', 'print(sum(x for x in range(3), 10))', 'python', 'SyntaxError', 'The bracket-free form only works in one situation.', 'A generator expression can skip its own parentheses only when it is the sole argument. With a second argument write sum((x for x in range(3)), 10).', NULL, NULL, 63);
