INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 1, 'fill_blank', 'What does this print? Type the exact output.', 'print([str(n) for n in [1, 2]])', 'python', '[''1'', ''2'']', 'str() turns each number into text.', 'The result is a list of strings; the quotes in the output show that. '',''.join(...) would then glue them into one string.', NULL, NULL, 69);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'true_false', '`[x for x in nums if x > 100]` can give back an empty list.', NULL, NULL, 'True', 'What if no item passes the test?', 'If nothing passes the filter, the result is []. That''s not an error, but code that then does result[0] will crash, so check it.', NULL, NULL, 70);
