INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 1, 'fill_blank', 'What does this print? Type the exact output.', 'print({c for c in "hello"} == {"h", "e", "l", "o"})', 'python', 'True', 'A set keeps only one copy of each value.', 'The two l''s collapse into one, so the set has 4 letters and equals the literal set. Set equality ignores order.', NULL, NULL, 71);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 1, 'fill_blank', 'Keep only the positive numbers: `[x for x in nums ____ x > 0]`', NULL, NULL, 'if', 'Same keyword you''d use for a condition anywhere else.', 'A trailing `if` filters: only items where the condition is True make it into the new list.', NULL, NULL, 72);
