INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 1, 'mcq', 'What does `clean = [w.lower() for w in tokens]` do?', NULL, NULL, 'Makes a new list with every token in lower case; tokens is unchanged', 'Comprehensions always build something new.', 'Each token is lower-cased and collected into a new list. Normalising case like this is one of the first steps in many text pipelines.', NULL, NULL, 74);
