INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'grid-aliasing'), 2, 'mcq', 'Why does setting grid[0][0] also change grid[1][0]?', 'grid = [[0] * 2] * 2\ngrid[0][0] = 1\nprint(grid)', 'python', '`* 2` on the outer list repeats a reference to the same row, so both slots are one list', '* copies references, not the row itself.', '[[0] * 2] * 2 puts the SAME row object in the list twice, so changing one ''row'' changes both. Build grids with a comprehension instead.', ' grid[0] --+\n           +--> [0, 0]   (one row object)\n grid[1] --+', 'Two shortcuts on your desktop pointing to the same file: edit through one, and both show the change.', 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Python copies the change to every row to keep the grid square', 0), (@q, 'B', 'Assigning to grid[0][0] broadcasts down the column, like NumPy', 0), (@q, 'C', 'All integers in a list are shared, so changing one changes them all', 0), (@q, 'D', '`* 2` on the outer list repeats a reference to the same row, so both slots are one list', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'grid-aliasing'), 2, 'true_false', 'This code prints `[[1, 0], [0, 0]]`.', 'grid = [[0] * 2 for _ in range(2)]\ngrid[0][0] = 1\nprint(grid)', 'python', 'True', 'The comprehension runs [0] * 2 again on each pass.', 'Each pass creates a new row, so the rows are independent. This is the correct way to build a list-of-lists grid in plain Python.', ' grid[0] --> [1, 0]   (row object A)\n grid[1] --> [0, 0]   (row object B, built separately)', NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'code_output', 'What does this print?', 'w2i = {"<pad>": 0, "hi": 1}\ni2w = {i: w for w, i in w2i.items()}\nprint([i2w[i] for i in [1, 0, 1]])', 'python', '[''hi'', ''<pad>'', ''hi'']', 'First invert the vocab, then decode the ids.', 'Tokenizers keep both directions: word -> id to encode text, and id -> word to decode the model''s output back into text.', ' w2i: ''<pad>'' -> 0   ''hi'' -> 1     (encode)\n i2w:  0 -> ''<pad>''   1 -> ''hi''    (decode)', NULL, 77);
