INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'code_output', 'What does this print?', 'print([[1 if j == y else 0 for j in range(3)] for y in [2, 0]])', 'python', '[[0, 0, 1], [1, 0, 0]]', 'One row per label; a 1 goes in the label''s column.', 'This is one-hot encoding: label 2 becomes [0, 0, 1]. In real code np.eye(n)[labels] or torch.nn.functional.one_hot does it without a Python loop.', ' label 2 -> [0, 0, 1]\n label 0 -> [1, 0, 0]\n column:     0  1  2', NULL, 78);
