INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 2, 'code_output', 'What does this print?', 'tokens = ["Hi", "", "AI", " "]\nprint([t.lower() for t in tokens if t.strip()])', 'python', '[''hi'', ''ai'']', 'An empty string is falsy, and so is a stripped space.', 't.strip() is '''' for blank tokens, so the filter drops them, and the expression lower-cases the rest. Filter and clean in one pass.', NULL, 'Like trimming and lower-casing emails before checking them for duplicates.', 79);
