INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 2, 'code_output', 'What does this print?', 'print([f"{i}:{c}" for i, c in enumerate("ab")])', 'python', '[''0:a'', ''1:b'']', 'enumerate gives (index, item) pairs, unpacked into i and c.', 'The loop target of a comprehension can unpack, just like a for loop. f-strings make the formatting readable.', NULL, NULL, 80);
