INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 2, 'code_output', 'What does this print?', 'print([a * b for a, b in zip([1, 2, 3], [4, 5, 6])])', 'python', '[4, 10, 18]', 'zip pairs items at the same position.', 'Element-wise products: 1*4, 2*5, 3*6. Wrapping it in sum() gives the dot product (32), the core operation behind similarity scores.', ' a: 1   2   3\n b: 4   5   6\n *: 4  10  18   -> sum = 32 (dot product)', NULL, 81);
