INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 2, 'code_output', 'What does this print?', 'print([[x * 2 for x in row] for row in [[1, 2], [3]]])', 'python', '[[2, 4], [6]]', 'A comprehension inside the expression keeps the rows separate.', 'The outer comprehension makes one new row per input row, so the 2D shape is kept. Compare with [x * 2 for row in m for x in row], which flattens.', NULL, 'Like mapping over each page of results while keeping the pages separate.', 85);
