INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 2, 'fill_blank', 'What does this print? Type the exact output.', 'print(max(len(w) for w in ["a", "abc", "ab"]))', 'python', '3', 'max can consume a generator directly.', 'The generator yields 1, 3, 2 and max picks 3. Note this gives the length, while max(words, key=len) would give the word itself.', NULL, NULL, 86);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 2, 'fill_blank', 'What does this print? Type the exact output.', 'g = (n for n in range(3))\nprint(next(g), next(g))', 'python', '0 1', 'A generator remembers where it stopped.', 'Each next() resumes the generator and gets the next value.', NULL, 'Like reading a paginated API with a cursor: each call returns the next page, never the first one again.', 87);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 2, 'true_false', 'This code prints `False False`.', 'print(all(x > 0 for x in []), any(x > 0 for x in []))', 'python', 'False', 'Is there any counter-example in an empty list? Any example?', 'all() of nothing is True (no item fails) and any() of nothing is False (no item passes). A validation check like all(...) on empty data quietly ''passes''.', NULL, 'Like a test suite with zero tests reporting ''all passed''.', 88);
