INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'walrus'), 2, 'code_output', 'What does this print?', 'nums = [3, 8, 1]\nprint([(n, sq) for n in nums if (sq := n * n) > 5])', 'python', '[(3, 9), (8, 64)]', 'The walrus stores n * n while the filter tests it.', 'sq is computed once per item, tested in the filter, and reused in the output. The brackets around (sq := n * n) are required.', NULL, NULL, 90);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[(8, 64)]', 0), (@q, 'B', 'SyntaxError', 0), (@q, 'C', '[(3, 9), (8, 64)]', 1), (@q, 'D', '[(3, 9), (8, 64), (1, 1)]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 2, 'true_false', '`list(map(str, nums))` and `[str(n) for n in nums]` give the same list.', 'nums = [1, 2, 3]\nassert list(map(str, nums)) == [str(n) for n in nums]', 'python', 'True', 'Both apply str to every item.', 'They are equivalent. map with a ready-made function is short and fast; the comprehension is clearer once you need a lambda or a filter.', NULL, NULL, 91);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 2, 'mcq', 'You want an empty set to add unique labels to. Which is right?', NULL, NULL, 'labels = set()', 'Two of these make a dict or a list.', '{} is an empty dict, so .add() on it fails with AttributeError. set() is the only way to write an empty set.', NULL, 'Like `{}` in JavaScript being an object, not a Set: you need new Set() / set().', 92);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'labels = {set}', 0), (@q, 'B', 'labels = {}', 0), (@q, 'C', 'labels = set()', 1), (@q, 'D', 'labels = []', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'grid-aliasing'), 3, 'mcq', 'How many inner list objects does `[[]] * 3` contain?', 'rows = [[]] * 3\nrows[0].append("x")\nprint(rows)', 'python', 'One, referenced three times', 'How many list objects are in rows?', 'There is one empty list, referenced three times, so appending through any slot shows up in all three. Use [[] for _ in range(3)].', ' rows[0] --+\n rows[1] --+--> [ ]   one list object\n rows[2] --+', 'Three street signs pointing at one house: paint the house and every sign leads to the new colour.', 93);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Three, which are copied when you first write to them', 0), (@q, 'B', 'None; it''s just an empty list', 0), (@q, 'C', 'Three separate empty lists', 0), (@q, 'D', 'One, referenced three times', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'grid-aliasing'), 3, 'mcq', 'What''s the safe way to give every key its own empty list?', 'd = dict.fromkeys(["a", "b"], [])\nd["a"].append(1)\nprint(d)', 'python', '{k: [] for k in keys}', 'fromkeys uses the same default object for every key.', 'Every key shares the one list passed in. When grouping, use {k: [] for k in keys} or collections.defaultdict(list).', ' fromkeys:      ''a'' --+\n                ''b'' --+--> [1]       (one shared list)\n comprehension: ''a'' --> []   ''b'' --> []   ([] runs per key)', NULL, 94);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'dict.fromkeys(keys, list())', 0), (@q, 'B', 'dict.fromkeys(keys, [] * 2)', 0), (@q, 'C', '{k: [] for k in keys}', 1), (@q, 'D', 'dict.fromkeys(keys, [][:])', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'grid-aliasing'), 3, 'code_output', 'What does this print?', 'a = [[0] * 2] * 2\nb = [[0] * 2 for _ in range(2)]\nprint(a[0] is a[1], b[0] is b[1])', 'python', 'True False', '`is` checks whether two names are the same object.', 'is shows the difference directly: a''s rows are one object, b''s are two. When a bug looks like ''changing one row changes another'', test with is.', NULL, NULL, 95);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True', 0), (@q, 'B', 'False True', 0), (@q, 'C', 'True False', 1), (@q, 'D', 'False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'grid-aliasing'), 3, 'mcq', 'What kind of copy does `[r for r in rows]` make?', 'rows = [[1], [2]]\ncopy = [r for r in rows]\ncopy[0].append(9)\nprint(rows, copy is rows)', 'python', 'A shallow copy: a new outer list whose items are the same inner lists', 'The outer list is new. Are the inner lists?', 'The comprehension copies the outer list only (a shallow copy), and the inner lists are shared. Use [r[:] for r in rows] or copy.deepcopy for a full copy.', ' rows --> [ * , * ]\n copy --> [ * , * ]   new outer list\n            |   |\n           [1,9] [2]  same inner lists', 'Copying a folder of shortcuts: the new folder still opens the same files.', 96);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'No copy at all; copy is rows', 0), (@q, 'B', 'A read-only view of rows', 0), (@q, 'C', 'A shallow copy: a new outer list whose items are the same inner lists', 1), (@q, 'D', 'A deep copy of every level', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'Why is padding needed before turning a batch like this into a tensor?', 'batch = [[5, 3], [7], [1, 2, 9]]\nn = max(len(s) for s in batch)\nprint([s + [0] * (n - len(s)) for s in batch])', 'python', 'A tensor must be rectangular, so every row needs the same length', 'Each sequence gets as many zeros as it''s short of the longest.', 'Right-padding to the longest length turns a ragged batch into a rectangle, which is what a tensor needs. 0 is the usual <pad> id.', ' [5, 3]     + [0]       -> [5, 3, 0]\n [7]        + [0, 0]    -> [7, 0, 0]\n [1, 2, 9]  + []        -> [1, 2, 9]', 'Like normalising rows before a bulk insert into a table with fixed columns.', 97);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A tensor must be rectangular, so every row needs the same length', 1), (@q, 'B', 'Tokenizers require zeros at the end of every sequence', 0), (@q, 'C', 'Python lists can''t hold rows of different lengths', 0), (@q, 'D', 'Padding makes the model train faster', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'What is a mask like this used for in a transformer?', 'batch = [[5, 3, 0], [7, 0, 0]]\nprint([[int(t != 0) for t in s] for s in batch])', 'python', 'Telling attention which positions are real tokens and which are padding to ignore', '1 for a real token, 0 for padding.', 'This is an attention mask: it tells a transformer which positions are real so it ignores the padding. int(True) is 1.', ' ids:  5  3  0      7  0  0\n mask: 1  1  0      1  0  0\n       real   pad   real  pad pad', NULL, 98);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Counting how many words are in the vocabulary', 0), (@q, 'B', 'Telling attention which positions are real tokens and which are padding to ignore', 1), (@q, 'C', 'Turning token ids into embeddings', 0), (@q, 'D', 'Dropping random tokens during training', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'On 1 million tokens with 50,000 unique words, why is `{w: tokens.count(w) for w in set(tokens)}` a bad way to count words?', NULL, NULL, 'Each .count scans the whole list, so it does about 50,000 x 1,000,000 steps; collections.Counter(tokens) counts in one pass', 'How much work is one tokens.count(w)?', 'It''s O(unique x n), which here is billions of comparisons. Counter does one O(n) pass. Correct code that is quadratic is a classic interview red flag.', NULL, 'Like running one COUNT(*) query per distinct value instead of a single GROUP BY.', 99);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Each .count scans the whole list, so it does about 50,000 x 1,000,000 steps; collections.Counter(tokens) counts in one pass', 1), (@q, 'B', 'It gives wrong counts for repeated words', 0), (@q, 'C', 'set(tokens) loses the words', 0), (@q, 'D', 'Dict comprehensions can''t have function calls as values', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'What does this vocabulary step produce?', 'from collections import Counter\ntokens = "a b a c a b".split()\ncounts = Counter(tokens)\nprint([w for w, c in counts.most_common() if c >= 2])', 'python', 'The words that appear at least twice, most frequent first', 'most_common gives (word, count) pairs, highest first.', 'Keeping words above a minimum count is how vocabularies drop rare words (min_freq). Counter does the counting and the comprehension does the filtering.', ' Counter: a=3  b=2  c=1\n c >= 2:  a    b    (c dropped as rare)', NULL, 100);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The words that appear at least twice, most frequent first', 1), (@q, 'B', 'Every word exactly once', 0), (@q, 'C', 'A count of characters', 0), (@q, 'D', 'Only the single most common word', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'code_output', 'What does this print?', 'data = list(range(7))\nprint([data[i:i + 3] for i in range(0, len(data), 3)])', 'python', '[[0, 1, 2], [3, 4, 5], [6]]', 'range with a step gives each batch''s start index.', 'Slicing never goes out of range, so the last batch is simply shorter. A one-line way to chunk a list into mini-batches.', NULL, 'Like OFFSET/LIMIT paging: offsets 0, 3, 6, and the last page is short.', 101);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[0, 3, 6]]', 0), (@q, 'B', '[[0, 1, 2], [3, 4, 5], [6, None, None]]', 0), (@q, 'C', '[[0, 1, 2], [3, 4, 5]]', 0), (@q, 'D', '[[0, 1, 2], [3, 4, 5], [6]]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'Why does the result come out in sorted order?', 'scores = {"a": 0.2, "b": 0.9, "c": 0.5}\ntop = {k: v for k, v in sorted(scores.items(), key=lambda kv: kv[1], reverse=True)[:2]}\nprint(top)', 'python', 'Dicts keep insertion order, and the pairs are inserted already sorted', 'Sort the pairs by value, keep two, and rebuild a dict.', 'Dicts keep insertion order, so the rebuilt dict stays sorted. This is a top-k selection such as keeping the 2 most likely labels.', NULL, 'Like ORDER BY score DESC LIMIT 2, then loading the rows into an ordered map.', 102);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Dict comprehensions sort their keys automatically', 0), (@q, 'B', 'Python sorts dict values on print', 0), (@q, 'C', 'sorted() returns a dict', 0), (@q, 'D', 'Dicts keep insertion order, and the pairs are inserted already sorted', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'mcq', 'What goes wrong with these ids?', 'vocab = ["a", "b", "a"]\nw2i = {w: i for i, w in enumerate(vocab)}\nprint(w2i, len(w2i))', 'python', '''a'' ends up as id 2 and id 0 is never used, so the ids have a gap and the largest id is not below len(w2i)', 'Duplicate keys: the last value wins.', '''a'' ends up as id 2 and id 0 is never used, so the ids have a gap and an embedding table sized len(w2i) would be too small for id 2. Deduplicate first: list(dict.fromkeys(vocab)).', ' i: 0    1    2\n w: a    b    a\n w2i: a -> 0, then overwritten -> 2;  b -> 1\n ids used: 1, 2   (0 is a hole, len = 2)', NULL, 103);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '''a'' ends up as id 2 and id 0 is never used, so the ids have a gap and the largest id is not below len(w2i)', 1), (@q, 'B', '''a'' gets two ids at once', 0), (@q, 'C', 'It raises an error on the duplicate word', 0), (@q, 'D', 'Nothing; the ids are 0 and 1 as expected', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 3, 'code_output', 'What does this print?', 'data = {"a": (1, 2), "b": (3, 4)}\nprint([k + str(x + y) for k, (x, y) in data.items()])', 'python', '[''a3'', ''b7'']', 'The target unpacks the key and the inner pair together.', 'Nested unpacking in the for clause pulls apart (''a'', (1, 2)) in one step, with no indexing like v[0], v[1].', NULL, NULL, 104);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''a12'', ''b34'']', 0), (@q, 'B', '[''a3'', ''b7'']', 1), (@q, 'C', 'ValueError', 0), (@q, 'D', '[''a(1, 2)'', ''b(3, 4)'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'list-comp'), 3, 'code_output', 'What does this print?', 'print([x, -x for x in range(2)])', 'python', 'SyntaxError', 'What is the comprehension''s expression here?', 'Two values in the expression need parentheses to form a tuple: [(x, -x) for x in ...]. Without them Python reports a SyntaxError.', NULL, NULL, 105);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SyntaxError', 1), (@q, 'B', '[[0, 0], [1, -1]]', 0), (@q, 'C', '[(0, 0), (1, -1)]', 0), (@q, 'D', '[0, 0, 1, -1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filters'), 3, 'mcq', 'Why doesn''t this raise ZeroDivisionError?', 'vals = [4, 0, 2]\nprint([10 // v for v in vals if v != 0 and 10 // v > 2])', 'python', '`and` short-circuits: when v != 0 is False, 10 // v is never evaluated', '`and` stops as soon as the left side is False.', 'v != 0 is checked first, so 10 // 0 is never computed. Put guard conditions first in a filter. 10 // 4 = 2 fails the second test; 10 // 2 = 5 passes.', NULL, 'Like `user && user.name` in JavaScript: the guard on the left protects the access on the right.', 106);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Integer division by zero returns 0 in a comprehension', 0), (@q, 'B', '`and` short-circuits: when v != 0 is False, 10 // v is never evaluated', 1), (@q, 'C', 'Comprehensions swallow exceptions', 0), (@q, 'D', 'The filter runs after the expression', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 3, 'code_output', 'What does this print?', 'print([x if x % 2 else None for x in range(4) if x])', 'python', '[1, None, 3]', 'The trailing `if x` drops 0 first.', '0 is filtered out. Of the rest, odd numbers are kept and even ones become None. A filter and a transform together, in the right positions.', NULL, NULL, 107);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[None, 1, None, 3]', 0), (@q, 'B', '[1, None, 3]', 1), (@q, 'C', 'SyntaxError', 0), (@q, 'D', '[1, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 3, 'mcq', 'How many times does each helper run?', 'def a(x):\n    print("a", x)\n    return x\n\ndef b(x):\n    print("b", x)\n    return -x\n\nr = [a(x) if x > 0 else b(x) for x in [1, -2]]\nprint(r)', 'python', 'Once each: a for 1 and b for -2, because only the chosen branch is evaluated', 'A conditional expression evaluates only the branch it picks.', 'For each item, only one of a or b runs. That matters when a branch is expensive or would fail on some inputs.', NULL, NULL, 108);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Once each: a for 1 and b for -2, because only the chosen branch is evaluated', 1), (@q, 'B', 'Both run for every item', 0), (@q, 'C', 'a runs for every item and b only for negatives', 0), (@q, 'D', 'Neither runs until r is printed', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 3, 'true_false', 'This code prints `[0, 6]`.', 'print([x * 2 if x else -1 for x in [0, 3]])', 'python', 'False', 'if-else binds more loosely than *.', 'It reads as (x * 2) if x else -1, not x * (2 if x else -1). Add parentheses when the precedence isn''t obvious.', NULL, NULL, 109);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'conditional-expr'), 3, 'mcq', 'How does Python group this chained conditional?', 'print(["pos" if x > 0 else "neg" if x < 0 else "zero" for x in [3, 0, -2]])', 'python', '"pos" if x > 0 else ("neg" if x < 0 else "zero")', 'Read it as: pos if x > 0, else (neg if x < 0 else zero).', 'Conditional expressions can chain, like elif. More than two branches gets hard to read, so a small helper function is often clearer.', NULL, NULL, 110);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '("pos" if x > 0 else "neg") if x < 0 else "zero"', 0), (@q, 'B', 'It only ever picks "pos" or "zero"', 0), (@q, 'C', '"pos" if x > 0 else ("neg" if x < 0 else "zero")', 1), (@q, 'D', 'It''s a SyntaxError; conditionals can''t chain', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 3, 'true_false', 'This code prints `{''a'': 0, ''b'': 0, ''n'': 0}`.', 'print({k: 0 for k in "banana"})', 'python', 'False', 'Repeated keys keep the position of their first appearance.', 'Dicts keep insertion order, and re-assigning an existing key doesn''t move it. So the order is b, a, n: first-seen order.', ' b a n a n a\n b: new  a: new  n: new  a, n, a: already there\n keys in first-seen order: b, a, n', NULL, 111);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 3, 'code_output', 'What does this print?', 'print({[x] for x in range(2)})', 'python', 'TypeError', 'What do set items have to be?', 'Set items and dict keys must be hashable. Lists aren''t, so you get TypeError: unhashable type: ''list''. Use tuples: {(x,) for x in ...}.', NULL, NULL, 112);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '{0, 1}', 0), (@q, 'B', 'TypeError', 1), (@q, 'C', '[{0}, {1}]', 0), (@q, 'D', '{[0], [1]}', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 3, 'code_output', 'What does this print?', 'm = [[1, 2], [], [3]]\nprint([x for row in m if row for x in row if x != 2])', 'python', '[1, 3]', 'Each if filters the for clause just before it.', '`if row` skips empty rows (here just a check, it would also guard row[0]); `if x != 2` filters items. Clauses read left to right, like nested loops.', ' for row in m:          [1, 2]   []     [3]\n   if row:              yes      skip   yes\n     for x in row:      1  2            3\n       if x != 2:       1  -            3', NULL, 113);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[1], [3]]', 0), (@q, 'B', '[1, 2, 3]', 0), (@q, 'C', '[1, 3]', 1), (@q, 'D', 'SyntaxError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 3, 'mcq', 'Why is there no pair with a = 0?', 'print([(a, b) for a in range(3) for b in range(a)])', 'python', 'range(0) is empty, so the inner clause produces nothing when a is 0', 'The inner range depends on the outer variable.', 'For a = 0 the inner range is empty; for a = 1 it gives b = 0; for a = 2, b = 0 and 1. A later for clause can use earlier loop variables.', ' a = 0: b in range(0) -> (none)\n a = 1: b in range(1) -> (1, 0)\n a = 2: b in range(2) -> (2, 0) (2, 1)', NULL, 114);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'range(0) is empty, so the inner clause produces nothing when a is 0', 1), (@q, 'B', 'a = 0 is falsy, so it''s filtered out', 0), (@q, 'C', 'The outer clause starts at 1', 0), (@q, 'D', 'b is never allowed to equal a', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 3, 'mcq', 'Why is `list(evens)` empty at the end?', 'nums = range(10)\nevens = (n for n in nums if n % 2 == 0)\nsq = (n * n for n in evens)\nprint(list(sq)[:3], list(evens))', 'python', 'sq pulled every item out of evens while producing its own, and a generator can''t be replayed', 'sq pulls its items from evens.', 'Chained generators form a lazy pipeline. Consuming sq used up evens too, so evens is empty afterwards. Also note list(sq)[:3] built the whole list before slicing.', ' range --> evens --> sq --> list()\n list(sq) drains sq, which drains evens', 'Like Unix pipes: `cat | grep | head` - once data has flowed through, it''s gone.', 115);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Generators empty themselves after three items', 0), (@q, 'B', 'sq pulled every item out of evens while producing its own, and a generator can''t be replayed', 1), (@q, 'C', 'Slicing list(sq)[:3] deleted evens', 0), (@q, 'D', 'evens never started', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 3, 'code_output', 'What does this print?', 'print(len(x for x in range(3)))', 'python', 'TypeError', 'Does a generator know how many items it will produce?', 'Generators have no len(), because the count isn''t known until they finish. Use sum(1 for _ in g), or build a list if you need the length.', NULL, 'Like asking a live stream how many frames it has before it''s finished.', 116);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3', 0), (@q, 'B', 'TypeError', 1), (@q, 'C', '0', 0), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 3, 'fill_blank', 'What does this print? Type the exact output.', 'print(min((x for x in []), default=None))', 'python', 'None', 'min has a keyword for the empty case.', 'min/max of an empty input raise ValueError unless you pass default=. With a generator argument plus a keyword, the generator needs its own brackets.', NULL, NULL, 117);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scope'), 3, 'mcq', 'Why does `list(''ab'')` still work after this line?', '[list for list in range(2)]\nprint(list("ab"))', 'python', 'The comprehension''s loop variable is private to it, so the built-in list is never shadowed', 'Where does the comprehension''s variable live?', 'The comprehension''s `list` is private to it, so the built-in list is untouched afterwards. A for loop named list would have shadowed the built-in and broken this call.', NULL, NULL, 118);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'list is a keyword and can''t be reassigned', 0), (@q, 'B', 'The comprehension never actually ran', 0), (@q, 'C', 'The comprehension''s loop variable is private to it, so the built-in list is never shadowed', 1), (@q, 'D', 'Python restores built-ins after each statement', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'walrus'), 3, 'mcq', 'Why does total equal 6 after the comprehension?', 'total = 0\nprint([total := total + x for x in [1, 2, 3]], total)', 'python', 'A walrus target inside a comprehension binds in the surrounding scope, so total is updated on each step', 'The walrus target binds in the surrounding scope.', 'Each step updates the outer total, giving running sums, and total keeps the final value. itertools.accumulate is the clearer tool for this.', ' x:      1   2   3\n total:  1   3   6   (outer variable, updated each step)', NULL, 119);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A walrus target inside a comprehension binds in the surrounding scope, so total is updated on each step', 1), (@q, 'B', 'Every comprehension variable leaks to the outer scope', 0), (@q, 'C', 'print returns the sum of the list', 0), (@q, 'D', 'total is shared because it''s an int', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'walrus'), 3, 'fill_blank', 'What does this print? Type the exact output.', 'nums = [3, 8, 12]\nif any((big := n) > 5 for n in nums):\n    print(big)', 'python', '8', 'any() stops at the first True, and the walrus remembers the last value it saw.', 'This captures the first item that passed (a ''witness''). any stopped at 8, so big is 8, not 12.', ' n = 3: big = 3, 3 > 5? no\n n = 8: big = 8, 8 > 5? yes -> any() stops\n n = 12: never reached       -> big is 8', NULL, 120);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 3, 'true_false', 'You can put try/except inside a list comprehension to skip items that fail to parse.', NULL, NULL, 'False', 'A comprehension holds expressions only.', 'try is a statement, so it can''t go in a comprehension. Write a helper (def safe_float(s): try... except: return None) and filter on its result, or use a loop.', NULL, NULL, 121);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 3, 'fill_blank', 'What does this print? Type the exact output.', 'print(list(dict.fromkeys([3, 1, 3, 2, 1])))', 'python', '[3, 1, 2]', 'Dict keys are unique and keep insertion order.', 'dict.fromkeys removes duplicates while keeping first-seen order, which list(set(...)) does not promise. Handy for deduplicating a vocabulary.', NULL, 'Like SELECT DISTINCT that also remembers the order rows first appeared.', 122);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 3, 'mcq', 'Which makes the clearest copy of a list called `items`?', NULL, NULL, 'items.copy() or list(items)', 'A comprehension that changes nothing hides your intent.', 'All four make the same shallow copy, but [x for x in items] makes readers look for a transform that isn''t there. Use a comprehension when you transform or filter.', NULL, NULL, 123);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'items.copy() or list(items)', 1), (@q, 'B', '[x for x in items]', 0), (@q, 'C', 'list(map(lambda x: x, items))', 0), (@q, 'D', '[*items, ]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 3, 'code_output', 'What does this print?', 'import numpy as np\nlabels = np.array([2, 0])\nprint(np.eye(3, dtype=int)[labels].tolist())', 'python', '[[0, 0, 1], [1, 0, 0]]', 'Row i of the identity matrix is the one-hot vector for class i.', 'Fancy indexing picks rows 2 and 0 of the identity matrix in one vectorised step: the same one-hot result as a nested comprehension, without a Python loop.', NULL, NULL, 124);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'IndexError', 0), (@q, 'B', '[[1, 0, 0], [0, 0, 1]]', 0), (@q, 'C', '[[2], [0]]', 0), (@q, 'D', '[[0, 0, 1], [1, 0, 0]]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'grid-aliasing'), 4, 'mcq', 'Why doesn''t deepcopy fix the shared rows?', 'import copy\ngrid = [[0] * 2] * 2\ng2 = copy.deepcopy(grid)\ng2[0][0] = 1\nprint(g2)', 'python', 'deepcopy keeps a memo of objects it has already copied, so a row that appears twice is copied once and stays shared', 'deepcopy reproduces the object graph, including shared parts.', 'deepcopy remembers objects it has already copied, so a row that was shared stays shared in the copy. Deep-copying doesn''t fix aliasing; rebuild the grid with a comprehension.', NULL, NULL, 125);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'deepcopy keeps a memo of objects it has already copied, so a row that appears twice is copied once and stays shared', 1), (@q, 'B', 'Rows of ints are immutable, so deepcopy skips them', 0), (@q, 'C', 'deepcopy doesn''t work on lists of ints', 0), (@q, 'D', 'deepcopy only copies the outer list', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'grid-aliasing'), 4, 'mcq', 'In this grid, which rows are the same object?', 'grid = [[0] * 2 for _ in range(2)] * 2\ngrid[0][0] = 1\nprint(grid)', 'python', 'Rows 0 and 2, and rows 1 and 3', 'The comprehension makes 2 distinct rows; then * repeats the references.', 'Rows 0 and 2 are the same object, and so are 1 and 3. Half-fixing an aliasing bug like this is easy to miss because only some rows change together.', ' grid[0], grid[2] --> row A [1, 0]\n grid[1], grid[3] --> row B [0, 0]', NULL, 126);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Rows 0 and 2, and rows 1 and 3', 1), (@q, 'B', 'All four rows', 0), (@q, 'C', 'None of them', 0), (@q, 'D', 'Rows 0 and 1, and rows 2 and 3', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 4, 'code_output', 'What does this print?', 'g = (10 // x for x in [5, 0, 2])\nout = []\ntry:\n    for v in g:\n        out.append(v)\nexcept ZeroDivisionError:\n    pass\nprint(out, list(g))', 'python', '[2] []', 'What state is a generator in after an exception escapes it?', 'Once an exception propagates out of a generator, the generator is finished for good. The 2 still waiting is lost, so catch errors inside the per-item code, not around the whole stream.', ' x=5 -> 2       appended\n x=0 -> ZeroDivisionError escapes -> generator is DONE\n x=2 -> never produced', 'Like a crashed stream consumer: everything after the failure is lost unless errors are handled per message.', 127);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2, 5] []', 0), (@q, 'B', '[2] [5]', 0), (@q, 'C', '[2] []', 1), (@q, 'D', 'ZeroDivisionError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genexp'), 4, 'true_false', 'This code prints `[1, 2]`.', 'x = [1, 2]\ng = (i for i in x)\nx.append(3)\nprint(list(g))', 'python', 'False', 'iter(x) is taken at creation, but it''s an iterator over the same list object.', 'The genexp grabbed an iterator over this list, not a snapshot. Mutating the list before consuming is visible; rebinding x to a new list would not be.', ' g created: holds iter(x) --> the SAME list object\n x.append(3): list is now [1, 2, 3]\n list(g): reads 1, 2, 3', NULL, 128);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'walrus'), 4, 'fill_blank', 'What does this print? Type the exact output.', 'def f():\n    total = 0\n    [total := total + x for x in range(3)]\n    return total\n\nprint(f())', 'python', '3', 'Which scope does a walrus inside a comprehension write to?', 'The walrus target binds in the function that contains the comprehension, so f''s total becomes 0 + 0 + 1 + 2 = 3. It''s the one deliberate scope leak in comprehensions.', NULL, NULL, 129);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'walrus'), 4, 'code_output', 'What does this print?', 'class C:\n    xs = [y := 1 for _ in range(2)]', 'python', 'SyntaxError', 'Where would the walrus target have to live?', 'In a class body the target would have to bind in the class namespace, which Python forbids: assignment expression within a comprehension cannot be used in a class body.', NULL, 'Like a rule that a helper can''t write into a config object while it''s still being defined.', 130);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SyntaxError', 1), (@q, 'B', 'TypeError', 0), (@q, 'C', 'NameError', 0), (@q, 'D', 'Nothing is printed', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'walrus'), 4, 'code_output', 'What does this print?', 'print([x for x in (data := [1, 2])])', 'python', 'SyntaxError', 'There''s a rule about walrus in the iterable part of a comprehension.', 'PEP 572 forbids := in a comprehension''s iterable expression, to avoid confusing scope. Assign data on its own line first.', NULL, 'Like a linter rule that bans assignments inside a for-loop header: legal elsewhere, confusing there.', 131);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', '[1, 2]', 0), (@q, 'C', '[[1, 2]]', 0), (@q, 'D', 'SyntaxError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'nested'), 4, 'mcq', 'Why does ''inner built'' print twice?', 'def inner():\n    print("inner built")\n    return [1, 2]\n\nprint([(a, b) for a in "xy" for b in inner()])', 'python', 'Only the first for clause''s iterable is evaluated once; later clauses are re-evaluated on each outer pass', 'Only the FIRST iterable is evaluated once.', 'Later for clauses are re-evaluated on each pass of the outer loop, just like a nested loop. Hoist expensive inner iterables into a variable first.', ' for a in "xy":          <- "xy" evaluated once\n     for b in inner():   <- inner() called per a\n         append((a, b))', NULL, 132);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Comprehensions evaluate everything twice', 0), (@q, 'B', 'inner is a generator, so it runs twice', 0), (@q, 'C', 'print is called once for each of a and b', 0), (@q, 'D', 'Only the first for clause''s iterable is evaluated once; later clauses are re-evaluated on each outer pass', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 4, 'mcq', 'Why does `x in seen or seen.add(x)` work as a ''not seen before'' test?', 'seen = set()\nprint([x for x in [1, 2, 1, 3, 2] if not (x in seen or seen.add(x))])', 'python', 'seen.add returns None (falsy), so for a new x the whole `or` is falsy and `not` keeps x, while x is added to seen', 'seen.add(x) returns None, which is falsy.', 'New x: x in seen is False, then seen.add(x) runs and gives None, so `not None` is True and x is kept. It works, but hiding a side effect in a filter is an anti-pattern; list(dict.fromkeys(xs)) says the same thing plainly.', ' x=1: in seen? no -> add -> None -> not None = True  keep\n x=2: in seen? no -> add -> None -> True             keep\n x=1: in seen? yes -> True -> not True = False       drop', NULL, 133);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'or only adds x to seen when x is new', 0), (@q, 'B', 'seen.add returns None (falsy), so for a new x the whole `or` is falsy and `not` keeps x, while x is added to seen', 1), (@q, 'C', 'set.add returns True when the item is new', 0), (@q, 'D', '`in` raises an error for unseen items', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 4, 'mcq', 'For a list `nums` of 1 million ints, which is usually fastest?', NULL, NULL, 'list(map(str, nums)), because map calls the C function str directly with no Python-level expression per item', 'What extra work does each option do per item?', 'map plus a built-in skips running any bytecode per item. map plus a lambda adds a Python function call per item and is usually the slowest; the comprehension sits in between. Measure with timeit before choosing.', NULL, 'Like calling a stored procedure directly vs wrapping it in an extra app-level function per row.', 134);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'list(map(lambda n: str(n), nums))', 0), (@q, 'B', '[str(n) for n in nums], because comprehensions are always fastest', 0), (@q, 'C', 'A for loop with result.append(str(n))', 0), (@q, 'D', 'list(map(str, nums)), because map calls the C function str directly with no Python-level expression per item', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'readability-perf'), 4, 'mcq', 'Why doesn''t this comprehension loop forever?', 'xs = [1, 2]\nr = [xs.append(x) or x for x in xs if len(xs) < 4]\nprint(r, xs)', 'python', 'The len(xs) < 4 filter stops more appends once xs has 4 items, so the iterator reaches the end', 'The comprehension iterates over the same list it''s growing.', 'The list iterator sees the appended items, but the len check stops further appends once xs has 4 items. Mutating the source inside a comprehension is legal and very hard to read.', NULL, NULL, 135);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The len(xs) < 4 filter stops more appends once xs has 4 items, so the iterator reaches the end', 1), (@q, 'B', 'append returns None, which ends the comprehension', 0), (@q, 'C', 'Python limits comprehensions to 4 items', 0), (@q, 'D', 'Comprehensions loop over a snapshot of xs', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'code_output', 'What does this print?', 'import numpy as np\nrows = [[1, 2], [3]]\ntry:\n    np.array([r for r in rows])\nexcept ValueError:\n    print("ragged")', 'python', 'ragged', 'NumPy 2 refuses to build an array from rows of different lengths.', 'Since NumPy 1.24, ragged nested lists raise ValueError (older versions quietly made an object array). That''s why batches are padded to equal length before becoming arrays or tensors.', ' [[1, 2],\n  [3]   ]   <- row lengths 2 and 1\n shape?  (2, ?)  -> not rectangular -> ValueError', NULL, 136);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[1, 2], [3]]', 0), (@q, 'B', 'Nothing is printed', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', 'ragged', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'code_output', 'What does this print?', 'import io\nwith io.StringIO("a\\nb\\n") as f:\n    lines = (l.strip() for l in f)\nprint(list(lines))', 'python', 'ValueError', 'The generator is consumed after the with block has closed the file.', 'The genexp only stored an iterator over f; the lines are read when list() runs, by which point the file is closed: ValueError: I/O operation on closed file. Consume inside the with block, or use a list.', ' with ...:  lines = genexp over f   (nothing read yet)\n exit with: f.close()\n list(lines): reads f -> closed -> ValueError', 'Like returning a database cursor from a function that closes the connection on the way out.', 137);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 1), (@q, 'B', '[]', 0), (@q, 'C', 'StopIteration', 0), (@q, 'D', '[''a'', ''b'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 4, 'mcq', 'Since Python 3.8, which part of `{k(i): v(i) for i in ...}` is evaluated first?', 'def k(x):\n    print("key", x)\n    return x\n\ndef v(x):\n    print("val", x)\n    return x\n\nd = {k(i): v(i) for i in range(1)}', 'python', 'The key, then the value', 'Python 3.8 fixed the evaluation order of dict comprehensions.', 'The key is evaluated before the value, matching dict literals and normal left-to-right reading. Before 3.8 dict comprehensions evaluated the value first.', NULL, NULL, 138);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The value, then the key', 0), (@q, 'B', 'The key, then the value', 1), (@q, 'C', 'It depends on the key''s hash', 0), (@q, 'D', 'Both at the same time', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dict-set'), 4, 'true_false', 'This code prints `{1: ''bool''}`.', 'print({k: type(k).__name__ for k in [1, 1.0, True]})', 'python', 'True', '1 == 1.0 == True, and they hash the same.', 'All three are the same dict key. The first key object (1) is kept and the value is overwritten each time, ending as ''bool''. Mixing ints, floats and bools as keys silently merges them.', ' 1 == 1.0 == True, same hash -> ONE key\n k=1    -> {1: ''int''}\n k=1.0  -> {1: ''float''}   key object 1 kept\n k=True -> {1: ''bool''}', NULL, 139);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-patterns'), 4, 'mcq', 'A preprocessing function does `return [tokenize(line) for line in open(path)]` on a 40 GB file. What''s the main problem, and the fix?', NULL, NULL, 'It holds every tokenized line in RAM at once; yield from a generator (or return a generator expression consumed inside a with block) to stream it', 'Where do 40 GB of results live?', 'The list version needs memory for the whole result. A generator processes one line at a time, so memory stays constant, which is how streaming datasets work. Opening inside a with block also guarantees the file gets closed.', NULL, 'Like streaming a large HTTP response instead of buffering the whole body in memory.', 140);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It''s slower than a for loop with append, so it should be rewritten as a loop', 0), (@q, 'B', 'Comprehensions can''t read files', 0), (@q, 'C', 'open() inside a comprehension raises a SyntaxError', 0), (@q, 'D', 'It holds every tokenized line in RAM at once; yield from a generator (or return a generator expression consumed inside a with block) to stream it', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'When Python shows a traceback, where is the most useful line usually?', NULL, NULL, 'The last line (error type and message)', 'Read tracebacks from the bottom up.', 'The last line names the error (e.g. KeyError: ''age''); the lines above show where it happened.', NULL, 'Like a stack trace in Java/Node: the message at the end tells you what broke.', 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The last line (error type and message)', 1), (@q, 'B', 'The middle', 0), (@q, 'C', 'The first line', 0), (@q, 'D', 'There is no useful line', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Which error do you get from int(''abc'')?', NULL, NULL, 'ValueError', 'The type (a string) is fine; the value inside isn''t a number.', 'ValueError: the argument has the right type but an unusable value.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', 'SyntaxError', 0), (@q, 'C', 'ValueError', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Which error do you get from ''a'' + 1?', NULL, NULL, 'TypeError', 'You''re mixing two kinds of things.', 'TypeError: you can''t add a str and an int. Convert one: ''a'' + str(1).', NULL, NULL, 3);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'IndexError', 0), (@q, 'B', 'NameError', 0), (@q, 'C', 'TypeError', 1), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'code_output', 'What does this print?', 'try:\n    x = 1 / 0\nexcept ZeroDivisionError:\n    print("cannot divide")', 'python', 'cannot divide', 'except catches the named error.', 'Dividing by zero raises ZeroDivisionError, which the except block handles.', NULL, 'try / catch in JavaScript or Java.', 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Error', 0), (@q, 'B', '0', 0), (@q, 'C', 'inf', 0), (@q, 'D', 'cannot divide', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 2, 'mcq', 'What does NameError: name ''df'' is not defined usually mean in a notebook?', NULL, NULL, 'The cell that creates df hasn''t been run yet', 'Notebooks remember only cells you''ve actually run.', 'Run the earlier cell that defines df (or Restart & Run All).', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df is the wrong type', 0), (@q, 'B', 'The file is missing', 0), (@q, 'C', 'The cell that creates df hasn''t been run yet', 1), (@q, 'D', 'Pandas isn''t installed', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tracebacks'), 1, 'mcq', 'A notebook cell crashes with the traceback below. What kind of error happened?', 'Traceback (most recent call last):\n  File "train.py", line 30, in <module>\n    y = load_labels(rows)\n  File "train.py", line 12, in load_labels\n    return [r["label"] for r in rows]\nKeyError: ''label''', 'text', 'KeyError', 'The type of error is the word before the colon on the last line.', 'The last line is always `ErrorType: message`. Here it is KeyError: the dict has no key ''label''. The File/line entries above only tell you where.', NULL, NULL, 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'train.py', 0), (@q, 'B', 'load_labels', 0), (@q, 'C', 'line 12', 0), (@q, 'D', 'KeyError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tracebacks'), 1, 'true_false', 'In a Python traceback, the most recent call (where the error was actually raised) is printed at the bottom.', NULL, NULL, 'True', 'Look at the header: ''most recent call last''.', 'Python prints the call chain oldest-first, so the frame that raised is the last one, just above the error line. Read it bottom-up.', NULL, 'Like scrolling a chat: the newest message is at the bottom.', 7);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 1, 'code_output', 'What does this print?', 'scores = {"alice": 90}\nprint(scores["bob"])', 'python', 'KeyError', 'Square brackets on a dict demand that the key exists.', '`d[key]` raises KeyError when the key is missing. It does not return None (that is what `.get` does).', NULL, NULL, 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'IndexError', 0), (@q, 'B', '0', 0), (@q, 'C', 'KeyError', 1), (@q, 'D', 'None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 1, 'code_output', 'What does this print?', 'nums = [10, 20, 30]\nprint(nums[3])', 'python', 'IndexError', 'Python counts positions from 0.', 'The valid positions are 0, 1, 2. Position 3 is past the end, so Python raises IndexError.', 'index:  0    1    2\nvalue: 10   20   30\n               nums[3] -> off the end', 'Like arr[3] on a 3-element array in Java (ArrayIndexOutOfBoundsException), except JavaScript would quietly give undefined.', 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', 'IndexError', 1), (@q, 'C', 'None', 0), (@q, 'D', '30', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 1, 'code_output', 'What does this print?', 'print(int("3.5"))', 'python', 'ValueError', 'int() on a string only accepts whole-number text.', 'int() parses the string as an integer literal; ''3.5'' isn''t one, so ValueError. Use int(float(''3.5'')) if you want 3.', NULL, NULL, 10);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3.5', 0), (@q, 'B', '3', 0), (@q, 'C', 'ValueError', 1), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 1, 'code_output', 'What does this print?', 'scores = {"alice": 90}\nprint(scores.get("bob"))', 'python', 'None', '.get is the polite version of square brackets.', '`dict.get(key)` returns None (or the default you pass) instead of raising KeyError.', NULL, 'Like optional chaining `obj?.bob` in JavaScript: no crash, just nothing.', 11);
