INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 1, 'code_output', 'What does this print?', 'name = "ravi"\nprint(name.shout())', 'python', 'AttributeError', 'The variable exists; the thing after the dot does not.', 'Strings have no method called shout, so looking it up raises AttributeError. NameError is for a variable name that doesn''t exist at all.', NULL, NULL, 12);
