INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 1, 'mcq', 'You type `print(totl)` but your variable is called `total`. Which error do you get?', NULL, NULL, 'NameError', 'Python is looking for a variable it has never seen.', 'NameError: name ''totl'' is not defined. A typo in a variable name is the most common cause.', NULL, NULL, 13);
