INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 1, 'code_output', 'What does this print?', 'try:\n    n = int("ten")\nexcept ValueError:\n    n = 0\nprint(n)', 'python', '0', 'The except block gives n a fallback value.', 'int(''ten'') raises ValueError, the except block catches it and sets n = 0, then the program continues.', NULL, NULL, 14);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', 'ten', 0), (@q, 'C', '0', 1), (@q, 'D', '10', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 1, 'code_output', 'What does this print?', 'try:\n    print("A")\n    x = int("5")\n    print("B")\nexcept ValueError:\n    print("C")', 'python', 'A\nB', 'Does int(''5'') actually fail?', '''5'' is a valid integer, so nothing is raised: both prints in try run and the except block is skipped.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'C', 0), (@q, 'B', 'A\nB', 1), (@q, 'C', 'A\nB\nC', 0), (@q, 'D', 'A\nC', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 1, 'true_false', 'If line 2 of a try block raises an error, lines 3 and 4 of that try block still run before the except block.', NULL, NULL, 'False', 'Think of an exception as an emergency exit.', 'The moment a line raises, Python jumps straight to the matching except. The rest of the try block is skipped.', NULL, NULL, 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'try-except'), 1, 'fill_blank', 'JavaScript and Java use `catch`. In Python the matching keyword is `_____`.', NULL, NULL, 'except', 'It''s the word that follows a try block.', 'Python spells it `try: ... except SomeError: ...`.', NULL, NULL, 17);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'catching'), 1, 'mcq', 'Why do experienced developers avoid a bare `except:` (with no error type)?', NULL, NULL, 'It catches everything, even Ctrl+C and typos in your code, so real bugs get hidden', 'What happens if the error is a bug you didn''t expect?', 'A bare except catches every exception, including NameError from typos and KeyboardInterrupt from Ctrl+C. Catch the specific error you can handle instead.', NULL, 'Like `catch (Throwable t) {}` in Java: it compiles, but it swallows things you never meant to swallow.', 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It catches everything, even Ctrl+C and typos in your code, so real bugs get hidden', 1), (@q, 'B', 'It makes the code run slower', 0), (@q, 'C', 'It only catches ValueError', 0), (@q, 'D', 'It is a syntax error in Python 3', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 1, 'code_output', 'What does this print?', 'def set_age(age):\n    if age < 0:\n        raise ValueError("age must be >= 0")\n    return age\n\ntry:\n    set_age(-1)\nexcept ValueError as e:\n    print(e)', 'python', 'age must be >= 0', '`as e` gives you the error object; printing it shows its message.', 'raise creates the ValueError with a message; `print(e)` prints just that message.', NULL, NULL, 19);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'None', 0), (@q, 'B', '-1', 0), (@q, 'C', 'age must be >= 0', 1), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'raising'), 1, 'fill_blank', 'To signal an error yourself (like `throw` in JavaScript), you write `_____ ValueError("bad input")`.', NULL, NULL, 'raise', 'Python doesn''t use the word throw.', '`raise` is Python''s throw: `raise ValueError(''bad input'')`.', NULL, NULL, 20);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'custom-exceptions'), 1, 'mcq', 'What is the usual way to create your own error type?', NULL, NULL, 'class ConfigError(Exception): pass', 'Your own error is just a class that extends a built-in one.', 'A custom exception is a class inheriting from Exception. `pass` is enough; it already has a message.', NULL, NULL, 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'error ConfigError', 0), (@q, 'B', 'class ConfigError(Exception): pass', 1), (@q, 'C', 'def ConfigError(): raise', 0), (@q, 'D', 'ConfigError = Error()', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 1, 'mcq', 'What is the main benefit of `with open("data.csv") as f:` over `f = open("data.csv")`?', NULL, NULL, 'The file is closed automatically when the block ends, even if an error happens', 'What do people forget to call at the end?', '`with` guarantees f.close() runs when the indented block finishes, whether normally or by an exception.', NULL, 'Like Java try-with-resources: the resource is released for you.', 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It stops the file from being found if it doesn''t exist', 0), (@q, 'B', 'It loads the whole file into memory', 0), (@q, 'C', 'The file is closed automatically when the block ends, even if an error happens', 1), (@q, 'D', 'It reads the file faster', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'context-managers'), 1, 'code_output', 'What does this print?', 'import io\n\nwith io.StringIO("hello") as f:\n    print(f.read())\nprint(f.closed)', 'python', 'hello\nTrue', 'StringIO behaves like a file that lives in memory. What does `with` do at the end?', 'Inside the block we read ''hello''. Leaving the block closes the file-like object, so f.closed is True.', NULL, NULL, 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'hello\nTrue', 1), (@q, 'B', 'hello', 0), (@q, 'C', 'hello\nFalse', 0), (@q, 'D', 'True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'assert-warnings'), 1, 'code_output', 'What does this print?', 'x = 5\nassert x > 0\nprint("ok")', 'python', 'ok', 'assert only complains when the condition is False.', 'x > 0 is True, so assert does nothing and the program continues.', NULL, NULL, 24);
