INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'debugging'), 2, 'code_output', 'What does this print?', 'import logging, sys\n\nlog = logging.getLogger("quiz_default_level")\nlog.addHandler(logging.StreamHandler(sys.stdout))\nlog.propagate = False\n\nlog.debug("d")\nlog.info("i")\nlog.warning("w")', 'python', 'w', 'No level was set, so the logger inherits the root logger''s default.', 'The default level is WARNING, so debug and info are dropped and only ''w'' prints. Call log.setLevel(logging.DEBUG) to see more.', NULL, NULL, 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'nothing is printed', 0), (@q, 'B', 'i\nw', 0), (@q, 'C', 'd\ni\nw', 0), (@q, 'D', 'w', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'debugging'), 2, 'mcq', 'Which list is the logging levels from least to most severe?', NULL, NULL, 'DEBUG < INFO < WARNING < ERROR < CRITICAL', 'Debug is the chattiest.', 'DEBUG (10), INFO (20), WARNING (30), ERROR (40), CRITICAL (50). A logger shows its level and above.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'DEBUG < WARNING < INFO < ERROR < CRITICAL', 0), (@q, 'B', 'DEBUG < INFO < WARNING < ERROR < CRITICAL', 1), (@q, 'C', 'TRACE < DEBUG < INFO < ERROR < FATAL', 0), (@q, 'D', 'INFO < DEBUG < WARNING < ERROR < CRITICAL', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'debugging'), 2, 'mcq', 'Why use `logging` instead of `print` in a training script that runs on a server overnight?', NULL, NULL, 'Levels, timestamps and file output can be configured without editing every line', 'Think about turning noise up and down later.', 'logging lets you filter by level, add timestamps and module names, and send output to files, all from one config. With print you''d have to edit or delete every line.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'logging is faster than print for every message', 0), (@q, 'B', 'Levels, timestamps and file output can be configured without editing every line', 1), (@q, 'C', 'print is not allowed in Python scripts', 0), (@q, 'D', 'print output can''t be redirected to a file', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tracebacks'), 3, 'code_output', 'What does this print?', 'import traceback\n\ntry:\n    {}["x"]\nexcept KeyError:\n    text = traceback.format_exc()\nprint(text.strip().splitlines()[-1])', 'python', 'KeyError: ''x''', 'format_exc returns the same text Python would have printed.', 'traceback.format_exc() gives the full traceback as a string; its last line is `KeyError: ''x''` (KeyError shows the key with repr quotes). Handy for logging a caught error.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Traceback (most recent call last):', 0), (@q, 'B', 'KeyError', 0), (@q, 'C', 'KeyError: x', 0), (@q, 'D', 'KeyError: ''x''', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tracebacks'), 3, 'mcq', 'A traceback contains two errors separated by: ''During handling of the above exception, another exception occurred:''. What happened?', NULL, NULL, 'Code inside an except block raised a new error while handling the first one', 'The second error is linked to the first automatically.', 'Raising inside an except block chains the errors implicitly (__context__). With an explicit `raise New from old` the message says ''The above exception was the direct cause...'' instead.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The first error was raised with `raise ... from ...`', 0), (@q, 'B', 'The same error was raised twice in a loop', 0), (@q, 'C', 'Code inside an except block raised a new error while handling the first one', 1), (@q, 'D', 'Python could not find the source file', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 3, 'code_output', 'What does this print?', 'count = 0\n\ndef inc():\n    count += 1\n\ninc()', 'python', 'UnboundLocalError', 'An assignment anywhere in a function makes that name local to the whole function.', 'Because count is assigned inside inc, Python treats it as local, and `count += 1` reads it before it has a value. UnboundLocalError (a subclass of NameError). Fix with `global count` or, better, pass and return values.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'NameError', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', '1', 0), (@q, 'D', 'UnboundLocalError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 3, 'code_output', 'What does this print?', 'print(issubclass(ModuleNotFoundError, ImportError), issubclass(KeyError, LookupError))', 'python', 'True True', 'The built-in exceptions form a family tree.', 'ModuleNotFoundError (no module of that name) is a subclass of ImportError; KeyError and IndexError are both LookupErrors.', NULL, NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True', 1), (@q, 'B', 'True False', 0), (@q, 'C', 'False False', 0), (@q, 'D', 'False True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'builtin-errors'), 3, 'code_output', 'What does this print?', 'def f(n):\n    return f(n + 1)\n\nf(0)', 'python', 'RecursionError', 'Python has a guard against infinite recursion.', 'When the call depth passes sys.getrecursionlimit() (about 1000), Python raises RecursionError, a subclass of RuntimeError.', NULL, NULL, 53);
