INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 1, 'mcq', 'A chat LLM that writes new text is an example of:', NULL, NULL, 'Generative AI (built with deep learning)', 'It generates new content.', 'Chat LLMs are deep neural networks that generate content, i.e. generative AI.', NULL, NULL, 17);
