INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 2, 'mcq', 'In a typical real-world ML project, where does most of the time go?', NULL, NULL, 'Collecting, cleaning and understanding data', 'Garbage in, garbage out.', 'Data work (getting labels, cleaning, fixing errors, building features) usually dominates. Model choice is often the smaller part.', NULL, NULL, 31);
