INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 2, 'true_false', 'A hospital needs a dosage calculator that must be exactly correct every time for a known formula. ML is a good fit here.', NULL, NULL, 'False', 'ML gives statistical answers, not guaranteed ones.', 'When the formula is known and errors are unacceptable, use the formula. ML is right when the rule is unknown and some error is OK.', NULL, NULL, 34);
