INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 2, 'mcq', 'A model scores 100% on its training data and 61% on new data. What is most likely happening?', NULL, NULL, 'It memorised the training data (overfitting)', 'Big gap between train and unseen performance.', 'A big train/test gap means the model learned quirks of the training set rather than the real pattern.', NULL, 'Like unit tests that hard-code the expected outputs: all green, but the code is still wrong.', 36);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It memorised the training data (overfitting)', 1), (@q, 'B', 'It is underfitting', 0), (@q, 'C', 'It is a perfect model', 0), (@q, 'D', 'The new data is too easy', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.tree import DecisionTreeRegressor\nfrom sklearn.model_selection import train_test_split\nrng = np.random.default_rng(0)\nX = rng.uniform(0, 10, size=(200, 1))\ny = np.sin(X[:, 0]) + rng.normal(0, 0.5, 200)\nXtr, Xte, ytr, yte = train_test_split(X, y, random_state=0)\nt = DecisionTreeRegressor(random_state=0).fit(Xtr, ytr)\nprint(t.score(Xtr, ytr), t.score(Xte, yte) < 0.9)', 'python', '1.0 True', 'An unlimited-depth tree can give every training point its own leaf.', 'An unpruned tree memorises the noisy training data (R^2 = 1.0) but scores clearly worse on held-out data.', NULL, NULL, 37);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1.0 True', 1), (@q, 'B', '0.5 True', 0), (@q, 'C', '1.0 False', 0), (@q, 'D', '0.9 False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 2, 'code_output', 'What does this print?', 'from sklearn.linear_model import LogisticRegression\nfrom sklearn.tree import DecisionTreeClassifier\nX = [[0, 0], [0, 1], [1, 0], [1, 1]]\ny = [0, 1, 1, 0]\nlin = LogisticRegression().fit(X, y).score(X, y)\ntree = DecisionTreeClassifier(random_state=0).fit(X, y).score(X, y)\nprint(lin, tree)', 'python', '0.5 1.0', 'XOR can''t be separated by a single straight line.', 'Logistic regression assumes a straight decision boundary, which can''t separate XOR (it gets 0.5). A tree''s axis-aligned splits can.', ' x2\n 1 | 1   0      no single line puts\n 0 | 0   1      both 1s on one side\n   +-------- x1\n     0   1', NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.5 1.0', 1), (@q, 'B', '1.0 0.5', 0), (@q, 'C', '1.0 1.0', 0), (@q, 'D', '0.75 0.75', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.neighbors import KNeighborsRegressor\nrng = np.random.default_rng(0)\nfor n in (100, 10000):\n    X = rng.normal(size=(n, 3)); y = X.sum(axis=1)\n    lr = LinearRegression().fit(X, y)\n    knn = KNeighborsRegressor().fit(X, y)\n    print(lr.coef_.size, knn.n_samples_fit_)', 'python', '3 100\n3 10000', 'One model stores weights; the other stores the training rows.', 'Linear regression keeps 3 weights whatever n is (parametric). kNN keeps every training sample to search at predict time (non-parametric).', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3 100\n3 10000', 1), (@q, 'B', '3 3\n3 3', 0), (@q, 'C', '100 100\n10000 10000', 0), (@q, 'D', '3 100\n3 100', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 2, 'code_output', 'What does this print?', 'from sklearn.dummy import DummyClassifier\nimport numpy as np\nX = np.zeros((100, 1))\ny = np.array([0] * 95 + [1] * 5)\nd = DummyClassifier(strategy="most_frequent").fit(X, y)\nprint(d.score(X, y))', 'python', '0.95', 'It always predicts the most common class.', 'Predicting ''not fraud'' for everyone already scores 95% accuracy. Any real model must beat this baseline, and accuracy is a poor metric here.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.05', 0), (@q, 'B', '1.0', 0), (@q, 'C', '0.95', 1), (@q, 'D', '0.5', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 2, 'mcq', 'An e-commerce site wants to ''reduce returns''. Which is the best-framed ML task?', NULL, NULL, 'At checkout, predict the probability this order will be returned within 30 days', 'A good framing says when you predict, what exactly, and over what window.', 'A precise framing fixes the prediction point (checkout), the target (returned or not) and the window (30 days).', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Predict returns', 0), (@q, 'B', 'Cluster all products', 0), (@q, 'C', 'Use AI to improve returns', 0), (@q, 'D', 'At checkout, predict the probability this order will be returned within 30 days', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 3, 'mcq', 'A learned model says a transaction is ''fraud'' with 0.97 probability. How should an engineer treat that output compared with a hand-written rule?', NULL, NULL, 'As a statistical estimate that can be wrong and needs evaluation and monitoring', 'Learned rules come from patterns in past data.', 'Model outputs are estimates from past data. They can be confidently wrong, especially on inputs unlike the training data.', NULL, NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'As something that never changes', 0), (@q, 'B', 'As less reliable than any rule', 0), (@q, 'C', 'As a guaranteed fact, because it was learned from data', 0), (@q, 'D', 'As a statistical estimate that can be wrong and needs evaluation and monitoring', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 3, 'mcq', 'Where should hyperparameters like max_depth be tuned?', NULL, NULL, 'On a validation set (or with cross-validation on the training data)', 'The test set must stay untouched until the very end.', 'Tuning on the test set leaks it into your choices, so the final score is optimistic. Tune with validation or cross-validation.', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'On the training set score alone', 0), (@q, 'B', 'On the test set', 0), (@q, 'C', 'On a validation set (or with cross-validation on the training data)', 1), (@q, 'D', 'They should never be tuned', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 3, 'mcq', 'Which of these is a hyperparameter of kNN, not a parameter?', NULL, NULL, 'k, the number of neighbours', 'What do you pass to the constructor?', 'k is chosen by you (n_neighbors). kNN has no learned weights; it stores the data and uses k at predict time.', NULL, NULL, 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The distance between two specific points', 0), (@q, 'B', 'The stored training points', 0), (@q, 'C', 'The predicted label', 0), (@q, 'D', 'k, the number of neighbours', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 3, 'mcq', 'A recommendation model is retrained nightly on a GPU cluster, then serves 50,000 requests per second. Which concern belongs to inference rather than training?', NULL, NULL, 'Latency per request (e.g. under 20 ms)', 'What does the user waiting for a response care about?', 'Inference is about latency, throughput and cost per request. Epochs, learning rates and dataset size are training concerns.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Latency per request (e.g. under 20 ms)', 1), (@q, 'B', 'Number of epochs', 0), (@q, 'C', 'Size of the training dataset', 0), (@q, 'D', 'Learning rate schedule', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 3, 'mcq', 'Why should you build a dumb baseline (majority class, last value, a simple rule) before a complex model?', NULL, NULL, 'It shows whether the complex model adds real value and catches pipeline bugs', 'How would you know your 92% accuracy is good?', 'If a baseline already gets 90%, your 92% model may not be worth the cost. A model that loses to the baseline usually has a bug.', NULL, 'Like benchmarking a new service against the old one before migrating.', 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It makes training faster', 0), (@q, 'B', 'It shows whether the complex model adds real value and catches pipeline bugs', 1), (@q, 'C', 'Complex models need a baseline to train', 0), (@q, 'D', 'Baselines are always good enough', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 3, 'true_false', 'If monitoring shows the input data in production has drifted away from the training data, the usual fix is to retrain on recent data, which sends you back into the workflow loop.', NULL, NULL, 'True', 'The workflow is a cycle, not a line.', 'Drift is caught by monitoring and triggers retraining (and sometimes re-framing), closing the loop.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 3, 'mcq', 'A team is deciding between a hand-tuned heuristic that gets 88% and an ML model that gets 89%. Which factor most strongly favours the heuristic?', NULL, NULL, 'The ML model needs data pipelines, retraining and monitoring for a 1-point gain', 'ML has an ongoing running cost.', 'ML systems carry maintenance cost (data, retraining, monitoring, debugging). A tiny gain rarely justifies it.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ML models can''t reach 89%', 0), (@q, 'B', 'Heuristics can''t be tested', 0), (@q, 'C', 'The ML model needs data pipelines, retraining and monitoring for a 1-point gain', 1), (@q, 'D', 'The heuristic is older', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 3, 'mcq', 'Which is the strongest reason NOT to use ML for a decision?', NULL, NULL, 'Each decision must be fully explainable by a fixed, auditable rule', 'Three of these are reasons FOR ML.', 'Lots of data, complex patterns and high volume favour ML. A hard requirement for exact, auditable rules favours explicit logic.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The pattern is complex', 0), (@q, 'B', 'Each decision must be fully explainable by a fixed, auditable rule', 1), (@q, 'C', 'The task is repeated millions of times', 0), (@q, 'D', 'You have lots of labelled data', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 3, 'mcq', 'GPT-style LLMs are best described as:', NULL, NULL, 'Deep learning models trained to generate text by predicting the next token', 'What does the model actually output at each step?', 'An LLM is a deep neural network (transformer) that generates text one token at a time, learned from huge amounts of text.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Unsupervised clustering models', 0), (@q, 'B', 'Classical ML models like decision trees', 0), (@q, 'C', 'Deep learning models trained to generate text by predicting the next token', 1), (@q, 'D', 'Rule-based systems with a huge dictionary', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 3, 'mcq', 'A model is too simple for the problem (e.g. a straight line for a curved pattern). Adding 10x more training data will:', NULL, NULL, 'Barely help, because the model still can''t represent the curve (high bias)', 'Is the problem the amount of data or what the model can express?', 'More data reduces variance, not bias. A straight line stays a straight line however much data you give it.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Make it overfit', 0), (@q, 'B', 'Fix it completely', 0), (@q, 'C', 'Make training error go to zero', 0), (@q, 'D', 'Barely help, because the model still can''t represent the curve (high bias)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 3, 'mcq', 'Which pair correctly matches the problem with the fix?', NULL, NULL, 'High variance -> more data or stronger regularisation; high bias -> a more flexible model or better features', 'Variance = over-reacting to the sample; bias = too-simple assumptions.', 'Overfitting (variance) is reduced by more data or constraints; underfitting (bias) needs more capacity or more informative features.', ' error\n  |\\                 /  total\n  | \\  bias^2    __/\n  |  \\_______ _/  variance\n  +------------------> model complexity\n     underfit   sweet   overfit', NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'High variance -> fewer training examples; high bias -> more regularisation', 0), (@q, 'B', 'High variance -> a more flexible model; high bias -> more data', 0), (@q, 'C', 'High variance -> more data or stronger regularisation; high bias -> a more flexible model or better features', 1), (@q, 'D', 'Both are fixed only by training longer', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.tree import DecisionTreeRegressor\nX = np.arange(10).reshape(-1, 1)\ny = 2 * X[:, 0]\nlr = LinearRegression().fit(X, y)\ndt = DecisionTreeRegressor().fit(X, y)\nprint(round(lr.predict([[20]])[0]), dt.predict([[20]])[0])', 'python', '40 18.0', 'x = 20 is outside the training range 0..9.', 'The linear model assumes a line and extrapolates to 40. A tree can only output values it saw in a leaf, so it returns 18 (the last leaf).', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '40 18.0', 1), (@q, 'B', '18 18.0', 0), (@q, 'C', '20 20.0', 0), (@q, 'D', '40 40.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 3, 'mcq', 'Which statement describes kNN''s inductive bias?', NULL, NULL, 'Points that are close together in feature space tend to have the same label', 'How does kNN make a prediction?', 'kNN predicts from the nearest training points, so it assumes nearby means similar. Linear = line; Naive Bayes = independence; CNN = locality.', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Features are independent given the class', 0), (@q, 'B', 'The output is a linear function of the inputs', 0), (@q, 'C', 'Nearby pixels matter more than distant ones', 0), (@q, 'D', 'Points that are close together in feature space tend to have the same label', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 3, 'true_false', 'A k-nearest-neighbours model does almost no work in fit and most of its work in predict.', NULL, NULL, 'True', 'What does kNN store, and when does it search?', 'kNN is a ''lazy learner'': fit just stores the data; predict computes distances to the stored points. That''s why its inference is slow on big data.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 3, 'mcq', 'Which of these models is non-parametric?', NULL, NULL, 'A decision tree with no depth limit', 'Which one can keep growing as you add more data?', 'An unlimited tree adds more splits and leaves as data grows. The others have a size fixed before training.', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Logistic regression', 0), (@q, 'B', 'Linear regression', 0), (@q, 'C', 'A neural network with a fixed architecture', 0), (@q, 'D', 'A decision tree with no depth limit', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 3, 'mcq', 'A bank wants to catch fraud. Missing a fraud costs about 50,000 rupees; flagging a good transaction costs about 50 rupees of support time. Which metric fits best?', NULL, NULL, 'Recall on fraud (at an acceptable precision), or expected cost', 'Which mistake is 1000x more expensive?', 'Misses are very costly, so you care about catching most frauds (recall) while keeping false alarms tolerable, ideally scoring by expected cost.', NULL, NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Recall on fraud (at an acceptable precision), or expected cost', 1), (@q, 'B', 'Mean squared error', 0), (@q, 'C', 'Plain accuracy', 0), (@q, 'D', 'Training loss', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 4, 'mcq', 'A loan-approval product uses an ML risk score, but a lawyer insists some applicants must always be rejected (e.g. under 18). What is the sound design?', NULL, NULL, 'Hard rules as guardrails before/after the model, with the model handling the fuzzy cases', 'Some requirements are not statistical.', 'Legal or safety invariants should be enforced by deterministic code. A model can learn ''usually'', never ''always''.', NULL, 'Like validation in a backend: you don''t trust the client, you enforce the invariant on the server.', 58);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Hard rules as guardrails before/after the model, with the model handling the fuzzy cases', 1), (@q, 'B', 'Add age as a feature and trust the model to learn the rule', 0), (@q, 'C', 'Drop the model and only use rules', 0), (@q, 'D', 'Retrain until the model never approves minors', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 4, 'mcq', 'You try 200 hyperparameter settings and pick the one with the best validation score. Why might that score still be optimistic?', NULL, NULL, 'You overfit to the validation set by selecting the luckiest setting; a separate test set (or nested CV) is needed', 'Selection itself is a form of fitting.', 'Picking the max of many noisy scores biases the result upwards. Keep an untouched test set or use nested cross-validation for an honest estimate.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'You overfit to the validation set by selecting the luckiest setting; a separate test set (or nested CV) is needed', 1), (@q, 'B', '200 trials is too few to matter', 0), (@q, 'C', 'Validation scores are always pessimistic', 0), (@q, 'D', 'Hyperparameters don''t affect generalisation', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 4, 'mcq', 'A model scores well offline, but in production its accuracy is much lower. Investigation shows the training pipeline computed ''average order value'' with pandas, while the serving code recomputes it in Java with a different rounding and time window. This is:', NULL, NULL, 'Training-serving skew', 'The same feature is computed differently in two places.', 'When features are computed differently at train and serve time, the model sees inputs it wasn''t trained on. Share one feature pipeline (or a feature store).', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Overfitting', 0), (@q, 'B', 'Class imbalance', 0), (@q, 'C', 'Training-serving skew', 1), (@q, 'D', 'Underfitting', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 4, 'mcq', 'A news app''s model ranks articles; it is retrained every week on what users clicked. Over months, it shows mostly one type of article and the click data reflects only that. What has gone wrong?', NULL, NULL, 'A feedback loop: the model''s own outputs now shape its training labels', 'Where does the training data come from?', 'Users can only click what the model showed them, so the labels are biased by past predictions. Add exploration or log what was shown, not just what was clicked.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Training-serving skew', 0), (@q, 'B', 'A feedback loop: the model''s own outputs now shape its training labels', 1), (@q, 'C', 'Overfitting to the test set', 0), (@q, 'D', 'The learning rate is too high', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 4, 'true_false', 'A deployed model can degrade silently: the service keeps returning 200 OK with valid-looking predictions while accuracy drops.', NULL, NULL, 'True', 'ML failures aren''t exceptions.', 'Unlike a crash, a wrong prediction looks normal. That''s why you monitor input distributions, prediction distributions and, when labels arrive, real accuracy.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 4, 'mcq', 'Why is ML a risky fit for spam/fraud detection compared with, say, weather forecasting?', NULL, NULL, 'The data is adversarial: attackers change behaviour to beat the model, so the distribution shifts on purpose', 'The weather doesn''t try to fool your forecast.', 'Adversaries probe and adapt, so a model decays faster and must be paired with rules, fast retraining and monitoring.', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The data is adversarial: attackers change behaviour to beat the model, so the distribution shifts on purpose', 1), (@q, 'B', 'There''s never any labelled data', 0), (@q, 'C', 'The costs of errors are always zero', 0), (@q, 'D', 'The patterns are too simple', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 4, 'true_false', 'Because ''AI'' appears in a product''s name, it must contain a model learned from data.', NULL, NULL, 'False', 'Recall what counts as AI but not ML.', 'Plenty of ''AI'' features are rules, search or heuristics. AI is the goal; ML is just one way to reach it.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 4, 'mcq', 'For squared-error regression, the expected test error at a point can be split into which three parts?', NULL, NULL, 'bias^2 + variance + irreducible noise', 'One part can''t be removed by any model.', 'Bias^2 (wrong assumptions) + variance (sensitivity to the sample) + noise (randomness in the labels themselves).', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'bias^2 + variance + irreducible noise', 1), (@q, 'B', 'training error + validation error + test error', 0), (@q, 'C', 'precision + recall + F1', 0), (@q, 'D', 'bias + variance - noise', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 4, 'true_false', 'Given enough data and a powerful enough model, test error can always be driven to zero.', NULL, NULL, 'False', 'What if two identical inputs have different true outcomes?', 'Irreducible noise remains: if the label isn''t fully determined by the features (e.g. same profile, different outcome), no model can be perfect.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 4, 'mcq', 'What does the No Free Lunch theorem actually say?', NULL, NULL, 'Averaged over ALL possible problems, every learning algorithm performs the same; any advantage comes from matching assumptions to a problem class', 'It''s a statement about an average over every imaginable problem.', 'NFL doesn''t say algorithms are equal on YOUR problem. It says no algorithm wins everywhere, so you choose one whose inductive bias fits the data.', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Deep learning is always the best algorithm', 0), (@q, 'B', 'All algorithms perform equally on every real dataset', 0), (@q, 'C', 'You can''t get good results without paying for cloud compute', 0), (@q, 'D', 'Averaged over ALL possible problems, every learning algorithm performs the same; any advantage comes from matching assumptions to a problem class', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 4, 'mcq', 'Convolutional neural networks work well on images mainly because their architecture builds in which inductive bias?', NULL, NULL, 'Locality and translation equivariance: nearby pixels matter together and a pattern means the same thing anywhere', 'A small filter slides across the whole image with the same weights.', 'Small shared filters assume local structure and that a cat''s ear is an ear wherever it appears. That''s the assumption that matches images.', NULL, NULL, 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Every pixel is equally related to every other pixel', 0), (@q, 'B', 'Feature independence', 0), (@q, 'C', 'Linear separability', 0), (@q, 'D', 'Locality and translation equivariance: nearby pixels matter together and a pattern means the same thing anywhere', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 4, 'true_false', 'A transformer with 70 billion weights is a non-parametric model because it has so many parameters.', NULL, NULL, 'False', 'Parametric is about whether the size grows with the data, not how big it is.', 'Its number of weights is fixed by the architecture before training, so it''s parametric, just very large.', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 4, 'true_false', '''Non-parametric'' means the model has no parameters at all.', NULL, NULL, 'False', 'Think of a decision tree''s thresholds.', 'Non-parametric models do have parameters (tree thresholds, stored points); their NUMBER grows with the data rather than being fixed.', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 4, 'mcq', 'A support team is rewarded on ''average ticket close time'', which a model is trained to predict and minimise. Agents start closing tickets early without solving them. This is an example of:', NULL, NULL, 'Goodhart''s law: a proxy metric stops measuring what you care about once you optimise it', 'When a measure becomes a target...', 'The proxy (close time) diverged from the goal (solved problems). Choose targets and guard-rail metrics that are hard to game.', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Goodhart''s law: a proxy metric stops measuring what you care about once you optimise it', 1), (@q, 'B', 'Overfitting', 0), (@q, 'C', 'Training-serving skew', 0), (@q, 'D', 'Data leakage', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 4, 'mcq', 'A churn model gets 0.99 AUC offline. One feature is ''number of support calls in the 30 days after the prediction date''. What is wrong?', NULL, NULL, 'Label leakage: the feature uses information from the future that won''t exist at prediction time', 'Ask: would this value be known at the moment you make the prediction?', 'Features must be computed only from data available at the prediction point. Future information makes offline scores great and production useless.', ' past data  | prediction point |  future (label window)\n features OK|        ^         |  NOT allowed as features', NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Label leakage: the feature uses information from the future that won''t exist at prediction time', 1), (@q, 'B', 'The model is underfitting', 0), (@q, 'C', 'AUC can''t be 0.99', 0), (@q, 'D', 'Nothing, it''s a strong feature', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 4, 'fill_blank', 'The principle ''when a measure becomes a target, it ceases to be a good measure'' is called ____''s law.', NULL, NULL, 'Goodhart', 'Named after a British economist.', 'Goodhart''s law: optimising a proxy hard enough makes it drift from the real goal (e.g. clicks -> clickbait).', NULL, NULL, 73);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 1, 'true_false', 'In an ML project you still write plenty of code; the part you don''t hand-write is the decision logic inside the model.', NULL, NULL, 'True', 'Who writes the data loading, the API and the tests?', 'You still write pipelines, training scripts, serving code and tests. Only the mapping from input to prediction is learned from examples instead of typed as if-statements.', NULL, NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 1, 'code_output', 'Train once, predict many. What does this print?', 'from sklearn.linear_model import LinearRegression\nm = LinearRegression().fit([[1], [2], [3]], [2, 4, 6])\nprint(m.predict([[5], [6]]).round(1))', 'python', '[10. 12.]', 'The model learned y = 2x once. Now it is just used.', 'Training found the rule y = 2x. Inference applies the frozen rule to any number of new inputs: 2*5 = 10 and 2*6 = 12. predict returns floats, so NumPy prints `10.` and `12.`.', NULL, NULL, 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2. 4.]', 0), (@q, 'B', '[10. 12.]', 1), (@q, 'C', '[10 12]', 0), (@q, 'D', '[5. 6.]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 1, 'mcq', 'In a table of houses with columns size, bedrooms, city and price, what are size, bedrooms and city called when you predict price?', NULL, NULL, 'Features: the inputs the model uses', 'They are what the model gets to look at.', 'Features are the input columns (X). The column you predict (price) is the label or target (y). Weights are what the model learns; hyperparameters are knobs you set.', ' size  bedrooms  city  | price\n 120   3         BLR   | 95 L\n \\_____ features (X) _/   label (y)', NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Weights', 0), (@q, 'B', 'Hyperparameters', 0), (@q, 'C', 'Labels: the answers', 0), (@q, 'D', 'Features: the inputs the model uses', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 1, 'code_output', 'This business rule needs no ML at all. What does it print?', 'def shipping_fee(order_total):\n    return 0 if order_total >= 500 else 40\n\nprint(shipping_fee(499), shipping_fee(500))', 'python', '40 0', 'Follow the if-rule exactly; 500 counts as ''at least 500''.', 'A business rule like ''free shipping from 500'' is exact and known. Plain code does it perfectly; training a model to guess it would only add errors and cost.', NULL, NULL, 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0 40', 0), (@q, 'B', '40 40', 0), (@q, 'C', '40 0', 1), (@q, 'D', '0 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 1, 'mcq', '''Deep learning'' means machine learning that uses:', NULL, NULL, 'Neural networks with many layers', 'The ''deep'' is about stacking.', 'Deep learning = neural networks with many stacked layers, each building on the one below. It works on text, audio and tables too, not just images.', NULL, 'Like a factory line: each layer (station) turns rough parts into more refined ones, and ''deep'' just means many stations.', 78);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Neural networks with many layers', 1), (@q, 'B', 'Very large spreadsheets', 0), (@q, 'C', 'Only image data', 0), (@q, 'D', 'Rules written by experts', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 1, 'mcq', 'A student memorises the answers to last year''s exam word for word, then fails this year''s exam with new questions. In ML terms the student:', NULL, NULL, 'Overfit: memorised the examples instead of learning the pattern', 'Did the student learn the subject, or the specific questions?', 'Memorising the training examples gives a perfect score on them and a poor one on new cases. Generalising means learning the pattern behind them.', NULL, 'Overfitting is a test suite that only passes because the code hard-codes the expected outputs.', 79);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Overfit: memorised the examples instead of learning the pattern', 1), (@q, 'B', 'Used too much data', 0), (@q, 'C', 'Underfit: learned too little from the examples', 0), (@q, 'D', 'Generalised well', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 1, 'mcq', 'A k-nearest-neighbours model keeps every training example and compares new points to them. If you train it on twice as much data, its saved model:', NULL, NULL, 'Gets about twice as big', 'What does kNN actually store?', 'kNN stores the training data itself, so its size grows with the data. That is what ''non-parametric'' means. A linear model would stay the same size.', 'linear model:  [w1 w2 w3 b]          same size at any n\nkNN:           [row1 row2 ... rowN]  grows with N', NULL, 80);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Gets about twice as big', 1), (@q, 'B', 'Stops working', 0), (@q, 'C', 'Stays exactly the same size', 0), (@q, 'D', 'Gets smaller', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 1, 'mcq', 'A telecom company asks ''will this customer cancel next month?''. What is a sensible label for each training row?', NULL, NULL, 'Yes/No: did that customer cancel in the following month', 'The label is the answer you want the model to predict, taken from history.', 'You take past customers, look at what happened next (cancelled or not) and use that as the label. It is a yes/no (binary classification) target.', NULL, NULL, 81);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The total number of customers', 0), (@q, 'B', 'Yes/No: did that customer cancel in the following month', 1), (@q, 'C', 'The customer''s name', 0), (@q, 'D', 'The model''s accuracy', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genai-lens'), 1, 'mcq', 'Your web app sends a prompt to an LLM API and gets an answer back. In ML terms, that call is:', NULL, NULL, 'Inference: running an already-trained model on new input', 'Did anyone change the model''s weights?', 'The provider trained the model earlier. Your request only runs it forward on your input, which is inference. Your prompt does not become training data at that moment.', NULL, NULL, 82);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Inference: running an already-trained model on new input', 1), (@q, 'B', 'Training the model on your prompt', 0), (@q, 'C', 'Hyperparameter tuning', 0), (@q, 'D', 'Labelling data', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genai-lens'), 1, 'true_false', 'An LLM is a machine-learning model: its behaviour came from training on huge amounts of text, not from rules typed in by hand.', NULL, NULL, 'True', 'Nobody wrote an if-statement for every possible question.', 'LLMs learn their weights from data (predicting the next token, then fine-tuning). That is why they can be wrong in surprising ways, like any learned function.', NULL, NULL, 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 2, 'code_output', 'What does this print?', 'from sklearn.linear_model import Ridge\nX = [[1, 0, 2], [0, 1, 1], [2, 1, 0], [1, 1, 1]]\ny = [3, 2, 4, 3]\nm = Ridge(alpha=1.0).fit(X, y)\nprint(m.alpha, m.coef_.shape)', 'python', '1.0 (3,)', 'alpha is what you set; coef_ is one learned weight per feature.', 'alpha (regularisation strength) is a hyperparameter you passed in. coef_ is learned: one weight per column, so 3 columns gives shape (3,). The underscore marks learned attributes.', NULL, NULL, 84);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(3,) 1.0', 0), (@q, 'B', 'AttributeError', 0), (@q, 'C', '1.0 (3,)', 1), (@q, 'D', '1.0 (4,)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.neighbors import KNeighborsClassifier\nfrom sklearn.model_selection import train_test_split\nrng = np.random.default_rng(0)\nX = rng.normal(size=(400, 2))\ny = (X[:, 0] + X[:, 1] + rng.normal(0, 1.2, 400) > 0).astype(int)\nXtr, Xte, ytr, yte = train_test_split(X, y, random_state=0)\nk1 = KNeighborsClassifier(n_neighbors=1).fit(Xtr, ytr)\nk15 = KNeighborsClassifier(n_neighbors=15).fit(Xtr, ytr)\nprint(k1.score(Xtr, ytr), k15.score(Xte, yte) > k1.score(Xte, yte))', 'python', '1.0 True', 'With k=1, every training point''s nearest neighbour is itself.', 'k=1 scores 1.0 on training data because each point votes for itself, so it memorises the noise. On the test set the smoother k=15 wins (0.78 vs 0.74). The training score said nothing about the test score.', NULL, NULL, 85);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1.0 False', 0), (@q, 'B', '0.78 True', 0), (@q, 'C', '0.5 False', 0), (@q, 'D', '1.0 True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 2, 'mcq', 'Why put the scaler inside a scikit-learn Pipeline with the model, instead of scaling the data once in a notebook?', NULL, NULL, 'The same fitted steps travel with the model, so serving and cross-validation apply them exactly as in training', 'Think about what the production server must repeat.', 'A Pipeline bundles preprocessing and model into one object: fit learns the scaler''s mean/std and the weights together, and predict replays both. That prevents train/serve mismatches and leakage inside cross-validation.', 'fit:     X --> [scaler.fit+transform] --> [model.fit]\npredict: x --> [scaler.transform]     --> [model.predict]\n          one object, saved and loaded together', NULL, 86);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Scalers only work inside pipelines', 0), (@q, 'B', 'It removes the need for a test set', 0), (@q, 'C', 'The same fitted steps travel with the model, so serving and cross-validation apply them exactly as in training', 1), (@q, 'D', 'Pipelines make the model more accurate by themselves', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 2, 'mcq', 'A PM wants ML to detect duplicate signups. Nobody has labelled duplicates, and ''same verified email or same phone number'' already catches 99% of them. Best first move?', NULL, NULL, 'Ship the rule, log the cases it misses, and revisit ML only if those misses matter', 'What does a simple rule already give you?', 'A cheap exact rule covers almost everything. Logging its misses also produces labelled examples, which you would need anyway if ML is ever justified.', NULL, NULL, 87);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Ship the rule, log the cases it misses, and revisit ML only if those misses matter', 1), (@q, 'B', 'Train a deep model on all signups', 0), (@q, 'C', 'Wait until 1 million duplicates are labelled', 0), (@q, 'D', 'Use clustering and call every cluster a duplicate group', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 2, 'mcq', 'Which of these is machine learning but NOT deep learning?', NULL, NULL, 'A random forest predicting loan default from a table of numbers', 'Which one learns from data without a multi-layer neural network?', 'Random forests learn from data (ML) but are ensembles of decision trees, not neural networks. The transformer and CNN are deep learning; the rule engine is not ML at all.', 'ML (learns from data)\n |-- classic: linear, trees, random forest, kNN\n +-- deep learning: CNN, RNN, transformer', NULL, 88);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A hand-written chess rule engine', 0), (@q, 'B', 'A transformer translating text', 0), (@q, 'C', 'A random forest predicting loan default from a table of numbers', 1), (@q, 'D', 'A convolutional network spotting cats in photos', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 2, 'mcq', 'You fit a linear regression of house price on size. Which assumption have you built in before seeing a single house?', NULL, NULL, 'Each extra square metre adds the same amount to the price, at any size', 'What shape can a linear model draw?', 'That is the inductive bias of a linear model: a constant slope. If the real effect flattens out for huge houses, the model can''t express it unless you add features like size squared.', NULL, NULL, 89);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Price can only take a few fixed values', 0), (@q, 'B', 'Price depends only on the city', 0), (@q, 'C', 'Each extra square metre adds the same amount to the price, at any size', 1), (@q, 'D', 'Big houses are always cheaper', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 2, 'mcq', 'For a model that predicts ''which customers will churn next month'', what should ONE training row usually be?', NULL, NULL, 'One customer at one point in time, with features up to that date and the label from the month after', 'What is the thing you make a prediction about, and when?', 'The unit of prediction is a customer at a snapshot date. Picking it decides what the features and label mean; mixing units (tickets vs customers) quietly breaks the model.', NULL, NULL, 90);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'One support ticket', 0), (@q, 'B', 'One customer at one point in time, with features up to that date and the label from the month after', 1), (@q, 'C', 'One month of the whole company''s data', 0), (@q, 'D', 'One feature column', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genai-lens'), 2, 'mcq', 'In an LLM app, a fixed set of example inputs with the expected (or acceptable) answers that you run after every prompt change is called an eval set. Its closest SDE equivalent is:', NULL, NULL, 'A regression test suite', 'You run it to catch things that used to work and broke.', 'Evals are to models what tests are to code: a change (new prompt, new model version) is only accepted if the scores don''t drop. Without them every prompt tweak is a guess.', NULL, 'Changing a prompt without evals is like refactoring without tests: it ''looks fine'' on the one case you tried.', 91);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A load balancer', 0), (@q, 'B', 'A feature flag', 0), (@q, 'C', 'A regression test suite', 1), (@q, 'D', 'A database index', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 2, 'code_output', 'What does this print?', 'from sklearn.linear_model import LinearRegression\nm = LinearRegression()\nm.fit([[1], [2], [3]], [2, 4, 6])\nm.fit([[1], [2], [3]], [5, 10, 15])\nprint(round(m.coef_[0], 1))', 'python', '5.0', 'Does the second fit continue from the first?', 'In scikit-learn, fit starts over from scratch: the second call throws away the old weights. Only partial_fit (or warm_start on some models) continues learning.', NULL, 'fit is a clean rebuild, not an incremental build.', 92);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '5.0', 1), (@q, 'B', '7.0', 0), (@q, 'C', '3.5', 0), (@q, 'D', '2.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.linear_model import LinearRegression\nrng = np.random.default_rng(0)\nfor n in (50, 5000):\n    X = rng.uniform(-3, 3, size=(n, 1))\n    y = X[:, 0] ** 2 + rng.normal(0, 0.3, n)\n    print(round(LinearRegression().fit(X, y).score(X, y), 1))', 'python', '0.0\n0.0', 'Can a straight line ever fit a U shape, however many points you give it?', 'The data is a parabola; a straight line through a symmetric U is almost flat, so R^2 is about 0 even on training data. 100x more data doesn''t help: this is high bias, and only a more flexible model or a better feature (x^2) fixes it.', NULL, NULL, 93);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.0\n0.9', 0), (@q, 'B', '1.0\n1.0', 0), (@q, 'C', '0.5\n1.0', 0), (@q, 'D', '0.0\n0.0', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.dummy import DummyRegressor\nX = np.zeros((5, 1))\ny = np.array([10.0, 20.0, 30.0, 40.0, 50.0])\nbase = DummyRegressor(strategy="mean").fit(X, y)\nprint(base.predict(X[:1]), base.score(X, y))', 'python', '[30.] 0.0', 'R^2 compares the model with always predicting the mean.', 'The mean baseline always predicts 30, and its R^2 is exactly 0 by definition. Any real model must beat 0; a negative R^2 means it is worse than this one-line baseline.', NULL, NULL, 94);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[30.] 1.0', 0), (@q, 'B', '[50.] 0.5', 0), (@q, 'C', '[30.] 0.0', 1), (@q, 'D', '[10.] 0.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 3, 'code_output', 'What does this print?', 'from sklearn.model_selection import GridSearchCV\nfrom sklearn.neighbors import KNeighborsClassifier\nfrom sklearn.datasets import load_iris\nX, y = load_iris(return_X_y=True)\ngrid = {"n_neighbors": [1, 3, 5], "weights": ["uniform", "distance"]}\ngs = GridSearchCV(KNeighborsClassifier(), grid, cv=5).fit(X, y)\nprint(len(gs.cv_results_["params"]), gs.n_splits_)', 'python', '6 5', 'Count the combinations of the two lists, then the folds.', '3 values x 2 values = 6 hyperparameter combinations, each scored with 5-fold CV: 30 fits, plus one refit of the winner on all data. Hyperparameter search multiplies training cost quickly.', NULL, NULL, 95);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3 5', 0), (@q, 'B', '30 1', 0), (@q, 'C', '6 5', 1), (@q, 'D', '5 6', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 3, 'code_output', 'What does this print?', 'from sklearn.base import clone\nfrom sklearn.linear_model import LinearRegression\nm = LinearRegression(fit_intercept=False).fit([[1], [2]], [2, 4])\nc = clone(m)\nprint(c.get_params()["fit_intercept"], hasattr(c, "coef_"))', 'python', 'False False', 'clone copies the recipe, not the result.', 'clone builds a fresh unfitted estimator with the same hyperparameters (fit_intercept=False) but no learned attributes, so coef_ is missing. Cross-validation uses this to train each fold from scratch.', NULL, 'clone copies the config file, not the compiled binary.', 96);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False False', 1), (@q, 'B', 'False True', 0), (@q, 'C', 'True False', 0), (@q, 'D', 'True True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.tree import DecisionTreeRegressor\nrng = np.random.default_rng(0)\nsizes = []\nfor n in (100, 1000):\n    X = rng.uniform(0, 10, size=(n, 1))\n    y = np.sin(X[:, 0]) + rng.normal(0, 0.3, n)\n    sizes.append(int(DecisionTreeRegressor(random_state=0).fit(X, y).get_n_leaves()))\nprint(sizes)', 'python', '[100, 1000]', 'An unlimited tree keeps splitting until every leaf is pure.', 'With no max_depth, the tree grows one leaf per (distinct) training point, so its size scales with the data. That is non-parametric behaviour, and also why unpruned trees overfit.', NULL, NULL, 97);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[50, 500]', 0), (@q, 'B', '[100, 1000]', 1), (@q, 'C', '[10, 10]', 0), (@q, 'D', '[1, 1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.linear_model import LinearRegression\nx = np.arange(-3, 4).reshape(-1, 1)\ny = x[:, 0] ** 2\nlin = LinearRegression().fit(x, y).score(x, y)\nx2 = np.hstack([x, x ** 2])\nquad = LinearRegression().fit(x2, y).score(x2, y)\nprint(round(lin, 2), round(quad, 2))', 'python', '0.0 1.0', 'The second model gets x squared as an extra input column.', 'A line through a symmetric parabola has slope 0, so R^2 = 0. Adding x^2 as a feature lets the same linear model fit perfectly. Feature engineering changes what a model can express without changing the algorithm.', NULL, NULL, 98);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.0 1.0', 1), (@q, 'B', '0.5 1.0', 0), (@q, 'C', '1.0 1.0', 0), (@q, 'D', '0.0 0.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 3, 'mcq', 'A model that spots potholes was trained only on daytime photos. At night it misses most potholes. What does this say about learned rules?', NULL, NULL, 'They are only reliable inside the kind of data they were trained on; outside it they can fail badly', 'Where did the model ever see a dark pothole?', 'A learned function is a statistical summary of its training data. Inputs from a region it never saw (night) are out of distribution; you need data from that region, not more training on the old data.', '   brightness\n   high | x x x x x x    <- training data (day)\n        |\n   low  |      ?  ?  ?   <- night: never seen\n        +------------------', NULL, 99);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The model has a bug in its code', 0), (@q, 'B', 'Night photos must be labelled wrong', 0), (@q, 'C', 'They are only reliable inside the kind of data they were trained on; outside it they can fail badly', 1), (@q, 'D', 'More epochs on the daytime data will fix it', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rules-vs-learned'), 3, 'true_false', 'A trained neural network is as easy to debug as hand-written rules, because you can print all of its weights.', NULL, NULL, 'False', 'Can you read a bug report out of a list of 10 million floats?', 'You can print weights, but they don''t map to readable reasons. Debugging ML means checking data, slices of errors and evals, not reading the logic line by line. Small trees and linear models are the exception.', NULL, 'Like trying to debug a program by reading the compiled binary: every byte is visible and none of it explains itself.', 100);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 3, 'mcq', 'Which list contains ONLY hyperparameters?', NULL, NULL, 'Learning rate, number of trees, max_depth, regularisation strength C', 'Ask of each item: did I choose it, or did training compute it?', 'Split thresholds, coef_, intercept_ and layer weights are learned (parameters). Learning rate, tree count, depth, C, number of layers and batch size are chosen before training.', NULL, 'Hyperparameters are build flags you set; parameters are the binary the build produces.', 101);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'coef_, intercept_, learning rate', 0), (@q, 'B', 'Learning rate, number of trees, max_depth, regularisation strength C', 1), (@q, 'C', 'Learning rate, the split thresholds of a tree, max_depth', 0), (@q, 'D', 'Number of layers, the layer weights, batch size', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 3, 'mcq', 'Your new recommendation model beats the old one offline. What is the safest way to confirm it helps real users before switching everyone?', NULL, NULL, 'An A/B test (or a shadow run first): send a slice of traffic to the new model and compare business metrics', 'Offline data is history; users react to what you show them.', 'Offline metrics can miss how users respond to new recommendations. A shadow run checks it works on live traffic without showing results; an A/B test measures the real effect.', 'traffic --+--> 95% --> old model --> metrics A\n          +-->  5% --> new model --> metrics B\n             compare A vs B, then roll out', NULL, 102);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Ask the data scientists to vote', 0), (@q, 'B', 'Deploy it to everyone and watch social media', 0), (@q, 'C', 'An A/B test (or a shadow run first): send a slice of traffic to the new model and compare business metrics', 1), (@q, 'D', 'Re-run the offline evaluation five times', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 3, 'true_false', 'A nightly job that retrains the model and automatically deploys it, without comparing it against the current model on a held-out set, is a safe setup.', NULL, NULL, 'False', 'What stops a bad data day from shipping a broken model?', 'Retraining needs a gate: evaluate the new model on held-out data (and key slices) and only promote it if it beats or matches the current one. Otherwise one corrupt data load ships straight to users.', NULL, 'It''s like auto-deploying every commit to production without running CI.', 103);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 3, 'mcq', 'For a ''is this message abusive?'' model, two expert moderators agree on only 55% of the same messages. What does that tell you before any training?', NULL, NULL, 'The labels are too inconsistent; fix the labelling guidelines first, because a model can''t learn a rule humans don''t share', 'What would a ''correct'' answer even mean here?', 'Label agreement caps what any model can achieve and makes evaluation meaningless. Clear guidelines and agreement checks come first; sometimes the honest answer is that the task is not well-defined enough for ML yet.', NULL, NULL, 104);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Drop the experts and use accuracy as the only metric', 0), (@q, 'B', 'Use a bigger model to resolve the disagreement', 0), (@q, 'C', 'This is perfect data for unsupervised learning', 0), (@q, 'D', 'The labels are too inconsistent; fix the labelling guidelines first, because a model can''t learn a rule humans don''t share', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 3, 'mcq', 'A sentiment classifier built on BERT and a chatbot built on GPT are both deep learning. What is the key difference in what they output?', NULL, NULL, 'The classifier outputs a label for the input (discriminative); the chatbot generates new text token by token (generative)', 'One answers ''which class?'', the other writes something new.', 'Discriminative models map input to a label, p(y given x). Generative models produce new content, p(next token given previous). GenAI is the generative part of deep learning.', '+--------------- AI ----------------+\n| rules   +-------- ML ----------+  |\n|         | trees  +---- DL ---+ |  |\n|         |        | BERT clf  | |  |\n|         |        | [GenAI:   | |  |\n|         |        |  GPT]     | |  |\n|         |        +-----------+ |  |\n|         +----------------------+  |\n+-----------------------------------+', NULL, 105);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only the chatbot uses a neural network', 0), (@q, 'B', 'The classifier is rule-based AI', 0), (@q, 'C', 'The classifier outputs a label for the input (discriminative); the chatbot generates new text token by token (generative)', 1), (@q, 'D', 'There is no difference; both generate text', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 3, 'mcq', 'You plot training and validation error against training-set size. Both curves flatten out close together, at a high error. What is the diagnosis?', NULL, NULL, 'High bias: the model is too simple, so more data won''t help; use a more flexible model or better features', 'A small gap means it isn''t memorising. A high floor means...?', 'Curves that meet at a high error mean the model can''t capture the pattern (underfitting). A big gap between low train error and high validation error would mean variance, which more data does help.', 'error\n |  val   \\_______________   <- both high,\n |  train /---------------      small gap\n |\n +------------------------> training size', NULL, 106);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The model is perfect', 0), (@q, 'B', 'High variance: get more data', 0), (@q, 'C', 'High bias: the model is too simple, so more data won''t help; use a more flexible model or better features', 1), (@q, 'D', 'Data leakage', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 3, 'true_false', 'Regularisation (for example a larger alpha in Ridge) usually adds a little bias in exchange for a larger drop in variance.', NULL, NULL, 'True', 'It pulls the weights towards zero. Is that simpler or more complex?', 'Shrinking weights makes the model less flexible (more bias) but much less sensitive to the particular training sample (less variance). Tuning alpha on validation data finds the balance.', NULL, NULL, 107);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 3, 'mcq', 'On tabular business data (mixed numeric and categorical columns, some irrelevant), gradient-boosted trees often beat neural networks. Which explanation fits best?', NULL, NULL, 'Trees'' inductive bias (axis-aligned splits, no need for scaling, ignoring useless columns) matches tables well', 'Think about what shape of function each model finds easy.', 'Tables have features with different units and sharp thresholds (''age > 65''), which split-based models express naturally. NNs prefer smooth functions and lots of data. It''s a match of assumptions, not a universal law.', NULL, NULL, 108);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'No free lunch says trees always win', 0), (@q, 'B', 'Neural networks can''t take numbers as input', 0), (@q, 'C', 'Trees'' inductive bias (axis-aligned splits, no need for scaling, ignoring useless columns) matches tables well', 1), (@q, 'D', 'Boosted trees have more parameters than any neural net', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 3, 'mcq', 'A fraud check must run on a phone in under 5 ms. The training set has 10 million rows. Which model family suits this better, and why?', NULL, NULL, 'A parametric model (e.g. logistic regression or a small NN): its size and prediction cost don''t grow with the training data', 'What would kNN have to ship to the phone and search per prediction?', 'kNN must store and search all 10M rows at prediction time. A parametric model compresses the data into a fixed set of weights, so it is small and fast to serve.', NULL, NULL, 109);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'kNN: it learns fastest', 0), (@q, 'B', 'A parametric model (e.g. logistic regression or a small NN): its size and prediction cost don''t grow with the training data', 1), (@q, 'C', 'kNN: it has no parameters to store', 0), (@q, 'D', 'Any model, as size never matters', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 3, 'mcq', 'A churn model predicts ''will this customer cancel TOMORROW?'' with great accuracy, but the retention team needs two weeks to run a save campaign. What is wrong?', NULL, NULL, 'The prediction point is too late to act on; predict far enough ahead (e.g. 30 days) for the action to work', 'A correct prediction you can''t act on is worth nothing.', 'Framing includes WHEN you predict. The horizon must leave time for the business action. Predicting further ahead is harder (lower accuracy) but useful.', 'today ---- 14 days to act ----> cancel date\n  ^ predict here            ^ ''tomorrow'' model\n    (useful)                  predicts here (too late)', NULL, 110);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Churn should be a regression problem', 0), (@q, 'B', 'Accuracy is the wrong metric', 0), (@q, 'C', 'Nothing; high accuracy is all that matters', 0), (@q, 'D', 'The prediction point is too late to act on; predict far enough ahead (e.g. 30 days) for the action to work', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genai-lens'), 3, 'mcq', 'A team must route support tickets into 5 categories. They have 200,000 labelled tickets, a 50 ms latency budget and millions of tickets a day. What fits best?', NULL, NULL, 'A small classifier trained on the labelled tickets (maybe on top of embeddings); an LLM prompt can help bootstrap or handle rare cases', 'Plenty of labels, strict latency, huge volume.', 'With lots of labels and a fixed set of classes, a trained classifier is cheaper, faster and easier to evaluate. LLM prompting shines when you have few labels or open-ended outputs.', NULL, NULL, 111);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A small classifier trained on the labelled tickets (maybe on top of embeddings); an LLM prompt can help bootstrap or handle rare cases', 1), (@q, 'B', 'Send every ticket to the largest LLM with a prompt', 0), (@q, 'C', 'Hand-write keyword rules for all 5 categories', 0), (@q, 'D', 'Clustering, since categories are known', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genai-lens'), 3, 'true_false', 'Because an LLM with sampling turned on can answer the same prompt differently each time, one passing run of an eval case is weaker evidence than one passing run of a deterministic unit test.', NULL, NULL, 'True', 'Would you trust a flaky test that passed once?', 'Non-deterministic outputs mean you should run cases several times, use temperature 0 where possible, and track pass rates, not single passes.', NULL, NULL, 112);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genai-lens'), 3, 'mcq', 'Before building a RAG system with a re-ranker, query rewriting and agents, what should come first?', NULL, NULL, 'A simple version (basic retrieval + one prompt) plus a small eval set, so every later addition can be measured', 'How will you know whether the re-ranker helped?', 'Same rule as classic ML: baseline first. Without a baseline and evals you can''t tell which part adds value and which only adds latency and cost.', NULL, 'Ship the MVP and its tests before the microservices.', 113);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The most advanced pipeline you can find', 0), (@q, 'B', 'A dashboard for the final product', 0), (@q, 'C', 'Fine-tuning the LLM on the documents', 0), (@q, 'D', 'A simple version (basic retrieval + one prompt) plus a small eval set, so every later addition can be measured', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 4, 'code_output', 'What does this print?', 'import numpy as np\npreds = np.array([2.0, 4.0, 6.0])   # 3 models trained on 3 samples\ntrue = 5.0\nbias2 = (preds.mean() - true) ** 2\nvar = preds.var()\nmse = ((preds - true) ** 2).mean()\nprint(bias2, round(var, 2), round(mse, 2))', 'python', '1.0 2.67 3.67', 'Average prediction 4 vs truth 5; then the spread around 4.', 'Bias^2 = (4 - 5)^2 = 1. Variance = mean of (2-4)^2, 0, (6-4)^2 = 8/3 = 2.67. Average squared error = (9 + 1 + 1)/3 = 3.67 = bias^2 + variance (no noise here). That is the decomposition, made concrete.', '  2.0      4.0  5.0  6.0\n   x--------o----*----x     o = mean prediction\n            |<-->|          * = truth\n           bias = 1, spread = variance', NULL, 114);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1.0 4.0 5.0', 0), (@q, 'B', '4.0 2.67 6.67', 0), (@q, 'C', '1.0 2.67 2.67', 0), (@q, 'D', '1.0 2.67 3.67', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 4, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.linear_model import LogisticRegression\nX = np.array([[100], [200], [300], [400]]); y = [0, 0, 1, 1]\nsc = StandardScaler().fit(X)\nm = LogisticRegression().fit(sc.transform(X), y)\nq = np.array([[150]])\nprint(m.predict(sc.transform(q))[0], m.predict(q)[0])', 'python', '0 1', 'The second call skips the scaler the model was trained with.', 'Training saw scaled inputs (150 becomes about -0.9, class 0). The serving call passes the raw 150, which looks huge, so it flips to class 1. This is training-serving skew in two lines, and why preprocessing must ship inside the model pipeline.', NULL, NULL, 115);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 0', 0), (@q, 'B', '0 0', 0), (@q, 'C', '0 1', 1), (@q, 'D', '1 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 4, 'mcq', 'A bank trains a default model on past loans. It only has outcomes (repaid or defaulted) for applicants it APPROVED. What is the subtle problem?', NULL, NULL, 'Selection bias: the model never sees outcomes for the kind of people the old policy rejected, so its scores for them are guesses', 'Whose labels are missing, and were they missing at random?', 'The labels exist only where the old decision said yes. The model learns about approved-looking applicants and can be badly wrong elsewhere. Teams fix this with small controlled approvals (exploration), reject inference or careful policy limits.', 'applicants -> old policy -+-> approved -> outcome known\n                          +-> rejected -> NEVER seen\nmodel trains only on the top branch', NULL, 116);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Defaults should be predicted with clustering', 0), (@q, 'B', 'Selection bias: the model never sees outcomes for the kind of people the old policy rejected, so its scores for them are guesses', 1), (@q, 'C', 'Too much data', 0), (@q, 'D', 'There is no problem if the test set is large', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'generalisation'), 4, 'mcq', 'Your model''s validation error stopped improving and now matches the rate at which two human experts disagree on the same cases. Best next step?', NULL, NULL, 'Look for new informative features or cleaner labels; a bigger model mostly can''t beat this noise floor', 'Some error comes from the data itself, not the model.', 'If identical-looking cases have different labels, that is irreducible error given these features. Only new information (features) or cleaner labels lower it; more capacity just fits the noise.', 'error\n | \\\n |  \\___________  <- plateau = noise floor\n |                  (experts disagree here too)\n +----------------- model size / epochs', NULL, 117);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Remove the validation set', 0), (@q, 'B', 'Look for new informative features or cleaner labels; a bigger model mostly can''t beat this noise floor', 1), (@q, 'C', 'Train for 10x more epochs', 0), (@q, 'D', 'Train a much bigger model', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 4, 'mcq', 'Vision transformers have weaker built-in assumptions about images than CNNs (no built-in locality or translation sharing). What is the practical consequence?', NULL, NULL, 'They usually need far more training data (or big pre-training) to match CNNs, but can surpass them at large scale', 'Assumptions are a substitute for data.', 'A strong, correct inductive bias lets a model learn from less data. Weaker bias means the model must learn those regularities from examples, which costs data but leaves room to learn things the bias would have ruled out.', 'data needed\n high |            ViT (weak bias)\n      |   CNN (strong bias)\n low  +--------------------------\n       assumptions built in: few -> many', NULL, 118);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Inductive bias has no effect on data needs', 0), (@q, 'B', 'They need less data because they assume less', 0), (@q, 'C', 'They usually need far more training data (or big pre-training) to match CNNs, but can surpass them at large scale', 1), (@q, 'D', 'They can never match CNNs on images', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inductive-bias'), 4, 'true_false', 'Flipping and cropping training images (data augmentation) is a way to give a model an inductive bias, such as ''a flipped cat is still a cat'', through the data instead of the architecture.', NULL, NULL, 'True', 'What assumption does each flipped copy teach?', 'Augmentation encodes invariances you believe are true. It is also where the bias can be wrong: flipping images of text produces mirror writing, and rotating a 6 turns it into a 9.', NULL, NULL, 119);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 4, 'mcq', 'Which statement about an RBF-kernel SVM is most accurate?', NULL, NULL, 'It stores support vectors, whose number tends to grow with the training data, so it behaves like a non-parametric model', 'What does the fitted model keep in order to predict?', 'A kernel SVM predicts by comparing new points to stored training points (the support vectors). Model size depends on the data, not just the number of features. Hyperparameters don''t decide whether a model is parametric.', NULL, NULL, 120);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It always stores exactly d+1 numbers', 0), (@q, 'B', 'It stores support vectors, whose number tends to grow with the training data, so it behaves like a non-parametric model', 1), (@q, 'C', 'It is parametric, because it has hyperparameters C and gamma', 0), (@q, 'D', 'It has no learned values', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'parametric'), 4, 'mcq', 'A RAG system combines an LLM with a searchable index of company documents. In parametric/non-parametric terms, which description is right?', NULL, NULL, 'The LLM''s weights are parametric memory (fixed size); the document index is non-parametric memory that grows as you add documents', 'Which part gets bigger when you add 10,000 new documents?', 'This is the framing used in the original RAG paper. Knowledge baked into weights needs retraining to change; knowledge in the index can be added, fixed or deleted by editing data.', 'query --> [index: grows with docs] --> top passages\n                                          |\n             [LLM weights: fixed] <-------+\n                    |\n                  answer', 'Weights are constants compiled into the binary; the index is a database you can update at runtime.', 121);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Both are parametric', 0), (@q, 'B', 'The index is parametric because it has embeddings', 0), (@q, 'C', 'The LLM''s weights are parametric memory (fixed size); the document index is non-parametric memory that grows as you add documents', 1), (@q, 'D', 'Both are non-parametric', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'params-hyper'), 4, 'mcq', 'Which statement about parameter count and model capacity (how complex a pattern a model can fit) is correct?', NULL, NULL, 'Parameter count is only a rough guide: a model like y = sin(w*x) has one parameter yet can fit very wiggly data', 'Can one number make a curve wiggle a lot?', 'Capacity depends on how parameters are used, not just how many. Regularisation, architecture and training time also change effective capacity, which is why a huge regularised network can generalise well.', 'y = sin(w * x),  ONE parameter w\nw small:  ~~~~          (smooth)\nw large:  /\\/\\/\\/\\/\\/\\    (wiggly, fits almost anything)', NULL, 122);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'More parameters always means more capacity, exactly', 0), (@q, 'B', 'A model with fewer parameters can never overfit', 0), (@q, 'C', 'Parameter count is only a rough guide: a model like y = sin(w*x) has one parameter yet can fit very wiggly data', 1), (@q, 'D', 'Capacity depends only on the training data size', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'train-infer'), 4, 'mcq', 'A chat product has thumbs-up/thumbs-down buttons and a ''memory'' feature. A user says ''it learned my name instantly''. What is really happening?', NULL, NULL, 'Memory is stored text added to future prompts; feedback is logged and may be used in a later offline training run; the served weights don''t change per chat', 'Where could ''your name'' live without touching the weights?', 'Updating a giant model per user message would be slow, costly and unsafe. Products store facts as context and collect feedback for future versions. Weights change only when a new model version is trained and deployed.', NULL, NULL, 123);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The model retrains after every message', 0), (@q, 'B', 'The user''s browser trains a local copy', 0), (@q, 'C', 'Each thumbs-up runs gradient descent on the live model', 0), (@q, 'D', 'Memory is stored text added to future prompts; feedback is logged and may be used in a later offline training run; the served weights don''t change per chat', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 4, 'mcq', 'A loan default model''s true labels arrive 90 days after each prediction. How do you catch problems in the meantime?', NULL, NULL, 'Monitor input feature distributions and the prediction score distribution for drift, plus any early proxy labels (e.g. first missed payment)', 'What can you observe on day 1 without the label?', 'Delayed labels are common (fraud, churn, credit). Input and output drift are early warning signals; proxy labels give earlier, noisier feedback. Real accuracy is checked once labels mature.', 'day 0 predict -- day 1..89: drift, proxies -- day 90 label\n      |              (early warnings)            |\n      +--------------- real accuracy ------------+', NULL, 124);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Check the training accuracy daily', 0), (@q, 'B', 'Retrain every hour on unlabelled data', 0), (@q, 'C', 'Wait 90 days; nothing can be checked earlier', 0), (@q, 'D', 'Monitor input feature distributions and the prediction score distribution for drift, plus any early proxy labels (e.g. first missed payment)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'workflow'), 4, 'mcq', 'You retrain last month''s model with the same script and get noticeably different results. To make training reproducible, what must be versioned?', NULL, NULL, 'The exact data snapshot, code, hyperparameters, random seeds and library versions', 'A model is code + data + config + environment.', 'Unlike a normal build, the ''source'' of a model includes the data. If the training table changed or a library update changed defaults, the same code produces a different model.', NULL, 'Like a build that needs the lockfile and the exact input assets, not just the source code.', 125);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The exact data snapshot, code, hyperparameters, random seeds and library versions', 1), (@q, 'B', 'Only the code in git', 0), (@q, 'C', 'Only the final model file', 0), (@q, 'D', 'Only the hyperparameters', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'when-not-ml'), 4, 'mcq', 'A team adds one new feature to a production model. Accuracy goes up overall, but a downstream fraud rule that used the model''s score threshold starts firing far too often. What ML maintenance issue is this?', NULL, NULL, 'Entanglement (changing anything changes everything): the score''s meaning shifted, and hidden consumers depended on it', 'Who else was reading the model''s output?', 'In ML, inputs are not independent: one change shifts all weights and the score distribution. Undeclared consumers of the score then break. Version model outputs, document consumers and re-calibrate thresholds on each release.', 'new feature --> model --> score dist shifts\n                             |\n          fraud rule (score > 0.8) fires 5x more', 'Like changing a shared global variable that half the codebase silently reads.', 126);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Underfitting', 0), (@q, 'B', 'Exploration vs exploitation', 0), (@q, 'C', 'Catastrophic forgetting', 0), (@q, 'D', 'Entanglement (changing anything changes everything): the score''s meaning shifted, and hidden consumers depended on it', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ai-ml-dl'), 4, 'true_false', 'An LLM ''agent'' that calls tools in a loop to finish a task is a reinforcement-learning agent, learning from rewards while it runs.', NULL, NULL, 'False', 'Do the model''s weights change between steps of the loop?', 'Most LLM agents are frozen models plus orchestration code: the ''learning'' within a task is just new text in the context. RL may have been used to train the model earlier (e.g. RLHF), but the running agent isn''t updating a policy from rewards.', NULL, NULL, 127);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'framing'), 4, 'mcq', 'Fraud labels come from chargebacks, which can arrive up to 60 days after a transaction. You build a training set that includes last week''s transactions, labelled ''not fraud'' if no chargeback exists yet. What goes wrong?', NULL, NULL, 'Recent rows are falsely labelled ''not fraud'' because their labels haven''t matured; exclude them or wait for the label window to close', 'Has last week''s fraud had time to show up?', 'Label maturity: a missing chargeback isn''t proof of no fraud yet. Training on immature labels teaches the model that recent fraud patterns are safe, exactly the ones you most need to catch.', 'txn date:  -90d ........ -60d ..... -7d  today\nlabels:    [   mature, trustworthy   ][ still open ]\ntrain on:  <------------------------>   exclude', NULL, 128);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Recent rows are falsely labelled ''not fraud'' because their labels haven''t matured; exclude them or wait for the label window to close', 1), (@q, 'B', 'Nothing; recent data is always the most valuable', 0), (@q, 'C', 'The model will overfit to old fraud', 0), (@q, 'D', 'It turns into an unsupervised problem', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genai-lens'), 4, 'mcq', 'You use an LLM to grade your chatbot''s answers (''LLM-as-judge''). Which risk is real and how do you handle it?', NULL, NULL, 'The judge has biases (prefers longer answers, the first option shown, or its own style); check its grades against a human-labelled sample and randomise order', 'A judge is also a model, with its own errors.', 'An automated judge is a measuring instrument; you calibrate it. Measure agreement with human labels, swap answer positions, and keep a small human-reviewed set as ground truth.', NULL, NULL, 129);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The judge has biases (prefers longer answers, the first option shown, or its own style); check its grades against a human-labelled sample and randomise order', 1), (@q, 'B', 'LLM judges are always objective, so no checks are needed', 0), (@q, 'C', 'LLM judges can only grade code', 0), (@q, 'D', 'The judge''s weights get updated by grading', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'genai-lens'), 4, 'mcq', 'A model scores 95% on a famous public benchmark but only 60% on your company''s internal test cases of the same kind. What are the two most likely explanations?', NULL, NULL, 'The benchmark leaked into its pre-training data (contamination), and your cases come from a different distribution than the benchmark', 'Has the model maybe already seen the benchmark answers? Does the benchmark look like your data?', 'Public test sets end up in web-scraped training data, inflating scores. And a benchmark is only a proxy for your task. This is why teams build their own eval sets from real traffic.', NULL, NULL, 130);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Your test cases must be labelled wrong', 0), (@q, 'B', 'Benchmarks are always harder than real tasks', 0), (@q, 'C', 'The model is underfitting the benchmark', 0), (@q, 'D', 'The benchmark leaked into its pre-training data (contamination), and your cases come from a different distribution than the benchmark', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Predicting house prices from past sales with known prices is which type of learning?', NULL, NULL, 'Supervised', 'Do the training examples come with the right answer?', 'Each example has a label (the price), so it''s supervised learning.', NULL, NULL, 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Unsupervised', 0), (@q, 'B', 'None', 0), (@q, 'C', 'Supervised', 1), (@q, 'D', 'Reinforcement', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Grouping customers into segments with no labels given is:', NULL, NULL, 'Unsupervised (clustering)', 'No right answers are provided; the model finds structure itself.', 'No labels -> unsupervised. Clustering finds natural groups.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Unsupervised (clustering)', 1), (@q, 'B', 'Regression', 0), (@q, 'C', 'Reinforcement', 0), (@q, 'D', 'Supervised (classification)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'An agent learning to play a game from rewards and penalties is:', NULL, NULL, 'Reinforcement learning', 'Think trial and error with a score.', 'RL learns by acting, getting a reward, and improving its policy.', '   +-------- action ------->+\n Agent                  Environment\n   +<--- reward, state -----+', NULL, 3);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Supervised learning', 0), (@q, 'B', 'Reinforcement learning', 1), (@q, 'C', 'Transfer learning', 0), (@q, 'D', 'Unsupervised learning', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Classification vs regression: which is regression?', NULL, NULL, 'Predicting tomorrow''s temperature in degrees', 'Regression predicts a number; classification predicts a category.', 'Temperature is a continuous number -> regression.', NULL, NULL, 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Fraud yes/no', 0), (@q, 'B', 'Predicting tomorrow''s temperature in degrees', 1), (@q, 'C', 'Spam or not spam', 0), (@q, 'D', 'Cat, dog or bird', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 2, 'true_false', 'Large language models are pre-trained with self-supervised learning: the ''label'' is just the next word in the text.', NULL, NULL, 'True', 'Nobody hand-labels the internet.', 'The text supplies its own labels (next token), which is why LLMs can train on so much data.', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 1, 'mcq', '''Supervised'' learning gets its name because:', NULL, NULL, 'Each training example comes with the correct answer, like a teacher marking work', 'What extra column does supervised data have?', 'Supervised data has labels: the right answer for each example. The model learns to map inputs to those answers.', NULL, 'Like learning with an answer key: every practice question comes with the correct answer to check against.', 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A human watches the model train', 0), (@q, 'B', 'It only works in supervised environments', 0), (@q, 'C', 'Each training example comes with the correct answer, like a teacher marking work', 1), (@q, 'D', 'The model is checked by a supervisor program', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 1, 'mcq', 'Which of these is a CLASSIFICATION task?', NULL, NULL, 'Deciding if an X-ray shows pneumonia: yes or no', 'Classification picks from a fixed set of categories.', 'Yes/no is a category. Rent, minutes and revenue are numbers, so those are regression.', NULL, NULL, 7);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Predicting a flat''s rent in rupees', 0), (@q, 'B', 'Forecasting next month''s revenue', 0), (@q, 'C', 'Deciding if an X-ray shows pneumonia: yes or no', 1), (@q, 'D', 'Estimating a delivery time in minutes', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 1, 'true_false', 'Predicting a customer''s age in years from their purchases is a regression task.', NULL, NULL, 'True', 'Is the output a category or a number?', 'Age is a number on a continuous scale, so it''s regression.', NULL, NULL, 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 1, 'mcq', 'Sorting emails into ''Primary'', ''Social'' or ''Promotions'' (exactly one each) is:', NULL, NULL, 'Multiclass classification', 'How many possible categories, and how many per email?', 'More than two classes, exactly one per example = multiclass.', NULL, NULL, 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Regression', 0), (@q, 'B', 'Multiclass classification', 1), (@q, 'C', 'Binary classification', 0), (@q, 'D', 'Clustering', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 1, 'mcq', 'In unsupervised learning, the training data has:', NULL, NULL, 'No labels: the model has to find structure by itself', '''Un''-supervised: no teacher.', 'There are no correct answers given. The model looks for groups, patterns or compressed representations.', NULL, 'Like sorting a box of mixed LEGO with no instructions: you group pieces by what they look like.', 10);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only images', 0), (@q, 'B', 'No labels: the model has to find structure by itself', 1), (@q, 'C', 'Rewards for every action', 0), (@q, 'D', 'Labels for every row', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 1, 'mcq', 'A bank wants to flag card transactions that look very unusual compared with normal ones, without having labelled fraud examples. This is:', NULL, NULL, 'Anomaly detection (usually unsupervised)', 'It''s about finding the odd ones out.', 'Anomaly detection learns what ''normal'' looks like and flags points that don''t fit; it doesn''t need labelled anomalies.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Anomaly detection (usually unsupervised)', 1), (@q, 'B', 'Regression', 0), (@q, 'C', 'Multiclass classification', 0), (@q, 'D', 'Reinforcement learning', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 1, 'mcq', 'In reinforcement learning, what is the ''reward''?', NULL, NULL, 'A number the environment gives the agent saying how good its last action was', 'Think of points in a video game.', 'The reward is a score signal from the environment. The agent learns actions that collect more reward over time.', '        action\n Agent ---------> Environment\n   ^                  |\n   +-- state, reward -+', NULL, 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The model''s accuracy on the test set', 0), (@q, 'B', 'The correct label for each example', 0), (@q, 'C', 'A number the environment gives the agent saying how good its last action was', 1), (@q, 'D', 'The learning rate', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 1, 'mcq', 'In reinforcement learning, the ''policy'' is:', NULL, NULL, 'The agent''s strategy: which action to take in each situation', 'It''s what the agent is trying to improve.', 'A policy maps state -> action. RL is about learning a good policy.', NULL, 'Like a request router: given the current state, decide what to do next.', 13);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The training dataset', 0), (@q, 'B', 'The reward the environment gives', 0), (@q, 'C', 'The agent''s strategy: which action to take in each situation', 1), (@q, 'D', 'The list of all states', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 1, 'mcq', 'A model that is updated a little bit every time a new data point arrives is doing:', NULL, NULL, 'Online learning', 'It learns continuously, piece by piece.', 'Online (incremental) learning updates as data streams in. Batch learning retrains on the whole dataset at once.', NULL, NULL, 14);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Batch learning', 0), (@q, 'B', 'Transfer learning', 0), (@q, 'C', 'Unsupervised learning', 0), (@q, 'D', 'Online learning', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 1, 'true_false', '''Online learning'' means the model is served behind a web API.', NULL, NULL, 'False', 'It''s about how the model learns, not where it runs.', 'Online learning = updating the model incrementally as new data arrives. A batch-trained model served via an API is still batch learning.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'transfer'), 1, 'mcq', 'Transfer learning means:', NULL, NULL, 'Starting from a model already trained on a big task and adapting it to your task', 'Reuse what was already learned.', 'A pretrained model already knows general patterns (edges, words). You adapt it with a little data instead of training from zero.', '[pretrained backbone] --> [new head] --> your classes\n  (big generic data)      (your small data)', 'Like forking a mature open-source library instead of writing one from scratch.', 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Starting from a model already trained on a big task and adapting it to your task', 1), (@q, 'B', 'Training two models at the same time', 0), (@q, 'C', 'Moving a model from Python to Java', 0), (@q, 'D', 'Copying data from one server to another', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'gen-disc'), 1, 'mcq', 'Which model can CREATE new examples, like brand-new images of faces?', NULL, NULL, 'A generative model', 'One family ''generates''.', 'Generative models learn what the data looks like, so they can sample new data. Discriminative models only separate classes.', NULL, NULL, 17);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A linear regression', 0), (@q, 'B', 'A generative model', 1), (@q, 'C', 'A discriminative classifier', 0), (@q, 'D', 'A decision tree classifier', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scenarios'), 1, 'mcq', 'A music app learns your taste from songs you skipped or replayed and has no explicit ratings. Each song is labelled ''liked'' if replayed. Predicting ''will they like this new song?'' is:', NULL, NULL, 'Supervised binary classification', 'There is a yes/no label for each past song.', 'Replays give a label (liked or not) per song, so it''s supervised, with two classes.', NULL, NULL, 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Clustering', 0), (@q, 'B', 'Dimensionality reduction', 0), (@q, 'C', 'Supervised binary classification', 1), (@q, 'D', 'Regression', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scenarios'), 1, 'mcq', 'A robot vacuum learns which routes clean the room fastest by trying routes and getting a score for each run. This is:', NULL, NULL, 'Reinforcement learning', 'Trial and error with a score.', 'The robot acts, gets feedback (time, coverage), and improves its route-picking policy: RL.', NULL, NULL, 19);
