INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.linear_model import SGDClassifier\nrng = np.random.default_rng(0)\nclf = SGDClassifier(random_state=0)\nfor day in range(3):\n    X = rng.normal(size=(50, 4)); y = (X[:, 0] > 0).astype(int)\n    clf.partial_fit(X, y, classes=[0, 1])\nprint(clf.coef_.shape, clf.classes_.tolist())', 'python', '(1, 4) [0, 1]', 'Binary linear classifiers keep one row of weights.', 'partial_fit updates the same model with each new batch (online learning). A binary linear model has one weight row: shape (1, 4).', NULL, NULL, 34);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(1, 4) [0, 1]', 1), (@q, 'B', '(3, 4) [0, 1]', 0), (@q, 'C', '(2, 4) [0, 1]', 0), (@q, 'D', '(4,) [0, 1]', 0);
