INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 3, 'mcq', 'For a multilabel problem with 20 tags, one simple approach is:', NULL, NULL, 'Train one binary classifier per tag (one-vs-rest)', 'Each tag is an independent yes/no question.', 'Multilabel = 20 yes/no decisions per item. Softmax forces exactly one label, which is wrong here; sigmoid per tag (or one-vs-rest) fits.', NULL, NULL, 41);
