INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.ensemble import IsolationForest\nrng = np.random.default_rng(0)\nX = np.vstack([rng.normal(0, 1, size=(200, 2)), [[8, 8], [-9, 7]]])\npred = IsolationForest(random_state=0).fit(X).predict(X)\nprint(np.unique(pred), pred[-2:])', 'python', '[-1  1] [-1 -1]', 'sklearn outlier detectors don''t use 0/1.', 'IsolationForest predicts 1 for inliers and -1 for outliers. The two far-away points are flagged -1, with no labels used.', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[-1  1] [1 1]', 0), (@q, 'B', '[0 1] [1 1]', 0), (@q, 'C', '[0 1] [0 0]', 0), (@q, 'D', '[-1  1] [-1 -1]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'semi-self'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.semi_supervised import LabelPropagation\nX = np.array([[0.0], [0.2], [0.4], [5.0], [5.2], [5.4]])\ny = np.array([0, -1, -1, 1, -1, -1])\nm = LabelPropagation().fit(X, y)\nprint(m.transduction_)', 'python', '[0 0 0 1 1 1]', 'In sklearn, -1 marks an unlabelled row.', 'Labels spread to nearby unlabelled points, so each cluster takes the label of its one labelled member. That''s semi-supervised learning.', NULL, NULL, 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0 0 0 0 0 0]', 0), (@q, 'B', '[0 1 0 1 0 1]', 0), (@q, 'C', '[0 -1 -1 1 -1 -1]', 0), (@q, 'D', '[0 0 0 1 1 1]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'semi-self'), 3, 'mcq', 'BERT is pre-trained by hiding some words and predicting them; GPT by predicting the next word. Both are:', NULL, NULL, 'Self-supervised objectives: the hidden word is the label, taken from the text itself', 'Who provides the ''correct'' word?', 'Masked-language modelling (BERT) and next-token prediction (GPT) both make labels from raw text, so no human labelling is needed.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Self-supervised objectives: the hidden word is the label, taken from the text itself', 1), (@q, 'B', 'Clustering', 0), (@q, 'C', 'Supervised with human labels', 0), (@q, 'D', 'Reinforcement learning', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'semi-self'), 3, 'mcq', 'In contrastive self-supervised learning (e.g. SimCLR, CLIP), what is the training signal?', NULL, NULL, 'Make embeddings of two views of the same item close, and of different items far apart', 'Positive pairs vs negative pairs.', 'Two crops of one photo (or a photo and its caption) are a positive pair; other items in the batch are negatives. No class labels needed.', ' view A of cat --\\  pull together\n view B of cat --/\n photo of car  <---- push apart ----> cat', NULL, 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Make embeddings of two views of the same item close, and of different items far apart', 1), (@q, 'B', 'Maximise a game score', 0), (@q, 'C', 'Predict a human-given class label', 0), (@q, 'D', 'Reconstruct every pixel exactly', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 3, 'code_output', 'What does this print?', 'rewards = [1, 1, 1]\ngamma = 0.9\nG = sum(r * gamma ** t for t, r in enumerate(rewards))\nprint(round(G, 2))', 'python', '2.71', 'Each later reward is multiplied by one more factor of gamma.', 'Discounted return G = 1 + 0.9*1 + 0.81*1 = 2.71. Discounting makes near rewards count more than far ones.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2.7', 0), (@q, 'B', '0.73', 0), (@q, 'C', '2.71', 1), (@q, 'D', '3.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 3, 'code_output', 'What does this print?', 'import numpy as np\nq = np.array([0.2, 0.5, 0.1])\nrng = np.random.default_rng(0)\neps = 0.1\npicks = [int(rng.integers(3)) if rng.random() < eps else int(np.argmax(q)) for _ in range(1000)]\nprint(np.bincount(picks).argmax(), picks.count(1) > 900)', 'python', '1 True', 'With probability 0.9 it takes the best-known action.', 'Epsilon-greedy exploits argmax(q) = 1 about 90% of the time, plus 1/3 of the random 10%, so ~93% of picks are action 1.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0 True', 0), (@q, 'B', '2 False', 0), (@q, 'C', '1 True', 1), (@q, 'D', '1 False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.linear_model import SGDClassifier\nX = np.array([[0.0], [1.0]]); y = np.array([0, 1])\nclf = SGDClassifier()\nclf.partial_fit(X, y)', 'python', 'ValueError', 'On the very first call, how would it know which classes might appear later?', 'The first partial_fit call must get classes=[...] because future batches may contain classes not seen yet. Without it sklearn raises ValueError.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', 'ValueError', 1), (@q, 'C', 'NotFittedError', 0), (@q, 'D', 'Nothing is printed', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 3, 'mcq', 'Which situation most favours online learning over nightly batch retraining?', NULL, NULL, 'Ad click prediction where user behaviour shifts within hours and data arrives as a stream', 'How fast does the pattern change?', 'Online learning shines when data streams in and the pattern drifts quickly. Stable data is easier to manage with batch retraining.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A yearly tax-category model with stable data', 0), (@q, 'B', 'Ad click prediction where user behaviour shifts within hours and data arrives as a stream', 1), (@q, 'C', 'A one-off research analysis', 0), (@q, 'D', 'An image classifier trained on a fixed dataset', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'transfer'), 3, 'code_output', 'What does this print?', 'import torch.nn as nn\nbackbone = nn.Linear(100, 50)\nhead = nn.Linear(50, 3)\nfor p in backbone.parameters():\n    p.requires_grad = False\nmodel = nn.Sequential(backbone, head)\nprint(sum(p.numel() for p in model.parameters() if p.requires_grad))', 'python', '153', 'Only the head is trainable: weights plus biases.', 'The head has 50*3 weights + 3 biases = 153 trainable numbers; the frozen backbone''s 5050 are not updated.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '5203', 0), (@q, 'B', '153', 1), (@q, 'C', '150', 0), (@q, 'D', '5050', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'transfer'), 3, 'mcq', 'You have 200 labelled X-rays and a model pretrained on ImageNet. What''s the usual best plan?', NULL, NULL, 'Freeze most of the backbone, train the head, then optionally unfreeze the top layers with a small learning rate', 'With little data, how many weights should you let move?', 'Small data + many trainable weights = overfitting. Train few weights first, then carefully unfreeze more if it helps.', NULL, NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Skip training and use ImageNet labels', 0), (@q, 'B', 'Unfreeze everything and train with a large learning rate', 0), (@q, 'C', 'Train a new network from scratch on the 200 images', 0), (@q, 'D', 'Freeze most of the backbone, train the head, then optionally unfreeze the top layers with a small learning rate', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'gen-disc'), 3, 'mcq', 'A discriminative model learns ____, while a generative model learns ____.', NULL, NULL, 'p(y | x); p(x, y) (or p(x | y) with p(y))', 'Discriminative = ''given the input, which class?''.', 'Discriminative models model the boundary p(y | x). Generative models model how the data is produced, p(x, y), so they can also sample x.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'p(x, y); p(y | x)', 0), (@q, 'B', 'p(y | x); p(x, y) (or p(x | y) with p(y))', 1), (@q, 'C', 'p(x); p(y)', 0), (@q, 'D', 'rewards; policies', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'gen-disc'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.naive_bayes import GaussianNB\nX = np.array([[1.0], [1.2], [0.8], [5.0], [5.2], [4.8], [5.1], [4.9]])\ny = np.array([0, 0, 0, 1, 1, 1, 1, 1])\nnb = GaussianNB().fit(X, y)\nprint(nb.class_prior_, nb.predict([[3.5]]))', 'python', '[0.375 0.625] [1]', 'A generative classifier learns p(y) and p(x | y) for each class.', 'GaussianNB stores class priors (3/8, 5/8) and a Gaussian per class. 3.5 is closer to class 1''s mean (5.0) than class 0''s (1.0), so it predicts 1.', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0.5 0.5] [0]', 0), (@q, 'B', '[0.375 0.625] [0]', 0), (@q, 'C', '[0.375 0.625] [1]', 1), (@q, 'D', '[3 5] [1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scenarios'), 3, 'mcq', 'A bank wants to (1) group customers into segments, then (2) predict, for each segment, who will take a loan offer using past offer outcomes. Which types are used?', NULL, NULL, '(1) unsupervised clustering, (2) supervised classification', 'Which step has labels?', 'Segments have no labels (clustering). Past offers have yes/no outcomes, so predicting acceptance is supervised classification.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(1) supervised regression, (2) clustering', 0), (@q, 'B', 'Both reinforcement learning', 0), (@q, 'C', 'Both unsupervised', 0), (@q, 'D', '(1) unsupervised clustering, (2) supervised classification', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 4, 'mcq', 'A team bins house prices into ''low/medium/high'' and trains a classifier instead of a regressor. What is the main cost?', NULL, NULL, 'Information is lost: a price just above a bin edge and one far above are treated the same, and the order of bins is ignored by plain multiclass loss', 'What happens to the exact number and to the order of the bins?', 'Binning discards within-bin detail and, with standard cross-entropy, treats ''low vs high'' as no worse than ''low vs medium''. Do it only if the decision really is categorical.', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Classifiers can''t handle three classes', 0), (@q, 'B', 'It always improves accuracy, so there is no cost', 0), (@q, 'C', 'Information is lost: a price just above a bin edge and one far above are treated the same, and the order of bins is ignored by plain multiclass loss', 1), (@q, 'D', 'Regression can''t predict prices', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 4, 'true_false', 'If you run KMeans with n_clusters=5 on purely random uniform noise, it will still return 5 clusters.', 'import numpy as np\nfrom sklearn.cluster import KMeans\nX = np.random.default_rng(0).uniform(size=(300, 2))\nprint(len(set(KMeans(n_clusters=5, n_init=10, random_state=0).fit_predict(X).tolist())))', 'python', 'True', 'Does KMeans check whether real groups exist?', 'KMeans always partitions data into exactly k groups, even if no structure exists. Use silhouette scores, stability checks or domain sense before trusting clusters.', NULL, NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 4, 'mcq', 'You have no labels but must report whether a clustering is ''good''. Which is the most defensible approach?', NULL, NULL, 'Internal metrics (e.g. silhouette) plus checking whether clusters are stable across seeds and useful for the business decision', 'Inertia always decreases as k grows.', 'Without labels there''s no accuracy. Inertia keeps falling with k, so it can''t pick k alone. Combine silhouette/elbow, stability and usefulness.', NULL, NULL, 58);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Report accuracy against the cluster IDs', 0), (@q, 'B', 'Internal metrics (e.g. silhouette) plus checking whether clusters are stable across seeds and useful for the business decision', 1), (@q, 'C', 'Pick k with the lowest inertia, since lower is always better', 0), (@q, 'D', 'Assume the clusters are correct', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'semi-self'), 4, 'mcq', 'Why did self-supervised pre-training make large language models possible?', NULL, NULL, 'Labels are free: every position in any text is a training example, so you can use trillions of tokens without human labelling', 'What''s the bottleneck in supervised learning?', 'Human labels are slow and expensive. Next-token prediction turns raw text into unlimited labelled examples, which is what lets models scale.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Labels are free: every position in any text is a training example, so you can use trillions of tokens without human labelling', 1), (@q, 'B', 'It guarantees the model is truthful', 0), (@q, 'C', 'It doesn''t need neural networks', 0), (@q, 'D', 'It needs less compute than supervised learning', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'semi-self'), 4, 'mcq', 'In self-training (pseudo-labelling), a model labels unlabelled data with its own confident predictions and retrains on them. What is the main risk?', NULL, NULL, 'Confirmation bias: early mistakes get labelled as truth and reinforced', 'What if the model is confidently wrong?', 'Wrong pseudo-labels are fed back as training data, so errors compound. Use high confidence thresholds and keep a clean labelled validation set.', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Confirmation bias: early mistakes get labelled as truth and reinforced', 1), (@q, 'B', 'It needs more labelled data than supervised learning', 0), (@q, 'C', 'It can only be used for regression', 0), (@q, 'D', 'It makes the model forget its classes', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 4, 'mcq', 'Why is RL not just ''supervised learning with the reward as the label''?', NULL, NULL, 'No correct action is given, rewards can come many steps later, and the agent''s own actions decide what data it sees', 'Think about a chess move that only pays off 30 moves later.', 'RL has delayed credit assignment, no target action, and non-i.i.d. data the agent collects itself. Those are exactly what supervised learning assumes away.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'RL never uses neural networks', 0), (@q, 'B', 'Rewards are always 0 or 1', 0), (@q, 'C', 'No correct action is given, rewards can come many steps later, and the agent''s own actions decide what data it sees', 1), (@q, 'D', 'Supervised learning can''t use numbers as labels', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 4, 'mcq', 'An RL agent in a boat-racing game learns to spin in circles hitting the same reward targets forever instead of finishing the race. This is:', NULL, NULL, 'Reward hacking: the agent maximised the reward as written, not the intended goal', 'The agent did exactly what the reward said.', 'Agents exploit any gap between the reward function and the real goal. Reward design and human checks matter; RLHF faces the same risk with learned reward models.', NULL, NULL, 62);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Too much exploration', 0), (@q, 'B', 'Reward hacking: the agent maximised the reward as written, not the intended goal', 1), (@q, 'C', 'Underfitting', 0), (@q, 'D', 'Catastrophic forgetting', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scenarios'), 4, 'mcq', 'In the usual LLM training recipe, which order is correct?', NULL, NULL, 'Self-supervised pre-training -> supervised fine-tuning on instructions -> RL from human preference feedback', 'Start with the cheapest, largest data.', 'Pre-training on raw text builds general knowledge; supervised fine-tuning teaches the instruction format; RLHF (or DPO-style methods) aligns answers with human preferences.', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only RL from the start', 0), (@q, 'B', 'Self-supervised pre-training -> supervised fine-tuning on instructions -> RL from human preference feedback', 1), (@q, 'C', 'RL first -> pre-training -> fine-tuning', 0), (@q, 'D', 'Supervised fine-tuning -> self-supervised pre-training -> clustering', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 4, 'mcq', 'An online-learning fraud model updates from every flagged transaction. Attackers send many small, harmless-looking transactions labelled ''legit'' to shift it. What is this risk called?', NULL, NULL, 'Data poisoning', 'The attacker controls part of the training stream.', 'Online learners trust incoming data immediately, so adversaries can steer them. Mitigate with rate limits, delayed/validated updates and monitoring.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Training-serving skew', 0), (@q, 'B', 'Underfitting', 0), (@q, 'C', 'Exploration', 0), (@q, 'D', 'Data poisoning', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 4, 'true_false', 'Continually updating a neural network only on the newest data can make it lose skills learned from older data.', NULL, NULL, 'True', 'What happens to old knowledge when every update targets new data?', 'This is catastrophic forgetting. Replay buffers, regularisation towards old weights, or periodic full retrains are common fixes.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'transfer'), 4, 'mcq', 'Fine-tuning a model pretrained on everyday photos makes it WORSE than a small model trained from scratch on satellite radar images. The most likely reason is:', NULL, NULL, 'Negative transfer: the source domain is too different, so pretrained features mislead', 'Transfer helps when the source and target share structure.', 'If the domains differ a lot, pretrained features can hurt. Check a from-scratch baseline and consider domain-specific pretraining.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Radar images have no labels', 0), (@q, 'B', 'Pretrained models can never be fine-tuned', 0), (@q, 'C', 'Negative transfer: the source domain is too different, so pretrained features mislead', 1), (@q, 'D', 'The learning rate was 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'gen-disc'), 4, 'mcq', 'Which statement about generative vs discriminative classifiers is most accurate?', NULL, NULL, 'Generative models (e.g. Naive Bayes) often do better with very little data; discriminative models (e.g. logistic regression) usually win as data grows', 'A classic Ng & Jordan result compared Naive Bayes and logistic regression.', 'Generative models make strong assumptions that help with small data; discriminative models target p(y|x) directly and have lower error asymptotically.', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Generative models can''t output probabilities', 0), (@q, 'B', 'Generative models (e.g. Naive Bayes) often do better with very little data; discriminative models (e.g. logistic regression) usually win as data grows', 1), (@q, 'C', 'Discriminative models always win', 0), (@q, 'D', 'Generative models need labels for p(x) but discriminative ones don''t', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'gen-disc'), 4, 'mcq', 'You use an LLM (a generative model) to label support tickets by prompting ''Answer with one of: billing, bug, other''. How should you think about this?', NULL, NULL, 'A generative model being used as a discriminative classifier; evaluate it like any classifier with a labelled test set', 'The output is a class label.', 'However it works inside, the task is classification. Measure precision/recall per class on labelled examples, exactly as for any classifier.', NULL, NULL, 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A generative model being used as a discriminative classifier; evaluate it like any classifier with a labelled test set', 1), (@q, 'B', 'It''s reinforcement learning', 0), (@q, 'C', 'It''s unsupervised, so no evaluation is possible', 0), (@q, 'D', 'Generative models can''t classify, so this won''t work', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 3, 'fill_blank', 'In reinforcement learning, the factor (usually written as gamma, between 0 and 1) that makes future rewards count less is called the ____ factor.', NULL, NULL, 'discount', 'It discounts the future.', 'The discount factor gamma weights a reward t steps away by gamma^t. gamma near 0 = short-sighted; near 1 = far-sighted.', NULL, NULL, 69);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 2, 'fill_blank', 'In scikit-learn, the method that updates a model with one new batch of data, without retraining from scratch, is ____.', NULL, NULL, 'partial_fit', 'It fits partially.', 'partial_fit is sklearn''s online-learning API (SGDClassifier, MultinomialNB, MiniBatchKMeans...). fit retrains from scratch.', NULL, NULL, 70);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 1, 'mcq', 'A photo app predicts the exact price (in rupees) a used phone will sell for. This is:', NULL, NULL, 'Regression: the output is a number on a scale', 'Is the answer a category or an amount?', 'Prices are continuous numbers, so it''s regression. If you only predicted ''cheap / mid / premium'', it would become classification.', 'classification:  input --> [cat | dog | bird]\nregression:      input --> 18,450.75  (any number)', NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Reinforcement learning', 0), (@q, 'B', 'Regression: the output is a number on a scale', 1), (@q, 'C', 'Clustering', 0), (@q, 'D', 'Classification: the output is a category', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 1, 'mcq', 'A shop wants to split its customers into groups with similar shopping habits, but nobody has defined the groups. Which technique fits?', NULL, NULL, 'Clustering', 'No labels, and you want groups.', 'Clustering (e.g. KMeans) finds groups of similar items without labels. The business then looks at each group and gives it a name like ''weekend bargain hunters''.', ' spend\n   |  o o          x x\n   |   o o        x x x     o, x, + = groups found\n   |        + + +              without any labels\n   +--------------------- visits', NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Binary classification', 0), (@q, 'B', 'Clustering', 1), (@q, 'C', 'Reinforcement learning', 0), (@q, 'D', 'Regression', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'semi-self'), 1, 'true_false', 'Semi-supervised learning trains one model using a small set of labelled examples together with a much larger set of unlabelled ones.', NULL, NULL, 'True', '''Semi'' = partly labelled.', 'Labels are expensive, raw data is cheap. Semi-supervised methods use the unlabelled data''s structure (which points sit close together) to spread the few labels further.', 'labelled:    A  B            (few, expensive)\nunlabelled:  . . . . . . . . . . . . (many, cheap)\nmodel uses both: labels spread to nearby dots', NULL, 73);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 1, 'mcq', 'In reinforcement learning, the ''environment'' is:', NULL, NULL, 'The world the agent acts in, which responds with a new situation and a reward', 'The agent acts; something reacts.', 'The agent picks an action, the environment (a game, a robot''s room, a market) responds with a new state and a reward. The agent learns from that loop.', '      action\nagent ------> environment\n  ^               |\n  +-- state, -----+\n      reward', NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The world the agent acts in, which responds with a new situation and a reward', 1), (@q, 'B', 'The computer the code runs on', 0), (@q, 'C', 'The training dataset of correct answers', 0), (@q, 'D', 'The neural network inside the agent', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 1, 'mcq', 'A model that is retrained from scratch every Sunday night on all the data collected so far is doing:', NULL, NULL, 'Batch (offline) learning', 'Does it learn continuously, or in one big job?', 'Batch learning trains on a full dataset in one job and then serves that fixed model until the next job. Online learning would update it as each new example arrives.', NULL, 'Batch learning is a weekly release; online learning is continuous deployment.', 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Unsupervised learning', 0), (@q, 'B', 'Online learning', 0), (@q, 'C', 'Batch (offline) learning', 1), (@q, 'D', 'Reinforcement learning', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'transfer'), 1, 'mcq', 'A startup has only 300 labelled photos of its products. What is usually the fastest way to get a good image classifier?', NULL, NULL, 'Start from a model already trained on millions of images and fine-tune it', 'Reuse what someone else already learned.', 'A pretrained model already knows edges, shapes and textures. Fine-tuning it on 300 photos only has to learn your specific classes, which is transfer learning.', NULL, 'Like hiring an experienced developer and teaching them your codebase, instead of teaching someone to code from zero.', 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Use clustering instead', 0), (@q, 'B', 'Start from a model already trained on millions of images and fine-tune it', 1), (@q, 'C', 'Train a huge model from scratch on the 300 photos', 0), (@q, 'D', 'Label nothing and use reinforcement learning', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'gen-disc'), 1, 'mcq', 'A model that only learns to tell spam from not-spam, without being able to write emails, is called:', NULL, NULL, 'Discriminative', 'It discriminates (separates) between classes.', 'Discriminative models learn the boundary between classes. A generative model would learn what emails look like and could produce new ones.', 'generative:      learns what each class looks like\ndiscriminative:  learns only the line between them\n   spam x x x  |  o o o ham', NULL, 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Generative', 0), (@q, 'B', 'Discriminative', 1), (@q, 'C', 'Unsupervised', 0), (@q, 'D', 'Reinforcement', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rlhf'), 1, 'mcq', 'After an LLM is pre-trained, people compare pairs of its answers and pick the better one, and the model is tuned to give answers people prefer. This step is often called:', NULL, NULL, 'RLHF: reinforcement learning from human feedback', 'The human gives a judgement, not a correct answer to copy.', 'RLHF turns human preferences into a reward signal and uses RL to make the model''s answers more helpful and safe. It comes after pre-training and supervised fine-tuning.', NULL, NULL, 78);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Pre-training', 0), (@q, 'B', 'Data augmentation', 0), (@q, 'C', 'RLHF: reinforcement learning from human feedback', 1), (@q, 'D', 'Clustering', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'label-strategy'), 1, 'true_false', 'Labelling data by hand is often the slowest and most expensive part of building a supervised model.', NULL, NULL, 'True', 'Think about paying experts to read 100,000 medical notes.', 'That is why teams use tricks like labelling only the most useful examples (active learning) or writing rough rules that label data automatically (weak supervision).', NULL, 'Labels are the hand-written test fixtures of ML: valuable, slow to write, and always in short supply.', 79);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scenarios'), 1, 'mcq', 'A phone keyboard suggests the next word as you type, learned from lots of text. Which learning type mostly powers it?', NULL, NULL, 'Self-supervised learning: the text itself supplies the next-word answers', 'Where do the training answers come from?', 'Next-word prediction is trained by hiding the next word in real sentences. It''s the same idea as LLM pre-training, at a smaller scale.', NULL, NULL, 80);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Self-supervised learning: the text itself supplies the next-word answers', 1), (@q, 'B', 'Hand-written rules', 0), (@q, 'C', 'Clustering', 0), (@q, 'D', 'Reinforcement learning from game scores', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 2, 'code_output', 'What does this print?', 'from sklearn.utils.multiclass import type_of_target\nprint(type_of_target(["cat", "dog", "cat"]), type_of_target(["a", "b", "c"]))', 'python', 'binary multiclass', 'Count the distinct values in each list.', 'String labels are fine: two distinct values make it binary, three make it multiclass. type_of_target looks at the number and kind of distinct values, not their type.', NULL, NULL, 81);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'binary multiclass', 1), (@q, 'B', 'multiclass multiclass', 0), (@q, 'C', 'unknown unknown', 0), (@q, 'D', 'binary binary', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 2, 'code_output', 'What happens when this runs?', 'from sklearn.linear_model import LogisticRegression\nLogisticRegression().fit([[1], [2], [3]], [1.5, 2.7, 3.1])', 'python', 'ValueError', 'What kind of target is [1.5, 2.7, 3.1]?', 'A classifier needs discrete classes; sklearn detects a ''continuous'' target and raises ValueError (''Unknown label type''). Use a regressor such as LinearRegression for numeric targets.', NULL, NULL, 82);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 1), (@q, 'B', 'NotFittedError', 0), (@q, 'C', 'Nothing; it fits fine', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 2, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.decomposition import PCA\na = np.arange(10.0)\nX = np.column_stack([a, 2 * a])\nprint(round(PCA().fit(X).explained_variance_ratio_[0], 2))', 'python', '1.0', 'The second column is just twice the first.', 'Both columns move together exactly, so all the variation lies along one direction. The first component explains 100% of the variance; the second explains nothing. Redundant features compress perfectly.', NULL, NULL, 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2.0', 0), (@q, 'B', '1.0', 1), (@q, 'C', '0.5', 0), (@q, 'D', '0.67', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'semi-self'), 2, 'code_output', 'What does this print?', 'tokens = "the cat sat on the mat".split()\ni = 2\ninputs = tokens[:i] + ["[MASK]"] + tokens[i + 1:]\nprint(" ".join(inputs), "->", tokens[i])', 'python', 'the cat [MASK] on the mat -> sat', 'Index 2 is the third token.', 'This is one masked-language-model training example (BERT style): hide a token and use the original as the label. The data labels itself, so this is self-supervised.', NULL, NULL, 84);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'the cat sat [MASK] the mat -> on', 0), (@q, 'B', 'the [MASK] sat on the mat -> cat', 0), (@q, 'C', 'the cat [MASK] on the mat -> [MASK]', 0), (@q, 'D', 'the cat [MASK] on the mat -> sat', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rl'), 2, 'code_output', 'A greedy agent with two slot-machine arms. What does this print?', 'import numpy as np\nQ = [0.0, 0.0]\ncounts = [0, 0]\ntrue_reward = [1.0, 2.0]   # arm 1 is better\nfor t in range(100):\n    a = int(np.argmax(Q))       # always greedy\n    counts[a] += 1\n    Q[a] += (true_reward[a] - Q[a]) / counts[a]\nprint(counts)', 'python', '[100, 0]', 'On a tie, argmax picks index 0. Then what is Q[0]?', 'The greedy agent tries arm 0 first (tie), sees reward 1, and now Q[0] = 1 > Q[1] = 0 forever. It never tries the better arm. A little exploration (epsilon-greedy) would find it.', NULL, NULL, 85);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 100]', 0), (@q, 'B', '[1, 99]', 0), (@q, 'C', '[100, 0]', 1), (@q, 'D', '[50, 50]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'online-batch'), 2, 'code_output', 'What does this print?', 'from sklearn.linear_model import LinearRegression, SGDRegressor\nprint(hasattr(LinearRegression(), "partial_fit"), hasattr(SGDRegressor(), "partial_fit"))', 'python', 'False True', 'Which one is trained step by step with gradient descent?', 'LinearRegression solves the whole problem at once from all the data, so it has only fit. SGD-based models update in small steps and support partial_fit for online learning.', NULL, NULL, 86);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True', 1), (@q, 'B', 'True True', 0), (@q, 'C', 'False False', 0), (@q, 'D', 'True False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'transfer'), 2, 'true_false', 'In transfer learning, ''freezing'' the backbone means its weights are not updated during fine-tuning; only the new head learns.', NULL, NULL, 'True', 'Frozen = doesn''t change.', 'Freezing keeps the general features the backbone learned and trains only the small task-specific head. It''s faster, needs less data and reduces overfitting.', NULL, NULL, 87);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'gen-disc'), 2, 'mcq', 'Naive Bayes classifies spam by learning, for each class, how likely each word is. Why is it called a generative model?', NULL, NULL, 'It models how the data (words) is produced for each class, p(x given y), then uses Bayes'' rule to classify', 'What does it learn about each class?', 'Generative = learns how examples of each class are generated, p(x | y) p(y). Classification then comes from Bayes'' rule. Logistic regression skips that and learns p(y | x) directly.', NULL, NULL, 88);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It writes new emails as its main job', 0), (@q, 'B', 'It is a neural network', 0), (@q, 'C', 'It models how the data (words) is produced for each class, p(x given y), then uses Bayes'' rule to classify', 1), (@q, 'D', 'It needs no labels', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'rlhf'), 2, 'mcq', 'In RLHF, why do people compare two answers (''A is better than B'') instead of writing the perfect answer for each prompt?', NULL, NULL, 'Judging which answer is better is much faster and more consistent than writing an ideal answer', 'Think about grading essays vs writing them.', 'Humans are better at ranking than at producing perfect outputs. Pairwise preferences train a reward model, which then scores many more answers than humans could ever label.', NULL, 'Like code review: it is much easier to say ''version B is better'' than to write the perfect version yourself.', 89);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Writing answers is not allowed', 0), (@q, 'B', 'Judging which answer is better is much faster and more consistent than writing an ideal answer', 1), (@q, 'C', 'RL can only use yes/no labels', 0), (@q, 'D', 'Comparisons need no humans at all', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'label-strategy'), 2, 'code_output', 'Active learning picks which email to send to a human labeller. What does this print?', 'import numpy as np\nprobs = np.array([0.98, 0.51, 0.75, 0.03])   # model''s P(spam) on unlabelled emails\nprint(int(np.argmin(np.abs(probs - 0.5))))', 'python', '1', 'Which email is the model least sure about?', 'Uncertainty sampling, the simplest active-learning rule: send the example closest to 0.5 to a human. Labelling confident cases (0.98, 0.03) teaches the model little.', NULL, 'Like spending QA time on the flaky tests, not the ones that always pass.', 90);
