INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.datasets import load_iris\nfrom sklearn.linear_model import LogisticRegression\nX, y = load_iris(return_X_y=True)\np = LogisticRegression(max_iter=500).fit(X, y).predict_proba(X[:4])\nprint(p.shape, round(p.sum(axis=1)[0], 2))', 'python', '(4, 3) 1.0', 'One row per flower, one column per class.', 'Multiclass: each row is a probability distribution over 3 classes that sums to 1, and predict picks the largest. In multilabel problems, rows do NOT have to sum to 1.', NULL, NULL, 91);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(4, 3) 3.0', 0), (@q, 'B', '(4, 3) 1.0', 1), (@q, 'C', '(3, 4) 1.0', 0), (@q, 'D', '(4,) 1.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'supervised'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.multiclass import OneVsRestClassifier\nfrom sklearn.linear_model import LogisticRegression\nX = np.array([[0, 0], [1, 1], [2, 2], [3, 3], [0, 3], [3, 0]])\nY = np.array([[1, 0, 1], [0, 1, 1], [1, 1, 0], [0, 0, 1], [1, 0, 0], [0, 1, 0]])\nclf = OneVsRestClassifier(LogisticRegression()).fit(X, Y)\nprint(len(clf.estimators_), clf.predict(X).shape)', 'python', '3 (6, 3)', 'One yes/no model per tag.', 'For a multilabel target, one-vs-rest trains a separate binary classifier per label (3 here) and predicts a 0/1 matrix with one column per label.', 'x --> clf_tag0 --> 1\n  \\-> clf_tag1 --> 0      -> [1, 0, 1]\n   \\> clf_tag2 --> 1', NULL, 92);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '6 (6, 3)', 0), (@q, 'B', '1 (6,)', 0), (@q, 'C', '3 (6,)', 0), (@q, 'D', '3 (6, 3)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 3, 'code_output', 'What does this print?', 'from sklearn.cluster import KMeans\nfrom sklearn.datasets import make_blobs\nX, _ = make_blobs(n_samples=300, centers=3, cluster_std=0.6, random_state=0)\nine = [KMeans(n_clusters=k, n_init=10, random_state=0).fit(X).inertia_ for k in (1, 2, 3, 4, 5)]\nprint([round(a / ine[0], 2) for a in ine])', 'python', '[1.0, 0.43, 0.14, 0.12, 0.1]', 'Inertia (total distance to centres) always drops as k grows. Where does it stop dropping fast?', 'Inertia keeps falling with more clusters, so ''lowest inertia'' would always pick the largest k. The ''elbow'' where the big drops stop (k = 3 here) is a hint, not proof, of the natural number of groups.', 'inertia\n1.0 |*\n    |  *\n    |     *____*____*   <- elbow at k=3\n    +----------------- k\n     1  2  3    4    5', NULL, 93);
