INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'unsupervised'), 3, 'code_output', 'What does this print?', 'from sklearn.metrics import adjusted_rand_score\nprint(adjusted_rand_score([0, 0, 1, 1], [1, 1, 0, 0]))', 'python', '1.0', 'Are the same items grouped together, whatever the names?', 'Both labelings put items {0,1} together and {2,3} together; only the cluster names are swapped. Adjusted Rand index ignores names, so it is a perfect 1.0. Compare clusterings with ARI, never with plain accuracy.', NULL, NULL, 94);
