INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Number of logins last month', 1), (@q, 'B', 'The model''s prediction', 0), (@q, 'C', 'The row number', 0), (@q, 'D', 'Cancelled (yes/no)', 0);
