INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'feature-types'), 1, 'mcq', 'Which feature is CATEGORICAL?', NULL, NULL, 'Payment method: card / UPI / cash', 'Categorical = one of a fixed set of named options.', 'Payment method is a category. The others are numbers you can add or average.', NULL, NULL, 9);
