INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'feature-types'), 1, 'mcq', 'T-shirt size (S, M, L, XL) is which kind of categorical feature?', NULL, NULL, 'Ordinal: the categories have a natural order', 'Is S < M < L < XL meaningful?', 'Sizes have an order, so they''re ordinal. Colours (red, blue) have no order, so they''re nominal.', NULL, NULL, 10);
