INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'encoding'), 1, 'mcq', 'One-hot encoding turns the column city = [BLR, MUM, BLR] into:', NULL, NULL, 'One 0/1 column per city, with a 1 in the row''s city column', '''One hot'' = exactly one 1 in each row.', 'One-hot creates a column per category (city_BLR, city_MUM) and puts a 1 in the matching column, 0 elsewhere.', ' city   ->  city_BLR  city_MUM\n BLR           1         0\n MUM           0         1\n BLR           1         0', NULL, 11);
