INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'scaling'), 1, 'mcq', 'Why do we often scale features (e.g. bring ''salary'' and ''age'' to similar ranges)?', NULL, NULL, 'So a feature with big numbers doesn''t dominate models that use distances or gradients', 'Salary ~ 1,000,000 vs age ~ 30.', 'Without scaling, salary''s huge numbers swamp age in distance calculations (kNN) and slow gradient-based training.', NULL, NULL, 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Because models only accept values between 0 and 1', 0), (@q, 'B', 'To remove missing values', 0), (@q, 'C', 'To make the dataset smaller', 0), (@q, 'D', 'So a feature with big numbers doesn''t dominate models that use distances or gradients', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'code_output', 'What does this print?', 'import numpy as np\nimport pandas as pd\ndf = pd.DataFrame({"age": [25, np.nan, 40], "city": ["BLR", "MUM", None]})\nprint(df.isna().sum().tolist())', 'python', '[1, 1]', 'isna() is True wherever a value is missing; sum counts the Trues per column.', 'Each column has one missing value (np.nan in age, None in city), so the counts are [1, 1].', NULL, NULL, 13);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 1]', 1), (@q, 'B', '[2, 0]', 0), (@q, 'C', '[0, 0]', 0), (@q, 'D', '[1, 0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'true_false', 'NaN in a pandas DataFrame means the value is missing.', NULL, NULL, 'True', 'NaN = Not a Number.', 'pandas uses NaN (and None/NaT/pd.NA) to mark missing values. Most models can''t accept them, so you must handle them.', NULL, NULL, 14);
