INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'shift'), 1, 'mcq', 'A survey to learn what all Indians think about online shopping is only sent to people who already use a shopping app. The results will be:', NULL, NULL, 'Biased: the sample doesn''t represent everyone', 'Who is missing from the sample?', 'Non-users never get the survey, so the sample is skewed. This is sampling bias; a model trained on it inherits the bias.', NULL, NULL, 19);
