INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'data-kinds'), 2, 'mcq', 'Before a model can use raw text like ''great product, fast delivery'', you must first:', NULL, NULL, 'Turn it into numbers, e.g. tokenise and map tokens to IDs or vectors', 'Models only do arithmetic.', 'Text is tokenised (split into pieces) and converted to numbers (IDs, counts like TF-IDF, or embeddings).', NULL, NULL, 24);
