INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'feature-types'), 2, 'true_false', 'A 6-digit PIN code like 560001 should be treated as a numeric feature, since it''s a number.', NULL, NULL, 'False', 'Is 560002 ''one more'' than 560001 in any meaningful way?', 'PIN codes, user IDs and phone numbers are identifiers. Their numeric size means nothing, so treat them as categorical (or derive features like region).', NULL, NULL, 25);
