INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tts'), 3, 'code_output', 'What does this print?', 'import numpy as np\nfrom sklearn.model_selection import train_test_split\nX = np.arange(10)\ny = np.array([0] * 5 + [1] * 5)\ntrain_test_split(X, y, stratify=y, shuffle=False)\nprint(''done'')', 'python', 'ValueError', 'Can you keep the original order AND sample each class evenly?', 'sklearn raises ValueError: stratified splitting is not implemented for shuffle=False.', NULL, NULL, 25);
