INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'kfold'), 1, 'true_false', 'In k-fold CV, every row is used for testing exactly once and for training k-1 times.', NULL, NULL, 'True', 'Count how many folds each row sits in as the test part.', 'The k test folds partition the data, so each row is tested once and trained on in the other k-1 rounds.', NULL, NULL, 40);
