INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Generating text', 0), (@q, 'B', 'Clustering', 0), (@q, 'C', 'Predicting prices', 0), (@q, 'D', 'Classification (probability of a class)', 1);
