INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'What is a token?', NULL, NULL, 'A chunk of text (word or sub-word) the model reads as one unit', '''unhappiness'' might become ''un'' + ''happi'' + ''ness''.', 'Tokens are the model''s units of text; each maps to an integer ID.', ' "unhappiness"  ->  [ un | happi | ness ]  ->  [ 403, 9152, 1108 ]\n   text               tokens                   token IDs', NULL, 1);
