INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Why do LLMs use sub-word tokens (like BPE) instead of whole words?', NULL, NULL, 'They can represent any word, even new or rare ones, with a fixed vocabulary', 'What happens to a word never seen in training?', 'Sub-words avoid ''unknown word'' problems and keep the vocabulary a manageable size.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Whole words are not allowed', 0), (@q, 'B', 'Sub-words are always shorter to type', 0), (@q, 'C', 'They can represent any word, even new or rare ones, with a fixed vocabulary', 1), (@q, 'D', 'To hide the text', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'true_false', 'API pricing and context limits for LLMs are measured in tokens, not words.', NULL, NULL, 'True', 'Check any LLM pricing page.', 'Roughly 1 token ≈ 3/4 of an English word; cost and limits are counted in tokens.', NULL, NULL, 3);
