INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'granularity'), 1, 'code_output', 'What does this print?', 'print(list("hi you"))', 'python', '[''h'', ''i'', '' '', ''y'', ''o'', ''u'']', 'list() of a string gives every character, including spaces.', 'Character tokenisation: every character is a token, the space too. The vocabulary is tiny but sequences get long.', NULL, NULL, 14);
