INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'autoregressive'), 1, 'mcq', '''Autoregressive'' generation means the model:', NULL, NULL, 'Produces one token at a time, feeding each new token back in as input for the next', '''Auto'' = self, ''regressive'' = depends on previous values.', 'Each new token is appended to the input and the model runs again, so the output is built left to right.', ' [The cat]        -> model -> "sat"\n [The cat sat]    -> model -> "on"\n [The cat sat on] -> model -> "the"   ... until <end>', NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Reads the answer from a database', 0), (@q, 'B', 'Corrects its own grammar automatically', 0), (@q, 'C', 'Writes the whole answer in one step', 0), (@q, 'D', 'Produces one token at a time, feeding each new token back in as input for the next', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'autoregressive'), 1, 'mcq', 'For each step, the model''s raw output is:', NULL, NULL, 'One score (logit) for every token in its vocabulary', 'It must rank every possible next token.', 'Logits (raw, unnormalised scores) cover the whole vocabulary, e.g. ~50k-200k numbers. Softmax turns them into probabilities.', NULL, NULL, 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A single finished word', 0), (@q, 'B', 'One score (logit) for every token in its vocabulary', 1), (@q, 'C', 'A full sentence', 0), (@q, 'D', 'A yes/no answer', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'autoregressive'), 1, 'code_output', 'What does this print?', 'next_tok = {''<s>'': ''the'', ''the'': ''cat'', ''cat'': ''sat'', ''sat'': ''</s>''}\ntok, words = ''<s>'', []\nwhile True:\n    tok = next_tok[tok]\n    if tok == ''</s>'':\n        break\n    words.append(tok)\nprint('' ''.join(words))', 'python', 'the cat sat', 'The loop stops as soon as the end token is produced.', 'A toy ''model'' that maps the last token to the next one. Real LLMs look at the whole context, but the loop shape is the same: predict, check for stop, append.', NULL, 'A while-loop calling next_token(context) until it returns the sentinel.', 7);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'the cat sat </s>', 0), (@q, 'B', '<s> the cat sat </s>', 0), (@q, 'C', 'the', 0), (@q, 'D', 'the cat sat', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'autoregressive'), 2, 'code_output', 'What does this print?', 'tokens = [5, 8, 2, 9]\ninputs, targets = tokens[:-1], tokens[1:]\nprint(inputs, targets)', 'python', '[5, 8, 2] [8, 2, 9]', 'Each position predicts the NEXT token.', 'In training, the input is shifted by one against the target, and all 3 predictions are made in one parallel pass (teacher forcing).', NULL, NULL, 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[5, 8, 2, 9] [8, 2, 9]', 0), (@q, 'B', '[5, 8] [2, 9]', 0), (@q, 'C', '[5, 8, 2] [8, 2, 9]', 1), (@q, 'D', '[8, 2, 9] [5, 8, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'autoregressive'), 2, 'true_false', 'During training, a GPT-style model predicts every next token of a sequence in one parallel pass, but at generation time it must produce tokens one by one.', NULL, NULL, 'True', 'In training you already know the true text.', 'Teacher forcing feeds the real previous tokens with a causal mask, so all positions train at once. At inference the next input doesn''t exist until it''s generated.', NULL, NULL, 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'autoregressive'), 3, 'mcq', 'Without a KV cache, generating token number t requires:', NULL, NULL, 'Running the model over all t previous tokens again', 'What is recomputed each step?', 'Without caching, every step re-encodes the whole prefix, making generation of n tokens roughly O(n²) passes worth of work. The KV cache keeps past K/V so each step processes only the new token.', NULL, NULL, 10);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only processing the new token', 0), (@q, 'B', 'Re-training the model', 0), (@q, 'C', 'Running the model over all t previous tokens again', 1), (@q, 'D', 'Processing only the first token', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'autoregressive'), 4, 'mcq', '''Exposure bias'' in autoregressive models refers to:', NULL, NULL, 'The model is trained on true previous tokens but at inference sees its own (possibly wrong) tokens, so errors can compound', 'Teacher forcing vs free-running.', 'Training never shows the model its own mistakes as context; at inference one bad token shifts the context and later tokens follow it.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Overexposure of the GPU to heat', 0), (@q, 'B', 'The model is trained on true previous tokens but at inference sees its own (possibly wrong) tokens, so errors can compound', 1), (@q, 'C', 'Bias in the training data toward one country', 0), (@q, 'D', 'The model sees too many images', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'decoding'), 1, 'code_output', 'What does this print?', 'import numpy as np\nvocab = [''cat'', ''mat'', ''hat'', ''bat'']\nlogits = np.array([1.2, 3.4, 0.5, 3.1])\nprint(vocab[int(np.argmax(logits))])', 'python', 'mat', 'Greedy = pick the highest score.', 'argmax returns index 1 (logit 3.4), which is ''mat''. Greedy decoding does exactly this every step.', NULL, NULL, 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'bat', 0), (@q, 'B', 'hat', 0), (@q, 'C', 'cat', 0), (@q, 'D', 'mat', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'decoding'), 1, 'mcq', 'Greedy decoding means:', NULL, NULL, 'Always choosing the single most likely next token', 'Grab the biggest piece every time.', 'Greedy takes argmax at each step: fast and deterministic, but it can get stuck in repetitive or suboptimal text.', NULL, NULL, 13);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Asking the user to choose', 0), (@q, 'B', 'Always choosing the single most likely next token', 1), (@q, 'C', 'Choosing the longest token', 0), (@q, 'D', 'Choosing a random token', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'decoding'), 2, 'code_output', 'What does this print?', 'p1 = {''A'': 0.6, ''B'': 0.4}\np2 = {''A'': {''x'': 0.3, ''y'': 0.3, ''z'': 0.4}, ''B'': {''x'': 0.9, ''y'': 0.05, ''z'': 0.05}}\ng1 = max(p1, key=p1.get)\ng2 = max(p2[g1], key=p2[g1].get)\nbest = max(((a, b) for a in p1 for b in p2[a]), key=lambda s: p1[s[0]] * p2[s[0]][s[1]])\nprint(g1 + g2, round(p1[g1] * p2[g1][g2], 2), ''''.join(best), round(p1[best[0]] * p2[best[0]][best[1]], 2))', 'python', 'Az 0.24 Bx 0.36', 'Greedy commits to ''A'' at step 1.', 'Greedy picks A (0.6) then z: 0.24 total. The best 2-token sequence is B then x: 0.36. Greedy is locally optimal, not globally.', NULL, NULL, 14);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Bx 0.36 Bx 0.36', 0), (@q, 'B', 'Ax 0.18 Bx 0.36', 0), (@q, 'C', 'Az 0.24 Bx 0.36', 1), (@q, 'D', 'Az 0.24 Az 0.24', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'decoding'), 2, 'true_false', 'Greedy decoding always finds the most probable complete sequence.', NULL, NULL, 'False', 'A low first step can lead to a much better second step.', 'Greedy maximises each step separately. A sequence starting with a less likely token can have a higher total probability.', NULL, NULL, 15);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'decoding'), 3, 'mcq', 'Beam search with beam width 3 works by:', NULL, NULL, 'Keeping the 3 highest-scoring partial sequences at each step and extending each of them', 'A breadth-limited search.', 'At each step it expands every kept sequence by every token, scores by total log-probability, and keeps the top 3. Width 1 = greedy.', ' step1: A(.6)  B(.4)          keep top-2\n step2: Ax Ay Az  Bx By Bz     score = P(a)*P(b|a)\n        .18 .18 .24 .36 .02 .02 -> keep Bx, Az', NULL, 16);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Generating 3 tokens at once', 0), (@q, 'B', 'Running 3 different models', 0), (@q, 'C', 'Keeping the 3 highest-scoring partial sequences at each step and extending each of them', 1), (@q, 'D', 'Sampling 3 random tokens and picking one', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'decoding'), 3, 'mcq', 'Beam search scores by sum of log-probabilities. Without length normalisation, it tends to prefer:', NULL, NULL, 'Shorter outputs, because every extra token adds a negative log-probability', 'log(p) < 0 for every token.', 'Each token makes the total score more negative, so ending early looks better. Dividing by length (or length^α) counteracts this.', NULL, NULL, 17);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Longer outputs', 0), (@q, 'B', 'Outputs with rare words', 0), (@q, 'C', 'Shorter outputs, because every extra token adds a negative log-probability', 1), (@q, 'D', 'Outputs in capital letters', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'decoding'), 4, 'mcq', 'Why do chat LLMs use sampling (temperature/top-p) rather than beam search for open-ended replies?', NULL, NULL, 'Beam search favours high-probability, generic text and often loops into repetition; humans write less predictably', '''The Curious Case of Neural Text Degeneration.''', 'Maximising probability gives bland, repetitive text for open-ended tasks. Beam search still suits tasks with one right output, like translation or short structured answers.', NULL, NULL, 18);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Beam search needs labelled data', 0), (@q, 'B', 'Beam search cannot run on GPUs', 0), (@q, 'C', 'Beam search favours high-probability, generic text and often loops into repetition; humans write less predictably', 1), (@q, 'D', 'Sampling is always more accurate', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 1, 'code_output', 'What does this print?', 'import numpy as np\nlogits = np.array([2.0, 1.0, 0.1])\np = np.exp(logits) / np.exp(logits).sum()\nprint(np.round(p, 2), round(float(p.sum()), 2))', 'python', '[0.66 0.24 0.1 ] 1.0', 'Softmax: exp, then divide by the total.', 'Softmax turns logits into probabilities summing to 1, keeping the order: the biggest logit gets the biggest probability.', NULL, NULL, 19);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0.5 0.3 0.2] 1.0', 0), (@q, 'B', '[2.  1.  0.1] 3.1', 0), (@q, 'C', '[0.33 0.33 0.33] 1.0', 0), (@q, 'D', '[0.66 0.24 0.1 ] 1.0', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 1, 'mcq', 'You want an LLM to extract invoice numbers from emails, as consistently as possible. Which temperature is the sensible choice?', NULL, NULL, '0 (or very low)', 'Extraction has one right answer.', 'Low temperature makes the model pick its most likely tokens, giving consistent, focused output. Higher values help for brainstorming, not extraction.', NULL, NULL, 20);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0 (or very low)', 1), (@q, 'B', '2.0', 0), (@q, 'C', '1.5', 0), (@q, 'D', 'It doesn''t matter for extraction', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 1, 'true_false', 'Raising the temperature makes the model more knowledgeable and accurate.', NULL, NULL, 'False', 'Temperature only reshapes the probabilities.', 'Higher temperature flattens the distribution so unlikely tokens are picked more often. That adds variety, and also more mistakes; it adds no knowledge.', NULL, NULL, 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 2, 'code_output', 'What does this print?', 'import numpy as np\nlogits = np.array([2.0, 1.0, 0.0])\nfor T in (0.5, 1.0, 2.0):\n    p = np.exp(logits / T) / np.exp(logits / T).sum()\n    print(T, round(float(p.max()), 3))', 'python', '0.5 0.867\n1.0 0.665\n2.0 0.506', 'Dividing by T < 1 widens the gaps between logits.', 'Low T sharpens (top token 0.867), high T flattens (0.506). Temperature is applied as softmax(logits / T).', NULL, NULL, 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.5 1.0\n1.0 0.665\n2.0 0.333', 0), (@q, 'B', '0.5 0.506\n1.0 0.665\n2.0 0.867', 0), (@q, 'C', '0.5 0.665\n1.0 0.665\n2.0 0.665', 0), (@q, 'D', '0.5 0.867\n1.0 0.665\n2.0 0.506', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 2, 'code_output', 'What does this print?', 'import torch\nlogits = torch.tensor([3.0, 1.0, 2.0, 0.5])\nvals, idx = torch.topk(logits, k=2)\nfiltered = torch.full_like(logits, float(''-inf''))\nfiltered[idx] = vals\nprint([round(x, 3) for x in filtered.softmax(-1).tolist()])', 'python', '[0.731, 0.0, 0.269, 0.0]', 'Only tokens 0 and 2 survive; then renormalise.', 'Top-k=2 keeps logits 3.0 and 2.0 and sets the rest to -inf. softmax([3, 2]) = [0.731, 0.269]; the others get 0.', NULL, NULL, 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0.731, 0.0, 0.269, 0.0]', 1), (@q, 'B', '[0.61, 0.083, 0.224, 0.083]', 0), (@q, 'C', '[0.5, 0.0, 0.5, 0.0]', 0), (@q, 'D', '[0.731, 0.269, 0.0, 0.0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 2, 'code_output', 'What does this print?', 'import numpy as np\nprobs = np.array([0.5, 0.2, 0.15, 0.1, 0.05])   # already sorted\ncum = np.cumsum(probs)\nkeep = (cum - probs) < 0.8\nprint(int(keep.sum()))', 'python', '3', 'Keep adding tokens until the running total reaches 0.8.', '0.5 -> 0.7 -> 0.85. The smallest set reaching p = 0.8 is the top 3 tokens; top-p then samples among those after renormalising.', NULL, NULL, 24);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2', 0), (@q, 'B', '4', 0), (@q, 'C', '5', 0), (@q, 'D', '3', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 2, 'mcq', 'Top-k vs top-p (nucleus) sampling: what''s the key difference?', NULL, NULL, 'Top-k keeps a fixed number of tokens; top-p keeps a variable number whose probabilities add up to p', 'What happens when the model is very sure vs very unsure?', 'If one token has 95% probability, top-p=0.9 keeps just 1 token while top-k=40 still keeps 40. When the model is unsure, top-p keeps many. It adapts to the distribution.', NULL, NULL, 25);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'They are two names for the same method', 0), (@q, 'B', 'Top-p keeps a fixed number of tokens; top-k a variable number', 0), (@q, 'C', 'Top-k keeps a fixed number of tokens; top-p keeps a variable number whose probabilities add up to p', 1), (@q, 'D', 'Top-k works only with temperature 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 2, 'fill_blank', 'Setting top_p = ____ keeps the whole distribution, i.e. applies no nucleus filtering.', NULL, NULL, '1.0', 'The cumulative probability of all tokens.', 'All probabilities sum to 1, so top_p = 1.0 keeps every token.', NULL, NULL, 26);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 3, 'code_output', 'What does this print?', 'import numpy as np\nlogits = np.array([0.3, 2.5, 2.4, -1.0])\nfor T in (0.2, 1.0, 5.0):\n    print(int(np.argmax(logits / T)), end='' '')', 'python', '1 1 1 ', 'Dividing every logit by the same positive number.', 'Temperature rescales logits by a positive constant, which never changes their order. The most likely token is the same at every T; only how peaked the distribution is changes.', NULL, NULL, 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1 1 1 ', 1), (@q, 'B', '1 2 0 ', 0), (@q, 'C', '1 1 0 ', 0), (@q, 'D', '2 1 1 ', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 3, 'code_output', 'What does this print?', 'logits = {''the'': 2.0, ''error'': -1.0, ''fix'': 0.5}\nseen = {''the'', ''error''}\npenalty = 2.0\nbuggy = {t: (l / penalty if t in seen else l) for t, l in logits.items()}\ncorrect = {t: ((l / penalty if l > 0 else l * penalty) if t in seen else l) for t, l in logits.items()}\nprint(buggy[''error''], correct[''error''])', 'python', '-0.5 -2.0', 'Dividing a negative number by 2 moves it toward zero.', 'Dividing -1.0 by 2 gives -0.5, which RAISES the probability of a repeated token. A correct (CTRL-style) repetition penalty divides positive logits and multiplies negative ones.', NULL, NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '-2.0 -0.5', 0), (@q, 'B', '-0.5 -0.5', 0), (@q, 'C', '-2.0 -2.0', 0), (@q, 'D', '-0.5 -2.0', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 3, 'mcq', 'OpenAI-style APIs have frequency_penalty and presence_penalty. How do they differ?', NULL, NULL, 'Frequency penalises a token more each time it repeats; presence applies a one-off penalty once it has appeared at all', 'Count vs yes/no.', 'frequency_penalty scales with how many times the token appeared; presence_penalty is a flat penalty for having appeared, nudging the model toward new topics.', NULL, NULL, 29);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Frequency changes the temperature; presence changes top-p', 0), (@q, 'B', 'Frequency penalises a token more each time it repeats; presence applies a one-off penalty once it has appeared at all', 1), (@q, 'C', 'They''re identical', 0), (@q, 'D', 'Presence penalises the prompt; frequency penalises the system message', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 4, 'mcq', 'You set temperature = 1.3 and top_p = 0.9 for a creative app and get occasional gibberish. What''s the most likely cause?', NULL, NULL, 'High temperature flattens the distribution, so the 0.9 nucleus now includes many junk tokens', 'Temperature is usually applied before top-p.', 'Samplers typically apply temperature, then top-k/top-p. Flattening first spreads mass to the tail, so 90% of it now covers far more low-quality tokens. Lower T (or top_p) fixes it.', NULL, NULL, 30);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Gibberish means the prompt was too short', 0), (@q, 'B', 'High temperature flattens the distribution, so the 0.9 nucleus now includes many junk tokens', 1), (@q, 'C', 'The model is out of tokens', 0), (@q, 'D', 'top_p is too low', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sampling'), 4, 'code_output', 'What does this print?', 'import numpy as np\nprobs = np.array([0.6, 0.2, 0.1, 0.06, 0.04])\nmin_p = 0.15\nkeep = probs >= min_p * probs.max()\nprint(keep.astype(int).tolist(), round(float(probs[keep].sum()), 2))', 'python', '[1, 1, 1, 0, 0] 0.9', 'The threshold is 0.15 x 0.6 = 0.09.', 'min-p keeps tokens at least min_p times as likely as the top token: here 0.6, 0.2 and 0.1. It scales with the model''s confidence, like top-p, but is robust at high temperatures.', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 1, 1, 1, 1] 1.0', 0), (@q, 'B', '[1, 1, 0, 0, 0] 0.8', 0), (@q, 'C', '[1, 1, 1, 0, 0] 0.9', 1), (@q, 'D', '[1, 0, 0, 0, 0] 0.6', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stopping-context'), 1, 'mcq', 'What does the max_tokens (max output tokens) setting do?', NULL, NULL, 'Caps how many tokens the model may generate in its reply', 'It''s a loop guard.', 'Generation stops once max_tokens have been produced, even mid-sentence. The API then reports a ''length'' finish reason.', NULL, NULL, 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Caps how many tokens the model may generate in its reply', 1), (@q, 'B', 'Sets how many tokens the model knows', 0), (@q, 'C', 'Sets the size of the vocabulary', 0), (@q, 'D', 'Limits the number of users', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stopping-context'), 1, 'true_false', 'If a conversation grows longer than the context window, the model still remembers the parts that no longer fit.', NULL, NULL, 'False', 'The model only sees what''s in its input.', 'The model has no memory outside the window. Apps must truncate, summarise or retrieve older content; whatever is dropped is simply invisible.', NULL, 'A fixed-size ring buffer: once something is overwritten, it''s gone.', 33);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stopping-context'), 2, 'code_output', 'What does this print?', 'text = ''Answer: 42\\n\\nQuestion: what is 6 x 9?''\nstop = ''\\n\\n''\nprint(repr(text.split(stop)[0]))', 'python', '''Answer: 42''', 'Cut at the first stop sequence.', 'A stop sequence ends generation and, in most APIs, the stop text itself is not included in the returned output. Here the model would have rambled into a new question.', NULL, NULL, 34);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '''Answer: 42\\n\\n''', 0), (@q, 'B', '''Answer: 42\\n\\nQuestion: what is 6 x 9?''', 0), (@q, 'C', '''Question: what is 6 x 9?''', 0), (@q, 'D', '''Answer: 42''', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stopping-context'), 2, 'code_output', 'What does this print?', 'context_window = 8192\nprompt_tokens = 7900\nrequested_max = 1000\nprint(min(requested_max, context_window - prompt_tokens))', 'python', '292', 'Prompt + completion share one window.', 'Only 8192 - 7900 = 292 tokens are left for the reply. Some APIs reject the request; others cut the reply short. Long prompts silently shrink your output budget.', NULL, NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '7900', 0), (@q, 'B', '1000', 0), (@q, 'C', '292', 1), (@q, 'D', '8192', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stopping-context'), 2, 'mcq', 'An API response returns finish_reason = ''length''. What happened?', NULL, NULL, 'The reply hit max_tokens (or the context limit) and was cut off', 'Natural end is ''stop''.', '''stop'' = end token or stop sequence; ''length'' = truncated by a limit. Check it in code: a ''length'' JSON output is probably incomplete and won''t parse.', NULL, NULL, 36);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The request was rejected for safety', 0), (@q, 'B', 'A stop sequence was matched', 0), (@q, 'C', 'The model chose to end with its end-of-sequence token', 0), (@q, 'D', 'The reply hit max_tokens (or the context limit) and was cut off', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stopping-context'), 3, 'true_false', 'In chat-completion APIs, max_tokens counts both the prompt and the reply.', NULL, NULL, 'False', 'Which side of the conversation does it limit?', 'max_tokens caps the completion only. The prompt still consumes the context window, so prompt + max_tokens must fit within it.', NULL, NULL, 37);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stopping-context'), 3, 'code_output', 'What does this print?', 'history = list(range(10))            # token ids, oldest first\nwindow = 6\nsystem = [100]\nkept = system + history[-(window - len(system)):]\nprint(kept)', 'python', '[100, 5, 6, 7, 8, 9]', 'Keep the system prompt, then the most recent turns that fit.', 'A common truncation strategy: pin the system prompt and keep the newest tokens. 6 - 1 = 5 slots for history: tokens 5..9.', NULL, NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[100, 0, 1, 2, 3, 4]', 0), (@q, 'B', '[100, 4, 5, 6, 7, 8, 9]', 0), (@q, 'C', '[100, 5, 6, 7, 8, 9]', 1), (@q, 'D', '[5, 6, 7, 8, 9, 100]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stopping-context'), 4, 'mcq', '''Lost in the middle'' research found that long-context models:', NULL, NULL, 'Use information at the start and end of the context best, and often miss facts buried in the middle', 'A U-shaped accuracy curve.', 'Accuracy on retrieval-style questions dropped when the relevant passage was in the middle of a long prompt. Put key instructions and the best RAG chunks near the start or end.', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Read the middle best and ignore the start', 0), (@q, 'B', 'Treat every position equally', 0), (@q, 'C', 'Can''t accept more than 4k tokens', 0), (@q, 'D', 'Use information at the start and end of the context best, and often miss facts buried in the middle', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tokens-cost'), 1, 'mcq', 'When an LLM API bills you per token, a token is:', NULL, NULL, 'A chunk of text: often a word or part of a word', '''unbelievable'' might be ''un'' + ''believ'' + ''able''.', 'Tokenizers split text into sub-word pieces. In English, 1 token is roughly 4 characters or 0.75 words.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Always one character', 0), (@q, 'B', 'One API call', 0), (@q, 'C', 'Always exactly one word', 0), (@q, 'D', 'A chunk of text: often a word or part of a word', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tokens-cost'), 1, 'fill_blank', 'Roughly, 1,000 tokens of English text is about ____ words.', NULL, NULL, '750', 'About three quarters of a word per token.', 'A common rule of thumb is ~0.75 words per token, so 1,000 tokens ≈ 750 words. Code, numbers and many non-English languages use more tokens.', NULL, NULL, 41);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tokens-cost'), 2, 'true_false', 'Prompt (input) tokens and completion (output) tokens are usually priced the same.', NULL, NULL, 'False', 'Check any provider''s pricing page.', 'Output tokens are typically several times more expensive than input tokens because they are generated one by one (decode), while input is processed in parallel (prefill).', NULL, NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tokens-cost'), 2, 'code_output', 'What does this print?', 'price_in, price_out = 3.00, 15.00        # $ per 1M tokens\nprompt, completion = 1200, 400\ncost = prompt * price_in / 1e6 + completion * price_out / 1e6\nprint(round(cost, 4))', 'python', '0.0096', 'Price each side separately.', '1200 x $3/M = $0.0036 and 400 x $15/M = $0.006, total $0.0096. The 400 output tokens cost more than the 1200 input tokens.', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '9.6', 0), (@q, 'B', '0.0072', 0), (@q, 'C', '0.0096', 1), (@q, 'D', '0.0288', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tokens-cost'), 3, 'code_output', 'What does this print?', 'calls_per_day = 50_000\nprompt, completion = 2000, 300\nprice_in, price_out = 0.15, 0.60        # $ per 1M tokens\ndaily = calls_per_day * (prompt * price_in + completion * price_out) / 1e6\nprint(round(daily, 2), round(daily * 30))', 'python', '24.0 720', 'Per call: 2000 x 0.15 + 300 x 0.60 millionths of a dollar.', 'Per call = (300 + 180) / 1e6 = $0.00048; x 50k = $24/day ≈ $720/month. Here the long prompt dominates, so shrinking it (or prompt caching) saves the most.', NULL, NULL, 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '15.0 450', 0), (@q, 'B', '24.0 720', 1), (@q, 'C', '240.0 7200', 0), (@q, 'D', '2.4 72', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tokens-cost'), 3, 'mcq', 'Why can the same sentence cost more tokens in Hindi or Japanese than in English on many models?', NULL, NULL, 'The tokenizer was trained mostly on English, so other scripts are split into more, smaller pieces', 'BPE merges frequent patterns from its training data.', 'Byte-pair encoding learns merges from its training corpus. Under-represented languages get fewer merges, so each word uses more tokens: more cost and less effective context.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'APIs charge extra for non-English text by policy', 0), (@q, 'B', 'The tokenizer was trained mostly on English, so other scripts are split into more, smaller pieces', 1), (@q, 'C', 'Non-English text is encrypted first', 0), (@q, 'D', 'Tokens are counted per byte only for English', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'tokens-cost'), 4, 'mcq', 'Prompt caching (offered by several LLM providers) reduces cost and latency by:', NULL, NULL, 'Reusing the computed KV cache for a repeated prompt prefix (like a long system prompt) across requests', 'What part of the work is identical across requests that share a prefix?', 'If many calls start with the same long prefix, the provider can store its prefill result and skip recomputing it. Keep the static part first and the varying part last to benefit.', NULL, NULL, 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Reusing the computed KV cache for a repeated prompt prefix (like a long system prompt) across requests', 1), (@q, 'B', 'Skipping the tokenizer', 0), (@q, 'C', 'Caching the final answers and returning them for any similar question', 0), (@q, 'D', 'Compressing the prompt text with gzip', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'training-pipeline'), 1, 'mcq', 'You give a BASE model (only pre-trained) the prompt ''What is the capital of France?''. A likely output is:', NULL, NULL, 'More text that continues the document, e.g. ''What is the capital of Germany? What is...''', 'A base model is pure autocomplete.', 'Base models continue text in the style of their training data; a list of quiz questions is a plausible continuation. Instruction tuning teaches the ''answer the user'' behaviour.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Always a polite answer: ''The capital of France is Paris.''', 0), (@q, 'B', 'Nothing', 0), (@q, 'C', 'More text that continues the document, e.g. ''What is the capital of Germany? What is...''', 1), (@q, 'D', 'An error message', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'training-pipeline'), 1, 'mcq', 'Put the usual LLM training stages in order:', NULL, NULL, 'Pre-training -> supervised fine-tuning (SFT) -> preference tuning (RLHF/DPO)', 'Learn language first, then manners.', 'Pre-training on huge text gives knowledge and language; SFT on instruction/answer pairs teaches following instructions; RLHF or DPO tunes toward answers people prefer.', ' raw web text  ->  [pre-train]  -> base model\n Q/A examples  ->  [SFT]        -> instruct model\n A vs B prefs  ->  [RLHF / DPO] -> chat assistant', NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Pre-training -> supervised fine-tuning (SFT) -> preference tuning (RLHF/DPO)', 1), (@q, 'B', 'Preference tuning -> SFT -> pre-training', 0), (@q, 'C', 'RLHF -> pre-training -> SFT', 0), (@q, 'D', 'SFT -> pre-training -> RLHF', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'training-pipeline'), 2, 'mcq', 'What data does supervised fine-tuning (SFT / instruction tuning) use?', NULL, NULL, 'Example prompts paired with high-quality responses', 'Show the model the answer you want.', 'SFT trains next-token prediction on demonstration conversations, usually tens of thousands to millions of curated examples.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only a reward score per answer', 0), (@q, 'B', 'Pairs of images and captions', 0), (@q, 'C', 'Example prompts paired with high-quality responses', 1), (@q, 'D', 'Raw web pages only', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'training-pipeline'), 2, 'mcq', 'In RLHF, the reward model is trained on:', NULL, NULL, 'Human rankings of which of two (or more) responses is better', 'People compare A vs B.', 'Labellers rank responses; a reward model learns to score them; then the LLM is optimised (e.g. with PPO) to get high reward while staying close to the SFT model.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Human rankings of which of two (or more) responses is better', 1), (@q, 'B', 'The original pre-training text', 0), (@q, 'C', 'The model''s perplexity', 0), (@q, 'D', 'Random labels', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'training-pipeline'), 3, 'mcq', 'How does DPO (Direct Preference Optimization) differ from classic RLHF with PPO?', NULL, NULL, 'DPO trains directly on preferred/rejected pairs with a classification-style loss, with no separate reward model or RL loop', 'Fewer moving parts.', 'DPO rewrites the RLHF objective so the policy itself acts as the reward model; it''s simpler and more stable to train, which is why many open models use it.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'DPO uses no human preference data', 0), (@q, 'B', 'DPO happens before pre-training', 0), (@q, 'C', 'DPO only changes the tokenizer', 0), (@q, 'D', 'DPO trains directly on preferred/rejected pairs with a classification-style loss, with no separate reward model or RL loop', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'training-pipeline'), 3, 'code_output', 'What does this print?', 'messages = [{''role'': ''system'', ''content'': ''Be brief.''}, {''role'': ''user'', ''content'': ''Hi''}]\nprompt = ''''.join(f"<|{m[''role'']}|>{m[''content'']}<|end|>" for m in messages) + ''<|assistant|>''\nprint(prompt)', 'python', '<|system|>Be brief.<|end|><|user|>Hi<|end|><|assistant|>', 'Chat messages are flattened into one string with special tokens.', 'A chat template turns the message list into one token sequence the model was fine-tuned on, ending with the assistant tag so the model writes the reply. Wrong templates noticeably hurt instruct models.', NULL, NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '<|system|>Be brief.<|end|><|user|>Hi<|end|><|assistant|>', 1), (@q, 'B', '<|assistant|><|system|>Be brief.<|end|><|user|>Hi<|end|>', 0), (@q, 'C', 'system: Be brief. user: Hi', 0), (@q, 'D', 'Be brief. Hi', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'training-pipeline'), 3, 'true_false', 'RLHF is the main stage where an LLM learns new factual knowledge.', NULL, NULL, 'False', 'Where does most of the training compute and data go?', 'Knowledge comes overwhelmingly from pre-training. SFT and RLHF/DPO mainly shape behaviour: format, helpfulness, tone and refusals.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'training-pipeline'), 4, 'mcq', '''Reward hacking'' during RLHF means the model:', NULL, NULL, 'Finds outputs that score high with the reward model without actually being better (e.g. longer, flattering answers)', 'The reward model is only a proxy for human judgement.', 'Optimising hard against an imperfect reward model exploits its blind spots: verbosity, sycophancy, confident tone. A KL penalty keeps the policy near the SFT model to limit this.', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Stops generating text', 0), (@q, 'B', 'Hacks into the training server', 0), (@q, 'C', 'Lowers its own learning rate', 0), (@q, 'D', 'Finds outputs that score high with the reward model without actually being better (e.g. longer, flattering answers)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'training-pipeline'), 4, 'mcq', 'Why does the RLHF objective include a KL-divergence penalty against the SFT (reference) model?', NULL, NULL, 'To stop the policy drifting into weird text that games the reward model, keeping it close to fluent language', 'A leash on the policy.', 'KL measures how far the new model''s token distribution moves from the reference. Penalising it trades a bit of reward for staying in the region where the reward model is reliable.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'To remove the need for a reward model', 0), (@q, 'B', 'To stop the policy drifting into weird text that games the reward model, keeping it close to fluent language', 1), (@q, 'C', 'To make training faster', 0), (@q, 'D', 'To increase the vocabulary', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hallucination'), 1, 'mcq', 'Why do LLMs hallucinate (state false things confidently)?', NULL, NULL, 'They are trained to produce likely-sounding text, not to check facts', 'Plausible is not the same as true.', 'The training objective rewards fluent, likely continuations. If the model doesn''t know, a confident-sounding guess is often the most ''likely'' text.', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'They are trained to produce likely-sounding text, not to check facts', 1), (@q, 'B', 'They are connected to a faulty database', 0), (@q, 'C', 'Their GPUs make mistakes', 0), (@q, 'D', 'Users type the questions wrong', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hallucination'), 2, 'true_false', 'Setting temperature to 0 stops an LLM from hallucinating.', NULL, NULL, 'False', 'What does greedy do if the model''s top guess is wrong?', 'Temperature 0 just picks the most likely token. If the model''s most likely answer is a made-up citation, it will produce that every time.', NULL, NULL, 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hallucination'), 2, 'mcq', 'Which technique most directly reduces hallucinations about your company''s internal policies?', NULL, NULL, 'Retrieval-augmented generation (RAG): fetch the relevant policy text and put it in the prompt', 'Give the model the facts instead of hoping it memorised them.', 'RAG grounds the answer in supplied documents. Pair it with ''answer only from the context, else say you don''t know'' and citations to make errors checkable.', NULL, NULL, 58);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Raising the temperature', 0), (@q, 'B', 'Retrieval-augmented generation (RAG): fetch the relevant policy text and put it in the prompt', 1), (@q, 'C', 'Asking the same question twice', 0), (@q, 'D', 'Using a longer max_tokens', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hallucination'), 3, 'mcq', 'A model is asked for a paper''s DOI and invents a valid-looking but fake one. Which explanation fits best?', NULL, NULL, 'Rare, precise facts are weakly stored in the weights, and the model fills in a plausible pattern', 'It learned what DOIs LOOK like.', 'Exact identifiers seen rarely in training are hard to recall; the model knows the format and produces a pattern-matching string. Tool calls or retrieval should supply such facts.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The DOI system was down', 0), (@q, 'B', 'The tokenizer can''t read numbers', 0), (@q, 'C', 'Rare, precise facts are weakly stored in the weights, and the model fills in a plausible pattern', 1), (@q, 'D', 'The context window was too large', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'hallucination'), 4, 'mcq', 'Research on why models hallucinate argues that common benchmark grading (1 point if right, 0 if wrong or ''I don''t know'') encourages hallucination because:', NULL, NULL, 'Guessing has a positive expected score while abstaining always scores 0, so training and evals reward bluffing', 'Think about a multiple-choice exam with no negative marking.', 'If wrong answers cost nothing extra, guessing beats ''I don''t know''. Penalising confident errors more than abstentions (and calibrating) reduces hallucination.', NULL, NULL, 60);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Guessing has a positive expected score while abstaining always scores 0, so training and evals reward bluffing', 1), (@q, 'B', 'Abstaining crashes the evaluation', 0), (@q, 'C', 'Graders prefer short answers', 0), (@q, 'D', 'Benchmarks are too easy', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'perplexity'), 1, 'mcq', 'A lower perplexity on a test text means the language model:', NULL, NULL, 'Was less surprised by the text: it assigned higher probability to the actual tokens', 'Perplexity = ''how many options it felt torn between''.', 'Perplexity measures how well the model predicts real text; lower is better. A perplexity of 10 is like choosing uniformly among 10 tokens at every step.', NULL, NULL, 61);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Has fewer parameters', 0), (@q, 'B', 'Is more confused', 0), (@q, 'C', 'Generates longer answers', 0), (@q, 'D', 'Was less surprised by the text: it assigned higher probability to the actual tokens', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'perplexity'), 2, 'fill_blank', 'Perplexity = exp(average negative ____ of the true tokens). (two words, hyphen ok)', NULL, NULL, 'log-likelihood', 'The training loss of a language model.', 'Perplexity is exp(cross-entropy loss), i.e. exp of the mean negative log-likelihood per token.', NULL, NULL, 62);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'perplexity'), 2, 'code_output', 'What does this print?', 'import numpy as np\np_true = np.array([0.5, 0.25, 0.125])   # model''s prob for each actual token\nnll = -np.log(p_true).mean()\nprint(round(float(np.exp(nll)), 4))', 'python', '4.0', 'The geometric mean of 1/p.', '1/p values are 2, 4, 8; their geometric mean is (2·4·8)^(1/3) = 4. So perplexity is 4.0.', NULL, NULL, 63);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.2917', 0), (@q, 'B', '4.0', 1), (@q, 'C', '2.0', 0), (@q, 'D', '8.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'perplexity'), 3, 'code_output', 'What does this print?', 'import numpy as np\nV = 50\np_true = np.full(1000, 1 / V)      # uniform guess for every token\nprint(round(float(np.exp(-np.log(p_true).mean())), 4))', 'python', '50.0', 'Uniform over V choices.', 'A model that guesses uniformly over V tokens has perplexity exactly V. Good LLMs on ordinary text reach single-digit perplexity despite vocabularies of 50k+.', NULL, NULL, 64);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3.912', 0), (@q, 'B', '1.0', 0), (@q, 'C', '50.0', 1), (@q, 'D', '0.02', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'perplexity'), 3, 'true_false', 'Model A (word-level tokenizer) has perplexity 30 and model B (sub-word tokenizer) has perplexity 12 on the same text, so B is clearly the better language model.', NULL, NULL, 'False', 'Perplexity is per token. Are the tokens the same?', 'Different tokenizers split the same text into different numbers of tokens, so per-token perplexities aren''t comparable. Compare bits per byte/character, or use the same tokenizer.', NULL, NULL, 65);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'perplexity'), 4, 'mcq', 'A chat model after RLHF has HIGHER perplexity on web text than its base model, yet users prefer it. Why is that not a contradiction?', NULL, NULL, 'Perplexity measures fit to the raw text distribution, not helpfulness; RLHF deliberately moves the model away from that distribution', 'What is perplexity actually rewarding?', 'Lower perplexity = better imitation of internet text. Preference tuning trades some of that for following instructions and being helpful, so perplexity alone can''t rank chat assistants.', NULL, NULL, 66);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Users can''t tell models apart', 0), (@q, 'B', 'RLHF makes the vocabulary smaller', 0), (@q, 'C', 'Perplexity is broken for chat models', 0), (@q, 'D', 'Perplexity measures fit to the raw text distribution, not helpfulness; RLHF deliberately moves the model away from that distribution', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'latency'), 1, 'mcq', '''Time to first token'' (TTFT) is:', NULL, NULL, 'How long you wait before the first word of the reply appears', 'What the user feels as ''is it thinking?''.', 'TTFT covers queueing plus processing the whole prompt (prefill). Streaming shows tokens as they arrive so the reply feels fast even if the total time is long.', NULL, NULL, 67);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The time to type the prompt', 0), (@q, 'B', 'How long the model took to train', 0), (@q, 'C', 'The total time for the whole reply', 0), (@q, 'D', 'How long you wait before the first word of the reply appears', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'latency'), 2, 'code_output', 'What does this print?', 'ttft = 0.4           # seconds\ntokens_per_sec = 50\noutput_tokens = 200\nprint(ttft + output_tokens / tokens_per_sec)', 'python', '4.4', 'Wait for the first token, then stream the rest.', 'Total ≈ TTFT + output_tokens / decode speed = 0.4 + 4.0 = 4.4 s. Output length usually dominates total latency.', NULL, NULL, 68);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4.4', 1), (@q, 'B', '0.4', 0), (@q, 'C', '10.4', 0), (@q, 'D', '4.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'latency'), 2, 'true_false', 'Asking for a much longer answer mostly increases time-to-first-token.', NULL, NULL, 'False', 'Which phase handles the prompt, and which the output?', 'TTFT depends mainly on prompt length (prefill) and queueing. A longer answer adds decode steps after the first token, increasing total time, not TTFT.', NULL, NULL, 69);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'latency'), 3, 'mcq', 'Prefill vs decode: which statement is correct?', NULL, NULL, 'Prefill processes all prompt tokens in parallel (compute-bound); decode generates one token per step (memory-bandwidth bound)', 'How many tokens per forward pass in each phase?', 'Prefill = big matrix-matrix multiplies over the prompt, keeping the GPU busy. Decode = one token''s matrix-vector work per step, but all weights and the KV cache must be read from memory each time.', ' prefill: [p1 p2 p3 ... p2000] -> one pass   (compute)\n decode : t1 -> t2 -> t3 -> ...  one per pass (memory)', NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Prefill processes all prompt tokens in parallel (compute-bound); decode generates one token per step (memory-bandwidth bound)', 1), (@q, 'B', 'Prefill generates the output; decode reads the prompt', 0), (@q, 'C', 'Decode is compute-bound because it processes many tokens at once', 0), (@q, 'D', 'Both phases process one token at a time', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'latency'), 3, 'code_output', 'What does this print?', 'weights_gb = 14          # 7B params in fp16\nbandwidth_gb_s = 1000    # GPU memory bandwidth\nprint(round(bandwidth_gb_s / weights_gb, 1), ''tokens/sec upper bound (batch 1)'')', 'python', '71.4 tokens/sec upper bound (batch 1)', 'Each decode step reads every weight once.', 'At batch 1, decode speed is capped by how fast all weights can be streamed from memory: 1000 / 14 ≈ 71 tokens/s. This is why quantisation (fewer bytes) speeds up decoding.', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '14.0 tokens/sec upper bound (batch 1)', 0), (@q, 'B', '71.4 tokens/sec upper bound (batch 1)', 1), (@q, 'C', '1000.0 tokens/sec upper bound (batch 1)', 0), (@q, 'D', '7.0 tokens/sec upper bound (batch 1)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'latency'), 4, 'code_output', 'What does this print?', 'layers, kv_heads, head_dim, bytes_ = 32, 32, 128, 2\nper_token = 2 * layers * kv_heads * head_dim * bytes_\nper_seq_gib = per_token * 4096 / 2**30\nfree_gib = 20\nprint(per_token / 2**20, ''MiB/token'', int(free_gib // per_seq_gib), ''sequences'')', 'python', '0.5 MiB/token 10 sequences', '2 (K and V) x layers x heads x head_dim x 2 bytes.', '0.5 MiB per token x 4096 tokens = 2 GiB per full sequence; 20 GiB of free GPU memory holds only 10 concurrent 4k-token sequences. The KV cache, not the weights, often caps concurrency.', NULL, NULL, 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.5 MiB/token 20 sequences', 0), (@q, 'B', '0.25 MiB/token 40 sequences', 0), (@q, 'C', '1.0 MiB/token 5 sequences', 0), (@q, 'D', '0.5 MiB/token 10 sequences', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'latency'), 4, 'mcq', 'Why does batching many users'' requests together raise total throughput (tokens/sec across all users) so much during decode?', NULL, NULL, 'Weights are read from memory once per step and reused for every sequence in the batch', 'Decode is memory-bound at batch 1.', 'At batch 1 the GPU mostly waits on memory. With batch 32, the same weight reads serve 32 tokens, so throughput rises almost linearly until compute or KV-cache memory becomes the limit. Continuous batching adds/removes sequences each step.', NULL, NULL, 73);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Batching reduces the number of tokens generated', 0), (@q, 'B', 'Weights are read from memory once per step and reused for every sequence in the batch', 1), (@q, 'C', 'Batching skips the softmax', 0), (@q, 'D', 'Each user gets a smaller model', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inference-opt'), 2, 'mcq', 'Quantising a model from 16-bit to 4-bit weights mainly:', NULL, NULL, 'Cuts the memory needed for weights about 4x, at some cost in quality', 'Fewer bits per number.', 'Each weight takes 4 bits instead of 16, so a 7B model shrinks from ~14 GB to ~3.5 GB, letting it fit on smaller GPUs. Quality usually drops slightly; very low bit-widths drop more.', NULL, NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Cuts the memory needed for weights about 4x, at some cost in quality', 1), (@q, 'B', 'Increases the context window 4x', 0), (@q, 'C', 'Makes the model 4x smarter', 0), (@q, 'D', 'Removes the need for a GPU in every case', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inference-opt'), 3, 'code_output', 'What does this print?', 'params = 7e9\nfor bits in (16, 8, 4):\n    print(bits, params * bits / 8 / 1e9, ''GB'')', 'python', '16 14.0 GB\n8 7.0 GB\n4 3.5 GB', 'bits / 8 = bytes per parameter.', 'fp16 = 2 bytes x 7B = 14 GB; int8 = 7 GB; int4 = 3.5 GB (plus small overhead for scales, and KV cache on top).', NULL, NULL, 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '16 14.0 GB\n8 14.0 GB\n4 14.0 GB', 0), (@q, 'B', '16 14.0 GB\n8 7.0 GB\n4 3.5 GB', 1), (@q, 'C', '16 7.0 GB\n8 3.5 GB\n4 1.75 GB', 0), (@q, 'D', '16 112.0 GB\n8 56.0 GB\n4 28.0 GB', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inference-opt'), 3, 'true_false', 'Quantising weights only saves memory; it can''t make token generation faster.', NULL, NULL, 'False', 'What limits decode speed?', 'Decode is memory-bandwidth bound, so moving 4x fewer bytes per step often speeds generation up, provided the kernels dequantise efficiently.', NULL, NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inference-opt'), 3, 'mcq', 'In speculative decoding, a small draft model proposes several tokens and the large model:', NULL, NULL, 'Checks all of them in a single forward pass, accepting a prefix and correcting the first rejected token', 'Verifying k tokens in parallel costs about as much as generating one.', 'The big model scores the draft tokens in parallel (like a mini prefill). Accepted tokens come almost free; on rejection, it samples a corrected token. Speed-up depends on the acceptance rate.', NULL, NULL, 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Retrains the draft model on the fly', 0), (@q, 'B', 'Checks all of them in a single forward pass, accepting a prefix and correcting the first rejected token', 1), (@q, 'C', 'Averages its output with the draft model''s', 0), (@q, 'D', 'Ignores them and generates normally', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inference-opt'), 4, 'true_false', 'With the standard acceptance rule, speculative decoding produces text from exactly the same probability distribution as the large model alone.', NULL, NULL, 'True', 'Is it an approximation or a reorganisation of work?', 'The accept/reject (rejection-sampling) step guarantees the output distribution matches the target model''s. It''s a pure latency optimisation, not a quality trade-off.', NULL, NULL, 78);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inference-opt'), 4, 'code_output', 'What does this print?', 'alpha, gamma = 0.8, 4      # acceptance rate, drafted tokens per step\nexpected = (1 - alpha ** (gamma + 1)) / (1 - alpha)\nprint(round(expected, 2))', 'python', '3.36', 'A geometric series: 1 + α + α² + ... + α^γ.', 'Expected tokens per big-model pass = (1 − α^(γ+1)) / (1 − α) ≈ 3.36 with α = 0.8 and γ = 4. Low acceptance (a poor draft model) quickly kills the gain.', NULL, NULL, 79);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '5.0', 0), (@q, 'B', '0.8', 0), (@q, 'C', '3.36', 1), (@q, 'D', '4.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inference-opt'), 4, 'mcq', 'A team quantises their model to int4 and sees fine chat quality but a clear drop on maths and code benchmarks. What''s the best explanation?', NULL, NULL, 'Low-bit quantisation adds small errors everywhere; tasks needing long precise reasoning chains are more sensitive, so evaluate on the actual task', 'Small errors compound over many exact steps.', 'Casual chat tolerates small logit errors; multi-step maths and code don''t. Methods like GPTQ/AWQ, keeping outlier channels in higher precision, or int8 reduce the loss. Always re-run task-specific evals after quantising.', NULL, NULL, 80);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Quantisation changes the tokenizer', 0), (@q, 'B', 'The benchmark is broken', 0), (@q, 'C', 'int4 cannot represent digits', 0), (@q, 'D', 'Low-bit quantisation adds small errors everywhere; tasks needing long precise reasoning chains are more sensitive, so evaluate on the actual task', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'determinism'), 1, 'true_false', 'Sending the same prompt twice to an LLM at temperature 0.8 can give two different replies.', NULL, NULL, 'True', 'Temperature > 0 means sampling.', 'With sampling, each token is drawn at random from the distribution, so different runs can pick different tokens and diverge.', NULL, NULL, 81);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'determinism'), 2, 'mcq', 'Temperature 0 is usually implemented as:', NULL, NULL, 'Greedy decoding: always take the argmax token', 'Dividing by 0 isn''t actually computed.', 'softmax(logits / T) approaches one-hot on the top token as T -> 0, so libraries special-case T = 0 as argmax.', NULL, NULL, 82);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Greedy decoding: always take the argmax token', 1), (@q, 'B', 'Random sampling', 0), (@q, 'C', 'Returning an empty reply', 0), (@q, 'D', 'Beam search with width 100', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'determinism'), 2, 'code_output', 'What does this print?', 'import numpy as np\nlogits = np.array([2.0, 5.0, 1.0])\np = np.exp(logits / 0.01 - (logits / 0.01).max())\np /= p.sum()\nprint(np.round(p, 3).tolist())', 'python', '[0.0, 1.0, 0.0]', 'Very small T = very sharp.', 'At T = 0.01 the gaps are multiplied by 100, so the top token gets essentially all the probability: sampling becomes greedy.', NULL, NULL, 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0.047, 0.936, 0.017]', 0), (@q, 'B', '[0.25, 0.625, 0.125]', 0), (@q, 'C', '[0.0, 1.0, 0.0]', 1), (@q, 'D', '[0.333, 0.333, 0.333]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'determinism'), 3, 'code_output', 'What does this print?', 'import torch\nprobs = torch.tensor([0.5, 0.3, 0.2])\na = torch.multinomial(probs, 5, replacement=True, generator=torch.Generator().manual_seed(42))\nb = torch.multinomial(probs, 5, replacement=True, generator=torch.Generator().manual_seed(42))\nprint(torch.equal(a, b))', 'python', 'True', 'Same seed, same generator, same calls.', 'Seeding the random generator makes sampling repeatable on the same software and hardware. Hosted APIs offer a ''seed'' parameter, but only as best effort.', NULL, NULL, 84);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'RuntimeError', 0), (@q, 'B', 'False', 0), (@q, 'C', 'None', 0), (@q, 'D', 'True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'determinism'), 3, 'code_output', 'What does this print?', 'print((0.1 + 0.2) + 0.3 == 0.1 + (0.2 + 0.3))\nprint((0.1 + 0.2) + 0.3, 0.1 + (0.2 + 0.3))', 'python', 'False\n0.6000000000000001 0.6', 'Floating-point addition isn''t associative.', 'Summing in a different order gives slightly different results. GPU kernels may sum in different orders depending on batch size, so logits differ in the last bits between runs.', NULL, NULL, 85);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True\n0.6000000000000001 0.6000000000000001', 0), (@q, 'B', 'False\n0.6000000000000001 0.6', 1), (@q, 'C', 'True\n0.6 0.6', 0), (@q, 'D', 'False\n0.6 0.6000000000000001', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'determinism'), 4, 'mcq', 'You call an API at temperature 0 with the same prompt 100 times and get 3 different answers. The most likely reason is:', NULL, NULL, 'Server-side batching changes the order of floating-point reductions, so near-tied logits sometimes flip and the texts diverge', 'Your request shares the GPU with other users'' requests.', 'Kernel results can depend on batch size/composition (not batch-invariant). A tiny logit difference changes the argmax when two tokens are nearly tied, and every later token follows from that. Mixture-of-experts routing can add more variation.', NULL, NULL, 86);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The model is retrained between calls', 0), (@q, 'B', 'Your network corrupted the request', 0), (@q, 'C', 'The API secretly uses temperature 1', 0), (@q, 'D', 'Server-side batching changes the order of floating-point reductions, so near-tied logits sometimes flip and the texts diverge', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'determinism'), 4, 'mcq', 'For an evaluation suite that must be reproducible, which practice is most reliable?', NULL, NULL, 'Pin the model version, use temperature 0 / a fixed seed, store the outputs, and score multiple samples rather than relying on bit-exact repeats', 'Treat LLM output like a flaky test.', 'Even at T = 0, hosted models can vary and aliases get silently updated. Pin versions, cache outputs, and measure pass rates over several runs.', NULL, 'Like flaky integration tests: pin dependencies and report pass rates, don''t trust a single green run.', 87);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Use the ''latest'' model alias', 0), (@q, 'B', 'Use temperature 2 so results average out', 0), (@q, 'C', 'Run each test once and assume the result never changes', 0), (@q, 'D', 'Pin the model version, use temperature 0 / a fixed seed, store the outputs, and score multiple samples rather than relying on bit-exact repeats', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'What is few-shot prompting?', NULL, NULL, 'Putting a few worked examples in the prompt', 'Show, don''t just tell.', 'Examples in the prompt show the model the exact format and style you want.', NULL, NULL, 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Putting a few worked examples in the prompt', 1), (@q, 'B', 'Asking very short questions', 0), (@q, 'C', 'Using a small model', 0), (@q, 'D', 'Training on a few GPUs', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'What is a system prompt for?', NULL, NULL, 'Setting the model''s role, rules and tone for the whole conversation', 'It sits above the user''s messages.', 'The system prompt is standing instructions: who to be, what to do and not do.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Setting the model''s role, rules and tone for the whole conversation', 1), (@q, 'B', 'Storing user passwords', 0), (@q, 'C', 'Choosing the GPU', 0), (@q, 'D', 'Logging errors', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'mcq', 'Your app needs to parse the model''s answer in code. Best approach?', NULL, NULL, 'Ask for structured output (JSON with a schema) and validate it', 'Treat it like an API contract.', 'Structured outputs / JSON schema give a predictable format; always validate before using.', NULL, 'Same as validating a request body against a schema in a REST API.', 3);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Use regex on free text', 0), (@q, 'B', 'Ask it nicely twice', 0), (@q, 'C', 'Ask for structured output (JSON with a schema) and validate it', 1), (@q, 'D', 'Hope it''s consistent', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, NULL, 1, 'true_false', 'Prompting changes the model''s weights.', NULL, NULL, 'False', 'Does the model file on disk change?', 'Prompting only changes the input. Fine-tuning changes the weights.', NULL, NULL, 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'chat-anatomy'), 1, 'mcq', 'In a chat request, which role carries the end user''s question?', NULL, NULL, 'user', 'Think of who is typing into the chat box.', 'The `user` message is the input from the person (or your app). `system` holds standing rules, `assistant` holds the model''s own earlier replies, `tool` holds tool results.', ' messages = [\n   system    -> standing rules ("You are a support bot")\n   user      -> "How do I reset my password?"\n   assistant -> the model''s earlier reply\n   user      -> the next question\n ]', NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'user', 1), (@q, 'B', 'tool', 0), (@q, 'C', 'system', 0), (@q, 'D', 'assistant', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'chat-anatomy'), 1, 'code_output', 'What does this print?', 'messages = [\n    {"role": "system", "content": "You are a helpful support bot."},\n    {"role": "user", "content": "How do I reset my password?"},\n]\nprint(len(messages), messages[0]["role"])', 'python', '2 system', 'A chat request is just a Python list of dicts.', 'Two dicts in the list, and the first one has role ''system''.', NULL, 'Like a JSON request body: a list of {role, content} objects.', 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2 user', 0), (@q, 'B', '2 system', 1), (@q, 'C', 'system 2', 0), (@q, 'D', '1 system', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'chat-anatomy'), 1, 'true_false', 'If you send one API call and then a second, separate call, the model automatically remembers what you said in the first call.', NULL, NULL, 'False', 'Does an HTTP request remember the previous request?', 'Chat APIs are stateless. The model only sees what is in this request; ''memory'' means your app resends the earlier messages.', NULL, 'A stateless REST endpoint: the session lives in your app, not on the server.', 7);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'chat-anatomy'), 1, 'mcq', 'What is an `assistant` message inside the history you send?', NULL, NULL, 'A reply the model gave earlier in the conversation', 'Whose words were they originally?', 'When you resend history, the model''s earlier answers go back in with role ''assistant'' so it can see what it said.', NULL, NULL, 8);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A reply the model gave earlier in the conversation', 1), (@q, 'B', 'The result of a tool call', 0), (@q, 'C', 'A hidden instruction only the developer can see', 0), (@q, 'D', 'A message from a human support agent', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'instructions'), 1, 'mcq', 'Which prompt is most likely to get a useful summary?', NULL, NULL, '"Summarise this support ticket in 3 bullet points for an on-call engineer: what broke, since when, who is affected."', 'Who reads it, how long, what to include?', 'Specific asks (audience, length, format, what to include) beat vague ones. Politeness and ''be smart'' add nothing concrete.', NULL, 'A good Jira ticket: acceptance criteria, not ''make it better''.', 9);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '"Summarise this."', 0), (@q, 'B', '"Please be smart and summarise."', 0), (@q, 'C', '"Summarise this support ticket in 3 bullet points for an on-call engineer: what broke, since when, who is affected."', 1), (@q, 'D', '"Summarise this as well as you possibly can, thank you!"', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'instructions'), 1, 'fill_blank', 'Markers like `<document> ... </document>` or `###` that wrap pasted text so the model can tell instructions from data are called ____.', NULL, NULL, 'delimiters', 'They mark where something starts and stops.', 'Delimiters separate your instructions from the content the model should work on (an email, a document, user input).', NULL, NULL, 10);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'instructions'), 1, 'mcq', 'A system prompt starts with "You are a senior tax accountant." What does this role line mainly do?', NULL, NULL, 'Steers tone, vocabulary and focus toward that domain', 'Can one sentence add facts to the weights?', 'Role prompting frames style and focus. It can''t add knowledge the model lacks; for that you need context (RAG) or training.', NULL, NULL, 11);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Makes the model legally certified', 0), (@q, 'B', 'Steers tone, vocabulary and focus toward that domain', 1), (@q, 'C', 'Switches the API to a special tax model', 0), (@q, 'D', 'Gives the model new tax knowledge it didn''t have', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'few-shot'), 1, 'mcq', 'What is zero-shot prompting?', NULL, NULL, 'Giving only the instruction, with no worked examples', '''Shot'' = example.', 'Zero-shot = instruction only. Few-shot = instruction plus a few input -> output examples.', NULL, NULL, 12);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Using temperature 0', 0), (@q, 'B', 'Sending an empty prompt', 0), (@q, 'C', 'A prompt the model has never seen in training', 0), (@q, 'D', 'Giving only the instruction, with no worked examples', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reasoning'), 1, 'mcq', 'What does "chain-of-thought" prompting mean?', NULL, NULL, 'Asking the model to work through intermediate steps before giving the final answer', 'Think of ''show your working'' in a maths exam.', 'Chain-of-thought asks for reasoning steps first, which helps on multi-step problems like maths and logic.', NULL, NULL, 13);
