INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'structured-output'), 1, 'code_output', 'What does this print?', 'import json\nreply = ''{"name": "Asha", "city": "Pune"}''\ndata = json.loads(reply)\nprint(data["city"])', 'python', 'Pune', 'json.loads turns a JSON string into a Python dict.', 'After json.loads the reply is a normal dict, so data[''city''] is ''Pune''.', NULL, NULL, 14);
