INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 1, 'mcq', 'What does `np.linspace(0, 1, 5)` return?', NULL, NULL, '[0.   0.25 0.5  0.75 1.  ]  (5 evenly spaced points, end included)', 'linspace asks for HOW MANY points, not the step size.', 'linspace(start, stop, num) gives num points evenly spaced, and includes stop by default. 5 points from 0 to 1 means a gap of 0.25.', NULL, NULL, 14);
