INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 2, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.arange(0, 1, 0.25))', 'python', '[0.   0.25 0.5  0.75]', 'arange takes a STEP and excludes the stop.', 'arange(start, stop, step) steps by 0.25 and stops before 1. Use linspace when you need the end point included.', NULL, NULL, 15);
