INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 3, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.full(3, 2.7, dtype=int))', 'python', '[2 2 2]', 'Converting float to int in NumPy truncates.', 'The explicit dtype wins: 2.7 is cast to int, which truncates toward zero to 2.', NULL, NULL, 24);
