INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.zeros((3, 4), dtype=np.float32)\nprint(a.itemsize, a.nbytes)', 'python', '4 48', 'float32 = 32 bits.', 'float32 is 32 bits = 4 bytes per item. nbytes = size * itemsize = 12 * 4 = 48.', NULL, NULL, 30);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4 48', 1), (@q, 'B', '4 12', 0), (@q, 'C', '32 384', 0), (@q, 'D', '8 96', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 2, 'mcq', 'What does len() return for this 2D array?', 'import numpy as np\na = np.arange(6).reshape(2, 3)\nprint(len(a))', 'python', '2', 'len() only looks at the first axis.', 'len(a) is the length of axis 0, here the number of rows (2). Use a.size for all elements.', NULL, NULL, 31);
