INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 2, 'true_false', 'An array of shape `(5,)` and an array of shape `(5, 1)` are the same thing.', NULL, NULL, 'False', 'Count the axes.', '(5,) is 1D (a flat vector). (5, 1) is 2D (a column of 5 rows). They behave very differently in broadcasting and matrix maths.', '(5,)    [a b c d e]        1 axis\n\n(5, 1)  [[a]               2 axes\n         [b]\n         [c] ...]', NULL, 32);
