INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 3, 'mcq', 'What are the shape, ndim and size of this 0-d array?', 'import numpy as np\ns = np.array(5)\nprint(s.shape, s.ndim, s.size)', 'python', '() 0 1', 'A single number wrapped in an array has no axes.', 'np.array(5) is a 0-d array: shape () (empty tuple), ndim 0, but it still holds 1 element.', NULL, NULL, 33);
