INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 3, 'mcq', 'For a 1,000 x 1,000 float64 array `a`, which is closest to `a.nbytes`?', NULL, NULL, '8,000,000 (8 MB)', 'float64 = 8 bytes; how many elements?', '1e6 elements x 8 bytes = 8e6 bytes. Quick estimates like this matter when you decide whether data fits in RAM.', NULL, NULL, 34);
