INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.zeros((0, 3))\nprint(a.size, a.shape, a.sum())', 'python', '0 (0, 3) 0.0', 'Zero rows is a legal shape.', 'Empty arrays are valid: size is 0 * 3 = 0 and the sum of nothing is the identity of +, which is 0.0.', NULL, NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0 (3,) nan', 0), (@q, 'B', '0 (0, 3) 0.0', 1), (@q, 'C', 'ValueError', 0), (@q, 'D', '3 (0, 3) 0.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'attributes'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(10)\nb = a[::2]\nprint(b.nbytes, b.base.nbytes)', 'python', '40 80', 'nbytes is size * itemsize of THIS array, not the memory it lives in.', 'b has 5 int64 elements, so b.nbytes = 40, even though it is a view into a''s 80-byte buffer. nbytes does not tell you how much memory a view keeps alive.', NULL, NULL, 36);
