INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 1, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.array([1, 2, 3]).dtype)\nprint(np.array([1.0, 2, 3]).dtype)', 'python', 'int64\nfloat64', 'One decimal point changes everything.', 'Whole numbers default to int64 (NumPy 2, on every platform). A single float makes the whole array float64.', NULL, NULL, 37);
