INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 2, 'mcq', 'What does the int array hold after assigning 9.7?', 'import numpy as np\na = np.array([1, 2, 3])\na[0] = 9.7\nprint(a)', 'python', '[9 2 3]', 'Assigning into an array never changes its dtype.', 'a stays int64, so 9.7 is truncated to 9. The array does not ''upgrade'' itself to float.', NULL, NULL, 38);
