INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1.7, -1.7])\nprint(a.astype(int))', 'python', '[ 1 -1]', 'Truncation goes toward zero, not down.', 'astype(int) truncates toward zero: 1.7 -> 1 and -1.7 -> -1. Use np.round or np.floor first if you need those.', NULL, NULL, 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[ 1 -2]', 0), (@q, 'B', '[2 -1]', 0), (@q, 'C', '[ 1 -1]', 1), (@q, 'D', '[ 2 -2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 2, 'mcq', 'What dtype does int array + float array produce?', 'import numpy as np\na = np.array([1, 2]) + np.array([0.5, 0.5])\nprint(a.dtype)', 'python', 'float64', 'Upcasting picks a type that can hold both.', 'int64 + float64 upcasts to float64 so no fractional part is lost.', NULL, NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'int64', 0), (@q, 'B', 'object', 0), (@q, 'C', 'float32', 0), (@q, 'D', 'float64', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([True, False, True])\nprint(a + 1)\nprint(a.sum())', 'python', '[2 1 2]\n2', 'True behaves like 1 in arithmetic.', 'Booleans upcast to int in arithmetic: True=1, False=0. That is why mask.sum() counts the True values.', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[True True True]\n2', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', '[2 1 2]\nTrue', 0), (@q, 'D', '[2 1 2]\n2', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1.0, 2.0], dtype=np.float32)\nprint((a + 1.0).dtype)\nprint((a + np.array([1.0])).dtype)', 'python', 'float32\nfloat64', 'A plain Python number is treated as ''weak''.', 'NumPy 2 (NEP 50): a Python scalar adapts to the array''s dtype, so float32 stays float32. A float64 ARRAY is a real dtype and wins, so the result is float64.', NULL, NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'float64\nfloat32', 0), (@q, 'B', 'float32\nfloat32', 0), (@q, 'C', 'float32\nfloat64', 1), (@q, 'D', 'float64\nfloat64', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 3, 'mcq', 'Which dtypes do the two mixed-type additions produce?', 'import numpy as np\na = np.array([1, 2], dtype=np.int8)\nb = np.array([1, 2], dtype=np.int16)\nc = np.array([1, 2], dtype=np.uint8)\nprint((a + b).dtype, (a + c).dtype)', 'python', 'int16 int16', 'Find the smallest type that can hold every value of both inputs.', 'int8 + int16 -> int16. int8 (-128..127) + uint8 (0..255) needs negatives and 255, so -> int16.', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'int16 int16', 1), (@q, 'B', 'int8 uint8', 0), (@q, 'C', 'int64 int64', 0), (@q, 'D', 'int16 int8', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1, 2], dtype=np.int8)\nprint((a + 1).dtype)\nprint(a + 300)', 'python', 'int8\nOverflowError', 'NumPy 2 keeps the array''s dtype for a Python int, then checks it fits.', 'Under NEP 50 the Python int adopts int8. 1 fits, so the result is int8. 300 does not fit in int8, so NumPy 2 raises OverflowError instead of silently upcasting (old NumPy 1 gave int16).', NULL, NULL, 44);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'int8\nOverflowError', 1), (@q, 'B', 'int16\n[301 302]', 0), (@q, 'C', 'int64\n[301 302]', 0), (@q, 'D', 'int8\n[45 46]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 3, 'true_false', '`a.astype(np.float32)` returns a new array even if `a` is already float32.', NULL, NULL, 'True', 'Check the default of the copy argument.', 'astype has copy=True by default, so it always allocates. Pass copy=False to reuse a when no conversion is needed.', NULL, NULL, 45);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([-1, 256, 300])\nprint(a.astype(np.uint8))', 'python', '[255   0  44]', 'astype on arrays does not check ranges; it keeps the low 8 bits.', 'Integer astype wraps modulo 2**8: -1 -> 255, 256 -> 0, 300 -> 44. No error, no warning: a classic image-processing bug.', NULL, NULL, 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[255   0  44]', 1), (@q, 'B', '[  0 255 255]', 0), (@q, 'C', '[-1 256 300]', 0), (@q, 'D', 'OverflowError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 4, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.float32(0.1) == 0.1)\nprint(np.float32(0.1) == np.float64(0.1))', 'python', 'True\nFalse', 'In NumPy 2 a plain Python float takes on the dtype of the NumPy value it meets.', 'Line 1: the Python float 0.1 is ''weak'' (NEP 50), so it is converted to float32 first and the two match. Line 2: both are real dtypes, so float32 is upcast to float64; 0.1 rounded to float32 is not the float64 0.1.', NULL, NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True\nTrue', 0), (@q, 'B', 'False\nTrue', 0), (@q, 'C', 'False\nFalse', 0), (@q, 'D', 'True\nFalse', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes'), 4, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.can_cast(np.int64, np.float64))\nprint(int(np.float64(2**53 + 1)) == 2**53 + 1)', 'python', 'True\nFalse', 'float64 has a 53-bit mantissa.', 'NumPy calls int64 -> float64 a ''safe'' cast, yet integers above 2**53 lose precision. ''Safe'' means the kind is preserved, not that every value survives.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False\nFalse', 0), (@q, 'B', 'False\nTrue', 0), (@q, 'C', 'True\nFalse', 1), (@q, 'D', 'True\nTrue', 0);
