INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(24).reshape(2, 3, 4)\nprint(a[1, 2, 3], a[:, 0, 0])', 'python', '23 [ 0 12]', 'Shape (2, 3, 4) = 2 blocks of 3 rows of 4 columns.', 'a[1, 2, 3] is the last element (23). a[:, 0, 0] takes the first element of each block: 0 and 12.', 'block 0          block 1\n[[ 0  1  2  3]   [[12 13 14 15]\n [ 4  5  6  7]    [16 17 18 19]\n [ 8  9 10 11]]   [20 21 22 23]]', NULL, 56);
