INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1, 2, 3, 4])\nprint(a[2:100])\nprint(a[10])', 'python', '[3 4]\nIndexError', 'Slices are forgiving; single indexes are not.', 'Slices clip to the valid range, so a[2:100] is [3 4]. A single index past the end raises IndexError.', NULL, NULL, 58);
