INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'indexing'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(10)\nprint(a[-1:-4:-1], a[7:2:-2])', 'python', '[9 8 7] [7 5 3]', 'With a negative step the slice runs from start DOWN to (but not including) stop.', 'a[-1:-4:-1] takes indexes 9, 8, 7 (stops before -4 = 6). a[7:2:-2] takes 7, 5, 3 (stops before 2).', NULL, NULL, 59);
