INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 3, 'mcq', 'What shape does a boolean mask over a 2D array return?', 'import numpy as np\na = np.arange(12).reshape(3, 4)\nr = a[a % 2 == 0]\nprint(r.shape)', 'python', '(6,)', 'Each row could keep a different number of elements.', 'A boolean mask over a 2D array returns a flat 1D array of the selected elements, because the result cannot be guaranteed to be rectangular.', NULL, NULL, 68);
