INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.zeros(3)\na[[0, 0, 1]] += 1\nprint(a)\nb = np.zeros(3)\nnp.add.at(b, [0, 0, 1], 1)\nprint(b)', 'python', '[1. 1. 0.]\n[2. 1. 0.]', 'a[idx] += 1 is really a[idx] = a[idx] + 1.', 'The fancy += reads a[[0,0,1]] once, adds 1, then writes back, so index 0 is written twice with the same value 1. np.add.at is ''unbuffered'' and really accumulates. Matters for histograms and embedding gradients.', NULL, NULL, 70);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2. 1. 0.]\n[1. 1. 0.]', 0), (@q, 'B', '[2. 1. 0.]\n[2. 1. 0.]', 0), (@q, 'C', '[1. 1. 0.]\n[1. 1. 0.]', 0), (@q, 'D', '[1. 1. 0.]\n[2. 1. 0.]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'masks-fancy'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(24).reshape(2, 3, 4)\nprint(a[:, [0, 1], [0, 1]].shape)\nprint(a[0, :, [0, 1]].shape)', 'python', '(2, 2)\n(2, 3)', 'When advanced indexes are separated by a slice, NumPy puts their dimension first.', 'Case 1: the two lists are adjacent, so their broadcast dim (2) replaces axes 1-2 in place: (2, 2). Case 2: the scalar 0 and list [0, 1] are both advanced but split by '':'', so the advanced dim goes first: (2, 3), not (3, 2).', NULL, NULL, 71);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(2, 2, 2)\n(3, 2)', 0), (@q, 'B', '(2, 2)\n(3, 2)', 0), (@q, 'C', '(2, 2)\n(2, 2)', 0), (@q, 'D', '(2, 2)\n(2, 3)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 1, 'true_false', 'Changing an element of a slice like `b = a[1:3]` also changes `a`.', NULL, NULL, 'True', 'A slice is a window, not a photocopy.', 'Basic slicing returns a view: b looks at a''s memory. Write to b and a changes. Use .copy() if you want independence.', NULL, 'A view is like a reference to the same object in JS or Java, not a clone.', 72);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 2, 'mcq', 'What is `a` after writing through the slice?', 'import numpy as np\na = np.array([1, 2, 3, 4])\nb = a[1:3]\nb[0] = 99\nprint(a)', 'python', '[ 1 99  3  4]', 'b is a view of a.', 'b[0] is a[1], so the 99 shows up in a.', NULL, NULL, 73);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[ 1 99  3  4]', 1), (@q, 'B', '[99  2  3  4]', 0), (@q, 'C', '[1 2 3 4]', 0), (@q, 'D', '[ 1 99 99  4]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 2, 'mcq', 'What is `a` after writing through the list-indexed result?', 'import numpy as np\na = np.array([1, 2, 3, 4])\nb = a[[1, 2]]\nb[0] = 99\nprint(a)', 'python', '[1 2 3 4]', 'Indexing with a list is ''fancy'' indexing.', 'Fancy indexing (lists or masks) always returns a copy, so changing b leaves a alone.', NULL, NULL, 74);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[ 1 99  3  4]', 0), (@q, 'B', '[1 2 3 4]', 1), (@q, 'C', '[99  2  3  4]', 0), (@q, 'D', 'IndexError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1, 2, 3])\nb = a.copy()\nb[0] = 50\nc = a\nc[1] = 60\nprint(a)', 'python', '[ 1 60  3]', 'Plain = does not copy anything.', 'b is a real copy, so 50 does not affect a. c = a just makes another name for the same array, so 60 does.', NULL, NULL, 75);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1 2 3]', 0), (@q, 'B', '[ 1 60  3]', 1), (@q, 'C', '[50 60  3]', 0), (@q, 'D', '[50  2  3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(6)\nprint(np.shares_memory(a, a[::2]), np.shares_memory(a, a[[0, 2, 4]]))', 'python', 'True False', 'One of these can be described with a step; the other is an arbitrary list.', 'a[::2] is a view (same buffer, bigger stride). a[[0, 2, 4]] is fancy indexing, so it is a fresh copy, even though it holds the same values.', NULL, NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True', 0), (@q, 'B', 'True False', 1), (@q, 'C', 'True True', 0), (@q, 'D', 'False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 3, 'mcq', 'What do the two `.base` checks report?', 'import numpy as np\na = np.arange(6)\nb = a.reshape(2, 3)\nprint(b.base is a, a.base is None)', 'python', 'True True', '.base points at the array that owns the memory.', 'reshape of a contiguous array is a view, so b.base is a. a owns its data, so a.base is None.', NULL, NULL, 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True', 1), (@q, 'B', 'True False', 0), (@q, 'C', 'False True', 0), (@q, 'D', 'False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.zeros((2, 3))\ncol = a[:, 0]\ncol += 1\ncol = col + 1\nprint(a[:, 0])', 'python', '[1. 1.]', 'One of these lines writes into memory; the other makes a new array.', 'col += 1 is in-place on the view, so a changes. col = col + 1 builds a NEW array and rebinds the name; a is not touched by that second line.', NULL, NULL, 78);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0. 0.]', 0), (@q, 'B', '[2. 2.]', 0), (@q, 'C', '[1. 1.]', 1), (@q, 'D', '[1. 2.]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 3, 'mcq', 'Which call returns the very same object, and which makes a new one?', 'import numpy as np\nlst = [1, 2, 3]\na = np.array([1, 2, 3])\nb = np.asarray(a)\nc = np.array(a)\nprint(b is a, c is a)', 'python', 'True False', 'One of these copies by default.', 'np.asarray returns its input unchanged if it is already a matching array. np.array copies by default.', NULL, NULL, 79);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True False', 1), (@q, 'B', 'True True', 0), (@q, 'C', 'False True', 0), (@q, 'D', 'False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 3, 'code_output', 'What does this print?', 'import numpy as np\ndef scale(x):\n    x *= 2\ndef scale2(x):\n    x = x * 2\na = np.array([1, 2])\nscale(a)\nscale2(a)\nprint(a)', 'python', '[2 4]', 'Which function mutates the caller''s buffer?', 'x *= 2 writes into the shared array, so the caller sees [2 4]. x = x * 2 only rebinds the local name.', NULL, 'Same as passing an object in JS: mutate a property and the caller sees it; reassign the parameter and it doesn''t.', 80);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1 2]', 0), (@q, 'B', '[2 4]', 1), (@q, 'C', '[1 2 4]', 0), (@q, 'D', '[4 8]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(6).reshape(2, 3)\nprint(np.shares_memory(a, a.ravel()))\nprint(np.shares_memory(a, a.T.ravel()))\nprint(np.shares_memory(a, a.flatten()))', 'python', 'True\nFalse\nFalse', 'ravel returns a view only when it can.', 'a is C-contiguous, so ravel can be a view. a.T read row by row is not a single stride pattern, so ravel must copy. flatten always copies.', NULL, NULL, 81);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False\nFalse\nFalse', 0), (@q, 'B', 'True\nTrue\nFalse', 0), (@q, 'C', 'True\nTrue\nTrue', 0), (@q, 'D', 'True\nFalse\nFalse', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 4, 'mcq', 'You slice a 10 MB view `small = big[:10]` from a 2 GB array, delete `big`, and keep `small` in a cache. What happens to memory?', NULL, NULL, 'The whole 2 GB buffer stays alive, because small.base still references it', 'A view keeps its owner alive.', 'A view holds a reference to the base buffer, so the full 2 GB cannot be freed. Store small.copy() instead when caching a tiny piece of a huge array.', NULL, NULL, 82);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Only 10 MB is kept; NumPy trims the buffer', 0), (@q, 'B', 'Python frees the 2 GB, and small now holds garbage', 0), (@q, 'C', 'The whole 2 GB buffer stays alive, because small.base still references it', 1), (@q, 'D', 'small becomes invalid and raises on access', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'views-copies'), 4, 'true_false', '`b = a[a > 0]` followed by `b[:] = 0` sets the positive elements of `a` to zero.', NULL, NULL, 'False', 'Is boolean indexing a view?', 'Boolean indexing makes a copy, so b[:] = 0 only clears the copy. Write a[a > 0] = 0 to change a.', NULL, NULL, 83);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
