INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 1, 'mcq', 'For a 2D array of shape (rows, cols), what does `a.sum(axis=0)` give?', NULL, NULL, 'One total per COLUMN (the rows are collapsed)', 'axis=0 is the axis that disappears.', 'The axis you name gets squashed. axis=0 runs down the rows, leaving one value per column.', '        axis=1 ->\naxis=0 [[0 1 2]\n  |     [3 4 5]]\n  v\nsum(axis=0) -> [3 5 7]    sum(axis=1) -> [ 3 12]', NULL, 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'One total per COLUMN (the rows are collapsed)', 1), (@q, 'B', 'The total of everything', 0), (@q, 'C', 'The first row', 0), (@q, 'D', 'One total per ROW', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.arange(6).reshape(2, 3)\nprint(a.sum(axis=0))\nprint(a.sum(axis=1))', 'python', '[3 5 7]\n[ 3 12]', 'a = [[0 1 2], [3 4 5]].', 'axis=0 adds down each column: 0+3, 1+4, 2+5. axis=1 adds across each row: 0+1+2, 3+4+5.', NULL, NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '15\n15', 0), (@q, 'B', '[0 1 2]\n[0 3]', 0), (@q, 'C', '[ 3 12]\n[3 5 7]', 0), (@q, 'D', '[3 5 7]\n[ 3 12]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 2, 'mcq', 'What do the three argmax calls return?', 'import numpy as np\na = np.array([[1, 9], [8, 2]])\nprint(a.argmax(), a.argmax(axis=1), a.argmax(axis=0))', 'python', '1 [1 0] [1 0]', 'Without an axis, argmax looks at the FLATTENED array.', 'Flattened: [1 9 8 2], the max is at index 1. Per row: row 0 max at col 1, row 1 at col 0. Per column: col 0 max at row 1, col 1 at row 0. Use np.unravel_index to turn a flat index into (row, col).', NULL, NULL, 29);
