INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 2, 'mcq', 'What shapes come out of these sums on a (2, 3) array?', 'import numpy as np\na = np.ones((2, 3))\nprint(a.sum(axis=1).shape, a.sum(axis=1, keepdims=True).shape)', 'python', '(2,) (2, 1)', 'keepdims leaves a length-1 axis where the reduced one was.', 'axis=1 removes the column axis: (2,). keepdims=True keeps it as size 1: (2, 1), which broadcasts back against (2, 3) correctly.', 'a            (2, 3)\nsum(axis=1)  (2,)     axis 1 removed\nkeepdims     (2, 1)   axis 1 kept as size 1\n(2, 3) / (2, 1) -> each row divided by its own total', NULL, 30);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(2,) (2,)', 0), (@q, 'B', '(2, 1) (2, 1)', 0), (@q, 'C', '(2,) (2, 1)', 1), (@q, 'D', '(3,) (1, 3)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 2, 'fill_blank', 'Which aggregation returns the INDEX of the largest value: `a.____()`?', NULL, NULL, 'argmax', '''arg'' = the argument (position) that gives the max.', 'argmax returns the position, max returns the value. In classification, argmax over the class axis gives the predicted label.', NULL, NULL, 31);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([[1, 2], [3, 4]])\nprint(a.cumsum(), a.cumsum(axis=0).tolist())', 'python', '[ 1  3  6 10] [[1, 2], [4, 6]]', 'Like sum, cumsum without an axis flattens first.', 'No axis: running total over 1, 2, 3, 4. axis=0: running total down each column: [1, 2] then [1+3, 2+4].', NULL, NULL, 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[1 3]\n [3 7]] [[1, 2], [4, 6]]', 0), (@q, 'B', '10 [[1, 2], [4, 6]]', 0), (@q, 'C', '[ 1  3  6 10] [[1, 2], [4, 6]]', 1), (@q, 'D', '[ 1  3  6 10] [[1, 3], [3, 7]]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 3, 'mcq', 'What do the two standard deviations come out as?', 'import numpy as np\nx = np.array([1, 2, 3, 4])\nprint(np.std(x), np.std(x, ddof=1))', 'python', '1.118033988749895 1.2909944487358056', 'NumPy''s default divides by n, not n - 1.', 'np.std uses ddof=0 (population std, divide by n). ddof=1 divides by n - 1 (sample std), which is what pandas'' .std() uses by default, so the two libraries disagree unless you set ddof.', NULL, NULL, 33);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1.25 1.6666666666666667', 0), (@q, 'B', '1.2909944487358056 1.118033988749895', 0), (@q, 'C', '1.118033988749895 1.118033988749895', 0), (@q, 'D', '1.118033988749895 1.2909944487358056', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 3, 'mcq', 'What shape does reducing over two axes give?', 'import numpy as np\na = np.ones((2, 3, 4))\nprint(a.sum(axis=(0, 2)).shape, a.mean(axis=-1).shape)', 'python', '(3,) (2, 3)', 'Remove the named axes; -1 is the last one.', 'Summing over axes 0 and 2 leaves axis 1: (3,). mean(axis=-1) removes the last axis: (2, 3). Example: mean over the sequence axis of a (batch, seq, dim) tensor.', NULL, NULL, 34);
