INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 3, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.array([]).sum())\nprint(np.array([]).max())', 'python', '0.0\nValueError', 'What is the max of nothing?', 'The empty sum is 0 (the identity of +). max has no identity, so it raises ValueError. Pass initial= (e.g. np.max(a, initial=-np.inf)) if empty inputs are possible.', NULL, NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.0\n0.0', 0), (@q, 'B', '0.0\nValueError', 1), (@q, 'C', 'ValueError', 0), (@q, 'D', 'nan\nnan', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 4, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([100, 100], dtype=np.int8)\nprint(a.sum(), a.sum().dtype)\nprint(a + a)', 'python', '200 int64\n[-56 -56]', 'Reductions and element-wise ops treat small ints differently.', 'sum of a small int type is accumulated in the default int (int64), so 200 fits. a + a keeps int8 and silently wraps: 200 - 256 = -56.', NULL, NULL, 36);
