INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 4, 'code_output', 'What does this print? (Careful: when is the print evaluated?)', 'import numpy as np\nx = np.arange(24).reshape(2, 3, 4)\nm = x.max(axis=1, keepdims=True)\nprint(m.shape, (x - m).shape, (x - x.max(axis=1)).shape)', 'python', 'ValueError', 'Without keepdims the result is (2, 4); line it up from the right against (2, 3, 4).', 'With keepdims, (2, 1, 4) broadcasts back fine. Without it, (2, 4) is compared as (1, 2, 4) vs (2, 3, 4): 2 vs 3 fails. Because the print evaluates all three first, the error happens before anything is printed.', NULL, NULL, 37);
