INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([30, 10, 20])\nprint(np.argsort(a))', 'python', '[1 2 0]', 'argsort gives the positions, in the order that would sort the array.', 'The smallest (10) is at index 1, then 20 at index 2, then 30 at index 0: [1 2 0]. a[np.argsort(a)] is sorted.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[2 0 1]', 0), (@q, 'B', '[1 2 0]', 1), (@q, 'C', '[0 1 2]', 0), (@q, 'D', '[10 20 30]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 2, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([3, 1, 2])\nr = a.sort()\nprint(r, a)', 'python', 'None [1 2 3]', 'Methods that change the object in place usually return None.', 'a.sort() sorts a itself and returns None, like Python''s list.sort(). Use np.sort(a) for a sorted copy.', NULL, NULL, 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1 2 3] [1 2 3]', 0), (@q, 'B', 'None [3 1 2]', 0), (@q, 'C', 'None [1 2 3]', 1), (@q, 'D', '[1 2 3] [3 1 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 2, 'mcq', 'What do unique and its counts come out as?', 'import numpy as np\nvals, counts = np.unique(np.array([3, 1, 3, 2, 1, 3]), return_counts=True)\nprint(vals, counts)', 'python', '[1 2 3] [2 1 3]', 'unique returns the values SORTED.', 'np.unique sorts the distinct values and return_counts gives how often each appears: a quick class-balance check.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[3 1 2] [3 2 1]', 0), (@q, 'B', '[1 2 3] [3 1 2]', 0), (@q, 'C', '[3 1 3 2 1 3] [1 1 1 1 1 1]', 0), (@q, 'D', '[1 2 3] [2 1 3]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 2, 'fill_blank', 'Reverse a sorted array to get descending order: `np.sort(a)[____]`', NULL, NULL, '::-1', 'A slice with step -1.', 'np.sort has no ''descending'' flag; reverse the result with [::-1], or sort the negated values.', NULL, NULL, 54);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'sorting'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([[3, 1], [2, 5]])\nprint(np.sort(a))\nprint(np.sort(a, axis=None))', 'python', '[[1 3]\n [2 5]]\n[1 2 3 5]', 'The default axis for sort is the LAST one.', 'np.sort sorts each row independently (axis=-1). axis=None flattens first.', NULL, NULL, 55);
