INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 1, 'code_output', 'What does this print?', 'import numpy as np\ny_true = np.array([1, 0, 1, 1])\ny_pred = np.array([1, 0, 0, 1])\nprint((y_true == y_pred).mean())', 'python', '0.75', 'The mean of booleans is the fraction of Trues.', '3 of 4 predictions match, so accuracy = 0.75. mean() of a mask is the standard accuracy one-liner.', NULL, NULL, 121);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.75', 1), (@q, 'B', '0.25', 0), (@q, 'C', '3', 0), (@q, 'D', '[ True  True False  True]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 2, 'code_output', 'What does this print?', 'import numpy as np\nx = np.array([10.0, 20.0, 30.0])\nprint((x - x.min()) / (x.max() - x.min()))', 'python', '[0.  0.5 1. ]', 'Shift so the min is 0, then scale so the max is 1.', 'Min-max scaling: (x - 10) / 20 gives 0, 0.5, 1.', NULL, NULL, 122);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0.  0.5 1. ]', 1), (@q, 'B', '[0.33 0.67 1.  ]', 0), (@q, 'C', '[-1.  0.  1.]', 0), (@q, 'D', '[10. 20. 30.]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 2, 'mcq', 'After standardising, what are the column means and stds?', 'import numpy as np\nrng = np.random.default_rng(0)\nX = rng.normal(50, 10, size=(100, 3))\nZ = (X - X.mean(axis=0)) / X.std(axis=0)\nprint(np.allclose(Z.mean(axis=0), 0), np.allclose(Z.std(axis=0), 1))', 'python', 'True True', 'axis=0 gives one mean and std per feature (column).', 'Standardising per column gives every feature mean 0 and std 1. The (3,) stats broadcast across the 100 rows.', NULL, NULL, 123);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True True', 1), (@q, 'B', 'True False', 0), (@q, 'C', 'False True', 0), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 2, 'code_output', 'What does this print?', 'import numpy as np\ny = np.array([0, 2, 1])\nprint(np.eye(3)[y])', 'python', '[[1. 0. 0.]\n [0. 0. 1.]\n [0. 1. 0.]]', 'Row k of the identity matrix is the one-hot vector for class k.', 'Fancy indexing the rows of eye(3) with the labels picks one identity row per label: one-hot encoding.', 'np.eye(3)        y = [0, 2, 1]\nrow 0 [1 0 0] <- label 0\nrow 1 [0 1 0] <- label 1\nrow 2 [0 0 1] <- label 2', NULL, 124);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[[0. 0. 1.]\n [1. 0. 0.]\n [0. 1. 0.]]', 0), (@q, 'B', '[[1. 0. 0.]\n [0. 1. 0.]\n [0. 0. 1.]]', 0), (@q, 'C', '[[1. 0. 0.]\n [0. 0. 1.]\n [0. 1. 0.]]', 1), (@q, 'D', '[0. 2. 1.]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 2, 'mcq', 'What does dividing each row by its norm do?', 'import numpy as np\nX = np.array([[3.0, 4.0], [1.0, 0.0]])\nU = X / np.linalg.norm(X, axis=1, keepdims=True)\nprint(U)\nprint(np.linalg.norm(U, axis=1))', 'python', 'Makes every row a unit vector (length 1) while keeping its direction', 'keepdims makes the norms a (2, 1) column.', 'Each row is divided by its own length, so rows become unit vectors: [0.6 0.8] and [1 0]. After this, cosine similarity is just a dot product.', NULL, NULL, 125);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Standardises each column to mean 0', 0), (@q, 'B', 'Makes every column sum to 1', 0), (@q, 'C', 'Raises, because the shapes (2, 2) and (2, 1) don''t broadcast', 0), (@q, 'D', 'Makes every row a unit vector (length 1) while keeping its direction', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 3, 'mcq', 'What does the broadcast comparison produce?', 'import numpy as np\ny = np.array([2, 0, 1])\nprint((y[:, None] == np.arange(3)).astype(int))', 'python', '[[0 0 1]\n [1 0 0]\n [0 1 0]]', '(3, 1) compared with (3,) broadcasts to a 3x3 table.', 'Row i, column j is True where y[i] == j: one-hot encoding by broadcasting, no loop and no identity matrix.', NULL, NULL, 126);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0 0 1 1 0 0 0 1 0]', 0), (@q, 'B', '[[1 0 0]\n [0 1 0]\n [0 0 1]]', 0), (@q, 'C', '[[0 0 1]\n [1 0 0]\n [0 1 0]]', 1), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 3, 'code_output', 'What does this print?', 'import numpy as np\nlogits = np.array([[1.0, 2.0, 3.0], [1.0, 1.0, 1.0]])\ne = np.exp(logits - logits.max(axis=1, keepdims=True))\np = e / e.sum(axis=1, keepdims=True)\nprint(p.sum(axis=1), p.argmax(axis=1), round(p[1, 0], 4))', 'python', '[1. 1.] [2 0] 0.3333', 'Softmax rows sum to 1; ties go to the first index.', 'Each row is a probability distribution (sums to 1). Row 0 is most confident in class 2. Row 1 is uniform (1/3 each) and argmax returns the first maximum, index 0.', NULL, NULL, 127);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1. 1.] [2 0] 0.3333', 1), (@q, 'B', '[1. 1.] [2 0] 0.0', 0), (@q, 'C', '[1. 1.] [2 2] 0.3333', 0), (@q, 'D', '[6. 3.] [2 0] 1.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 3, 'code_output', 'What does this print?', 'import numpy as np\nlogits = np.array([[1.0, 2.0, 3.0], [3.0, 1.0, 1.0], [0.0, 0.0, 5.0]])\ne = np.exp(logits)\np = e / e.sum(axis=1)\nprint(np.allclose(p.sum(axis=1), 1))', 'python', 'False', 'e.sum(axis=1) has shape (3,). Which axis does it line up with?', 'Without keepdims the (3,) row sums broadcast across COLUMNS, so element [i, j] is divided by the sum of row j. With a square batch there is no error, just wrong probabilities. Always use keepdims=True.', 'e          (3, 3)\nrow sums   (3,)  -> lined up as (1, 3): one per COLUMN\np[i, j] = e[i, j] / rowsum[j]     wrong!\nkeepdims   (3, 1): p[i, j] = e[i, j] / rowsum[i]', NULL, 128);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False', 1), (@q, 'B', 'True', 0), (@q, 'C', 'nan', 0), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 3, 'code_output', 'What does this print?', 'import numpy as np\na = np.array([1.0, 0.0])\nb = np.array([1.0, 1.0])\ncos = a @ b / (np.linalg.norm(a) * np.linalg.norm(b))\nprint(round(cos, 4))', 'python', '0.7071', 'cos = dot / (length x length).', 'a . b = 1, |a| = 1, |b| = sqrt(2), so cos = 1/sqrt(2) ~ 0.7071: a 45 degree angle.', NULL, NULL, 129);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1.4142', 0), (@q, 'B', '1.0', 0), (@q, 'C', '0.5', 0), (@q, 'D', '0.7071', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 3, 'mcq', 'What shape is the pairwise distance matrix?', 'import numpy as np\nA = np.ones((5, 3))\nB = np.zeros((4, 3))\nD = np.linalg.norm(A[:, None, :] - B[None, :, :], axis=-1)\nprint(D.shape, round(D[0, 0], 4))', 'python', '(5, 4), and D[0, 0] = 1.7321', '(5, 1, 3) - (1, 4, 3) -> (5, 4, 3); then norm over the last axis.', 'Broadcasting builds every A-row minus B-row pair (5, 4, 3); the norm over the features gives a (5, 4) matrix. D[0, 0] = |(1, 1, 1)| = sqrt(3).', 'A[:, None, :]  (5, 1, 3)\nB[None, :, :]  (1, 4, 3)\ndifference     (5, 4, 3)\nnorm(axis=-1)  (5, 4)    D[i, j] = |A[i] - B[j]|', NULL, 130);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(4, 5), and D[0, 0] = 1.7321', 0), (@q, 'B', '(5, 4), and D[0, 0] = 1.7321', 1), (@q, 'C', '(5, 3), and D[0, 0] = 3.0', 0), (@q, 'D', '(5, 4, 3), and D[0, 0] = 1.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 3, 'code_output', 'What does this print?', 'import numpy as np\nprobs = np.array([0.1, 0.5, 0.15, 0.25])\nprint(np.argsort(probs)[::-1][:2])', 'python', '[1 3]', 'argsort is ascending; reverse it for the best first.', 'Ascending order of indexes is [0 2 3 1]; reversed it is [1 3 2 0]; the top 2 classes are 1 and 3.', NULL, NULL, 131);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1 3]', 1), (@q, 'B', '[3 1]', 0), (@q, 'C', '[0.5  0.25]', 0), (@q, 'D', '[0 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 3, 'mcq', 'You standardise features before a train/test split, using the mean and std of ALL the data. What is the problem?', NULL, NULL, 'Data leakage: test-set statistics influence training. Fit mean/std on the training set and apply them to test', 'In production you won''t know the future data''s mean.', 'The test set must act like unseen data. Compute the mean and std on train only, then reuse those exact numbers on test.', NULL, NULL, 132);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Standardisation must be done after training', 0), (@q, 'B', 'Data leakage: test-set statistics influence training. Fit mean/std on the training set and apply them to test', 1), (@q, 'C', 'std must be computed with ddof=1 for test data', 0), (@q, 'D', 'None; more data gives better statistics', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 4, 'mcq', 'What shapes do the batched attention-score computations give?', 'import numpy as np\nQ = np.ones((2, 4, 8))\nK = np.ones((2, 4, 8))\nS = Q @ K.transpose(0, 2, 1)\nS2 = np.einsum("bqd,bkd->bqk", Q, K)\nprint(S.shape, np.array_equal(S, S2), S[0, 0, 0])', 'python', '(2, 4, 4), equal, 8.0', 'Transpose only the last two axes of K: (2, 8, 4).', '(2, 4, 8) @ (2, 8, 4) -> (2, 4, 4): one query-by-key score matrix per batch item. Each score is a dot of two 8-dim ones vectors = 8. The einsum writes the same thing explicitly.', NULL, NULL, 133);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(2, 4, 4), not equal, 8.0', 0), (@q, 'B', '(2, 8, 8), equal, 4.0', 0), (@q, 'C', '(4, 4), equal, 16.0', 0), (@q, 'D', '(2, 4, 4), equal, 8.0', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 4, 'mcq', 'What do the expanded formula and the direct formula give for the squared distance?', 'import numpy as np\nX = np.array([[1e8 + 1.0, 1e8], [1e8, 1e8 + 1.0]])\nsq = (X ** 2).sum(axis=1)\nD2 = sq[:, None] + sq[None, :] - 2 * X @ X.T\nprint(D2[0, 1], ((X[0] - X[1]) ** 2).sum())', 'python', '0.0 2.0', 'The expansion subtracts two huge, nearly equal numbers.', '|a|^2 + |b|^2 - 2a.b is fast (one matmul) but each term is ~4e16 here, where float64 spacing is 8, so the true answer 2 is lost. Centre the data first, and clip at 0 before sqrt because results can even go negative.', NULL, NULL, 134);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '-2.0 2.0', 0), (@q, 'B', '0.0 0.0', 0), (@q, 'C', '2.0 2.0', 0), (@q, 'D', '0.0 2.0', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-idioms'), 4, 'code_output', 'What does this print?', 'import numpy as np\nlogits = np.array([2.0, 1.0, 0.1])\np = np.exp(logits) / np.exp(logits).sum()\nprint(np.argmax(p) == np.argmax(logits), np.allclose(p, np.exp(logits - 5) / np.exp(logits - 5).sum()))', 'python', 'True True', 'exp is increasing, and softmax(x) = softmax(x + c).', 'Because exp preserves order, argmax(softmax) = argmax(logits): you can skip softmax at prediction time. Shifting all logits by a constant leaves softmax unchanged, which is the basis of the max-subtraction trick.', NULL, NULL, 135);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'False True', 0), (@q, 'B', 'True True', 1), (@q, 'C', 'True False', 0), (@q, 'D', 'False False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stability'), 3, 'code_output', 'What does this print?', 'import numpy as np\nx = np.array([1000.0, 1001.0])\nwith np.errstate(over="ignore", invalid="ignore"):\n    naive = np.exp(x) / np.exp(x).sum()\nstable = np.exp(x - x.max()) / np.exp(x - x.max()).sum()\nprint(naive, stable)', 'python', '[nan nan] [0.26894142 0.73105858]', 'exp(1000) is far beyond the largest float64 (~1.8e308).', 'exp overflows to inf, and inf / inf = nan. Subtracting the max first makes the largest exponent exp(0) = 1, so nothing overflows and the answer is unchanged.', NULL, NULL, 136);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[nan nan] [0.26894142 0.73105858]', 1), (@q, 'B', '[0.26894142 0.73105858] [0.26894142 0.73105858]', 0), (@q, 'C', '[0. 1.] [0.26894142 0.73105858]', 0), (@q, 'D', '[inf inf] [0.26894142 0.73105858]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stability'), 3, 'mcq', 'Why is subtracting the max before softmax safe, i.e. why doesn''t it change the answer?', NULL, NULL, 'softmax(x - c) = softmax(x) for any constant c: the e^-c factor cancels between top and bottom', 'Write exp(x_i - c) as exp(x_i) * exp(-c).', 'Every term in numerator and denominator gets the same factor e^-c, which cancels. Choosing c = max(x) keeps every exponent <= 0, so nothing overflows and at least one term is exactly 1.', NULL, NULL, 137);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'softmax(x - c) = softmax(x) for any constant c: the e^-c factor cancels between top and bottom', 1), (@q, 'B', 'Because exp(x - c) = exp(x) - exp(c)', 0), (@q, 'C', 'It changes the answer slightly, but nobody notices', 0), (@q, 'D', 'Because the max element is always 0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stability'), 3, 'code_output', 'What does this print?', 'import numpy as np\nx = np.array([1000.0, 1000.0])\nwith np.errstate(over="ignore"):\n    print(np.log(np.sum(np.exp(x))))\nm = x.max()\nprint(m + np.log(np.sum(np.exp(x - m))))', 'python', 'inf\n1000.6931471805599', 'log(e^1000 + e^1000) = 1000 + log 2.', 'The naive log-sum-exp overflows. Factoring out the max gives m + log(sum(exp(x - m))) = 1000 + log(2). This logsumexp trick is how cross-entropy is computed from logits.', NULL, NULL, 138);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1000.6931471805599\n1000.6931471805599', 0), (@q, 'B', 'nan\n1000.0', 0), (@q, 'C', 'inf\n1000.0', 0), (@q, 'D', 'inf\n1000.6931471805599', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stability'), 3, 'true_false', 'Computing `np.log(p)` for predicted probabilities can return `-inf` when a probability underflows to 0, which then turns the loss into inf or nan.', NULL, NULL, 'True', 'What is log(0)?', 'log(0) = -inf. That is why losses clip p to [eps, 1 - eps] or, better, compute log-softmax directly from logits.', NULL, NULL, 139);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stability'), 4, 'code_output', 'What does this print?', 'import numpy as np\nprint(np.log(1 + 1e-20), np.log1p(1e-20))\nprint(np.exp(1e-20) - 1, np.expm1(1e-20))', 'python', '0.0 1e-20\n0.0 1e-20', '1 + 1e-20 is exactly 1.0 in float64.', 'The tiny value is lost when added to 1 before log is applied. log1p and expm1 compute log(1 + x) and exp(x) - 1 accurately for small x.', NULL, NULL, 140);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1e-20 1e-20\n1e-20 1e-20', 0), (@q, 'B', '0.0 1e-20\n0.0 1e-20', 1), (@q, 'C', '1e-20 0.0\n1e-20 0.0', 0), (@q, 'D', '0.0 0.0\n0.0 0.0', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stability'), 4, 'mcq', 'What do the textbook variance formula and np.var give?', 'import numpy as np\nx = 1e8 + np.array([1.0, 2.0, 3.0, 4.0])\nnaive = (x ** 2).mean() - x.mean() ** 2\nprint(naive, x.var())', 'python', '2.0 1.25', 'E[x^2] - E[x]^2 subtracts two numbers around 1e16.', 'The textbook formula suffers catastrophic cancellation: both terms are ~1e16, so their tiny difference is garbage. np.var subtracts the mean first (two-pass), giving the true 1.25.', NULL, NULL, 141);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1.25 1.25', 0), (@q, 'B', '2.0 1.25', 1), (@q, 'C', '-2.0 1.25', 0), (@q, 'D', '0.0 1.25', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stability'), 4, 'mcq', 'What do sum() and the running cumsum give in float32?', 'import numpy as np\na = np.ones(2**24 + 10, dtype=np.float32)\nprint(a.sum(), a.cumsum()[-1])', 'python', '16777226.0 16777216.0', 'float32 cannot represent 2**24 + 1.', 'A running float32 total gets stuck at 2**24 = 16777216, because adding 1 rounds back. np.sum uses pairwise summation (adds partial sums of similar size), so it stays exact. Accumulate in float64 when unsure.', NULL, NULL, 142);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '16777226.0 16777226.0', 0), (@q, 'B', '16777216.0 16777226.0', 0), (@q, 'C', '16777216.0 16777216.0', 0), (@q, 'D', '16777226.0 16777216.0', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stability'), 4, 'code_output', 'What does this print?', 'import numpy as np\nx = np.array([-1000.0, 0.0, 1000.0])\nwith np.errstate(over="ignore", divide="ignore"):\n    naive = np.log(1 / (1 + np.exp(-x)))\nstable = -np.logaddexp(0, -x)\nprint(naive[0], stable[0], np.allclose(naive[1:], stable[1:]))', 'python', '-inf -1000.0 True', 'For x = -1000, exp(1000) overflows, so the sigmoid becomes exactly 0.', 'log(sigmoid(x)) = -log(1 + e^-x) = -logaddexp(0, -x), which never forms the overflowing value. The naive form gives -inf at -1000 instead of the correct -1000. This is why frameworks offer ''with logits'' losses.', NULL, NULL, 143);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '-inf -inf True', 0), (@q, 'B', 'nan -1000.0 True', 0), (@q, 'C', '-1000.0 -1000.0 True', 0), (@q, 'D', '-inf -1000.0 True', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stability'), 4, 'mcq', 'A model trained in float16 suddenly shows `loss = nan`. Which is the most likely cause, and fix?', NULL, NULL, 'Values exceeded float16''s max (~65504) or underflowed; use loss scaling / bfloat16 / keep reductions in float32', 'float16 has a tiny range.', 'float16 overflows above 65504 to inf, and inf - inf or 0 * inf gives nan. Mixed-precision training keeps master weights and sums in float32, scales the loss, or uses bfloat16 (float32''s range with fewer digits).', NULL, NULL, 144);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'float16 cannot represent negative numbers', 0), (@q, 'B', 'NaN means the learning rate is too small', 0), (@q, 'C', 'np.random was not seeded', 0), (@q, 'D', 'Values exceeded float16''s max (~65504) or underflowed; use loss scaling / bfloat16 / keep reductions in float32', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'stability'), 4, 'mcq', 'Why do numerically careful libraries compute the norm of a vector without simply doing `np.sqrt(np.sum(x**2))`?', NULL, NULL, 'x**2 can overflow (or underflow) even when the norm itself is representable, so they rescale by max|x| first', 'Try x = 1e200.', '(1e200)**2 = inf in float64, yet the norm 1e200 is fine. Scaling by s = max|x| gives s * sqrt(sum((x/s)**2)), which never overflows (the idea behind hypot).', NULL, NULL, 145);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'np.sqrt is inaccurate', 0), (@q, 'B', 'Summation in NumPy is not deterministic', 0), (@q, 'C', 'Squaring is slower than taking absolute values', 0), (@q, 'D', 'x**2 can overflow (or underflow) even when the norm itself is representable, so they rescale by max|x| first', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 2, 'fill_blank', 'Which argument of `sum`/`mean`/`max` keeps the reduced axis as size 1 so the result broadcasts back? `____=True`', NULL, NULL, 'keepdims', 'It ''keeps the dimensions''.', 'keepdims=True turns a (n,) result into (n, 1) (or (1, d)), so X / X.sum(axis=1, keepdims=True) divides each row by its own total.', NULL, NULL, 146);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'compare-where'), 2, 'fill_blank', 'Which function keeps values inside a range, e.g. `np.____(p, 1e-7, 1 - 1e-7)` before taking log(p)?', NULL, NULL, 'clip', 'Like a hair clip holding things in place.', 'np.clip(x, lo, hi) replaces values below lo with lo and above hi with hi, preventing log(0) = -inf in a loss.', NULL, NULL, 147);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'linalg'), 3, 'fill_blank', 'Which linear-algebra function solves `A @ x = b` for x without computing an inverse? `np.linalg.____(A, b)`', NULL, NULL, 'solve', 'It does exactly what the name says.', 'np.linalg.solve(A, b) factorises A and back-substitutes: faster and more accurate than inv(A) @ b.', NULL, NULL, 148);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'random'), 2, 'fill_blank', 'Which Generator method returns a shuffled COPY of `np.arange(n)` (or of an array): `rng.____(n)`?', NULL, NULL, 'permutation', 'Not shuffle: that one works in place.', 'rng.permutation(n) returns a new shuffled array; rng.shuffle(a) shuffles a in place and returns None.', NULL, NULL, 149);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'broadcasting'), 2, 'true_false', 'Broadcasting works on any two shapes as long as they have the same total number of elements.', NULL, NULL, 'False', 'The rule is about each axis, not the total.', '(2, 3) and (3, 2) both have 6 elements but don''t broadcast (3 vs 2 on the last axis). (4, 1) and (3,) have different sizes but do broadcast, to (4, 3).', NULL, NULL, 150);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'linalg'), 2, 'true_false', '`a @ b` and `np.matmul(a, b)` are the same operation.', NULL, NULL, 'True', '@ is an operator that calls a function.', 'The @ operator calls np.matmul (via __matmul__). np.dot is the one that differs for N-d inputs.', NULL, NULL, 151);
