INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'aggregation'), 1, 'true_false', 'For an int64 array `a`, `a.mean()` returns a float64 even though every element is an integer.', NULL, NULL, 'True', 'What is the mean of 1 and 2?', 'mean always uses floating point for integer input, so the result is float64 (1.5 for [1, 2]).', NULL, NULL, 152);
