INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'mcq', 'What does NaN stand for in pandas?', NULL, NULL, 'Not a Number: the marker pandas uses for a missing numeric value', 'It''s a special float value.', 'NaN (Not a Number) is a special floating-point value that pandas uses to mark missing data. It is not 0 and not an empty string.', NULL, 'Like NULL in a SQL table: ''we don''t know this value''.', 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Null and Nothing: an empty string', 0), (@q, 'B', 'Not a Number: the marker pandas uses for a missing numeric value', 1), (@q, 'C', 'A zero that has not been calculated yet', 0), (@q, 'D', 'A row that has been deleted', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"a": [1, np.nan, 3], "b": [None, "x", "y"]})\nprint(df.isna().sum().tolist())', 'python', '[1, 1]', 'isna() marks each missing cell True; sum() counts the Trues per column.', 'Column a has one NaN, column b has one None; isna() treats both as missing, so each column counts 1.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 0]', 0), (@q, 'B', '[1, 1]', 1), (@q, 'C', '[2]', 0), (@q, 'D', '[1, 0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"a": [1, np.nan, 3], "b": [4, 5, np.nan]})\nprint(df.dropna().shape)', 'python', '(1, 2)', 'dropna() removes a row if ANY of its values is missing.', 'Row 1 has NaN in a, row 2 has NaN in b. Only row 0 is complete, so 1 row is left.', '     a     b     any NaN?   dropna()\n0    1     4     no         kept\n1   NaN    5     yes        dropped\n2    3    NaN    yes        dropped', NULL, 3);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '(3, 2)', 0), (@q, 'B', '(0, 2)', 0), (@q, 'C', '(2, 2)', 0), (@q, 'D', '(1, 2)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ns = pd.Series([1, np.nan, 3])\nprint(s.fillna(0).tolist())', 'python', '[1.0, 0.0, 3.0]', 'fillna replaces missing values; the dtype stays float.', 'fillna(0) puts 0 where NaN was. The Series was float64 because of the NaN, and it stays float64 after filling.', NULL, NULL, 4);
