INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'duplicates'), 3, 'mcq', 'Why can duplicate rows between your train and test sets make a model look better than it is?', NULL, NULL, 'The model is tested on rows it has already memorised, so test accuracy overstates real-world accuracy', 'Think of exam questions you''ve already seen the answers to.', 'If the same record sits in both sets, the test is no longer ''unseen data''. Deduplicate (or split by entity, e.g. user_id) before splitting.', NULL, NULL, 26);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Duplicates make training slower but don''t affect scores', 0), (@q, 'B', 'Duplicates only matter for regression, not classification', 0), (@q, 'C', 'Duplicates are automatically removed by scikit-learn', 0), (@q, 'D', 'The model is tested on rows it has already memorised, so test accuracy overstates real-world accuracy', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'types'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["10", "20", "30"])\nprint(s.astype(int).sum())', 'python', '60', 'Convert the text to numbers first.', 'astype(int) turns ''10'', ''20'', ''30'' into integers, so sum is 60. Without it, summing strings concatenates them.', NULL, NULL, 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'TypeError', 0), (@q, 'B', '60', 1), (@q, 'C', '102030', 0), (@q, 'D', '''102030''', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'types'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["1", "two", "3"])\nprint(pd.to_numeric(s, errors="coerce").tolist())', 'python', '[1.0, nan, 3.0]', 'errors=''coerce'' turns anything unparseable into missing.', '''two'' can''t be parsed, so it becomes NaN, and NaN makes the column float64.', NULL, NULL, 28);
