INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'types'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["2024-01-05", "2024-03-20"])\nd = pd.to_datetime(s)\nprint(d.dtype, (d[1] - d[0]).days)', 'python', 'datetime64[ns] 75', 'Once parsed, subtracting dates gives a Timedelta.', 'to_datetime gives datetime64[ns]. Jan 5 -> Mar 20 in the leap year 2024: 26 (rest of Jan) + 29 (Feb) + 20 = 75 days.', NULL, NULL, 32);
