INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'strings'), 1, 'true_false', 'To call a string method like `.lower()` on every value of a Series, you write `s.str.lower()`.', NULL, NULL, 'True', 'A Series isn''t a string, so the string methods live under an accessor.', 'The .str accessor applies the string method to each element and skips missing values. s.lower() would raise AttributeError.', NULL, NULL, 41);
