INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 3, 'code_output', 'What does this print?', 'import pandas as pd\np = pd.DataFrame({"d": ["x", "x", "y"], "c": ["m", "m", "n"], "v": [1, 2, 3]})\np.pivot(index="d", columns="c", values="v")', 'python', 'ValueError', 'Two rows land in the same (x, m) cell.', 'pivot can only reshape, not aggregate. Duplicate (index, column) pairs raise ValueError (''Index contains duplicate entries''). Use pivot_table with an aggfunc.', NULL, NULL, 102);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 1), (@q, 'B', '(nothing is printed)', 0), (@q, 'C', 'KeyError', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 3, 'code_output', 'What does this print?', 'import pandas as pd\np = pd.DataFrame({"d": ["x", "x", "y"], "c": ["m", "m", "n"], "v": [1, 2, 3]})\nprint(p.pivot_table(index="d", columns="c", values="v").loc["x", "m"])', 'python', '1.5', 'pivot_table aggregates duplicates, and its default aggfunc is...?', 'pivot_table''s default aggfunc is ''mean'', so the two values 1 and 2 in (x, m) become 1.5. Pass aggfunc=''sum'' for 3.', NULL, NULL, 103);
