INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 3, 'code_output', 'What does this print?', 'import pandas as pd\np = pd.DataFrame({"d": ["x", "x", "y"], "c": ["m", "n", "n"], "v": [1, 2, 3]})\nt = p.pivot_table(index="d", columns="c", values="v", aggfunc="sum", fill_value=0, margins=True)\nprint(t.loc["All", "All"], t.loc["y", "m"])', 'python', '6 0', 'margins adds totals; fill_value replaces empty cells.', 'margins=True adds an ''All'' row and column with grand totals (1 + 2 + 3 = 6). The empty (y, m) cell is filled with 0.', NULL, NULL, 104);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '6 0', 1), (@q, 'B', '6 nan', 0), (@q, 'C', '3 0', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"sex": ["M", "F", "F", "M"], "smoker": ["y", "n", "y", "y"]})\nprint(pd.crosstab(df["sex"], df["smoker"]).loc["M", "y"])', 'python', '2', 'crosstab counts how often each pair of values occurs.', 'crosstab builds a frequency table: M and y occurs twice.', NULL, NULL, 105);
