INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binning'), 2, 'mcq', 'What is the difference between `pd.cut` and `pd.qcut`?', NULL, NULL, 'cut uses fixed bin edges (equal-width or given); qcut uses quantiles so each bin has about the same number of rows', 'The q stands for quantile.', 'cut splits the value RANGE; qcut splits the sorted DATA into equal-count groups (e.g. quartiles).', NULL, NULL, 110);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'qcut is the faster version of cut', 0), (@q, 'B', 'cut uses fixed bin edges (equal-width or given); qcut uses quantiles so each bin has about the same number of rows', 1), (@q, 'C', 'cut drops outliers, qcut keeps them', 0), (@q, 'D', 'cut works on strings, qcut on numbers', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binning'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nc = pd.cut(pd.Series([0, 5, 10]), bins=[0, 5, 10])\nprint(c.isna().tolist(), c.cat.codes.tolist())', 'python', '[True, False, False] [-1, 0, 1]', 'Bins are (left, right]: the left edge is excluded.', 'By default bins are right-closed, so 0 is not inside (0, 5] and becomes NaN. 5 falls in (0, 5]. Use include_lowest=True or right=False to change it.', 'bins=[0, 5, 10]  ->  (0, 5]   (5, 10]\n                     ^ open    ^ closed\nvalue 0  -> outside every bin -> NaN (code -1)\nvalue 5  -> (0, 5]   value 10 -> (5, 10]', NULL, 111);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[True, False, False] [-1, 0, 1]', 1), (@q, 'B', '[False, False, False] [0, 0, 1]', 0), (@q, 'C', '[False, False, False] [0, 1, 1]', 0), (@q, 'D', '[False, False, True] [0, 1, -1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binning'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, 2, 3, 4, 5, 6, 7, 100])\nprint(pd.qcut(s, 4, labels=False).tolist())', 'python', '[0, 0, 1, 1, 2, 2, 3, 3]', 'Quantile bins have equal counts no matter how extreme a value is.', 'qcut(4) puts 2 of the 8 values in each quartile, so the outlier 100 only affects the last bin. Equal-width cut(4) would put 7 values in the first bin.', 'values: 1 2 | 3 4 | 5 6 | 7 100\nqcut:   q0    q1    q2    q3     (equal counts)\ncut:    |1..25|25..50|50..75|75..100|\n         7 vals  0      0     1     (equal widths)', NULL, 112);
