INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binning'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, 1, 1, 1, 2])\nprint(pd.qcut(s, 4))', 'python', 'ValueError', 'Several quartile edges are the same number.', 'The quartiles are 1, 1, 1, 1, 2, so bin edges repeat and qcut raises ValueError (''Bin edges must be unique''). Pass duplicates=''drop'' or use rank first.', NULL, NULL, 114);
