INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 1, 'true_false', 'You can only use `.dt.year` on a column after it has been converted to a datetime dtype.', NULL, NULL, 'True', 'A string ''2024-03-15'' has no year attribute.', 'On an object (string) column, .dt raises AttributeError (''Can only use .dt accessor with datetimelike values''). Convert with pd.to_datetime first.', NULL, NULL, 118);
