INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nd = pd.Series(pd.to_datetime(["2024-01-01", "2024-01-03"]))\nprint(d.diff().dt.days.tolist())', 'python', '[nan, 2.0]', 'diff subtracts the previous row; the first row has none.', 'diff gives Timedeltas [NaT, 2 days]; .dt.days turns them into numbers, with NaN for the missing first value.', NULL, NULL, 123);
