INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"color": ["red", "green", "red"]})\nd = pd.get_dummies(df)\nprint(d.columns.tolist(), d.dtypes.iloc[0])', 'python', '[''color_green'', ''color_red''] bool', 'One column per category, sorted; pandas 2 uses booleans.', 'get_dummies one-hot encodes: one column per distinct value (sorted), prefixed with the column name. Since pandas 2.0 the columns are bool, not uint8; pass dtype=int if you want 0/1.', 'color      color_green  color_red\nred    ->     False        True\ngreen  ->     True         False\nred    ->     False        True', NULL, 128);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''color''] object', 0), (@q, 'B', '[''color_red'', ''color_green''] int64', 0), (@q, 'C', '[''color_green'', ''color_red''] bool', 1), (@q, 'D', '[''green'', ''red''] uint8', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 1, 'mcq', 'Why do we one-hot encode a categorical column like `city` before giving it to most ML models?', NULL, NULL, 'Models need numbers, and coding cities as 0, 1, 2 would invent an order and distance that don''t exist', 'Is Pune ''twice'' Goa?', 'Label codes like Goa=0, Pune=1, Delhi=2 imply Delhi > Pune > Goa. One-hot gives each city its own 0/1 column, so no fake order is created.', NULL, NULL, 129);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Models can read strings, but one-hot is faster', 0), (@q, 'B', 'One-hot encoding makes the data smaller', 0), (@q, 'C', 'It removes missing values', 0), (@q, 'D', 'Models need numbers, and coding cities as 0, 1, 2 would invent an order and distance that don''t exist', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"color": ["red", "green", "blue"]})\nprint(pd.get_dummies(df, drop_first=True).columns.tolist())', 'python', '[''color_green'', ''color_red'']', 'Categories are sorted; drop_first removes the first one.', 'Sorted categories are blue, green, red; drop_first drops blue (it''s implied when both others are 0). Useful for linear models to avoid perfectly correlated columns.', NULL, NULL, 130);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''color_blue'', ''color_green'', ''color_red'']', 0), (@q, 'B', '[''color_green'', ''color_red'']', 1), (@q, 'C', '[''color_red'', ''color_green'']', 0), (@q, 'D', '[''color_blue'', ''color_green'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ntrain = pd.DataFrame({"c": ["a", "b"]})\ntest = pd.DataFrame({"c": ["a", "z"]})\nprint(pd.get_dummies(train).columns.tolist(), pd.get_dummies(test).columns.tolist())', 'python', '[''c_a'', ''c_b''] [''c_a'', ''c_z'']', 'get_dummies only knows the values it sees.', 'Encoding train and test separately gives different columns, so the model''s inputs don''t line up. Fit an encoder on train (OneHotEncoder(handle_unknown=''ignore'')) or reindex test columns to train''s.', NULL, NULL, 131);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''c_a'', ''c_b''] [''c_a'', ''c_b'']', 0), (@q, 'B', '[''c_a'', ''c_b''] [''c_a'', ''c_z'']', 1), (@q, 'C', '[''c_a'', ''c_b''] [''c_a'', ''c_b'', ''c_z'']', 0), (@q, 'D', 'ValueError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 2, 'mcq', 'You fill missing ages with `df[''age''].fillna(df[''age''].mean())` on the FULL dataset and then split into train and test. What''s the problem?', NULL, NULL, 'Data leakage: the mean includes test rows, so information from the test set leaks into training', 'Would you know the test set''s mean in production?', 'Any statistic used for preprocessing (mean, std, bin edges, vocabularies) must be learned from training data only, then applied to test. Split first, or use a scikit-learn Pipeline so this happens automatically.', 'WRONG                         RIGHT\nfull data -> fit mean         split -> train / test\n          -> fill             train -> fit mean\n          -> split            mean  -> fill train AND test\n(test rows shaped the mean)   (test never seen while fitting)', 'Like letting a test suite peek at the expected outputs while the code is being written.', 132);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'There is no problem as long as you shuffle', 0), (@q, 'B', 'The mean should be computed on the test set only', 0), (@q, 'C', 'fillna can''t take a mean', 0), (@q, 'D', 'Data leakage: the mean includes test rows, so information from the test set leaks into training', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"age": [20, np.nan, 40, 100]})\ntrain, test = df.iloc[:3].copy(), df.iloc[3:].copy()\nm = train["age"].mean()\ntrain["age"] = train["age"].fillna(m)\nprint(m, df["age"].mean())', 'python', '30.0 53.333333333333336', 'Which rows contribute to each mean?', 'The training mean (20, 40) is 30.0. The full-data mean includes the test row 100, giving 53.3: a different value, learned from data the model must not see.', NULL, NULL, 133);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '30.0 30.0', 0), (@q, 'B', '20.0 53.333333333333336', 0), (@q, 'C', '53.333333333333336 30.0', 0), (@q, 'D', '30.0 53.333333333333336', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 1, 'true_false', '`df.iterrows()` is the recommended way to compute a new column from two existing columns.', NULL, NULL, 'False', 'How fast is a Python loop over a million rows?', 'iterrows creates a Series for every row and loops in Python. Write df[''c''] = df[''a''] + df[''b''] (vectorised), or use np.where / np.select for conditions.', NULL, NULL, 134);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"score": [35, 65, 90]})\ncond = [df["score"] >= 80, df["score"] >= 50]\ndf["grade"] = np.select(cond, ["A", "B"], default="C")\nprint(df["grade"].tolist())', 'python', '[''C'', ''B'', ''A'']', 'np.select picks the FIRST condition that is True for each row.', '90 meets >= 80 first -> A; 65 meets only >= 50 -> B; 35 meets none -> default C. It replaces a row-wise if/elif chain with one vectorised call.', NULL, NULL, 135);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''A'', ''B'', ''C'']', 0), (@q, 'B', '[''C'', ''A'', ''A'']', 0), (@q, 'C', '[''C'', ''B'', ''B'']', 0), (@q, 'D', '[''C'', ''B'', ''A'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": [3, 4]})\nfor row in df.itertuples():\n    print(row.Index, row.a + row.b)', 'python', '0 4\n1 6', 'itertuples yields namedtuples with an Index field plus one field per column.', 'itertuples gives lightweight namedtuples (much faster than iterrows and dtype-preserving). row.Index is the index label.', NULL, NULL, 136);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4\n6', 0), (@q, 'B', '0 4\n1 6', 1), (@q, 'C', 'AttributeError', 0), (@q, 'D', '0 (1, 3)\n1 (2, 4)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 4, 'mcq', 'A feature `days_since_signup` is built as `(df[''signup''].max() - df[''signup'']).dt.days` on the full dataset before a time-based split. Why is that a leak?', NULL, NULL, 'The reference date (max) comes from the latest rows, which belong to the future/test period', 'What date is ''today'' for a training row?', 'Using the global max lets training rows know how far the data extends into the test period. Use a fixed reference date known at training time, or compute relative to each row''s own timestamp.', NULL, NULL, 137);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The reference date (max) comes from the latest rows, which belong to the future/test period', 1), (@q, 'B', 'It''s not a leak; max is a harmless statistic', 0), (@q, 'C', 'dt.days rounds the values', 0), (@q, 'D', 'Timedeltas can''t be used as features', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"y": [0, 0, 0, 1]})\nprint(df["y"].value_counts(normalize=True)[1], df["y"].mean())', 'python', '0.25 0.25', 'For a 0/1 column, the mean IS the share of ones.', 'Only 1 in 4 labels is positive: 25%. A model that always predicts 0 scores 75% accuracy, so check class balance before trusting accuracy.', NULL, NULL, 138);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '0.25 0.25', 1), (@q, 'B', '1 0.25', 0), (@q, 'C', '0.75 0.25', 0), (@q, 'D', '0.25 1', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 3, 'mcq', 'You need features for a 50-million-row DataFrame. Which ordering is fastest, from fastest to slowest?', NULL, NULL, 'vectorised column ops  >  list comprehension over zip(...)  >  apply(axis=1)  >  iterrows', 'Less Python per row = faster.', 'Vectorised ops run one C loop. A comprehension over zip touches plain Python values. apply(axis=1) and especially iterrows box every row into a Series, adding large per-row overhead.', NULL, NULL, 139);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'They are all about the same speed', 0), (@q, 'B', 'iterrows  >  apply(axis=1)  >  vectorised column ops  >  list comprehension', 0), (@q, 'C', 'vectorised column ops  >  list comprehension over zip(...)  >  apply(axis=1)  >  iterrows', 1), (@q, 'D', 'apply(axis=1)  >  vectorised column ops  >  iterrows  >  list comprehension', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 4, 'mcq', 'A colleague''s training data has a column `target_mean_by_city` computed with `df.groupby(''city'')[''target''].transform(''mean'')` on all rows. Validation accuracy is excellent; production accuracy is poor. What happened?', NULL, NULL, 'Target leakage: each row''s feature includes its own label (and test labels), so the model learned a shortcut it won''t have in production', 'The feature was computed from the very thing you''re predicting.', 'Target (mean) encoding must be fitted out-of-fold on training data only, excluding the row itself; otherwise the feature leaks the label. This is a classic reason for ''too good to be true'' validation scores.', NULL, NULL, 140);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The model overfit because the column is float', 0), (@q, 'B', 'Target leakage: each row''s feature includes its own label (and test labels), so the model learned a shortcut it won''t have in production', 1), (@q, 'C', 'groupby transform returns values in the wrong order', 0), (@q, 'D', 'Mean encoding can''t be used with categorical data', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 4, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ndf = pd.DataFrame({"x": [1.0, 2.0, 3.0, 4.0]})\nz = (df["x"] - df["x"].mean()) / df["x"].std()\nprint(round(z.std(), 3), round(((df["x"] - df["x"].mean()) / df["x"].std(ddof=0)).std(ddof=0), 3))', 'python', '1.0 1.0', 'Standardising with a given ddof gives std 1 under that same ddof.', 'pandas std uses ddof=1; scikit-learn''s StandardScaler uses ddof=0. Each version gives std 1 under its own definition, but the z-values themselves differ slightly between the two, which matters when reproducing a pipeline.', NULL, NULL, 141);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '1.155 1.0', 0), (@q, 'B', '1.0 1.155', 0), (@q, 'C', '0.866 1.0', 0), (@q, 'D', '1.0 1.0', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'fill_blank', 'To count the missing values in every column, write `df.____().sum()`.', NULL, NULL, 'isna', '''Is it NA?'' for every cell.', 'df.isna() gives True for each missing cell; .sum() counts the Trues per column. isnull is an alias.', NULL, NULL, 142);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'true_false', 'In pandas, `None` and `np.nan` are both treated as missing by `isna()`, `dropna()` and `fillna()`.', NULL, NULL, 'True', 'pandas has several missing markers but one way to detect them.', 'isna/dropna/fillna recognise None, np.nan, pd.NaT and pd.NA. In a numeric column None is converted to NaN on creation.', NULL, NULL, 143);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'missing'), 1, 'mcq', 'Which statement about `df.fillna(0)` is true?', NULL, NULL, 'It returns a new DataFrame with missing values replaced; df itself is unchanged unless you assign the result', 'Most pandas methods return a new object.', 'fillna returns a filled copy. Write df = df.fillna(0) (or assign one column: df[''a''] = df[''a''].fillna(0)).', NULL, NULL, 144);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It returns a new DataFrame with missing values replaced; df itself is unchanged unless you assign the result', 1), (@q, 'B', 'It deletes rows that contain NaN', 0), (@q, 'C', 'It permanently changes df in place', 0), (@q, 'D', 'It only works on the first column', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'types'), 2, 'mcq', 'A ''price'' column was read as object dtype. What is the most likely cause?', NULL, NULL, 'Some entries are not plain numbers, e.g. ''$12'', ''1,200'', ''N/A'' or blanks with spaces', 'A single bad value is enough.', 'If any value can''t be parsed as a number, read_csv keeps the whole column as text. Missing values alone give float64, not object. Find them with pd.to_numeric(s, errors=''coerce'').isna().', NULL, NULL, 145);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The prices are too large for int64', 0), (@q, 'B', 'read_csv always reads money as object', 0), (@q, 'C', 'Some entries are not plain numbers, e.g. ''$12'', ''1,200'', ''N/A'' or blanks with spaces', 1), (@q, 'D', 'The column has missing values', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'types'), 1, 'true_false', '`pd.to_numeric(s, errors=''coerce'')` raises an error if any value can''t be parsed.', NULL, NULL, 'False', 'What does ''coerce'' mean?', 'coerce turns unparseable values into NaN silently. errors=''raise'' (the default) is the one that raises.', NULL, NULL, 146);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'strings'), 1, 'mcq', 'You want every value in a ''name'' column trimmed and lower-cased. Which is idiomatic pandas?', NULL, NULL, 'df["name"] = df["name"].str.strip().str.lower()', 'Series string methods live under an accessor and can be chained.', 'The .str accessor applies each method element-wise and skips missing values. The loop version is slow and is also chained assignment.', NULL, NULL, 147);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df["name"] = df["name"].str.strip().str.lower()', 1), (@q, 'B', 'for i in range(len(df)): df["name"][i] = df["name"][i].strip().lower()', 0), (@q, 'C', 'df["name"].str.lower(strip=True)', 0), (@q, 'D', 'df["name"] = df["name"].strip().lower()', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'strings'), 2, 'fill_blank', 'To replace every match of a regular expression in a text column, write `s.str.replace(pattern, '''', ____=True)`.', NULL, NULL, 'regex', 'Since pandas 2.0 the default treats the pattern literally.', 'str.replace(..., regex=True) treats the pattern as a regex; the default regex=False replaces the literal text.', NULL, NULL, 148);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 1, 'mcq', 'In SQL terms, what is `df.groupby(''dept'').agg(avg_salary=(''salary'', ''mean''))`?', NULL, NULL, 'SELECT dept, AVG(salary) AS avg_salary FROM df GROUP BY dept', 'agg reduces each group to one row.', 'groupby + agg is GROUP BY with aggregate functions; named aggregation is the AS alias. The window-function version (one value per original row) is transform.', NULL, NULL, 149);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'SELECT dept, AVG(salary) OVER (PARTITION BY dept) FROM df', 0), (@q, 'B', 'SELECT AVG(salary) FROM df', 0), (@q, 'C', 'SELECT dept, AVG(salary) AS avg_salary FROM df GROUP BY dept', 1), (@q, 'D', 'SELECT dept, salary FROM df ORDER BY dept', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby-advanced'), 2, 'true_false', '`groupby(...).transform(''sum'')` returns one row per group.', NULL, NULL, 'False', 'transform keeps the original shape.', 'transform returns one value per ORIGINAL row (the group''s result broadcast back). agg is the one that returns one row per group.', NULL, NULL, 150);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'groupby'), 2, 'mcq', 'What does `df.groupby(''g'')[''v''].nunique()` return?', NULL, NULL, 'The number of distinct v values in each group', 'n + unique.', 'nunique counts distinct values per group (SQL COUNT(DISTINCT v)). .unique() would return the arrays of values instead.', NULL, 'SQL: COUNT(DISTINCT v) ... GROUP BY g.', 151);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The number of groups', 0), (@q, 'B', 'The number of distinct v values in each group', 1), (@q, 'C', 'The number of rows in each group', 0), (@q, 'D', 'The unique v values as a list per group', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 1, 'mcq', 'Which `how` keeps every row from BOTH tables, matched where possible?', NULL, NULL, '"outer"', 'FULL OUTER JOIN.', 'how=''outer'' keeps all keys from both sides and fills NaN where one side has no match. ''cross'' is the Cartesian product.', NULL, NULL, 152);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '"inner"', 0), (@q, 'B', '"outer"', 1), (@q, 'C', '"cross"', 0), (@q, 'D', '"left"', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 2, 'true_false', '`df1.join(df2)` joins on the index by default, while `pd.merge(df1, df2)` joins on common column names by default.', NULL, NULL, 'True', 'Two APIs, two defaults.', 'join is index-based (left join by default); merge uses columns with the same name (inner join by default), unless you pass on=/left_on=/left_index= etc.', NULL, NULL, 153);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'merge'), 3, 'mcq', 'Before merging a fact table with a dimension (lookup) table, which `validate=` value encodes ''each fact row must match at most one dimension row''?', NULL, NULL, '"many_to_one"', 'Left side is many (facts), right side is one (lookup).', 'validate=''many_to_one'' checks that the right-hand keys are unique and raises MergeError otherwise, stopping silent row duplication.', NULL, NULL, 154);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '"one_to_many"', 0), (@q, 'B', '"one_to_one"', 0), (@q, 'C', '"many_to_one"', 1), (@q, 'D', '"many_to_many"', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'concat'), 1, 'mcq', 'What is the difference between `pd.concat` and `pd.merge`?', NULL, NULL, 'concat stacks or glues frames along an axis by index/column labels; merge matches rows by key values', 'UNION ALL vs JOIN.', 'concat(axis=0) is like UNION ALL; concat(axis=1) aligns on the index. merge is a SQL JOIN on column values.', NULL, NULL, 155);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'concat stacks or glues frames along an axis by index/column labels; merge matches rows by key values', 1), (@q, 'B', 'merge stacks rows, concat joins on keys', 0), (@q, 'C', 'concat is for strings, merge is for numbers', 0), (@q, 'D', 'They are the same function with different names', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 2, 'true_false', '`pivot` can handle duplicate (index, column) pairs by averaging them.', NULL, NULL, 'False', 'Which of pivot / pivot_table takes an aggfunc?', 'pivot only reshapes and raises ValueError on duplicates. pivot_table aggregates them (mean by default).', NULL, NULL, 156);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'reshape'), 1, 'fill_blank', 'The function that turns wide columns (q1, q2, q3) into long rows (variable, value) is `df.____(id_vars=''id'')`.', NULL, NULL, 'melt', 'The opposite of pivot.', 'melt unpivots wide data into long format.', NULL, NULL, 157);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'binning'), 1, 'mcq', 'You want to turn ages into groups 0-18, 18-60, 60+ for a dashboard. Which function fits?', NULL, NULL, 'pd.cut with explicit bin edges', 'The edges are fixed by meaning, not by the data''s distribution.', 'cut takes the edges you choose. qcut would choose edges so each group has the same number of people, which wouldn''t match 18 and 60.', NULL, NULL, 158);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.groupby(''age'')', 0), (@q, 'B', 'pd.get_dummies(''age'')', 0), (@q, 'C', 'pd.qcut with 3 quantiles', 0), (@q, 'D', 'pd.cut with explicit bin edges', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 1, 'mcq', 'What is NaT?', NULL, NULL, 'The datetime version of NaN: a missing timestamp', 'Not a ...', 'NaT (Not a Time) marks a missing datetime or timedelta. isna() detects it, and it propagates through arithmetic like NaN.', NULL, NULL, 159);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A Timedelta of zero', 0), (@q, 'B', 'A timezone name', 0), (@q, 'C', 'The datetime version of NaN: a missing timestamp', 1), (@q, 'D', 'The first valid date pandas supports', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'datetime'), 2, 'true_false', '`df.resample(''W'')` works on any DataFrame, even one with a plain RangeIndex and no date column.', NULL, NULL, 'False', 'What would it group by?', 'resample needs a DatetimeIndex (or on=''date_col'' pointing to a datetime column). Otherwise it raises TypeError.', NULL, NULL, 160);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 2, 'mcq', 'For a time-series model (predict tomorrow''s sales), how should you split train and test?', NULL, NULL, 'By time: train on earlier dates, test on later dates', 'In production you never know the future.', 'A random split lets the model train on days after the ones it is tested on, leaking the future. Split chronologically (or use TimeSeriesSplit).', NULL, NULL, 161);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Use the same rows for train and test', 0), (@q, 'B', 'By time: train on earlier dates, test on later dates', 1), (@q, 'C', 'Put every weekend in the test set', 0), (@q, 'D', 'Randomly shuffle rows and take 20% as test', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 4, 'true_false', 'For a tree-based model like a random forest, label-encoding a high-cardinality category (one integer per value) can be acceptable, while for linear models one-hot encoding is usually safer.', NULL, NULL, 'True', 'Trees split on thresholds; linear models multiply by a weight.', 'A linear model would treat code 7 as ''7 times'' code 1. Trees can carve any integer ranges and are less hurt by arbitrary codes, and one-hot on thousands of values can bloat the feature matrix.', NULL, NULL, 162);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'ml-prep'), 3, 'mcq', 'Why does scikit-learn recommend putting imputation and encoding inside a `Pipeline` with cross-validation?', NULL, NULL, 'So each fold fits the imputer/encoder on that fold''s training part only, preventing leakage', 'What would happen if you imputed once before cross-validation?', 'Preprocessing done once on all data leaks validation statistics into every fold. A Pipeline refits the preprocessing inside each training fold.', NULL, NULL, 163);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Because pandas can''t do imputation', 0), (@q, 'B', 'Pipelines make the model more accurate by default', 0), (@q, 'C', 'So each fold fits the imputer/encoder on that fold''s training part only, preventing leakage', 1), (@q, 'D', 'To avoid converting DataFrames to arrays', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'series-vs-df'), 1, 'mcq', 'In pandas, what is a Series?', NULL, NULL, 'A single labelled column of values (values + an index)', 'Think of one column of a spreadsheet, together with its row labels.', 'A Series is one-dimensional: an array of values plus an index (the row labels). A DataFrame is a table made of several Series that share the same index.', 'Series "age"          DataFrame\nindex  value          index  name  age\n  0     30              0    Ann   30\n  1     25              1    Bob   25\n(labels) (data)         (shared index, many columns)', 'A Series is one column in an Excel sheet; a DataFrame is the whole sheet.', 1);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'A database connection to a CSV file', 0), (@q, 'B', 'A Python list with extra methods but no labels', 0), (@q, 'C', 'A whole table with rows and columns', 0), (@q, 'D', 'A single labelled column of values (values + an index)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'series-vs-df'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"name": ["Ann", "Bob"], "age": [30, 25]})\nprint(type(df).__name__, type(df["age"]).__name__)', 'python', 'DataFrame Series', 'One pair of square brackets with one column name gives you a single column.', 'df is a DataFrame; df["age"] picks one column, which is a Series.', NULL, NULL, 2);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'DataFrame Series', 1), (@q, 'B', 'Series Series', 0), (@q, 'C', 'DataFrame list', 0), (@q, 'D', 'DataFrame DataFrame', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'series-vs-df'), 1, 'true_false', 'Every column of a DataFrame shares the same index (row labels).', NULL, NULL, 'True', 'How else would row 3 of one column line up with row 3 of another?', 'A DataFrame is a dict of Series that all share one index. That shared index is what keeps each row''s values together.', NULL, NULL, 3);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'series-vs-df'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([10, 20, 30], index=["a", "b", "c"])\nprint(s["b"], s.index.tolist())', 'python', '20 [''a'', ''b'', ''c'']', 'With a custom index, s["b"] looks up the label "b".', 'The index holds the labels a, b, c. s["b"] returns the value stored under label b, which is 20.', NULL, NULL, 4);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '20 [''a'', ''b'', ''c'']', 1), (@q, 'B', '20 [0, 1, 2]', 0), (@q, 'C', '10 [''a'', ''b'', ''c'']', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'series-vs-df'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": [3.5, 4.5]})\nrow = df.iloc[0]\nprint(type(row).__name__, row.dtype)', 'python', 'Series float64', 'One row must hold both an int and a float in a single 1-D container.', 'A single row comes back as a Series. Its values must share one dtype, so int 1 is upcast to float64 to live next to 3.5.', NULL, NULL, 5);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Series object', 0), (@q, 'B', 'Series float64', 1), (@q, 'C', 'Series int64', 0), (@q, 'D', 'DataFrame int64', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'series-vs-df'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "c": ["x", "y"]})\nprint(df.iloc[0].dtype)', 'python', 'object', 'A Series has exactly one dtype. What can hold both 1 and ''x''?', 'The row holds an int and a str, so pandas falls back to object dtype (generic Python objects). Row access on mixed tables silently loses the column dtypes.', NULL, NULL, 6);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'mixed', 0), (@q, 'B', 'string', 0), (@q, 'C', 'int64', 0), (@q, 'D', 'object', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'series-vs-df'), 2, 'mcq', 'You run `s = df[''price'']` and then `s.to_frame()`. What is the result?', NULL, NULL, 'A one-column DataFrame whose column is named ''price''', 'to_frame turns 1-D into 2-D.', 'Series.to_frame() wraps the Series into a DataFrame with one column; the column name is the Series name (''price'').', NULL, NULL, 7);
