INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'creating'), 3, 'code_output', 'What does this print?', 'import pandas as pd\na = pd.Series([1, 2], index=["r1", "r2"])\nb = pd.Series([3, 4], index=["r2", "r3"])\ndf = pd.DataFrame({"a": a, "b": b})\nprint(df.shape, df.isna().sum().sum())', 'python', '(3, 2) 2', 'Series in a dict are lined up by their index labels, not by position.', 'The index becomes the union r1, r2, r3. a has no r3 and b has no r1, so 2 cells are NaN.', NULL, NULL, 16);
