INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 1, 'mcq', 'Which method prints the column names, non-null counts and dtypes of a DataFrame?', NULL, NULL, 'df.info()', 'It gives information about the structure, not statistics.', 'info() prints the index range, each column''s non-null count and dtype, and memory usage. describe() gives summary statistics instead.', NULL, 'info() is like `DESCRIBE table` in SQL: the schema, not the data.', 21);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.info()', 1), (@q, 'B', 'df.describe()', 0), (@q, 'C', 'df.head()', 0), (@q, 'D', 'df.columns()', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"name": ["Ann", "Bob", "Cy"], "age": [30, 25, 35]})\nprint(df.describe().loc["mean", "age"], df.describe().columns.tolist())', 'python', '30.0 [''age'']', 'By default describe() only summarises numeric columns.', 'describe() skips the text column, so only ''age'' appears; its mean is 30.0 (always a float in describe).', NULL, NULL, 22);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '30.0 [''age'']', 1), (@q, 'B', 'KeyError', 0), (@q, 'C', '30.0 [''name'', ''age'']', 0), (@q, 'D', '30 [''age'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"name": ["Ann", "Bob"], "age": [30, 25], "score": [9.5, 8.0]})\nprint(df.dtypes.tolist())', 'python', '[dtype(''O''), dtype(''int64''), dtype(''float64'')]', 'dtypes is a Series of NumPy dtype objects; text is stored as Python objects.', 'Text columns default to object dtype (shown as dtype(''O'')), whole numbers to int64, decimals to float64.', NULL, NULL, 23);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[dtype(''<U3''), dtype(''int64''), dtype(''float64'')]', 0), (@q, 'B', '[dtype(''O''), dtype(''int64''), dtype(''float64'')]', 1), (@q, 'C', '[''object'', ''int64'', ''float64'']', 0), (@q, 'D', '[str, int, float]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"name": ["Ann", "Bob", "Cy"], "age": [30, 25, 35]})\nprint(df.describe())', 'python', '        age\ncount   3.0\nmean   30.0\nstd     5.0\nmin    25.0\n25%    27.5\n50%    30.0\n75%    32.5\nmax    35.0', 'pandas uses the sample standard deviation (divide by n-1).', 'describe() shows count, mean, std, min, quartiles and max for numeric columns. std is the sample std: sqrt(((-0)^2+5^2+5^2)/2) = 5.0, not the population value 4.08.', NULL, NULL, 24);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '        age\ncount     3\nmean     30\nstd       5\nmin      25\nmax      35', 0), (@q, 'B', '        age\ncount   3.0\nmean   30.0\nstd     4.1\nmin    25.0\n25%    27.5\n50%    30.0\n75%    32.5\nmax    35.0', 0), (@q, 'C', '       name   age\ncount     3   3.0\nmean    NaN  30.0\nstd     NaN   5.0\nmin     Ann  25.0\nmax      Cy  35.0', 0), (@q, 'D', '        age\ncount   3.0\nmean   30.0\nstd     5.0\nmin    25.0\n25%    27.5\n50%    30.0\n75%    32.5\nmax    35.0', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 3, 'true_false', '`df.describe()` uses the population standard deviation (dividing by n).', NULL, NULL, 'False', 'Compare with NumPy''s default ddof.', 'pandas'' std() and describe() use ddof=1 (sample std, divide by n-1). NumPy''s np.std defaults to ddof=0. The two disagree on the same data.', NULL, NULL, 25);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 2, 'code_output', 'What does this print?', 'import pandas as pd\nimport numpy as np\ns = pd.Series([1, np.nan, 3])\nprint(len(s), s.count(), s.mean())', 'python', '3 2 2.0', 'count() counts non-missing values; mean() skips NaN by default.', 'len counts every slot (3); count() ignores NaN (2); mean skips NaN, so (1 + 3) / 2 = 2.0.', NULL, NULL, 26);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3 2 nan', 0), (@q, 'B', '3 2 2.0', 1), (@q, 'C', '2 2 2.0', 0), (@q, 'D', '3 3 1.333', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 2, 'mcq', '`df.info()` shows a column with `998 non-null` while the RangeIndex says 1000 entries. What does that tell you?', NULL, NULL, 'That column has 2 missing values', 'Non-null count vs total rows.', 'Non-null count lower than the row count means missing values (NaN/None). df[''col''].isna().sum() would print 2.', NULL, NULL, 27);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '2 rows failed to parse and were dropped', 0), (@q, 'B', 'The column uses 998 bytes', 0), (@q, 'C', 'That column has 2 missing values', 1), (@q, 'D', 'The column has 2 duplicate values', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": ["x", "y"]})\nprint(df.size, df.ndim, df.columns.tolist())', 'python', '4 2 [''a'', ''b'']', 'size counts cells; ndim counts axes.', 'size = rows x columns = 4; a DataFrame has 2 axes (rows and columns); columns is an Index converted to a list.', NULL, NULL, 28);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '4 2 [''a'', ''b'']', 1), (@q, 'B', '(2, 2) 2 [''a'', ''b'']', 0), (@q, 'C', '2 2 [''a'', ''b'']', 0), (@q, 'D', '4 1 [''a'', ''b'']', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'inspecting'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"g": ["a", "b", "a"], "v": [1, 2, 3]})\nprint(df.describe(include="all").loc["unique", "g"], df.describe(include="all").loc["top", "g"])', 'python', '2 a', 'include=''all'' adds count/unique/top/freq rows for text columns.', 'For object columns describe reports unique (2 distinct values), top (most frequent, ''a'') and freq. Numeric-only rows like mean are NaN for that column.', NULL, NULL, 29);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '3 a', 0), (@q, 'B', '2 a', 1), (@q, 'C', '2 b', 0), (@q, 'D', 'nan nan', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"name": ["Ann", "Bob"], "age": [30, 25]})\nprint(type(df["age"]).__name__, type(df[["age"]]).__name__)', 'python', 'Series DataFrame', 'A string inside [] vs a list inside [].', 'df[''age''] gives a Series (1-D). df[[''age'']] passes a list of column names, so you get a DataFrame with one column (2-D).', NULL, NULL, 30);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Series DataFrame', 1), (@q, 'B', 'Series Series', 0), (@q, 'C', 'DataFrame DataFrame', 0), (@q, 'D', 'DataFrame Series', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 1, 'mcq', 'How do you select the two columns `name` and `age` from df?', NULL, NULL, 'df[["name", "age"]]', 'You pass ONE thing inside the brackets: a list.', 'df[[''name'', ''age'']] passes a Python list of names. df[''name'', ''age''] looks for a single column whose label is the tuple (''name'', ''age'') and raises KeyError.', NULL, NULL, 31);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df[["name", "age"]]', 1), (@q, 'B', 'df[name, age]', 0), (@q, 'C', 'df.select("name", "age")', 0), (@q, 'D', 'df["name", "age"]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"name": ["Ann", "Bob"], "age": [30, 25]})\nprint(df["name", "age"])', 'python', 'KeyError', 'Python turns `a, b` inside [] into a tuple.', 'df[''name'', ''age''] is df[(''name'', ''age'')]: pandas looks for one column labelled by that tuple and raises KeyError. Use double brackets.', NULL, NULL, 32);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 1), (@q, 'B', 'IndexError', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', '  name  age\n0  Ann   30\n1  Bob   25', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"name": ["Ann", "Bob"], "age": [30, 25]})\nprint(df.age.tolist(), df["age"].tolist())', 'python', '[30, 25] [30, 25]', 'Columns with simple names are also reachable as attributes.', 'df.age is a shortcut for df[''age''] when the name is a valid Python identifier and doesn''t clash with a method.', NULL, NULL, 33);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'AttributeError', 0), (@q, 'B', '[30, 25] [30, 25]', 1), (@q, 'C', '[30, 25] KeyError', 0), (@q, 'D', 'None [30, 25]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"count": [1, 2], "first name": ["A", "B"]})\nprint(type(df.count).__name__)', 'python', 'method', 'DataFrame already has a method with this name.', 'df.count is the DataFrame.count method, not your column. Attribute access loses to built-in methods; columns with spaces can''t be reached by dot at all. Prefer df[''count''].', NULL, NULL, 34);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'method', 1), (@q, 'B', 'int', 0), (@q, 'C', 'AttributeError', 0), (@q, 'D', 'Series', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 2, 'true_false', '`df.new_col = [1, 2, 3]` creates a new column named new_col.', NULL, NULL, 'False', 'Attribute *reading* works for existing columns. What about attribute *writing*?', 'Assigning to a new attribute just sets a Python attribute on the object (pandas warns about it). New columns must be created with df[''new_col''] = ...', NULL, NULL, 35);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1], "b": [2], "c": [3]})\nprint(df[["c", "a"]].columns.tolist())', 'python', '[''c'', ''a'']', 'The list decides the order.', 'Selecting with a list returns the columns in the order you listed them, which is also an easy way to reorder columns.', NULL, NULL, 36);
