INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'selecting'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3], "b": [4, 5, 6]})\nprint(df[0:2].shape, df[["a"]].shape)', 'python', '(2, 2) (3, 1)', 'A slice inside df[] is treated differently from a label.', 'df[0:2] slices ROWS by position (a historical shortcut), giving 2 rows. df[''a''] or df[[''a'']] select columns. Mixing these is confusing, so prefer .iloc for rows.', NULL, NULL, 38);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '(2, 2) (3,)', 0), (@q, 'C', '(3, 2) (3, 1)', 0), (@q, 'D', '(2, 2) (3, 1)', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 1, 'mcq', 'What is the difference between `df.loc` and `df.iloc`?', NULL, NULL, 'loc selects by label (index names); iloc selects by integer position', 'The ''i'' stands for integer.', 'loc uses index labels and column names. iloc uses 0-based positions like a list, regardless of what the labels are.', NULL, 'loc is looking someone up by name; iloc is ''the 3rd person in the queue''.', 39);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'loc selects rows; iloc selects columns', 0), (@q, 'B', 'loc selects by label (index names); iloc selects by integer position', 1), (@q, 'C', 'loc is faster; iloc is safer', 0), (@q, 'D', 'loc returns a copy; iloc returns a view', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"v": [10, 20, 30, 40]})\nprint(df.loc[1:2, "v"].tolist(), df.iloc[1:2, 0].tolist())', 'python', '[20, 30] [20]', 'One of them includes the end of the slice.', 'loc slices by label and INCLUDES the end label (1 and 2). iloc slices by position like Python, EXCLUDING the end (just position 1).', 'labels:   0   1   2   3\nvalues:  10  20  30  40\nloc[1:2]     [------]     -> 20, 30  (end included)\niloc[1:2]    [--]         -> 20      (end excluded)', NULL, 40);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[20, 30] [20, 30]', 0), (@q, 'B', '[20] [20]', 0), (@q, 'C', '[20, 30] [20]', 1), (@q, 'D', '[10, 20] [20]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"name": ["Ann", "Bob", "Cy"], "age": [30, 25, 35]})\nprint(df.loc[2, "name"], df.iloc[0, 1])', 'python', 'Cy 30', 'loc[row label, column name]; iloc[row position, column position].', 'loc[2, ''name''] is the row labelled 2 in column name: Cy. iloc[0, 1] is row 0, column 1 (age): 30.', NULL, NULL, 41);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Bob Ann', 0), (@q, 'B', 'Cy 30', 1), (@q, 'C', 'Cy Ann', 0), (@q, 'D', 'Bob 30', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"v": [10, 20, 30]}, index=[2, 0, 1])\nprint(df.loc[0, "v"], df.iloc[0, 0])', 'python', '20 10', 'When the index isn''t 0,1,2 in order, labels and positions disagree.', 'loc[0] finds the row whose LABEL is 0 (value 20). iloc[0] takes the FIRST row by position (label 2, value 10).', 'position:  0    1    2\nlabel:     2    0    1\nvalue:    10   20   30\niloc[0] -> position 0 -> 10\nloc[0]  -> label 0    -> 20', NULL, 42);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '20 10', 1), (@q, 'B', '20 20', 0), (@q, 'C', '10 20', 0), (@q, 'D', '10 10', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"v": [10, 20, 30]}, index=["a", "b", "c"])\nprint(df.iloc[-1, 0])\nprint(df.loc[-1, "v"])', 'python', '30\nKeyError', 'Negative positions work like Python lists; negative labels must actually exist.', 'iloc[-1] is the last row (30). loc[-1] looks for a row labelled -1, which doesn''t exist, so it raises KeyError after the first print.', NULL, NULL, 43);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '30\nIndexError', 0), (@q, 'B', '30\nKeyError', 1), (@q, 'C', '30\n30', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 1, 'fill_blank', 'Complete to select the `age` column for rows labelled ''r1'' through ''r3'' inclusive: `df.____[''r1'':''r3'', ''age'']`', NULL, NULL, 'loc', 'Label-based, and the end is included.', 'df.loc[''r1'':''r3'', ''age''] slices by labels and includes ''r3''.', NULL, NULL, 44);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": [3, 4], "c": [5, 6]})\nprint(df.loc[:, "a":"b"].columns.tolist(), df.iloc[:, 0:1].columns.tolist())', 'python', '[''a'', ''b''] [''a'']', 'The same inclusive/exclusive rule applies to column slices.', 'loc ''a'':''b'' includes b; iloc 0:1 excludes position 1, so only column a.', NULL, NULL, 45);
