INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"v": [10, 20, 30]}, index=[0, 1, 2])\nprint(df.loc[[0, 2], "v"].tolist(), type(df.loc[1, "v"]).__name__)', 'python', '[10, 30] int64', 'A list of labels returns several rows; a single label plus single column returns one cell.', 'loc with a list of labels returns those rows. A single row label with a single column returns a scalar, which is a NumPy int64 here.', NULL, NULL, 46);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[10, 30] Series', 0), (@q, 'B', '[10, 20, 30] int64', 0), (@q, 'C', '[10, 30] int', 0), (@q, 'D', '[10, 30] int64', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"v": [10, 20, 30]}, index=[1, 1, 2])\nprint(type(df.loc[1]).__name__, type(df.loc[2]).__name__)', 'python', 'DataFrame Series', 'Index labels don''t have to be unique.', 'Label 1 appears twice, so loc[1] returns both rows as a DataFrame; label 2 is unique, so loc[2] is one row (a Series). Code that assumes one type breaks on duplicate labels.', 'index  v\n  1   10  \\ loc[1] -> 2 rows -> DataFrame\n  1   20  /\n  2   30    loc[2] -> 1 row  -> Series', NULL, 47);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'DataFrame Series', 1), (@q, 'B', 'Series Series', 0), (@q, 'C', 'DataFrame DataFrame', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"v": [10, 20, 30]}, index=[3, 1, 2])\nprint(df.loc[1:3, "v"].tolist())', 'python', '[]', 'Label slices follow the order of the index, not sorted order.', 'On a non-sorted index, loc[1:3] goes from wherever label 1 is to wherever label 3 is, in the index''s current order. Label 1 is at position 1 and 3 is at 0, so the slice is empty.', NULL, NULL, 48);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[20, 30]', 0), (@q, 'B', 'KeyError', 0), (@q, 'C', '[10, 20, 30]', 0), (@q, 'D', '[]', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 3, 'mcq', 'You want the value in the 3rd row of column `price`, regardless of the index labels. Which is correct and clear?', NULL, NULL, 'df["price"].iloc[2]', 'Mix ''position for rows'' with ''name for columns'' safely.', 'df[''price''].iloc[2] is position-based for the row. df[''price''][2] and df.loc[2] look for the LABEL 2. df.iloc[2, ''price''] fails because iloc only takes integers.', NULL, NULL, 49);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df.iloc[2, "price"]', 0), (@q, 'B', 'df["price"].iloc[2]', 1), (@q, 'C', 'df["price"][2]', 0), (@q, 'D', 'df.loc[2, "price"]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([10, 20, 30], index=[2, 1, 0])\nprint(s[0], s.iloc[0])', 'python', '30 10', 'With an integer index, plain [] on a Series means label.', 's[0] on an integer index looks up LABEL 0 (value 30). s.iloc[0] is position 0 (value 10). This ambiguity is exactly why .loc/.iloc exist.', NULL, NULL, 50);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '30 10', 1), (@q, 'B', '10 30', 0), (@q, 'C', '10 10', 0), (@q, 'D', '30 30', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'loc-iloc'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3]})\ndf.loc[5, "a"] = 9\nprint(df.index.tolist(), df["a"].dtype)', 'python', '[0, 1, 2, 5] float64', 'loc assignment to a missing label behaves like an upsert.', 'Setting with loc on a label that doesn''t exist appends a new row (enlargement). The column is temporarily NaN-filled during the insert, so it ends up float64. iloc would raise IndexError instead.', NULL, NULL, 51);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '[0, 1, 2, 5] int64', 0), (@q, 'C', '[0, 1, 2, 5] float64', 1), (@q, 'D', 'IndexError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"name": ["Ann", "Bob", "Cy"], "age": [30, 25, 35]})\nprint(df[df["age"] > 28]["name"].tolist())', 'python', '[''Ann'', ''Cy'']', 'The condition makes a True/False per row; df[...] keeps the True rows.', 'df[''age''] > 28 gives a boolean mask [True, False, True]. df[mask] keeps rows Ann and Cy.', 'name  age   age > 28   keep?\nAnn    30     True      yes\nBob    25     False     no\nCy     35     True      yes', 'SQL: SELECT name FROM df WHERE age > 28.', 52);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''Bob'']', 0), (@q, 'B', '[True, False, True]', 0), (@q, 'C', '[''Cy'']', 0), (@q, 'D', '[''Ann'', ''Cy'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"age": [30, 25, 35]})\nprint((df["age"] > 28).tolist())', 'python', '[True, False, True]', 'A comparison on a column compares every element.', 'Comparing a Series to a number gives a boolean Series of the same length: the mask.', NULL, NULL, 53);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 2]', 0), (@q, 'B', '[True, False, True]', 1), (@q, 'C', '[30, 35]', 0), (@q, 'D', 'True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 1, 'mcq', 'Which line correctly keeps rows where age > 20 AND city == ''Pune''?', NULL, NULL, 'df[(df["age"] > 20) & (df["city"] == "Pune")]', 'Element-wise AND is a different symbol, and it binds tighter than >.', 'Use & (element-wise AND) with each condition in parentheses. `and` tries to turn a whole Series into one True/False and fails; without parentheses, & is evaluated before > and ==.', NULL, NULL, 54);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'df[(df["age"] > 20) & (df["city"] == "Pune")]', 1), (@q, 'B', 'df[df["age"] > 20 & df["city"] == "Pune"]', 0), (@q, 'C', 'df[df["age"] > 20 and df["city"] == "Pune"]', 0), (@q, 'D', 'df[(df["age"] > 20) && (df["city"] == "Pune")]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"age": [30, 25, 35]})\nprint(df[df["age"] > 26 and df["age"] < 34])', 'python', 'ValueError', '`and` needs ONE True or False.', 'Python''s `and` calls bool() on a Series, and pandas refuses: ''The truth value of a Series is ambiguous''. That is a ValueError. Use & with parentheses.', NULL, NULL, 55);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'KeyError', 0), (@q, 'B', '   age\n0   30', 0), (@q, 'C', 'TypeError', 0), (@q, 'D', 'ValueError', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"age": [30, 25, 35]})\nprint(df[(df["age"] < 26) | (df["age"] > 34)].index.tolist(), df[~(df["age"] > 26)].index.tolist())', 'python', '[1, 2] [1]', '| is OR, ~ is NOT.', 'Ages under 26 or over 34 are rows 1 and 2. ~ flips the mask age > 26 ([T, F, T]) to [F, T, F], leaving row 1.', NULL, NULL, 56);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2] [1]', 1), (@q, 'B', '[1, 2] [0, 1, 2]', 0), (@q, 'C', '[1, 2] [0, 2]', 0), (@q, 'D', '[0] [1]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"city": ["Pune", "Goa", "Delhi", "Pune"]})\nprint(df[df["city"].isin(["Pune", "Goa"])].index.tolist())', 'python', '[0, 1, 3]', 'isin is SQL''s IN (...).', 'isin checks membership in a list for each row: Pune, Goa and Pune match at positions 0, 1, 3.', NULL, 'SQL: WHERE city IN (''Pune'', ''Goa'').', 57);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 3]', 0), (@q, 'B', '[0, 1, 3]', 1), (@q, 'C', '[0, 1]', 0), (@q, 'D', '[1, 2]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"name": ["Ann", "Bob", "Cy"], "age": [30, 25, 35]})\nlimit = 28\nprint(df.query("age > @limit")["name"].tolist())', 'python', '[''Ann'', ''Cy'']', '@ refers to a Python variable inside a query string.', 'query() takes a string expression; @limit pulls in the local variable. It is the same filter as df[df[''age''] > limit], just easier to read.', NULL, NULL, 58);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''Ann'', ''Cy'']', 1), (@q, 'B', '[''Bob'']', 0), (@q, 'C', 'NameError', 0), (@q, 'D', 'UndefinedVariableError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"age": [30, 25, 35], "city": ["Pune", "Goa", "Pune"]})\nprint(df.query("age > 26 and city == ''Pune''").shape)', 'python', '(2, 2)', 'Inside a query string the rules differ from plain Python.', 'query() parses its own expression language, where `and`/`or` are allowed and mean element-wise &/|. Rows 0 and 2 match.', NULL, NULL, 59);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'ValueError', 0), (@q, 'B', '(3, 2)', 0), (@q, 'C', '(2, 2)', 1), (@q, 'D', '(1, 2)', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'filtering'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"age": [30, 25, 35]})\nprint(df[df["age"] > 26 & df["age"] < 34])', 'python', 'ValueError', '& is evaluated first: 26 & df[''age'']. Then Python sees a chained comparison a > b < c.', 'Without parentheses, Python computes 26 & df[''age''], then expands `x > y < z` into `(x > y) and (y < z)`, and `and` calls bool() on a Series: ValueError. Always parenthesise each condition.', 'written:   df.age > 26 & df.age < 34\nPython:    df.age > (26 & df.age) < 34\nbecomes:   (df.age > X) and (X < 34)   <- `and` on Series\nfix:       (df.age > 26) & (df.age < 34)', NULL, 60);
