INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1], "b": [2]})\ndf.rename(columns={"a": "x"})\nprint(df.columns.tolist())', 'python', '[''a'', ''b'']', 'Most pandas methods return a NEW object.', 'rename returns a new DataFrame; the result was thrown away, so df is unchanged. Write df = df.rename(columns={''a'': ''x''}).', NULL, NULL, 65);
