INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'modifying'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2]})\ndf2 = df.assign(b=df["a"] * 10, c=lambda d: d["b"] + 1)\nprint(df2["c"].tolist(), df.columns.tolist())', 'python', '[11, 21] [''a'']', 'assign returns a new frame; later keywords can see earlier ones via a lambda.', 'assign builds b first, then the lambda receives the frame that already has b, so c = b + 1. The original df is untouched.', NULL, NULL, 71);
