INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["lo", "hi", "lo"])\nprint(s.map({"lo": 0, "hi": 1}).tolist())', 'python', '[0, 1, 0]', 'map with a dict looks up each value.', 'Series.map(dict) replaces each value with its dict value, a common way to encode labels.', NULL, NULL, 76);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 1, 0]', 1), (@q, 'B', '[''lo'', ''hi'', ''lo'']', 0), (@q, 'C', '[0, 1]', 0), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 1, 'true_false', 'A vectorised operation like `df[''a''] * 2` is usually much faster than `df[''a''].apply(lambda x: x * 2)`.', NULL, NULL, 'True', 'Where does the loop run: in C or in Python?', 'Vectorised ops loop in compiled C over a NumPy array. apply calls a Python function once per element, which is often 10-100x slower.', NULL, 'Like one bulk SQL UPDATE versus a for-loop issuing one UPDATE per row.', 77);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["lo", "hi", "mid"])\nprint(s.map({"lo": 0, "hi": 1}).tolist())', 'python', '[0.0, 1.0, nan]', 'What does map do with a value that is not in the dict?', 'Values missing from the dict become NaN, and NaN forces the result to float64. Use .replace() if unmatched values should stay as they are.', NULL, NULL, 78);
