INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'apply-vectorise'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": [3, 4]})\nr = df.apply(lambda row: row["a"] + row["b"], axis=1)\nprint(type(r).__name__, r.tolist())', 'python', 'Series [4, 6]', 'When the function returns a scalar per row, what shape is the result?', 'apply(axis=1) with a scalar-returning function gives one value per row: a Series indexed like df.', NULL, NULL, 82);
