INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'true_false', 'In pandas 2.2, copy-on-write is turned on by default.', NULL, NULL, 'False', 'It becomes the default in a later major version.', 'In 2.2 copy-on-write is opt-in (pd.options.mode.copy_on_write = True, or ''warn''). It becomes the only behaviour in pandas 3.0.', NULL, NULL, 97);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 2, 'mcq', 'What does SettingWithCopyWarning mean?', NULL, NULL, 'You may be modifying a temporary copy, so the original DataFrame might not change', 'It''s about whether your write actually reaches the original data.', 'pandas can''t tell if the object you''re writing to is a view of the original or a copy, so it warns that your change may be lost. Fix by doing the selection and assignment in ONE .loc call, or by calling .copy() explicitly.', NULL, NULL, 98);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'Your DataFrame has duplicate column names', 0), (@q, 'B', 'You made too many copies and memory is low', 0), (@q, 'C', 'You may be modifying a temporary copy, so the original DataFrame might not change', 1), (@q, 'D', 'The column you set has the wrong dtype', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3], "b": [10, 20, 30]})\ndf[df["a"] > 1]["b"] = 0\nprint(df["b"].tolist())', 'python', '[10, 20, 30]', 'Two separate [] steps: the first one makes a NEW frame.', 'df[mask] creates a new DataFrame (a copy). Setting [''b''] on that temporary copy is lost; pandas emits SettingWithCopyWarning. df is unchanged.', 'df --df[mask]--> temp copy --["b"] = 0--> temp changed\n |                                          (then discarded)\n +-- unchanged\n\ndf.loc[mask, "b"] = 0  --> writes straight into df', NULL, 99);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[0, 0, 0]', 0), (@q, 'B', 'KeyError', 0), (@q, 'C', '[10, 20, 30]', 1), (@q, 'D', '[10, 0, 0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3], "b": [10, 20, 30]})\ndf.loc[df["a"] > 1, "b"] = 0\nprint(df["b"].tolist())', 'python', '[10, 0, 0]', 'One .loc call with both the row filter and the column.', 'loc[row_mask, column] = value writes directly into df, with no intermediate copy. This is the fix for SettingWithCopyWarning.', NULL, 'SQL: UPDATE df SET b = 0 WHERE a > 1, one statement.', 100);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[10, 20, 0]', 0), (@q, 'B', '[10, 20, 30]', 0), (@q, 'C', '[10, 0, 0]', 1), (@q, 'D', '[0, 0, 0]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 1, 'fill_blank', 'To get an independent DataFrame that you can change without touching the original, call `sub = df[df.a > 1].____()`.', NULL, NULL, 'copy', 'Make it explicit.', '.copy() returns a deep copy by default. Changing sub afterwards can never affect df, and no SettingWithCopyWarning is raised.', NULL, NULL, 101);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3]})\ns = df["a"]\ns[0] = 100\nprint(df["a"].tolist())', 'python', '[100, 2, 3]', 'In pandas 2.2 without copy-on-write, df[''a''] can share memory with df.', 'With copy-on-write off (the 2.2 default), the column Series is a view of df''s data, so writing to it changes df. With copy-on-write on, df would stay [1, 2, 3].', NULL, NULL, 102);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[100, 100, 100]', 0), (@q, 'B', '[1, 2, 3]', 0), (@q, 'C', '[100, 2, 3]', 1), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'code_output', 'What does this print?', 'import pandas as pd\nwith pd.option_context("mode.copy_on_write", True):\n    df = pd.DataFrame({"a": [1, 2, 3]})\n    s = df["a"]\n    s[0] = 100\n    print(df["a"].tolist(), s.tolist())', 'python', '[1, 2, 3] [100, 2, 3]', 'Under copy-on-write, every derived object behaves like a copy.', 'With copy-on-write, s shares memory only until it is written to; the write triggers a real copy, so df is protected. Behaviour is predictable: only the object you modify changes.', 's = df["a"]      df --\\\n                      +--> [1, 2, 3]   (shared)\n                 s ---/\ns[0] = 100       df --> [1, 2, 3]\n                 s  --> [100, 2, 3]  (copied on write)', NULL, 103);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 3] [100, 2, 3]', 1), (@q, 'B', '[100, 2, 3] [100, 2, 3]', 0), (@q, 'C', 'ValueError', 0), (@q, 'D', '[1, 2, 3] [1, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3]})\ndf["a"][0] = 99\nprint(df["a"].tolist())', 'python', '[99, 2, 3]', 'In 2.2 with default settings, df[''a''] is a cached view of the column.', 'Chained assignment through a column still writes through in pandas 2.2 (with a FutureWarning saying it will stop working). Under copy-on-write / pandas 3.0 it never updates df. Use df.loc[0, ''a''] = 99.', NULL, NULL, 104);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[99, 2, 3]', 1), (@q, 'B', 'KeyError', 0), (@q, 'C', 'ValueError', 0), (@q, 'D', '[1, 2, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'code_output', 'What does this print?', 'import pandas as pd\nwith pd.option_context("mode.copy_on_write", True):\n    df = pd.DataFrame({"a": [1, 2, 3]})\n    df["a"][0] = 99\n    print(df["a"].tolist())', 'python', '[1, 2, 3]', 'Under copy-on-write, df[''a''] is always a new object as far as writes are concerned.', 'With copy-on-write, chained assignment never reaches df; pandas only emits a ChainedAssignmentError *warning*, so the code runs and df is unchanged. This is how pandas 3.0 behaves.', NULL, NULL, 105);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[99, 2, 3]', 0), (@q, 'B', 'ChainedAssignmentError', 0), (@q, 'C', '[1, 2, 3]', 1), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2, 3], "b": [4, 5, 6]})\nsub = df[["a"]]\nsub.loc[0, "a"] = 100\nprint(df["a"].tolist())', 'python', '[1, 2, 3]', 'Selecting columns with a list builds a new frame.', 'df[[''a'']] (list indexing) always returns a copy, so changing sub never affects df; pandas still warns because it cannot be sure. Under copy-on-write the warning disappears and the result is the same.', NULL, NULL, 106);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[100, 2, 3]', 0), (@q, 'B', '[100, 100, 100]', 0), (@q, 'C', '[1, 2, 3]', 1), (@q, 'D', 'KeyError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 3, 'mcq', 'A teammate''s function does `def clean(df): df[''x''] = df[''x''].fillna(0); return df`. What''s the design risk?', NULL, NULL, 'It mutates the caller''s DataFrame as a side effect', 'DataFrames are passed by reference, like objects in JS or Java.', 'The function receives a reference to the same object, so assigning a column modifies the caller''s frame too. Start with df = df.copy() (or use assign) to keep functions pure.', NULL, 'Same as mutating an object argument in a JS function: the caller sees the change.', 107);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'It returns a copy, so the changes are lost', 0), (@q, 'B', 'fillna cannot be used inside a function', 0), (@q, 'C', 'It raises SettingWithCopyWarning every time', 0), (@q, 'D', 'It mutates the caller''s DataFrame as a side effect', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'mcq', 'Under pandas copy-on-write, why can `df2 = df.reset_index(drop=True)` be cheap even for a huge df?', NULL, NULL, 'The new object shares the underlying data until one of them is written to', 'Copying is deferred until it is actually needed.', 'Copy-on-write lets methods return new objects that share memory with the original; a real copy happens only when one side is modified. You get copy semantics at near-view cost.', NULL, 'Like fork() in Unix or immutable data structures: pages are shared until someone writes.', 108);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'The new object shares the underlying data until one of them is written to', 1), (@q, 'B', 'It deletes df''s data and moves it into df2', 0), (@q, 'C', 'reset_index is always done lazily on disk', 0), (@q, 'D', 'copy-on-write skips creating df2 entirely', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'copy-view'), 4, 'true_false', '`df.copy()` with the default `deep=True` also deep-copies Python objects stored inside object-dtype cells (e.g. lists in a cell).', NULL, NULL, 'False', 'The ''deep'' refers to the data arrays, not to Python objects within them.', 'deep=True copies the arrays, but for object dtype it copies the references, not the Python objects themselves. Mutating a list stored in a cell affects both copies. Use copy.deepcopy if you truly need it.', NULL, NULL, 109);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 0), (@q, 'B', 'False', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, None, 3])\nprint(s.dtype)', 'python', 'float64', 'NumPy integer arrays cannot store a missing value.', 'None becomes NaN, and NaN is a float, so pandas upcasts the whole column to float64. The ints are now 1.0 and 3.0.', NULL, NULL, 110);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'int64', 0), (@q, 'B', 'Int64', 0), (@q, 'C', 'object', 0), (@q, 'D', 'float64', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 2, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, None, 3], dtype="Int64")\nprint(s.dtype, s.tolist())', 'python', 'Int64 [1, <NA>, 3]', 'Capital-I Int64 is pandas'' nullable integer type.', 'Int64 (capital I) stores integers plus a mask of missing values, shown as <NA>. The ints stay ints.', NULL, NULL, 111);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'float64 [1.0, nan, 3.0]', 0), (@q, 'B', 'TypeError', 0), (@q, 'C', 'Int64 [1, <NA>, 3]', 1), (@q, 'D', 'int64 [1, nan, 3]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 1, 'mcq', 'What dtype does pandas 2.2 give a column of Python strings by default?', NULL, NULL, 'object', 'The dedicated text type exists but isn''t the default yet.', 'Strings default to object dtype (an array of pointers to Python str objects). The ''string'' dtype exists and must be requested with dtype=''string'' or astype(''string'').', NULL, NULL, 112);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'object', 1), (@q, 'B', 'string', 0), (@q, 'C', 'category', 0), (@q, 'D', 'str', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["1", "2", "3"])\nprint(s.astype(int).sum(), s.sum())', 'python', '6 123', 'Adding strings joins them.', 'astype(int) converts text to numbers, so the sum is 6. Summing the object column concatenates the strings: ''123''.', NULL, NULL, 113);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '123 123', 0), (@q, 'B', '6 123', 1), (@q, 'C', '6 6', 0), (@q, 'D', 'TypeError', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 1, 'code_output', 'What does this print?', 'import pandas as pd\ndf = pd.DataFrame({"a": [1, 2], "b": [1.5, 2.5], "c": ["x", "y"], "d": [True, False]})\nprint(df.dtypes.astype(str).tolist())', 'python', '[''int64'', ''float64'', ''object'', ''bool'']', 'Default NumPy-backed dtypes for each Python type.', 'ints -> int64, floats -> float64, str -> object, bools -> bool.', NULL, NULL, 114);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''int'', ''float'', ''str'', ''bool'']', 0), (@q, 'B', '[''int64'', ''float64'', ''object'', ''object'']', 0), (@q, 'C', '[''int64'', ''float64'', ''string'', ''bool'']', 0), (@q, 'D', '[''int64'', ''float64'', ''object'', ''bool'']', 1);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 2, 'true_false', 'Converting a column with few distinct values (e.g. ''lo''/''hi'' over a million rows) to `category` usually saves a lot of memory.', NULL, NULL, 'True', 'Store each distinct string once.', 'category stores the unique values once plus a small integer code per row, instead of a Python string object per row.', 'object column           category column\n"lo" -> str obj         categories: ["hi", "lo"]\n"hi" -> str obj         codes (int8): 1 0 1 1 ...\n"lo" -> str obj\n...  one object per row  one byte per row', 'Like normalising a table: a lookup table of values plus a foreign-key integer column.', 115);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'True', 1), (@q, 'B', 'False', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["lo", "hi", "lo", "lo"] * 1000)\nc = s.astype("category")\nprint(c.cat.categories.tolist(), c.cat.codes.dtype, c.memory_usage(deep=True) < s.memory_usage(deep=True) / 10)', 'python', '[''hi'', ''lo''] int8 True', 'Categories are sorted; with 2 categories the codes need only 1 byte.', 'Categories are stored sorted (hi, lo); the codes use the smallest integer type that fits (int8). Memory drops by over 10x.', NULL, NULL, 116);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[''hi'', ''lo''] int64 True', 0), (@q, 'B', '[''hi'', ''lo''] int8 False', 0), (@q, 'C', '[''hi'', ''lo''] int8 True', 1), (@q, 'D', '[''lo'', ''hi''] int8 True', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'mcq', 'Why does `df.memory_usage()` report much less than `df.memory_usage(deep=True)` for a text column?', NULL, NULL, 'Without deep, object columns count only the 8-byte pointers, not the Python strings they point to', 'An object column is an array of references.', 'An object array stores pointers (8 bytes each). Only deep=True follows the pointers and adds the size of each Python str object, which is the real cost.', NULL, NULL, 117);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', 'deep=True also counts the memory of the index twice', 0), (@q, 'B', 'Without deep, object columns count only the 8-byte pointers, not the Python strings they point to', 1), (@q, 'C', 'deep=True includes the memory of the CSV file it came from', 0), (@q, 'D', 'Without deep, pandas compresses the strings first', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, 2, 300])\nprint(s.astype("int8").tolist())', 'python', '[1, 2, 44]', 'int8 holds -128..127, and astype doesn''t check range.', 'astype(''int8'') wraps around silently on overflow: 300 - 256 = 44. pd.to_numeric(s, downcast=''integer'') picks a safe size instead.', NULL, NULL, 118);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[1, 2, 44]', 1), (@q, 'B', '[1, 2, 127]', 0), (@q, 'C', 'OverflowError', 0), (@q, 'D', '[1, 2, 300]', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 3, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series(["a", None], dtype="string")\no = pd.Series(["a", None])\nprint(s.isna().tolist(), repr(s[1]), repr(o[1]))', 'python', '[False, True] <NA> None', 'The string dtype uses pandas'' own missing marker.', 'The ''string'' dtype stores missing as pd.NA (printed <NA>). An object Series keeps the actual None object, though isna() treats both as missing.', NULL, NULL, 119);
INSERT INTO question_options (question_id, label, option_text, is_correct) VALUES (@q, 'A', '[False, False] None None', 0), (@q, 'B', '[False, True] <NA> nan', 0), (@q, 'C', '[False, True] <NA> None', 1), (@q, 'D', '[False, True] nan None', 0);
INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, None], dtype="Int64")\nprint(s[1] == 1, s.sum())', 'python', '<NA> 1', 'pd.NA propagates through comparisons (three-valued logic, like SQL NULL).', 'pd.NA == 1 is pd.NA, not False, mirroring SQL where NULL = 1 is NULL. Aggregations skip NA, so the sum is 1 and stays an integer.', NULL, NULL, 120);
