INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([1, None], dtype="Int64")\nif s[1] == 1:\n    print("yes")', 'python', 'TypeError', 'What is bool(pd.NA)?', 's[1] == 1 is pd.NA, and pd.NA refuses to be converted to True/False: TypeError (''boolean value of NA is ambiguous''). Check with pd.isna() first.', NULL, NULL, 121);
