INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'dtypes-memory'), 4, 'code_output', 'What does this print?', 'import pandas as pd\ns = pd.Series([True, False, None])\nprint(s.dtype, s.astype("boolean").sum())', 'python', 'object 1', 'A NumPy bool array has no slot for missing.', 'With a None present, the column can''t be bool, so it falls back to object. The nullable ''boolean'' dtype holds True/False/<NA>; its sum skips NA and counts 1 True.', NULL, NULL, 122);
