INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'labels-legends'), 3, 'true_false', '`plt.title(''x'')` and `ax.set_title(''x'')` can set titles on different plots if `ax` is not the current Axes.', NULL, NULL, 'True', 'pyplot functions act on the ''current'' Axes.', 'plt.title targets plt.gca(), the most recently active Axes. In a multi-plot figure that may not be the ax you think. Using ax.set_title is explicit.', NULL, NULL, 35);
