INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'pandas-plot'), 1, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nimport pandas as pd\ndf = pd.DataFrame({"train": [1.0, 0.6, 0.4], "val": [1.1, 0.8, 0.7]})\nax = df.plot()\nprint(type(ax).__name__, len(ax.lines))', 'python', 'Axes 2', 'df.plot() draws one line per numeric column and returns the Axes.', 'DataFrame.plot is a wrapper around matplotlib: it returns the Axes so you can keep customising (ax.set_xlabel...).', NULL, 'Like a UI component library wrapping raw DOM calls: quick defaults, and you can still reach the underlying element.', 47);
