INSERT INTO questions (subject_id, topic_id, level, qtype, question, code_snippet, code_language, answer, hint, explanation, diagram, analogy, sort_order) VALUES (@s, (SELECT id FROM topics WHERE subject_id = @s AND slug = 'pandas-plot'), 4, 'code_output', 'What does this print?', 'import matplotlib.pyplot as plt\nimport numpy as np\nimport pandas as pd\nidx = pd.date_range("2024-01-01", periods=4, freq="D")\ns = pd.Series([1, 3, 2, 4], index=idx)\nax = s.rolling(2).mean().plot()\ny = ax.lines[0].get_ydata()\nprint(type(y).__name__, len(y), int(np.ma.count_masked(y)))', 'python', 'MaskedArray 4 1', 'The NaN point is neither dropped nor set to zero.', 'rolling(2).mean() has NaN in the first slot. pandas hands matplotlib a masked array: all 4 points are kept, the NaN one is masked, and the line simply has a gap there.', NULL, NULL, 56);
